				--ruins
				if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].monsters~=nil and monsterPugs[hover_object.guid].pugType=="yellow" and hover_object.guid~="f3c6e3" and hover_object.guid~="28cc9c" and hover_object.guid~="2f9a1f" then
					colorConvert={
						["gray"]="{en}Keep Garison (Gray){ru}Гарнизон крепости (Серый){zh-tw}要塞守军（灰色）{zh-cn}要塞守军（灰色）{ko}성 수비대 (회색){es}Mantener Garison (Gris){fr}Garder Garison (Gris){pt-br}Forte Guarnição (Cinza){de}Garison behalten (Grau)",
						["tan"]="{en}Dungeon Monster (Tan){ru}Монстр из подземелья (Коричневый){zh-tw}地下城怪物（棕色）{zh-cn}地下城怪物（棕色）{ko}던전 몬스터 (갈색){es}Monstruo de Mazmorra (Marrón){fr}Monstre du donjon (Tan){pt-br}Monstro de Masmorra (Bronze){de}Kerkermonster (Braun)",
						["green"]="{en}Maraudering Orcs (Green){ru}Орк-мародер (Зеленый){zh-tw}兽人劫掠队（绿色）{zh-cn}兽人劫掠队（绿色）{ko}오크 습격자 (녹색){es}Orkos Merodeadores (Verde){fr}Orques maraudeurs (Vert){pt-br}Orks saqueadores (Verde){de}Marodierende Orks (Grün)",
						["red"]="{en}Draconum (Red){ru}Драконум (красный){zh-tw}龍族（紅色）{zh-cn}龙族（红色）{ko}드라코넘 (적색){es}Draconum (Rojo){fr}Draconum (Rouge){pt-br}Draconum (Vermelho){de}Draconum (Rot)",
						["purple"]="{en}Mage Tower Garison (Purple){ru}Гарнизон башни магов (Фиолетовый){zh-tw}法师塔守军（紫色）{zh-cn}法师塔守军（紫色）{ko}마법사 탑 수비대 (보라색){es}Torre de Mago Garison (Morado){fr}Tour des mages Garison (Violet){pt-br}Guarnição da Torre do Mago (Roxo){de}Magierturm Garison (Violett)",
						["white"]="{en}City Garison (white){ru}Гарнизон города (Белый){zh-tw}城市守军（白色）{zh-cn}城市守军（白色）{ko}도시 수비대 (흰색){es}Ciudad Garison (Blanco){fr}Garison de la ville (Blanc){pt-br}Guarnição da cidade (Branco){de}Stadt Garison (Weiß)"}
					monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ENEMIES DEFENDING: [-]One {ru}[00ff00]ОХРАНА: [-]Один {zh-tw}[00ff00]防守的敌人：[-]一个{zh-cn}[00ff00]防守的敌人：[-]一个{ko}[00ff00]방어 중인 적: [-]1개의 {es}[00ff00]ENEMIGOS DEFENDIENDO: [-]Uno {fr}[00ff00]ENNEMIS EN DÉFENSE : [-]Un {pt-br}[00ff00]INIMIGOS DEFENDENDO: [-]Um {de}[00ff00]ENEMIES DEFENDING: [-]Einer ", colorConvert[monsterPugs[hover_object.guid].monsters[1]], "{en} and one {ru} и один {zh-tw}和一个{zh-cn}和一个{ko} 그리고 1개의 {es} y uno {fr} et un {pt-br} e um {de} und einer ", colorConvert[monsterPugs[hover_object.guid].monsters[2]], "{en}.\n{zh-tw}。\n{zh-cn}。\n"})
				end
				if hover_object.guid=="f3c6e3" then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ENEMIES DEFENDING: [-]Two Maraudering Orcs(Green).\n{ru}[00ff00]ОХРАНА: [-]Два Орка-мародер (Зеленый).\n{zh-tw}[00ff00]驻守敌人：[-]两个兽人劫掠队（绿色）。\n{zh-cn}[00ff00]驻守敌人：[-]两个兽人劫掠队（绿色）。\n{ko}[00ff00]방어 중인 적: [-]2개의 오크(녹색).\n{es}[00ff00]ENEMIGOS DEFENDIENDO: [-]Dos Orkos Merodeadores(Verde).\n{fr}[00ff00]ENNEMIES DEFENDANTS : [-]Deux Orks maraudeurs (vert).\n{pt-br}[00ff00]INIMIGOS DEFENDENDO: [-]Dois Orks saqueadores(verde).\n{de}[00ff00]ENEMIES DEFENDING: [-]Zwei marodierende Orks(grün).\n"}) end
				if hover_object.guid=="28cc9c" then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ENEMIES DEFENDING: [-]Two Mage Tower Garisons(Purple).\n{ru}[00ff00]ОХРАНА: [-]Два Гарнизона башни магов (Фиолетовый).\n{zh-tw}[00ff00]驻守敌人：[-]两个法师塔守军（紫色）。\n{zh-cn}[00ff00]驻守敌人：[-]两个法师塔守军（紫色）。\n{ko}[00ff00]방어 중인 적: [-]2개의 마법사 탑 수비대(보라색).\n{es}[00ff00]ENEMIGOS DEFENDIENDO: [-]Dos Mage Tower Garisons(Purple).\n{fr}[00ff00]ENEMIS EN DEFENSE : [-]Deux Garisons de la Tour des Mages (Pourpre).\n{pt-br}[00ff00]INIMIGOS DEFENDENDO: [-]Duas Guarnições da Torre do Mago (Roxo).\n{de}[00ff00]ENEMIES DEFENDING: [-]Zwei Magierturm-Garisons(Lila).\n"}) end
				if hover_object.guid=="2f9a1f" then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ENEMIES DEFENDING: [-]Three Maraudering Orcs(Green).\n{ru}[00ff00]ОХРАНА: [-]Три Орка-мародер (Зеленый).\n{zh-tw}[00ff00]驻守敌人：[-]三个兽人劫掠队（绿色）。\n{zh-cn}[00ff00]驻守敌人：[-]三个兽人劫掠队（绿色）。\n{ko}[00ff00]방어 중인 적: [-]3개의 오크(녹색).\n{es}[00ff00]ENEMIGOS DEFENDIENDO: [-]Tres Orkos Merodeadores(Verde).\n{fr}[00ff00]ENEMIS EN DEFENSE : [-]Trois Orks maraudeurs(Vert).\n{pt-br}[00ff00]INIMIGOS DEFENDENDO: [-]Três Orcs Saqueadores(Verde).\n{de}[00ff00]ENEMIES DEFENDING: [-]Drei marodierende Orks(Grün).\n"}) end
				if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].required~=nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ALTER REQUIRES: [-]{ru}[00ff00]ПОДНОШЕНИЕ АЛТАРЮ: [-]{zh-tw}[00ff00]改变要求：[-]{zh-cn}[00ff00]改变要求：[-]{ko}[00ff00]재단 활성화: [-]{es}[00ff00]ALTER REQUIRE: [-]{fr}[00ff00]ALTER REQUIRES : [-]{pt-br}[00ff00]ALTERAR REQUISITOS: [-]{de}[00ff00]ALTER ERFORDERT: [-]", monsterPugs[hover_object.guid].required, "{en}.\n{zh-tw}。\n{zh-cn}。\n"}) end
				if hover_object.getGMNotes()~="Puppet Master" then monsterDescription=joinLang({monsterDescription, "\n"}) end
				if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].reward~=nil and monsterPugs[hover_object.guid].pugType=="yellow" then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]REWARD FOR DEFEATING: [-]{ru}[00ff00]НАГРАДА ЗА ПОБЕДУ: [-]{zh-tw}[00ff00]击败奖励：[-]{zh-cn}[00ff00]击败奖励：[-]{ko}[00ff00]정복 보상: [-]{es}[00ff00]RECOMPENSA POR DERROTA: [-]{fr}[00ff00]RÉCOMPENSE POUR LA DÉFENSE : [-]{pt-br}[00ff00]RECOMPENSA PELA DEFESA: [-]{de}[00ff00]BELOHNUNG FÜR DIE BESIEGUNG: [-]", monsterPugs[hover_object.guid].reward, "{en}.{zh-tw}。{zh-cn}。"}) end
				--swiftness
				if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].swiftness~=nil) or (gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].swiftness~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]SWIFTNESS[-][i] - This enemy's attack is doubled when trying to Block it.[/i]\n\n{ru}[00ff00]БЫСТРАЯ АТАКА[-][i] - Блокирование атаки врага требует вдвое больше очков блока, чем обычно.[/i]\n\n{zh-tw}[00ff00]迅捷[-][i] - 当试图阻挡敌人时，该敌人的攻击力会加倍。[/i]\n\n{zh-cn}[00ff00]迅捷[-][i] - 当试图阻挡敌人时，该敌人的攻击力会加倍。[/i]\n\n{ko}[00ff00]신속[-][i] - 이 공격을 방어할 때는 두 배의 수치가 필요.[/i]\n\n{es}[00ff00]VELOCIDAD[-][i] - El ataque de este enemigo se duplica al intentar Bloquearlo[/i]\n\n{fr}[00ff00]SOUPLESSE[-][i] - L'attaque de cet ennemi est doublée lorsque l'on tente de le bloquer.[/i]\n\n{pt-br}[00ff00]AGILIDADE[-][i] - O ataque deste inimigo é dobrado ao tentar bloqueá-lo.[/i]\n\n{de}[00ff00]GESCHWINDIGKEIT[-][i] - Der Angriff dieses Gegners wird verdoppelt, wenn man versucht, ihn zu blocken.[/i]\n\n"}) end
				--cumbersome
				if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].cumbersome~=nil) or (gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].cumbersome~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]CUMBERSOME[-][i] - This enemy's attack can be reduced by the amount of Move a player spends.[/i]\n\n{ru}[00ff00]НЕПОВОРОТЛИВЫЙ[-][i] - В фазе блока вы можете потратить очки Движения, уменьшив значение Атаки врага на 1 за каждое очко. Атака, уменьшенная до 0, успешно заблокирована.[/i]\n\n{zh-tw}[00ff00]笨重[-][i] - 该敌人的攻击力可以被玩家消耗的移动力减少。[/i]\n\n{zh-cn}[00ff00]笨重[-][i] - 该敌人的攻击力可以被玩家消耗的移动力减少。[/i]\n\n{ko}[00ff00]육중함[-][i] - 플레이어가 소비한 이동력만큼 이 적의 공격력이 감소.[/i]\n\n{es}[00ff00]CUMBERSOME[-][i] - El ataque de este enemigo puede ser reducido por la cantidad de Movimiento que gaste el jugador.[/i]\n\n{fr}[00ff00]CUMBERSOME[-][i] - L'attaque de cet ennemi peut être réduite par la quantité de Mouvement dépensée par le joueur.[/i]\n\n{pt-br}[00ff00]CORPULENTO-][i] - O ataque desse inimigo pode ser reduzido pela quantidade de movimento que o jogador gasta.[/i]\n\n{de}[00ff00]GESCHWINDIGKEIT[-][i] - Der Angriff dieses Gegners kann um die Menge an Bewegung reduziert werden, die ein Spieler ausgibt.[/i]\n\n"}) end
				--poison
				if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].poison~=nil) or (gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].poison~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]POISON[-][i] - The Player adds an extra wound to their discard pile for each wound from this enemy. Units get two wounds if taking a wound.[/i]\n\n{ru}[00ff00]ЯДОВИТАЯ АТАКА[-][i] - Отряд получает две карты ран вместо одной от атаки ядовитого врага. За каждую рану, полученную героем от этой атаки, он также кладет одну карту раны в свой сброс.[/i]\n\n{zh-tw}[00ff00]剧毒[-][i] - 此敌人每造成一次伤害，玩家就会在弃牌堆中额外增加一次伤害。如果受伤，单位会获得两个伤口。[/i]\n\n{zh-cn}[00ff00]剧毒[-][i] - 此敌人每造成一次伤害，玩家就会在弃牌堆中额外增加一次伤害。如果受伤，单位会获得两个伤口。[/i]\n\n{ko}[00ff00]독성[-][i] - 이 적에게 받는 부상 하나당, 자신의 버린 카드 더미에 부상 하나를 추가. 유닛이 부상을 받을 경우 두 개를 받음.[/i]\n\n{es}[00ff00]VENENO[-][i] - El Jugador añade una herida extra a su pila de descartes por cada herida de este enemigo. Las unidades reciben dos heridas si reciben una herida.[/i]\n\n{fr}[00ff00]POISON[-][i] - Le joueur ajoute une blessure supplémentaire à sa pile de défausse pour chaque blessure infligée par cet ennemi.[/i]\n\n{pt-br}[00ff00]VENENO[-][i] - O jogador adiciona um ferimento extra à sua pilha de descarte para cada ferimento desse inimigo. As unidades recebem dois ferimentos se receberem um ferimento.[/i]\n\n{de}[00ff00]GIFT[-][i] - Der Spieler legt für jede Verwundung durch diesen Feind eine zusätzliche Wunde auf seinen Ablagestapel. Einheiten erhalten zwei Verwundungen, wenn sie eine Verwundung erleiden.[/i]\n\n"}) end
				--brutal
				if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].brutal~=nil) or (gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].brutal~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]BRUTAL[-][i] - This enemy's attack is doubled if not blocked.[/i]\n\n{ru}[00ff00]ЖЕСТОКАЯ АТАКА[-][i] - Если враг не заблокирован, он наносит вдвое больше урона, чем его значение Атаки.[/i]\n\n{zh-tw}[00ff00]残暴[-][i] - 如果没有被阻挡，这个敌人的攻击会加倍。[/i]\n\n{zh-cn}[00ff00]残暴[-][i] - 如果没有被阻挡，这个敌人的攻击会加倍。[/i]\n\n{ko}[00ff00]난폭[-][i] - 방어하지 못하면, 공격력의 두 배만큼의 대미지를 받음.[/i]\n\n{es}[00ff00]BRUTAL[-][i] - El ataque de este enemigo se duplica si no es bloqueado.[/i]\n\n{fr}[00ff00]BRUTAL[-][i] - L'attaque de cet ennemi est doublée si elle n'est pas bloquée.[/i]\n\n{pt-br}[00ff00]BRUTAL[-][i] - O ataque desse inimigo é dobrado se não for bloqueado.[/i]\n\n{de}[00ff00]BRUTAL[-][i] - Der Angriff dieses Feindes wird verdoppelt, wenn er nicht geblockt wird.[/i]\n\n"}) end
				--vampiric
				if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].vampiric~=nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]VAMPIRIC[-][i] - Increase the armour of this enemy by the amount of wounds this enemy has dealt to the player and units.[/i]\n\n{ru}[00ff00]ВАМПИРИЗМ[-][i] - Броня врага с вампиризмом увеличивается на 1 до конца битвы каждый раз, когда в результате его атаки отряд получает рану или игрок берёт карту раны в руку.[/i]\n\n{zh-tw}[00ff00]吸血[-][i] - 增加该敌人的护甲，数值为该敌人对玩家和单位造成的伤害值。[/i]\n\n{zh-cn}[00ff00]吸血[-][i] - 增加该敌人的护甲，数值为该敌人对玩家和单位造成的伤害值。[/i]\n\n{ko}[00ff00]흡혈[-][i] - 이 적의 방어구가, 플레이어와 유닛에게 준 부상의 개수만큼 증가합니다.[/i]\n\n{es}[00ff00]VAMPÍRICO[-][i] - Aumenta la armadura de este enemigo por la cantidad de heridas que este enemigo haya infligido al jugador y a las unidades.[/i]\n\n{fr}[00ff00]VAMPIRIC[-][i] - Augmente l'armure de cet ennemi du nombre de blessures qu'il a infligées au joueur et à ses unités.[/i]\n\n{pt-br}[00ff00]VAMPÍRICO[-][i] - Aumenta a armadura desse inimigo pela quantidade de ferimentos que esse inimigo causou ao jogador e às unidades.[/i]\n\n{de}[00ff00]VAMPIRISCH[-][i] - Erhöht die Rüstung dieses Feindes um die Anzahl der Wunden, die dieser Feind dem Spieler und seinen Einheiten zugefügt hat.[/i]\n\n"}) end
				--Paralyse
				if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].paralyse~=nil) or (gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].paralyse~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]PARALYZE[-][i] - Player discards all non-wound cards when taking a wound from this enemy. Units are destroyed if taking a wound.[/i]\n\n{ru}[00ff00]ПАРАЛИЗУЮЩАЯ АТАКА[-][i] - Отряд, получивший рану от такой атаки, немедленно уничтожается. Если герой получает раны от такой атаки, управляющий им игрок немедленно сбрасывает с руки все карты, кроме карт ран.[/i]\n\n{zh-tw}[00ff00]瘫痪[-][i] - 玩家在受到该敌人的伤害时会丢弃所有非受伤的牌。如果受伤，单位将被摧毁。[/i]\n\n{zh-cn}[00ff00]瘫痪[-][i] - 玩家在受到该敌人的伤害时会丢弃所有非受伤的牌。如果受伤，单位将被摧毁。[/i]\n\n{ko}[00ff00]마비[-][i] - 플레이어가 이 공격으로 한 장 이상의 부상을 받으면, 즉시 손에서 부상을 제외한 모든 카드를 버림. 부상을 받은 유닛은 게임에서 제거됨.[/i]\n\n{es}[00ff00]PARALYSE[-][i] - El jugador descarta todas las cartas no heridas al recibir una herida de este enemigo. Las unidades son destruidas si reciben una herida.[/i]\n\n{fr}[00ff00]PARALYSE[-][i] - Le joueur défausse toutes les cartes non blessées lorsqu'il est blessé par cet ennemi. Les unités sont détruites si elles subissent une blessure.[/i]\n\n{pt-br}[00ff00]PARALISIA[-][i] - O jogador descarta todas as cartas não feridas ao receber um ferimento desse inimigo. As unidades são destruídas se receberem um ferimento.[/i]\n\n{de}[00ff00]PARALYSE[-][i] - Der Spieler wirft alle Karten ab, die nicht verwundet sind, wenn er eine Verwundung durch diesen Feind erleidet. Einheiten werden zerstört, wenn sie eine Verwundung erleiden.[/i]\n\n"}) end
				--assassination
				if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].assassination~=nil) or (gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].assassination~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ASSASSINATION[-][i] - This enemy's attack damage can only be assigned to the player.[/i]\n\n{ru}[00ff00]НАЕМНЫЙ УБИЙЦА[-][i] - Урон от атаки врага не может быть распределён на отряды. Если враг не заблокирован, урон получает только герой.[/i]\n\n{zh-tw}[00ff00]刺杀[-][i] - 该敌人的攻击伤害只能分配给玩家。[/i]\n\n{zh-cn}[00ff00]刺杀[-][i] - 该敌人的攻击伤害只能分配给玩家。[/i]\n\n{ko}[00ff00]암살[-][i] - 이 적의 대미지는 유닛에게 할당 불가.[/i]\n\n{es}[00ff00]ASESINATO[-][i] - El daño de ataque de este enemigo sólo puede ser asignado al jugador.[/i]\n\n{fr}[00ff00]ASSASSINATION[-][i] - Les dégâts d'attaque de cet ennemi ne peuvent être attribués qu'au joueur.[/i]\n\n{pt-br}[00ff00]ASSASSINATO[-][i] - O dano de ataque desse inimigo só pode ser atribuído ao jogador.[/i]\n\n{de}[00ff00]ASSASSINATION[-][i] - Der Angriffsschaden dieses Feindes kann nur dem Spieler zugewiesen werden.[/i]\n\n"}) end
				if gStates.summonStates[hover_object.guid]~="summoned" then
					--armour
					local bonus=0
					if gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].armour~=nil then bonus=gStates.monsterPerks[hover_object.guid].armour end
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].armour~=nil and monsterPugs[hover_object.guid].elusive==nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ARMOUR: [-]{ru}[00ff00]БРОНЯ: [-]{zh-tw}[00ff00]护甲：[-]{zh-cn}[00ff00]护甲：[-]{ko}[00ff00]방어구: [-]{es}[00ff00]ARMADURA: [-]{fr}[00ff00]ARMURE : [-]{pt-br}[00ff00] ARMADURA: [-]{de}[00ff00]RÜSTUNG: [-]", tostring(monsterPugs[hover_object.guid].armour+bonus), "\n\n"}) end
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].armour~=nil and monsterPugs[hover_object.guid].elusive~=nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ARMOUR: [-]{ru}[00ff00]БРОНЯ: [-]{zh-tw}[00ff00]护甲：[-]{zh-cn}[00ff00]护甲：[-]{ko}[00ff00]방어구: [-]{es}[00ff00]ARMADURA: [-]{fr}[00ff00]ARMURE : [-]{pt-br}[00ff00] ARMADURA: [-]{de}[00ff00]RÜSTUNG: [-]", tostring(monsterPugs[hover_object.guid].armour+bonus), "[7b7b7b]/", tostring((monsterPugs[hover_object.guid].armour*2)+bonus), "[-]\n\n"}) end
					--Elusive
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].elusive~=nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ELUSIVE[-][i] - This enemy's higher Armour value is used until successfully Blocked.[/i]\n\n{ru}[00ff00]НЕУЛОВИМЫЙ[-][i] - Меньшее значение брони используется только в фазе ближнего боя и только если все атаки этого врага были успешно заблокированы.[/i]\n\n{zh-tw}[00ff00]盾逸 [-][i]-该敌人的较高护甲值会被使用，直到成功阻挡。[/i]\n\n{zh-cn}[00ff00]盾逸 [-][i]-该敌人的较高护甲值会被使用，直到成功阻挡。[/i]\n\n{ko}[00ff00]은밀함[-][i] - 이 공격을 성공적으로 방어하기 전 까지, 더 높은 방어구 수치를 적용.[/i]\n\n{es}[00ff00]ELUSIVO[-][i] - El valor de Armadura más alto de este enemigo se utiliza hasta que es Bloqueado con éxito.[/i]\n\n{fr}[00ff00]ELUSIVE[-][i] - La valeur d'armure la plus élevée de cet ennemi est utilisée jusqu'à ce qu'il soit bloqué avec succès.[/i]\n\n{pt-br}[00ff00]ELUSIVO[-][i] - O valor mais alto de Armadura desse inimigo é usado até que ele seja bloqueado com sucesso[/i]\n\n{de}[00ff00]ELUSIV[-][i] - Der höhere Rüstungswert dieses Gegners wird verwendet, bis er erfolgreich geblockt wird[/i]\n\n"}) end
					--defender
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].defend~=nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]DEFENDER[-][i] - The first enemy attacked by the player gets {ru}[00ff00]ПРИКРЫТИЕ[-][i] - Первый враг, атакованный игроком, получает {zh-tw}[00ff00]守护[-][i] - 第一个被玩家攻击的敌人会被增加护甲。{zh-cn}[00ff00]守护[-][i] - 第一个被玩家攻击的敌人会被增加护甲。{ko}[00ff00]수비[-][i] - 플레이어가 처음 공격하는 적에게{es}[00ff00]DEFENSOR[-][i] - El primer enemigo atacado por el jugador obtiene {fr}[00ff00]DEFENDER[-][i] - Le premier ennemi attaqué par le joueur voit son armure augmentée {pt-br}[00ff00]DEFENSOR[-][i] - O primeiro inimigo atacado pelo jogador recebe {de}[00ff00]VERTEIDIGER[-][i] - Der erste vom Spieler angegriffene Feind erhält ", monsterPugs[hover_object.guid].defend, "{en} added to its armour.[/i]\n\n{ru} к его броне.[/i]\n\n{zh-tw}增加其护甲。[/i]\n\n{zh-cn}增加其护甲。[/i]\n\n{ko}방어구를 추가.[/i]\n\n{es} se añade a su armadura.[/i]\n\n{fr}ajouté à son armure.[/i]\n\n{pt-br} adicionado à sua armadura.[/i]\n\n{de} zu seiner Rüstung hinzugefügt.[/i]\n\n"}) end
					--Fortified
					if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].fortified~=nil and (gStates.monsterPerks[hover_object.guid]==nil or (gStates.monsterPerks[hover_object.guid].fortified==nil and gStates.monsterPerks[hover_object.guid].wallFortified==nil))) or (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].fortified==nil and gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].fortified~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]FORTIFIED[-][i] - This enemy can't be attacked with Ranged attacks in the Range phase.[/i]\n\n{ru}[00ff00]УКРЕПЛЕННЫЙ[-][i] - Во время фазы боя на расстоянии против врага можно играть только Осадные атаки.[/i]\n\n{zh-tw}[00ff00]城防[-][i] - 在远程攻击阶段，该敌人无法受到远程攻击。[/i]\n\n{zh-cn}[00ff00]城防[-][i] - 在远程攻击阶段，该敌人无法受到远程攻击。[/i]\n\n{ko}[00ff00]요새화[-][i] - 이 적을 원거리 단계에서 원거리 공격으로 공격할 수 없음.[/i]\n\n{es}[00ff00]FORTIFICADO[-][i] - Este enemigo no puede ser atacado con ataques a distancia en la fase de Alcance.[/i]\n\n{fr}[00ff00]FORTIFIÉ[-][i] - Cet ennemi ne peut pas être attaqué avec des attaques à distance lors de la phase de portée.[/i]\n\n{pt-br}[00ff00]FORTIFICADO[-][i] - Esse inimigo não pode ser atacado com ataques de longo alcance na fase de alcance[/i]\n\n{de}[00ff00]VERTEIDIGT[-][i] - Dieser Gegner kann in der Fernkampfphase nicht mit Fernkampfangriffen angegriffen werden.[/i]\n\n"}) end
					--double Fortified
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].fortified~=nil and gStates.monsterPerks[hover_object.guid]~=nil and (gStates.monsterPerks[hover_object.guid].fortified~=nil or gStates.monsterPerks[hover_object.guid].wallFortified~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]DOUBLE FORTIFIED[-][i] - This enemy can't be attacked with Ranged or Siege attacks in the Range phase.[/i]\n\n{ru}[00ff00]ДВАЖДЫ УКРЕПЛЕННЫЙ[-][i] - Враг не может быть атакован во время фазы боя на расстоянии.[/i]\n\n{zh-tw}[00ff00]双重城防[-][i] - 在远程攻击阶段不能使用远程攻击或攻城攻击攻击该敌人。[/i]\n\n{zh-cn}[00ff00]双重城防[-][i] - 在远程攻击阶段不能使用远程攻击或攻城攻击攻击该敌人。[/i]\n\n{ko}[00ff00]이중 요새화[-][i] - 이 적을 원거리 단계에서 원거리 공격이나 공성 공격으로 공격할 수 없음.[/i]\n\n{es}[00ff00]DOBLE FORTIFICADO[-][i] - Este enemigo no puede ser atacado con ataques a distancia o de asedio en la fase de alcance.[/i]\n\n{fr}[00ff00]DOUBLE FORTIFIÉ[-][i] - Cet ennemi ne peut pas être attaqué avec des attaques à distance ou de siège lors de la phase à distance.[/i]\n\n{pt-br}[00ff00]DUPLAMENTE FORTIFICADO[-][i] - Esse inimigo não pode ser atacado com ataques de longo alcance ou de cerco na fase de alcance[/i]\n\n{de}[00ff00]DOPPELT BEFESTIGT[-][i] - Dieser Feind kann in der Fernkampfphase nicht mit Fernkampf- oder Belagerungsangriffen angegriffen werden[/i]\n\n"}) end
					--Wall Fortified
					if gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].wallFortified~=nil and (monsterPugs[hover_object.guid]==nil or monsterPugs[hover_object.guid].fortified==nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]WALL FORTIFIED[-][i] - This enemy can't be attacked with Ranged attacks in the Range phase.[/i]\n\n{ru}[00ff00]УКРЕПЛЕННЫЙ ЗА СТЕНОЙ[-][i] - Во время фазы боя на расстоянии против врага можно играть только Осадные атаки.[/i]\n\n{zh-tw}[00ff00]城防[-][i] - 在远程攻击阶段，该敌人无法受到远程攻击。[/i]\n\n{zh-cn}[00ff00]城防[-][i] - 在远程攻击阶段，该敌人无法受到远程攻击。[/i]\n\n{ko}[00ff00]벽 요새화[-][i] - 이 적을 원거리 단계에서 원거리 공격으로 공격할 수 없음.[/i]\n\n{es}[00ff00]PARED FORTIFICADA[-][i] - Este enemigo no puede ser atacado con ataques a distancia en la fase de Alcance.[/i]\n\n{fr}[00ff00]FORTIFIÉ PAR UN MUR[-][i] - Cet ennemi ne peut pas être attaqué avec des attaques à distance lors de la phase de portée.[/i]\n\n{pt-br}[00ff00]PAREDE FORTIFICADA[-][i] - Esse inimigo não pode ser atacado com ataques de longo alcance na fase de alcance[/i]\n\n{de}[00ff00]DURCH MAUER BEFESTIGT[-][i] - Dieser Gegner kann in der Fernkampfphase nicht mit Fernkampfangriffen angegriffen werden.[/i]\n\n"}) end
					--Unfortified
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].unfortified~=nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]UN-FORTIFIED[-][i] - This enemy ignores site fortifications, and can be attacked with Range and Siege attacks.[/i]\n\n{ru}[00ff00]НЕУКРЕПЛЕННЫЙ[-][i] - Этот враг игнорирует все местные укрепления и может быть атакован с помощью Дальних и Осадных атак.[/i]\n\n{zh-tw}[00ff00]不设城防[-][i] - 该敌人无视地点城防，可以使用远程攻击和攻城攻击。[/i]\n\n{zh-cn}[00ff00]不设城防[-][i] - 该敌人无视地点城防，可以使用远程攻击和攻城攻击。[/i]\n\n{ko}[00ff00]무방비[-][i] - 이 적을 요새화를 무시하고 원거리 및 공성 공격으로 공격할 수 있음.[/i]\n\n{es}[00ff00]NO FORTIFICADO[-][i] - Este enemigo ignora las fortificaciones del sitio, y puede ser atacado con ataques de Alcance y Asedio.[/i]\n\n{fr}[00ff00]NON FORTIFIE[-][i] - Cet ennemi ignore les fortifications du site et peut être attaqué avec des attaques à distance et de siège.[/i]\n\n{pt-br}[00ff00]NÃO FORTIFICADO[-][i] - Esse inimigo ignora as fortificações do local e pode ser atacado com ataques de longo alcance e de cerco.[/i]\n\n{de}[00ff00]UNVERBESSERT[-][i] - Dieser Feind ignoriert Standortbefestigungen und kann mit Fernkampf- und Belagerungsangriffen angegriffen werden.[/i]\n\n"}) end
					--physical resistance
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].pResist~=nil then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]PHYSICAL RESISTANCE[-][i] - Physical attacks are halved against this enemy.[/i]\n\n{ru}[00ff00]ФИЗИЧЕСКОЕ СОПРОТИВЛЕНИЕ[-][i] - Значения Физических атак делятся на 2, с округлением вниз[/i]\n\n{zh-tw}[00ff00]物理抗性[-][i] - 对该敌人的物理攻击减半。[/i]\n\n{zh-cn}[00ff00]物理抗性[-][i] - 对该敌人的物理攻击减半。[/i]\n\n{ko}[00ff00]물리 저항[-][i] - 모든 물리 공격이 반감됨.[/i]\n\n{es}[00ff00]RESISTENCIA FÍSICA[-][i] - Los ataques físicos se reducen a la mitad contra este enemigo.[/i]\n\n{fr}[00ff00]RÉSISTANCE PHYSIQUE[-][i] - Les attaques physiques sont réduites de moitié contre cet ennemi.[/i]\n\n{pt-br}[00ff00]RESISTÊNCIA FÍSICA[-][i] - Os ataques físicos são reduzidos à metade contra esse inimigo.[/i]\n\n{de}[00ff00]PHYSISCHE RESISTENZ[-][i] - Physische Angriffe werden gegen diesen Feind halbiert.[/i]\n\n"}) end
					--fire resistance
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].fResist~=nil and monsterPugs[hover_object.guid].iResist==nil then monsterDescription=joinLang({monsterDescription, "{en}[ff0000]FIRE RESISTANCE[-][i] - Fire attacks are halved against this enemy. This enemy can't be targeted by Unit abilities powered by Red Mana, nor from non-attack effects of Red cards.[/i]\n\n{ru}[ff0000]СОПРОТИВЛЕНИЕ ОГНЮ[-][i] - Значения Огненных атак делятся на 2, с округлением вниз. Этот отряд игнорирует все эффекты карт и способности отрядов, сыгранные за красную ману (кроме эффектов Атак).[/i]\n\n{zh-tw}[ff0000]火焰抗性[-][i] - 对该敌人的火焰攻击减半。该敌人无法成为由红色法力驱动的单位能力的目标，也无法成为红色卡牌的非攻击效果的目标。[/i]\n\n{zh-cn}[ff0000]火焰抗性[-][i] - 对该敌人的火焰攻击减半。该敌人无法成为由红色法力驱动的单位能力的目标，也无法成为红色卡牌的非攻击效果的目标。[/i]\n\n{ko}[ff0000]불 저항[-][i] - 모든 불 공격이 반감됨. 이 적은 적색 카드나 적색 마나로 강화한 유닛의 (공격이 아닌) 특수 효과를 무시함.[/i]\n\n{es}[ff0000]RESISTENCIA AL FUEGO[-][i] - Los ataques de fuego se reducen a la mitad contra este enemigo. Este enemigo no puede ser objetivo de habilidades de Unidad potenciadas con Maná Rojo, ni de efectos de no-ataque de cartas Rojas.[/i]\n\n{fr}[ff0000]RÉSISTANCE AU FEU[-][i] - Les attaques de feu sont réduites de moitié contre cet ennemi. Cet ennemi ne peut pas être ciblé par des capacités d'unité alimentées par du mana rouge, ni par des effets de cartes rouges qui n'attaquent pas.[/i]\n\n{pt-br}[ff0000]RESISTÊNCIA AO FOGO[-][i] - Os ataques de fogo são reduzidos à metade contra esse inimigo. Esse inimigo não pode ser alvo de habilidades de unidade alimentadas por Mana vermelha nem de efeitos de cartas vermelhas que não sejam de ataque.[/i]\n\n{de}[ff0000]FEUERWIDERSTAND[-][i] - Feuerangriffe werden gegen diesen Feind halbiert. Dieser Feind kann weder von Einheitenfähigkeiten, die durch rotes Mana angetrieben werden, noch von Nicht-Angriffseffekten roter Karten angegriffen werden.[/i]\n\n"}) end
					--ice resistance
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].iResist~=nil and monsterPugs[hover_object.guid].fResist==nil then monsterDescription=joinLang({monsterDescription, "{en}[5a5aff]ICE RESISTANCE[-][i] - Ice attacks are halved against this enemy. This enemy can't be targeted by Unit abilities powered by Blue Mana, nor from non-attack effects of Blue cards.[/i]\n\n{ru}[5a5aff]СОПРОТИВЛЕНИЕ ЛЬДУ[-][i] - Значения Ледяных атак делятся на 2, с округлением вниз. Этот отряд игнорирует все эффекты карт и способности отрядов, сыгранные за синюю ману (кроме эффектов Атак).[/i]\n\n{zh-tw}[5a5aff]寒冰抗性[-][i] - 此敌人受到的寒冰攻击减半。该敌人不能成为由蓝色法力驱动的单位异能的目标，也不能成为蓝色卡牌非攻击效果的目标。[/i]\n\n{zh-cn}[5a5aff]寒冰抗性[-][i] - 此敌人受到的寒冰攻击减半。该敌人不能成为由蓝色法力驱动的单位异能的目标，也不能成为蓝色卡牌非攻击效果的目标。[/i]\n\n{ko}[5a5aff]얼음 저항[-][i] - 모든 얼음 공격이 반감됨. 이 적은 청색 카드나 총색 마나로 강화한 유닛의 (공격이 아닌) 특수 효과를 무시함.[/i]\n\n{es}[5a5aff]RESISTENCIA AL HIELO[-][i] - Los ataques de hielo se reducen a la mitad contra este enemigo. Este enemigo no puede ser objetivo de habilidades de Unidad potenciadas con Maná Azul, ni de efectos de no-ataque de cartas Azules.[/i]\n\n{fr}[5a5aff]RÉSISTANCE À LA GLACE[-][i] - Les attaques de glace sont réduites de moitié contre cet ennemi. Cet ennemi ne peut pas être ciblé par les capacités d'unité alimentées par du mana bleu, ni par les effets non offensifs des cartes bleues.[/i]\n\n{pt-br}[5a5aff]RESISTÊNCIA AO GELO[-][i] - Os ataques de gelo são reduzidos à metade contra esse inimigo. Esse inimigo não pode ser alvo de habilidades de Unidade alimentadas por Mana Azul nem de efeitos de cartas Azuis que não sejam de ataque.[/i]\n\n{de}[5a5aff]EISWIDERSTAND[-][i] - Eisangriffe werden gegen diesen Feind halbiert. Dieser Feind kann weder von Einheitenfähigkeiten, die durch blaues Mana angetrieben werden, noch von Nicht-Angriffseffekten blauer Karten angegriffen werden.[/i]\n\n"}) end
					--cold fire resistance
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].iResist~=nil and monsterPugs[hover_object.guid].fResist~=nil then monsterDescription=joinLang({monsterDescription, "{en}[ff00fe]COLD FIRE RESISTANCE[-][i] - Fire, Ice and Cold Fire attacks are halved against this enemy. This enemy can't be targeted by Unit abilities powered by Red or Blue Mana, nor from non-attack effects of Red or Blue cards.[/i]\n\n{ru}[ff00fe]СОПРОТИВЛЕНИЕ ОГНЮ И ЛЬДУ[-][i] - Значения Огненных, Ледяных и Огненно-ледяных атак делятся на 2, с округлением вниз. Этот отряд игнорирует все эффекты карт и способности отрядов, сыгранные за красную или синюю ману (кроме эффектов Атак).[/i]\n\n{zh-tw}[ff00fe]冰火抗性[-][i] - 此敌人受到的火、冰和冰火攻击减半。该敌人不能成为由红色或蓝色法力驱动的单位能力的目标，也不能成为红色或蓝色卡牌的非攻击效果的目标。[/i]\n\n{zh-cn}[ff00fe]冰火抗性[-][i] - 此敌人受到的火、冰和冰火攻击减半。该敌人不能成为由红色或蓝色法力驱动的单位能力的目标，也不能成为红色或蓝色卡牌的非攻击效果的目标。[/i]\n\n{ko}[ff00fe]차가운불 저항[-][i] - 모든 불, 얼음, 차가운 불 공격이 반감됨. 이 적은 청,적색 카드나 청,적색 마나로 강화한 유닛의 (공격이 아닌) 특수 효과를 무시함..[/i]\n\n{es}[ff00fe]RESISTENCIA AL FUEGO FRÍO[-][i] - Los ataques de Fuego, Hielo y Fuego Frío se reducen a la mitad contra este enemigo. Este enemigo no puede ser objetivo de habilidades de Unidad potenciadas con Maná Rojo o Azul, ni de efectos de no-ataque de cartas Rojas o Azules.[/i]\n\n{fr}[ff00fe]RÉSISTANCE AU FEU FROID[-][i] - Les attaques de Feu, de Glace et de Feu froid sont réduites de moitié contre cet ennemi. Cet ennemi ne peut pas être ciblé par des capacités d'unité alimentées par du mana rouge ou bleu, ni par des effets non offensifs de cartes rouges ou bleues.[/i]\n\n{pt-br}[ff00fe]RESISTÊNCIA A FOGO FRIO[-][i] - Os ataques de Fogo, Gelo e Fogo Frio são reduzidos à metade contra esse inimigo. Esse inimigo não pode ser alvo de habilidades de unidade alimentadas por Mana vermelha ou azul, nem de efeitos que não sejam de ataque de cartas vermelhas ou azuis.[/i]\n\n{de}[ff00fe]KALTE FEUERWIDERSTAND[-][i] - Feuer-, Eis- und Kältefeuer-Angriffe werden gegen diesen Feind halbiert. Dieser Feind kann weder von Einheitenfähigkeiten, die durch rotes oder blaues Mana angetrieben werden, noch von Nicht-Angriffseffekten roter oder blauer Karten angegriffen werden.[/i]\n\n"}) end
					--arcane immunity
					if (monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].arcaneImmunity~=nil) or (gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].arcaneImmunity~=nil) then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]ARCANE IMMUNITY[-][i] - This enemy can't be targeted by non-Attack or non-Block effects from any source. Effects that directly affect an enemy's attack(s) still apply.[/i]\n\n{ru}[00ff00]ЗАЩИТА ОТ МАГИИ[-][i] - На врага не влияют никакие эффекты, кроме атак и блоков. Эффекты, действующие напрямую на атаку этого врага, по-прежнему можно использовать.[/i]\n\n{zh-tw}[00ff00]魔法免疫[-][i] - 该敌人无法成为任何来源的非攻击或非阻断效果的目标。直接影响敌人攻击的效果仍然适用。[/i]\n\n{zh-cn}[00ff00]魔法免疫[-][i] - 该敌人无法成为任何来源的非攻击或非阻断效果的目标。直接影响敌人攻击的效果仍然适用。[/i]\n\n{ko}[00ff00]마법 면역[-][i] - 이 적은 공격, 방어를 제외한 그 어떠한 특수 효과를 무시함. 적의 공격에 직접 영향을 주는 효과는 여전히 적용.[/i]\n\n{es}[00ff00]INMUNIDAD ARCANA[-][i] - Este enemigo no puede ser objetivo de efectos que no sean de Ataque o Bloqueo de ninguna fuente. Los efectos que afectan directamente a los ataques de un enemigo se siguen aplicando.[/i]\n\n{fr}[00ff00]IMMUNITÉ DE L'ARCANE[-][i] - Cet ennemi ne peut pas être ciblé par des effets autres qu'une attaque ou un blocage, quelle qu'en soit la source. Les effets qui affectent directement les attaques de l'ennemi s'appliquent toujours.[/i]\n\n{pt-br}[00ff00]IMUNIDADE ARCANA[-][i] - Esse inimigo não pode ser alvo de efeitos que não sejam de ataque ou de bloqueio de nenhuma fonte. Os efeitos que afetam diretamente o(s) ataque(s) de um inimigo ainda se aplicam.[/i]\n\n{de}[00ff00]ARKANE IMMUNITÄT[-][i] - Dieser Feind kann nicht durch Nicht-Angriffs- oder Nicht-Block-Effekte aus irgendeiner Quelle angegriffen werden. Effekte, die sich direkt auf die Attacke(n) des Feindes auswirken, gelten weiterhin.[/i]\n\n"}) end
					--reward
					local factionTranslate=({	["Dark"]="{en}Dark Crusader{ru}Тёмный крестоносец{zh-tw}黑暗遠征軍{zh-cn}黑暗远征军{ko}암흑 십자군{es}Cruzado Oscuro{fr}Croisé des ténèbres{pt-br}Cruzado das Trevas{de}Dunkler Kreuzritter",
												["Elem"]="{en}Elementalist{ru}Элементалист{zh-tw}元素之力{zh-cn}元素之力{ko}원소술사{es}Elementalista{fr}Élémentaliste{pt-br}Elementalista{de}Elementarist",
												["Apoc"]="{en}Apocalypse Cult{ru}Культ Апокалипсиса{zh-tw}末日教團{zh-cn}末日教团{ko}아포칼립스 컬트{es}Culto del Apocalipsis{fr}Culte de l'Apocalypse{pt-br}Culto do Apocalipse{de}Apokalypse-Kult",
												["Coun"]="{en}Council of the Void{ru}Совет Пустоты{zh-tw}虛空議會{zh-cn}虚空议会{ko}공허 의회{es}Consejo del Vacío{fr}Conseil du Vide{pt-br}Conselho do Vazio{de}Rat der Leere"})
					local used=false
					local rewardLabel="{en}[00ff00]FACTION REWARD:[-] {ru}[00ff00]НАГРАДЫ ФРАКЦИИ:[-] {zh-tw}[00ff00]派系奖励：[-] {zh-cn}[00ff00]派系奖励：[-] {ko}[00ff00]세력 보상:[-] {es}[00ff00]RECOMPENSA DE FACCIÓN:[-] {fr}[00ff00]RÉCOMPENSE DE FACTION:[-] {pt-br}[00ff00]RECOMPENSA DE FAÇÃO:[-] {de}[00ff00]FRAKTIONSBELOHNUNG:[-] "
					local printed=monsterPugs[hover_object.guid]
					if printed~=nil and printed.pugType~="yellow" and type(printed.reward)=="number" and printed.reward>0 and factionRewardUsesJustFame(printed.faction)~=true then
						local faction=factionTranslate[printed.faction]
						if faction~=nil then monsterDescription=joinLang({monsterDescription,rewardLabel,faction}) used=true end
					end
					local perks=gStates.monsterPerks[hover_object.guid]
					if perks~=nil and type(perks.reward)=="number" and perks.reward>0 and factionRewardUsesJustFame(perks.faction)~=true then
						local faction=factionTranslate[perks.faction]
						if faction~=nil then
							if used==true then monsterDescription=joinLang({monsterDescription,"\n"}) end
							monsterDescription=joinLang({monsterDescription,rewardLabel,faction})
							used=true
						end
					end
					if used==true then monsterDescription=joinLang({monsterDescription,"\n\n"}) end
					--fame: each faction independently uses +1 Fame when its own reward pile has been removed.
					local rewardPug,rewardPerk=monsterFactionRewardFameFallback(hover_object.guid)
					local reward=rewardPug+rewardPerk
					local bonus=0
					if gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].fame~=nil then bonus=gStates.monsterPerks[hover_object.guid].fame end
					if monsterPugs[hover_object.guid]~=nil and monsterPugs[hover_object.guid].fame~=nil and monsterPugs[hover_object.guid].fame>0 then monsterDescription=joinLang({monsterDescription, "{en}[00ff00]FAME: [-]{ru}[00ff00]СЛАВА: [-]{zh-tw}[00ff00]名望：[-]{zh-cn}[00ff00]名望：[-]{ko}[00ff00]명성: [-]{es}[00ff00]FAMA: [-]{fr}[00ff00]FAME : [-]{pt-br}[00ff00]FAMA: [-]{de}[00ff00]RUHM: [-]", tostring(monsterPugs[hover_object.guid].fame+reward+bonus)}) end
					if gStates.monsterPerks[hover_object.guid]~=nil and gStates.monsterPerks[hover_object.guid].dragonGround==true then
						local headName=apocalypseDragonGroundHeadNameForGUID(hover_object.guid)
						if headName=="Control" then monsterDescription=joinLang({monsterDescription,"{en}\n[00ff00]CONTROL HEAD[-] - This head may never be attacked.{ru}\n[00ff00]ГОЛОВА КОНТРОЛЯ[-] - Эту голову нельзя атаковать.{zh-tw}\n[00ff00]控制龍首[-] - 此龍首永遠不能被攻擊。{zh-cn}\n[00ff00]控制龙首[-] - 此龙首永远不能被攻击。{ko}\n[00ff00]통제 머리[-] - 이 머리는 공격할 수 없습니다.{es}\n[00ff00]CABEZA DE CONTROL[-] - Esta cabeza nunca puede ser atacada.{fr}\n[00ff00]TÊTE DE CONTRÔLE[-] - Cette tête ne peut jamais être attaquée.{pt-br}\n[00ff00]CABEÇA DE CONTROLE[-] - Esta cabeça nunca pode ser atacada.{de}\n[00ff00]KONTROLLKOPF[-] - Dieser Kopf kann niemals angegriffen werden."}) end
					end
				end
			end
			hover_object.setDescription(monsterDescription)
		end
end

-- Fame/Reputation accounting wraps these UI entry points explicitly rather than replacing globals by require order.
function mainUIUpdate(...)
	return fameReputationMainUIUpdate(...)
end

function valueAdjust(player, mouseButton, id)
	return fameReputationValueAdjust(player, mouseButton, id)
end

end)
__bundle_register("PlayingGame.Rollers", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Centralised dice-roller logic for the Roll Crystal Die / Roll Dungeon Die bags.
-- The old object scripts were copies of the same MrStump roller with a few settings changed.

local ROLLER_CONFIG = {
    ["4fcc61"] = {maxCount = 1, layout = "single"},
    ["9758bf"] = {maxCount = 4, layout = "row"},
    ["c4a961"] = {maxCount = 4, layout = "row"},
    ["03de4d"] = {maxCount = 4, layout = "row"},
}

local RADIUS = 2
local ARC = 120
local ROTATION = 180
local HEIGHT = 1.5
local ROLL_DELAY = 1.2
local CLEANUP_DELAY = 15

local RESULT_ROTATION = {
    {270.00, 0.00, 0.00},
    {0.00, 90.00, 0.00},
    {0.00, 270.00, 270.00},
    {0.00, 180.00, 90.00},
    {0.00, 270.00, 180.00},
    {90.00, 180.00, 0.00},
}

local ROW_X = {
    [1] = {0},
    [2] = {-1.1, 1.1},
    [3] = {-2.2, 0, 2.2},
    [4] = {-3.3, -1.1, 1.1, 3.3},
}

local rollerState = {}

local function pointOnArc(roller, index, count)
    local i = index - 0.5
    local angle = ARC / count
    local offset = -ARC / 2 + ROTATION
    local x = math.sin(math.rad(angle * i + offset)) * RADIUS
    local z = math.cos(math.rad(angle * i + offset)) * RADIUS
    return roller.positionToWorld({x = x, y = HEIGHT, z = z})
end

local function randomRotation()
    local u1 = math.random()
    local u2 = math.random()
    local u3 = math.random()
    local u1sqrt = math.sqrt(u1)
    local u1m1sqrt = math.sqrt(1 - u1)
    local qx = u1m1sqrt * math.sin(2 * math.pi * u2)
    local qy = u1m1sqrt * math.cos(2 * math.pi * u2)
    local qz = u1sqrt * math.sin(2 * math.pi * u3)
    local qw = u1sqrt * math.cos(2 * math.pi * u3)
    local ysqr = qy * qy
    local t0 = -2.0 * (ysqr + qz * qz) + 1.0
    local t1 = 2.0 * (qx * qy - qw * qz)
    local t2 = -2.0 * (qx * qz + qw * qy)
    local t3 = 2.0 * (qy * qz - qw * qx)
    local t4 = -2.0 * (qx * qx + ysqr) + 1.0
    if t2 > 1.0 then t2 = 1.0 end
    if t2 < -1.0 then t2 = -1.0 end
    return {math.deg(math.asin(t2)), math.deg(math.atan2(t3, t4)), math.deg(math.atan2(t1, t0))}
end

local function alphanumSort(values)
    local function padnum(d) return ("%03d%s"):format(#d, d) end
    table.sort(values, function(a, b)
        return tostring(a):gsub("%d+", padnum) < tostring(b):gsub("%d+", padnum)
    end)
end

local function cleanupRoller(state)
    for _, die in ipairs(state.dice) do
        if die ~= nil then destroyObject(die) end
    end
    state.dice = {}
    state.phase = nil
    state.rollToken = state.rollToken + 1
    state.cleanupToken = state.cleanupToken + 1
end

local function displayResults(state, color)
    local values = {}
    for _, die in ipairs(state.dice) do
        if die ~= nil then table.insert(values, tostring(die.getRotationValue())) end
    end
    alphanumSort(values)
    local text = Player[color].steam_name .. "    " .. string.char(9679) .. "    " .. table.concat(values, ", ")
    broadcastToAll(text, stringColorToRGB(color))
end

local function layoutResults(state)
    local roller = state.roller
    local count = #state.dice
    for index, die in ipairs(state.dice) do
        local result = die.getValue()
        die.setLock(true)
        die.setScale(Vector(3, 3, 3))
        local zOffset = math.floor((roller.getBounds().size.z / 2) + (die.getBounds().size.z / 2) + 0.5)
        local xOffset = state.config.layout == "single" and 0 or ROW_X[count][index]
        die.setPositionSmooth(roller.getPosition() + Vector(xOffset, 2, zOffset))
        die.setRotationSmooth(RESULT_ROTATION[result])
    end
end

local function finalizeRoll(state, color)
    displayResults(state, color)
    layoutResults(state)
    state.phase = "done"
    state.cleanupToken = state.cleanupToken + 1
    local cleanupToken = state.cleanupToken
    local guid = state.guid
    safeWaitTime("Rollers",function()
        local current = rollerState[guid]
        if current ~= nil and current.cleanupToken == cleanupToken and current.phase == "done" then cleanupRoller(current) end
    end, CLEANUP_DELAY)
end

local function waitForDiceToRest(guid, rollToken, color)
    local state = rollerState[guid]
    if state == nil or state.rollToken ~= rollToken or state.phase ~= "rolling" then return end
    for _, die in ipairs(state.dice) do
        if die ~= nil and not die.resting then
            safeWaitFrames("Rollers",function() waitForDiceToRest(guid, rollToken, color) end, 1)
            return
        end
    end
    -- One physical roll only. The old object scripts rolled every die a second time here.
    finalizeRoll(state, color)
end

local function beginRoll(guid, rollToken, color)
    local state = rollerState[guid]
    if state == nil or state.rollToken ~= rollToken or state.phase ~= "waiting" then return end
    state.phase = "rolling"
    for _, die in ipairs(state.dice) do
        die.setLock(false)
        die.randomize()
    end
    safeWaitFrames("Rollers",function() waitForDiceToRest(guid, rollToken, color) end, 1)
end

local function queueRoll(state, color)
    state.rollToken = state.rollToken + 1
    local rollToken = state.rollToken
    local guid = state.guid
    safeWaitTime("Rollers",function() beginRoll(guid, rollToken, color) end, ROLL_DELAY)
end

function MKRollDieButton(roller, color)
    local state = rollerState[roller.getGUID()]
    if state == nil then return end
    if state.phase == "done" then
        cleanupRoller(state)
    elseif state.phase == "rolling" then
        Player[color].broadcast("{en}Roll in progress.{ru}Бросок выполняется.{zh-tw}正在擲骰。{zh-cn}正在掷骰。{ko}주사위를 굴리는 중입니다.{es}Tirada en curso.{fr}Lancer en cours.{pt-br}Rolagem em andamento.{de}Wurf läuft.", {0.8, 0.2, 0.2})
        return
    end
    if #state.dice >= state.config.maxCount then
        Player[color].broadcast("{en}Roll in progress.{ru}Бросок выполняется.{zh-tw}正在擲骰。{zh-cn}正在掷骰。{ko}주사위를 굴리는 중입니다.{es}Tirada en curso.{fr}Lancer en cours.{pt-br}Rolagem em andamento.{de}Wurf läuft.", {0.8, 0.2, 0.2})
        return
    end
    local newCount = #state.dice + 1
    for index, die in ipairs(state.dice) do die.setPositionSmooth(pointOnArc(roller, index, newCount)) end
    local die = roller.takeObject({position = pointOnArc(roller, newCount, newCount), rotation = randomRotation()})
    die.setScale({1, 1, 1})
    die.setLock(true)
    die.script_state = " "
    table.insert(state.dice, die)
    state.phase = "waiting"
    queueRoll(state, color)
end

local function installRoller(guid)
    local roller = getObjectFromGUID(guid)
    if roller == nil then return false end
    rollerState[guid] = {guid = guid, roller = roller, config = ROLLER_CONFIG[guid], dice = {}, phase = nil, rollToken = 0, cleanupToken = 0}
    roller.clearButtons()
    roller.createButton({click_function = "MKRollDieButton", function_owner = Global, position = {0, 0.05, 0}, height = 650, width = 650, color = {1, 1, 1, 0}})
    return true
end

local function installRollers(attempt)
    local missing = false
    for guid in pairs(ROLLER_CONFIG) do
        if rollerState[guid] == nil and not installRoller(guid) then missing = true end
    end
    if missing and attempt < 60 then safeWaitFrames("Rollers",function() installRollers(attempt + 1) end, 1) end
end

local function destroySavedRollerDice(savedState)
    if type(savedState) ~= "table" then return end
    for _, dice in pairs(savedState) do
        if type(dice) == "table" then
            for _, dieGUID in ipairs(dice) do
                local die = getObjectFromGUID(dieGUID)
                if die ~= nil then destroyObject(die) end
            end
        end
    end
end

function rollerOnSave()
    local savedState = {}
    for guid, state in pairs(rollerState) do
        local dice = {}
        for _, die in ipairs(state.dice or {}) do
            if die ~= nil then dice[#dice + 1] = die.getGUID() end
        end
        savedState[guid] = dice
    end
    return savedState
end

function rollerOnLoad(savedState)
    destroySavedRollerDice(savedState)
    rollerState = {}
    installRollers(1)
end

function rollerSavedState(saved_data)
	if type(saved_data)~="string" or saved_data=="" then return nil end
	local ok,data=pcall(JSON.decode,saved_data)
	if ok and type(data)=="table" then return data.rollerDice end
	return nil
end

end)
__bundle_register("PlayingGame.Movement", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Player movement guidance and digital movement-cost display.

--Fractured Lands: show the folding-corridor marker on every other explored hex matching
--the active Mage Knight's current terrain type. These are guidance only; movement stays manual.
fracturedLandsTeleportDecalName="Fractured Lands Teleport"
fracturedLandsTeleportDecalURL="https://steamusercontent-a.akamaihd.net/ugc/9408415852573608798/AAD04981F964B49DD1479EFE6DFBD6D294294B82/"
function fracturedLandsTeleportHexLegal(hexType)
	if hexType==nil or hexType=="" or hexType=="ocean" then return false end
	if gStates.moveCost~=nil and gStates.moveCost[hexType]~=nil then return gStates.moveCost[hexType]<900 end
	return hexType~="lake" and hexType~="mountain"
end
function fracturedLandsTeleportRampageKey(terrainGUID, bearing)
	return tostring(terrainGUID).."|"..tostring(bearing)
end
function fracturedLandsTeleportRecordDefeatedRampager(position)
	if gStates.gameScenario~="The Fractured Lands Blitz" or position==nil then return end
	local hex=runtimeMapHexAtPosition(position)
	if hex==nil or (hex.feature~="rampaging" and hex.feature~="draconum") then return end
	if gStates.fracturedLandsDefeatedRampagingHexes==nil then gStates.fracturedLandsDefeatedRampagingHexes={} end
	gStates.fracturedLandsDefeatedRampagingHexes[fracturedLandsTeleportRampageKey(hex.terrainGUID,hex.bearing)]=true
end
function fracturedLandsTeleportHexSafeNoSite(hex,spatial)
	if hex==nil or hex.position==nil or spatial==nil then return false end
	local feature=hex.feature or ""
	local noSite=feature=="" or feature=="portal"
	if feature=="monastery" and gStates.monasteryBurned~=nil and gStates.monasteryBurned[hex.terrainGUID]==true then noSite=true end
	if feature=="rampaging" or feature=="draconum" then
		local cleared=gStates.fracturedLandsDefeatedRampagingHexes or {}
		noSite=cleared[fracturedLandsTeleportRampageKey(hex.terrainGUID,hex.bearing)]==true
	end
	if noSite~=true then return false end
	--A safe destination cannot currently contain an enemy or another Mage Knight.
	for _, obj in ipairs(runtimeMapSpatialNearbyObjects(spatial,hex.position,1.1)) do
		local pos=spatial.positions[obj.guid] or obj.getPosition()
		if ((pos[1]-hex.position[1])^2)+((pos[3]-hex.position[3])^2)<1 then
			if monsterPugs[obj.guid]~=nil then return false end
			if feature~="portal" then
				for _, details in pairs(mageKnights) do
					if obj.guid==details.model or obj.guid==details.token or obj.guid==details.standee then return false end
				end
			end
		end
	end
	return true
end
function fracturedLandsTeleportSourcePosition(playerIndex)
	local player=turnOrder[playerIndex]
	if player==nil or player.mage==gStates.positionMageKnight[5] or coopAssaultVirtualPlayer(playerIndex)==true then return nil end
	local avatar=coopAssaultAvatarObject(playerIndex)
	if avatar==nil then return nil end
	local position=avatar.getPosition()
	--Avatars physically sit on City cards after entering a City, so translate that back to the map hex.
	for zone, citySearch in pairs(cityScriptZones) do
		local zoneObj=getObjectFromGUID(zone)
		if zoneObj~=nil then
			for _, obj in pairs(zoneObj.getObjects()) do
				if obj.guid==avatar.guid then
					local cityObj=nil
					if zone==volkare.discZone and gStates.volkareModel~=nil then cityObj=getObjectFromGUID(gStates.volkareModel) else cityObj=getObjectFromGUID(citySearch.cityGUID) end
					if cityObj~=nil then position=cityObj.getPosition() end
					return position
				end
			end
		end
	end
	return position
end
function fracturedLandsTeleportDecals()
	local decals={}
	if gStates.gameScenario~="The Fractured Lands Blitz" or gStates.firstStarted~=true or turnOrder[gStates.turnNumber]==nil then return decals end
	local sourcePos=fracturedLandsTeleportSourcePosition(gStates.turnNumber)
	if sourcePos==nil then return decals end
	local spatial=runtimeMapSpatialSnapshot()
	local snapshot=spatial.topology
	local sourceHex=runtimeMapHexAtPosition(sourcePos,snapshot)
	if sourceHex==nil or fracturedLandsTeleportHexLegal(sourceHex.hexType)~=true then return decals end
	local sourceKey=runtimeMapHexKey(sourceHex)
	for _, hex in ipairs(snapshot.hexes or {}) do
		if hex.hexType==sourceHex.hexType and fracturedLandsTeleportHexLegal(hex.hexType)==true and runtimeMapHexKey(hex)~=sourceKey then
			if fracturedLandsTeleportHexSafeNoSite(hex,spatial)==true then
				decals[#decals+1]={name=fracturedLandsTeleportDecalName, url=fracturedLandsTeleportDecalURL,
					position={hex.position[1],1.12,hex.position[3]}, rotation={90,0,0}, scale={2.0,2.0,1}}
			end
		end
	end
	return decals
end
function refreshFracturedLandsTeleportHighlights()
	--Fresh-start games never switch scenarios mid-game, so non-Fractured-Lands games do not need to touch Global decals every turn.
	if gStates.gameScenario~="The Fractured Lands Blitz" then return end
	local existing=Global.getDecals() or {}
	local decals={}
	for _, decal in pairs(existing) do if decal.name~=fracturedLandsTeleportDecalName then decals[#decals+1]=decal end end
	for _, decal in pairs(fracturedLandsTeleportDecals()) do decals[#decals+1]=decal end
	Global.setDecals(decals)
end

moveDisplayAutoPause=nil
moveDisplayBaseVectorLines=nil
moveDisplayRefreshDelay=0.75
moveDisplayTerrainCache={signature=nil, hexMap=nil}
moveDisplayTextSlotRequests={}
moveDisplayTextSpawning={}
MOVE_DISPLAY_HEX_BEARINGS={"center", "0", "60", "120", "180", "240", "300"}
MOVE_DISPLAY_BEARING_ADJUST={center={0,0}, ["0"]={0,-1}, ["60"]={-1,-1}, ["120"]={-1,0}, ["180"]={0,1}, ["240"]={1,1}, ["300"]={1,0}}
MOVE_DISPLAY_WALL_ADJUST={
	["0"]={ ["300"]={0.5,-0.5}, ["center"]={0,-0.5}, ["60"]={-0.5,-0.5}},
	["60"]={ ["0"]={-0.5,-1}, ["center"]={-0.5,-0.5}, ["120"]={-1,-0.5}},
	["120"]={ ["60"]={-1,-0.5}, ["center"]={-0.5,0}, ["180"]={-0.5,0.5}},
	["180"]={ ["120"]={-0.5,0.5}, ["center"]={0,0.5}, ["240"]={0.5,1}},
	["240"]={ ["180"]={0.5,1}, ["center"]={0.5,0.5}, ["300"]={1,0.5}},
	["300"]={ ["240"]={1,0.5}, ["center"]={0.5,0}, ["0"]={0.5,-0.5}},
	["center"]={ ["0"]={0,-0.5}, ["60"]={-0.5,-0.5}, ["120"]={-0.5,0}, ["180"]={0,0.5}, ["240"]={0.5,0.5}, ["300"]={0.5,0}}
}
MOVE_DISPLAY_VECTORS={{0,-1}, {-1,-1}, {-1,0}, {0,1}, {1,1}, {1,0}}
MOVE_DISPLAY_RAMPAGE_ADJACENT={{1,0}, {0,-1}, {-1,-1}, {-1,0}, {0,1}, {1,1}, {1,0}, {0,-1}}
MOVE_DISPLAY_RAMPAGE_WALL={{0.5,-0.5}, {-0.5,-1}, {-1,-0.5}, {-0.5,0.5}, {0.5,1}, {1,0.5}, {0.5,-0.5}}
MOVE_DISPLAY_CITY_GUIDS=nil
function moveDisplayCityGUIDLookup()
	if MOVE_DISPLAY_CITY_GUIDS==nil then
		MOVE_DISPLAY_CITY_GUIDS={
			[cityModel.white]=true, [cityModel.blue]=true, [cityModel.red]=true, [cityModel.green]=true,
			[volkare.terrainHex]=true, [darkCrusader.terrainHex]=true, [elementalist.terrainHex]=true
		}
	end
	return MOVE_DISPLAY_CITY_GUIDS
end

function moveDisplayCloneHexMap(source)
	local copy={}
	for hor, row in pairs(source or {}) do
		local rowCopy={}
		copy[hor]=rowCopy
		for vec, hex in pairs(row) do
			local hexCopy={}
			rowCopy[vec]=hexCopy
			for key, value in pairs(hex) do hexCopy[key]=value end
		end
	end
	return copy
end

--Dungeon Lords turns every conquered Dungeon/Tomb into an underground network node. The tunnel
--distance ignores terrain costs and walls but can only cross revealed spaces, and may not cross Lakes/Swamps.
--Store the measured path as well as its 2+distance cost so the display can show how the price was found.
function moveDisplayDungeonLordsTunnelNetwork(hexMap,playAreaObjects,startTilePos)
	if gStates.gameScenario~="Dungeon Lords" then return {} end
	local nodes={}
	local nodeList={}
	local function gridForPosition(pos)
		local vec,hor=runtimeMapWorldToAxial(pos,startTilePos)
		return hor,vec
	end
	for _,obj in pairs(playAreaObjects or {}) do
		if obj.getName()=="Shield" and volkarePursuitShieldRegistered(obj)~=true then
			local hor,vec=gridForPosition(obj.getPosition())
			local row=hexMap[tostring(hor)]
			local hex=row~=nil and row[tostring(vec)] or nil
			if hex~=nil and (hex.feature=="dungeon" or hex.feature=="tomb") then
				local key=tostring(hor)..":"..tostring(vec)
				if nodes[key]==nil then
					nodes[key]={hor=hor,vec=vec,key=key}
					nodeList[#nodeList+1]=nodes[key]
				end
			end
		end
	end
	if #nodeList<2 then return {} end

	local function openForDistance(hor,vec)
		local row=hexMap[tostring(hor)]
		local hex=row~=nil and row[tostring(vec)] or nil
		if hex==nil or hex.tileGUID==nil then return false end
		local terrain=hex.terrainType or hex.hexType
		return terrain~=nil and terrain~="lake" and terrain~="swamp" and terrain~="ocean"
	end
	local network={}
	for _,source in ipairs(nodeList) do
		local visited={[source.key]={hor=source.hor,vec=source.vec,distance=0,prev=nil}}
		local queue={{hor=source.hor,vec=source.vec,key=source.key}}
		local head=1
		while head<=#queue do
			local current=queue[head]
			head=head+1
			local currentVisit=visited[current.key]
			for _,vector in ipairs(MOVE_DISPLAY_VECTORS) do
				local hor=current.hor+vector[1]
				local vec=current.vec+vector[2]
				local key=tostring(hor)..":"..tostring(vec)
				if visited[key]==nil and openForDistance(hor,vec)==true then
					visited[key]={hor=hor,vec=vec,distance=currentVisit.distance+1,prev=current.key}
					queue[#queue+1]={hor=hor,vec=vec,key=key}
				end
			end
		end
		for _,destination in ipairs(nodeList) do
			if destination.key~=source.key and visited[destination.key]~=nil then
				local path={}
				local cursor=destination.key
				while cursor~=nil do
					local step=visited[cursor]
					table.insert(path,1,{hor=step.hor,vec=step.vec})
					cursor=step.prev
				end
				if network[source.key]==nil then network[source.key]={} end
				network[source.key][#network[source.key]+1]={hor=destination.hor,vec=destination.vec,cost=2+visited[destination.key].distance,path=path}
			end
		end
	end
	return network
end

--Cache only the terrain/wall portion of the digital movement map. Dynamic shields, Cities and
--monsters are overlaid fresh each render. Position, rotation and printed hex data are part of the
--signature so a changed tile/site automatically rebuilds the base graph.
function moveDisplayBaseHexMap(playAreaObjects, startTileGUID, startTilePos)
	local snapshot=runtimeMapSnapshot()
	local terrainEntries=snapshot.terrainEntries or {}
	local signature=startTileGUID.."@"..string.format("%.3f,%.3f", startTilePos[1], startTilePos[3]).."|"..(snapshot.terrainSignature or "")
	if moveDisplayTerrainCache.signature==signature and moveDisplayTerrainCache.hexMap~=nil then return moveDisplayCloneHexMap(moveDisplayTerrainCache.hexMap) end

	local hexMap={}
	for _, entry in pairs(terrainEntries) do
		local details=entry.details
		local hexGridAxial,hexGridHorizontal=runtimeMapWorldToAxial(entry.position,startTilePos)
		for hexBearing, hexType in pairs(details.hexType) do
			local fixedBearing="center"
			if hexBearing~="center" then
				local adjusted=tonumber(hexBearing)-entry.rotationAdjust
				if adjusted<0 then adjusted=adjusted+360 end
				fixedBearing=tostring(adjusted)
			end
			local adjust=MOVE_DISPLAY_BEARING_ADJUST[fixedBearing]
			local mapHor=tostring(hexGridHorizontal+adjust[1])
			local mapVec=tostring(hexGridAxial+adjust[2])
			if hexMap[mapHor]==nil then hexMap[mapHor]={} end
			if hexMap[mapHor][mapVec]==nil then hexMap[mapHor][mapVec]={} end
			local mapHex=hexMap[mapHor][mapVec]
			mapHex.terrainType=hexType
			mapHex.feature=details.hexFeature[hexBearing]
			mapHex.tileGUID=entry.guid
			mapHex.bearing=hexBearing
			if mapHex.hexType==nil then mapHex.hexType=hexType end
			if (mapHex.feature=="keep" or mapHex.feature=="mage tower") and mapHex.fortified==nil then mapHex.fortified=mapHex.feature end
		end
		if details.wallList~=nil then
			for hexBearing, hexAdjacent in pairs(details.wallList) do
				for hexAdjacentBearing, _ in pairs(hexAdjacent) do
					local fixedBearing="center"
					if hexBearing~="center" then
						local adjusted=tonumber(hexBearing)-entry.rotationAdjust
						if adjusted<0 then adjusted=adjusted+360 end
						fixedBearing=tostring(adjusted)
					end
					local fixedAdjacentBearing="center"
					if hexAdjacentBearing~="center" then
						local adjusted=tonumber(hexAdjacentBearing)-entry.rotationAdjust
						if adjusted<0 then adjusted=adjusted+360 end
						fixedAdjacentBearing=tostring(adjusted)
					end
					local adjust=MOVE_DISPLAY_WALL_ADJUST[fixedBearing][fixedAdjacentBearing]
					local wallHor=tostring(hexGridHorizontal+adjust[1])
					local wallVec=tostring(hexGridAxial+adjust[2])
					if hexMap[wallHor]==nil then hexMap[wallHor]={} end
					hexMap[wallHor][wallVec]={hexType="wall"}
				end
			end
		end
	end
	moveDisplayTerrainCache={signature=signature, hexMap=hexMap}
	return moveDisplayCloneHexMap(hexMap)
end

function moveDisplayParkTextMarker(marker)
	if marker~=nil then marker.setPosition({0, -10, 0}) end
end

function moveDisplayApplyTextMarker(marker, request, slot, delayPosition)
	if marker==nil or request==nil then return end
	if marker.TextTool~=nil then
		marker.TextTool.setValue(request.value)
		marker.TextTool.setFontSize(request.fontSize)
		marker.TextTool.setFontColor(request.color)
	end
	if delayPosition==true then
		local markerGUID=marker.guid
		safeWaitFrames("Movement",function()
			local liveMarker=getObjectFromGUID(markerGUID)
			local latest=moveDisplayTextSlotRequests[slot]
			if liveMarker==nil then return end
			if latest~=nil and latest.generation==gStates.moveDisplayGeneration and slot<=(gStates.moveDisplayTextActiveCount or 0) then liveMarker.setPosition(latest.position)
			else moveDisplayParkTextMarker(liveMarker) end
		end, 2)
	else
		marker.setPosition(request.position)
	end
end

function moveDisplayRequestTextMarker(slot, request)
	moveDisplayTextSlotRequests[slot]=request
	gStates.moveDisplayTextGUIDs=gStates.moveDisplayTextGUIDs or {}
	local markerGUID=gStates.moveDisplayTextGUIDs[slot]
	local marker=markerGUID~=nil and getObjectFromGUID(markerGUID) or nil
	if marker~=nil then moveDisplayApplyTextMarker(marker, request, slot, false) return end
	if moveDisplayTextSpawning[slot]==true then return end
	moveDisplayTextSpawning[slot]=true
	safeSpawnObject("Movement",{type="3DText", position={request.position[1], -10, request.position[3]}, rotation={90,0,0}, scale={0.70,0.70,0.70}, sound=false, callback_function=function(newMarker)
		moveDisplayTextSpawning[slot]=nil
		gStates.moveDisplayTextGUIDs=gStates.moveDisplayTextGUIDs or {}
		gStates.moveDisplayTextGUIDs[slot]=newMarker.guid
		newMarker.setName("Move Cost Indicator")
		newMarker.setGMNotes("Move Cost Indicator")
		newMarker.interactable=false
		newMarker.setLock(true)
		local latest=moveDisplayTextSlotRequests[slot]
		if latest~=nil and latest.generation==gStates.moveDisplayGeneration and slot<=(gStates.moveDisplayTextActiveCount or 0) then moveDisplayApplyTextMarker(newMarker, latest, slot, true)
		else moveDisplayParkTextMarker(newMarker) end
	end})
end

function moveDisplayHideUnusedText(usedCount)
	usedCount=usedCount or 0
	gStates.moveDisplayTextActiveCount=usedCount
	gStates.moveDisplayTextGUIDs=gStates.moveDisplayTextGUIDs or {}
	for slot=usedCount+1, #gStates.moveDisplayTextGUIDs do
		moveDisplayTextSlotRequests[slot]=nil
		local marker=getObjectFromGUID(gStates.moveDisplayTextGUIDs[slot])
		if marker~=nil then moveDisplayParkTextMarker(marker) end
	end
end

function updateMoveDisplay(id)
	--With zero Move and no active markers there is nothing for the movement display to do.
	local moveValue=gStates.resourceTracker~=nil and gStates.resourceTracker.move~=nil and gStates.resourceTracker.move.move or 0
	local hasMoveMarkers=(gStates.moveDisplayTextActiveCount or 0)>0
	if moveValue<=0 and hasMoveMarkers==false then
		if moveDisplayAutoPause~=nil then Wait.stop(moveDisplayAutoPause) moveDisplayAutoPause=nil end
		if moveDisplayBaseVectorLines~=nil then Global.setVectorLines(moveDisplayBaseVectorLines) moveDisplayBaseVectorLines=nil end
		return
	end

	--Resource Tracker clicks redraw immediately. Background object/map refreshes retain their quiet period
	--so newly explored terrain still has time to settle before its map snapshot is taken.
	if id~=nil then
		if moveDisplayAutoPause~=nil then Wait.stop(moveDisplayAutoPause) moveDisplayAutoPause=nil end
		renderMoveDisplay(id)
		return
	end
	if moveDisplayAutoPause~=nil then Wait.stop(moveDisplayAutoPause) end
	moveDisplayAutoPause=safeWaitTime("Movement",function() moveDisplayAutoPause=nil renderMoveDisplay() end, moveDisplayRefreshDelay)
end

function renderMoveDisplay(id)
	--Preserve Global vector lines that existed before the movement display started.
	local moveValue=gStates.resourceTracker~=nil and gStates.resourceTracker.move~=nil and gStates.resourceTracker.move.move or 0
	if moveValue>0 and moveDisplayBaseVectorLines==nil then moveDisplayBaseVectorLines=Global.getVectorLines() or {} end

	gStates.moveDisplayGeneration=(gStates.moveDisplayGeneration or 0)+1
	local displayGeneration=gStates.moveDisplayGeneration
	moveDisplayTextSlotRequests={}
	gStates.moveDisplayTextGUIDs=gStates.moveDisplayTextGUIDs or {}
	gStates.moveDisplayTextActiveCount=0

	if moveValue<=0 then
		moveDisplayHideUnusedText(0)
		if moveDisplayBaseVectorLines~=nil then Global.setVectorLines(moveDisplayBaseVectorLines) moveDisplayBaseVectorLines=nil end
		return
	end

	--Reuse movement text objects by slot. Only a larger display grows the pool; normal +/- clicks update
	--the existing TextTools in place instead of destroying and respawning every label.
	local moveTextZOffset=0.65
	local moveTextUsed=0
	local function addMoveCostText(value, x, z, affordable, combat, multipleCosts, dualCosts)
		local function addPart(partValue, partX, partAffordable, partCombat, fontSize, partY)
			moveTextUsed=moveTextUsed+1
			gStates.moveDisplayTextActiveCount=moveTextUsed
			local color={r=0.95,g=0.20,b=0.20}
			if partAffordable==true and partCombat==true then color={r=1.00,g=0.50,b=0.00}
			elseif partAffordable==true then color={r=1,g=1,b=1} end
			moveDisplayRequestTextMarker(moveTextUsed, {generation=displayGeneration,value=tostring(partValue),fontSize=fontSize,color=color,position={partX,partY or 1.35,z+moveTextZOffset}})
		end
		if multipleCosts==true and dualCosts~=nil then
			--3DText has one colour per object, so split a dual cost into three pooled markers.
			--Keep the smaller slash underneath the two numbers so it cannot visually cut through them.
			local lowText=tostring(dualCosts.low)
			local highText=tostring(dualCosts.high)
			local charWidth=0.29
			local centerGap=0.68
			local lowX=x-(centerGap/2)-((#lowText*charWidth)/2)
			local highX=x+(centerGap/2)+((#highText*charWidth)/2)
			addPart("/",x,dualCosts.low<=moveValue,false,58,1.33)
			addPart(lowText,lowX,dualCosts.low<=moveValue,dualCosts.lowCombat==true,80,1.37)
			addPart(highText,highX,dualCosts.high<=moveValue,dualCosts.highCombat==true,80,1.37)
		else
			addPart(value,x,affordable,combat,multipleCosts==true and 80 or 120)
		end
	end

	--Snapshot the map once. The static terrain/wall graph is cached; dynamic objects are overlaid below.
	--Against the Horsemen deliberately removes the normal start tile, so use Country01 as the grid origin.
	local startTileGUID=gStates.gameScenario=="Against the Horsemen Blitz" and GUID.tile.country01 or startTerrain.open
	local startTile=getObjectFromGUID(startTileGUID)
	if startTile==nil and gStates.gameScenario~="Against the Horsemen Blitz" then startTileGUID=startTerrain.wedge startTile=getObjectFromGUID(startTileGUID) end
	local mapObject=getObjectFromGUID(mapArea)
	if startTile==nil or mapObject==nil then moveDisplayHideUnusedText(0) return end
	local startTilePos=startTile.getPosition()
	local snapshot=runtimeMapSnapshot()
	local playAreaObjects=snapshot.objects or {}
	local hexMap=moveDisplayBaseHexMap(playAreaObjects, startTileGUID, startTilePos)
	--The Dragon's three lair spaces keep their printed terrain Move cost, but entering any of them
	--starts the Dragon assault. Mark them as combat-only destinations so the movement helper shows
	--the cost in orange and never routes onward through the Lair as though it were a safe space.
	if gStates.gameScenario=="Against the Dragon Blitz" and gStates.apocalypseDragonLairRevealed==true and gStates.apocalypseDragonDefeated~=true and gStates.apocalypseDragonLair~=nil then
		for _,lairHex in ipairs(gStates.apocalypseDragonLair.hexes or {}) do
			local p=lairHex.position
			if p~=nil then
				local lairVecNumber,lairHorNumber=runtimeMapWorldToAxial(p,startTilePos)
				local lairHor=tostring(lairHorNumber)
				local lairVec=tostring(lairVecNumber)
				if hexMap[lairHor]~=nil and hexMap[lairHor][lairVec]~=nil then hexMap[lairHor][lairVec].dragonLair=true end
			end
		end
	end
	local rampagerHexes={}
	local cityGUIDs=moveDisplayCityGUIDLookup()
	for _, mightBeMap in pairs(playAreaObjects) do
		local guid=mightBeMap.guid
		local cityObject=cityGUIDs[guid]==true
		local monsterDetails=monsterPugs[guid]
		local rampager=monsterDetails~=nil and (monsterDetails.pugType=="green" or monsterDetails.pugType=="red")
		local shield=false
		if cityObject==false and rampager==false and mightBeMap.getName()=="Shield" and volkarePursuitShieldRegistered(mightBeMap)~=true then
			shield=(gStates.coop==1 or mightBeMap.getDescription()==turnOrder[gStates.turnNumber].mage)
		end
		if cityObject==true or shield==true or rampager==true then
			local objectPosition=mightBeMap.getPosition()
			local hexGridAxial,hexGridHorizontal=runtimeMapWorldToAxial(objectPosition,startTilePos)
			local hor=tostring(hexGridHorizontal)
			local vec=tostring(hexGridAxial)
			if hexMap[hor]==nil then hexMap[hor]={} end
			if shield==true then
				if hexMap[hor][vec]==nil then hexMap[hor][vec]={} end
				hexMap[hor][vec].fortified="shield"
			end
			if cityObject==true then
				if hexMap[hor][vec]==nil then hexMap[hor][vec]={} end
				local cityHex=hexMap[hor][vec]
				if cityHex.terrainType==nil and cityHex.hexType~=nil and cityHex.hexType~="city" then cityHex.terrainType=cityHex.hexType end
				cityHex.hexType="city"
				cityHex.fortified="city"
				local cityBeaten=gStates.friendlyCity[guid]==true
				local cityMonsters=gStates.cityMonsterQty[guid]
				if cityBeaten==false and cityMonsters~=nil then
					cityBeaten=true
					for monsterGUID, state in pairs(cityMonsters) do if monsterGUID~="extra" and state=="alive" then cityBeaten=false break end end
					local cityOrder=gStates.cityDeployOrder[guid]
					if cityOrder~=nil and gStates.cityLevels[cityOrder]==0 then cityBeaten=false end
				end
				if cityBeaten==true then cityHex.fortified="shield" end
			end
			if rampager==true and objectPosition[2]<1.09 then
				if hexMap[hor][vec]==nil then hexMap[hor][vec]={} end
				local rampagerHex=hexMap[hor][vec]
				if rampagerHex.terrainType==nil and rampagerHex.hexType~=nil and rampagerHex.hexType~="rampager" then rampagerHex.terrainType=rampagerHex.hexType end
				rampagerHex.hexType="rampager"
				rampagerHex.rampager=true
				rampagerHexes[#rampagerHexes+1]={hor=hexGridHorizontal, vec=hexGridAxial, ambushing=gStates.ambushingMonsters[guid]~=nil}
			end
		end
	end

		local dungeonLordsTunnelNetwork=moveDisplayDungeonLordsTunnelNetwork(hexMap,playAreaObjects,startTilePos)

		--Fractured Lands: index every revealed safe no-site destination by its printed terrain.
		--Teleporting costs 1 Move, ignores intervening spaces/walls/rampagers, and can be mixed with normal movement repeatedly.
		local fracturedLandsTeleport=gStates.gameScenario=="The Fractured Lands Blitz"
		local teleportHexesByTerrain={}
		if fracturedLandsTeleport==true then
			local occupiedByOtherMage={}
			for playerIndex, playerDetails in pairs(turnOrder) do
				if playerIndex~=gStates.turnNumber and playerDetails.mage~="Volkare" then
					local otherPos=fracturedLandsTeleportSourcePosition(playerIndex)
					if otherPos~=nil then
						local otherVec,otherHor=runtimeMapWorldToAxial(otherPos,startTilePos)
						occupiedByOtherMage[tostring(otherHor)..":"..tostring(otherVec)]=true
					end
				end
			end
			--Match the teleport-logo safety test: any enemy token physically occupying a hex blocks teleporting there.
			--Do not rely on the rampager map flag here, because that flag has extra movement-specific filtering.
			local occupiedByMonster={}
			for _, mapObject in pairs(playAreaObjects) do
				if monsterPugs[mapObject.guid]~=nil then
					local monsterPos=mapObject.getPosition()
					local monsterVec,monsterHor=runtimeMapWorldToAxial(monsterPos,startTilePos)
					occupiedByMonster[tostring(monsterHor)..":"..tostring(monsterVec)]=true
				end
			end
			for hor, rowOfHexes in pairs(hexMap) do
				for vec, hex in pairs(rowOfHexes) do
					local terrain=hex.terrainType
					local feature=hex.feature or ""
					local clearedRampager=false
					if (feature=="rampaging" or feature=="draconum") and hex.tileGUID~=nil and hex.bearing~=nil then
						local cleared=gStates.fracturedLandsDefeatedRampagingHexes or {}
						clearedRampager=cleared[fracturedLandsTeleportRampageKey(hex.tileGUID,hex.bearing)]==true
					end
					local noSite=feature=="" or feature=="portal" or clearedRampager or
						(feature=="monastery" and gStates.monasteryBurned[hex.tileGUID]==true)
					local terrainAccessible=terrain~=nil and gStates.moveCost[terrain]~=nil and gStates.moveCost[terrain]<900
					local occupancyKey=tostring(hor)..":"..tostring(vec)
					local occupied=(feature~="portal" and occupiedByOtherMage[occupancyKey]==true) or occupiedByMonster[occupancyKey]==true
					if noSite==true and terrainAccessible==true and occupied==false and hex.rampager~=true then
						if teleportHexesByTerrain[terrain]==nil then teleportHexesByTerrain[terrain]={} end
						teleportHexesByTerrain[terrain][#teleportHexesByTerrain[terrain]+1]={coord={tonumber(hor), tonumber(vec)}}
					end
				end
			end
		end

		--Pre-calculate each Ambushing Rampager's own two-hex threat area. Keeping the maps separate is important: both spaces of a move must be threatened by the same Rampager.
		local rampagerVectors=MOVE_DISPLAY_VECTORS
		local ambusherRangeMaps={}
		local function wallBetween(hor1, vec1, hor2, vec2)
			local wallHor=tostring((hor1+hor2)/2)
			local wallVec=tostring((vec1+vec2)/2)
			return hexMap[wallHor]~=nil and hexMap[wallHor][wallVec]~=nil
		end
		local function rangeHexOpen(hor, vec)
			local row=hexMap[tostring(hor)]
			local hex=row and row[tostring(vec)] or nil
			return hex~=nil and hex.hexType~="mountain" and hex.hexType~="lake"
		end
		local function addRangeHex(rangeMap, hor, vec)
			hor=tostring(hor) vec=tostring(vec)
			if rangeMap[hor]==nil then rangeMap[hor]={} end
			rangeMap[hor][vec]=true
		end
		for _, rampager in pairs(rampagerHexes) do
			if rampager.ambushing==true then
				local rangeMap={}
				local fringe={{rampager.hor, rampager.vec}}
				addRangeHex(rangeMap, rampager.hor, rampager.vec)
				for distance=1, 2 do
					local nextFringe={}
					for _, fromHex in pairs(fringe) do
						for _, vector in pairs(rampagerVectors) do
							local hor=fromHex[1]+vector[1]
							local vec=fromHex[2]+vector[2]
							local already=rangeMap[tostring(hor)]~=nil and rangeMap[tostring(hor)][tostring(vec)]==true
							if already==false and rangeHexOpen(hor, vec)==true and wallBetween(fromHex[1], fromHex[2], hor, vec)==false then
								addRangeHex(rangeMap, hor, vec)
								nextFringe[#nextFringe+1]={hor, vec}
							end
						end
					end
					fringe=nextFringe
				end
				ambusherRangeMaps[#ambusherRangeMaps+1]=rangeMap
			end
		end
		local function ambusherProvoked(fromHor, fromVec, toHor, toVec)
			fromHor=tostring(fromHor) fromVec=tostring(fromVec) toHor=tostring(toHor) toVec=tostring(toVec)
			for _, rangeMap in pairs(ambusherRangeMaps) do
				if rangeMap[fromHor]~=nil and rangeMap[fromHor][fromVec]==true and rangeMap[toHor]~=nil and rangeMap[toHor][toVec]==true then return true end
			end
			return false
		end
		--work out players hex grid position from the actual start tile; Fury's four-player
		--predefined map deliberately relocates the open start tile.
		local playerPos={startTilePos[1],0.97,startTilePos[3]}
		if gStates.gameScenario=="Against the Horsemen Blitz" then
			local gladePos=againstHorsemenCentralGladePosition(0.97)
			if gladePos~=nil then playerPos=gladePos end
		end
		if gStates.resourceTracker.playerPos==nil and turnOrder[gStates.turnNumber].turnStartLoc[1]~=nil and turnOrder[gStates.turnNumber].turnStartLoc[1]>-42 then
			gStates.resourceTracker.playerPos={turnOrder[gStates.turnNumber].turnStartLoc[1], turnOrder[gStates.turnNumber].turnStartLoc[2], turnOrder[gStates.turnNumber].turnStartLoc[3]}--{0, 0, 0}
		end
		if id=="MovemAmountUpdate" then
			for b, details in pairs(mageKnights) do
				if details.mage==turnOrder[gStates.turnNumber].mage then
					if getObjectFromGUID(details.model)~=nil then gStates.resourceTracker.playerPos={getObjectFromGUID(details.model).getPosition()[1], getObjectFromGUID(details.model).getPosition()[2], getObjectFromGUID(details.model).getPosition()[3]} end
					if getObjectFromGUID(details.token)~=nil then gStates.resourceTracker.playerPos=getObjectFromGUID(details.token).getPosition() end
					if getObjectFromGUID(details.standee)~=nil then gStates.resourceTracker.playerPos=getObjectFromGUID(details.standee).getPosition() end
				end
			end
			if turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" or turnOrder[gStates.turnNumber].avatarLocation=="Volkare's Camp" then
				--figure out which city avatar is in
				for zone, citySearch in pairs(cityScriptZones) do
					for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
						if detail.getName()==turnOrder[gStates.turnNumber].mage then
							gStates.resourceTracker.playerPos=getObjectFromGUID(citySearch.cityGUID).getPosition()
							break
						end
					end
				end
			end
		end
		if gStates.resourceTracker.playerPos~=nil then playerPos=gStates.resourceTracker.playerPos end
		--The shared Magical Glade is authoritative while the active Horsemen-scenario avatar is parked
		--off-map between turns; never let an old Portal/start-tile position override that logical hex.
		if againstHorsemenPlayerAtCentralGlade(turnOrder[gStates.turnNumber])==true then
			local gladePos=againstHorsemenCentralGladePosition(0.97)
			if gladePos~=nil then playerPos=gladePos end
		end

		local playerHexGridAxial,playerHexGridHorizontal=runtimeMapWorldToAxial(playerPos,startTilePos)
		local moveMap={[tostring(playerHexGridHorizontal)]={[tostring(playerHexGridAxial)]={main=0}}}
		local fringe={{coord={playerHexGridHorizontal, playerHexGridAxial}}}
		local tempFringe={}
		local tempFringeSet={}
		--When two onward routes cost the same, prefer the predecessor that is already using its
		--cheapest state. This avoids choosing the 5 side of a 4/5 hex when an ordinary 5 route is equal.
		local function continuationPenalty(hor, vec, state)
			local row=moveMap[tostring(hor)]
			local move=row~=nil and row[tostring(vec)] or nil
			if move==nil or move[state or "main"]==nil then return 0 end
			local cheapest=move.main or 99
			if move.tricky~=nil and move.tricky<cheapest then cheapest=move.tricky end
			return move[state or "main"]>cheapest and 1 or 0
		end

		--Search fringe hexes recorded from the previous loop
		local searchLimit=10
		local noMove=false
		while noMove==false do
			noMove=true
			--check every hex added in the last round
			for checkingHex, hexDetail in pairs(fringe) do
				local moveSpent=99
				local sourceState="main"
				if moveMap[tostring(hexDetail.coord[1])]~=nil and moveMap[tostring(hexDetail.coord[1])][tostring(hexDetail.coord[2])]~=nil then
					local sourceMove=moveMap[tostring(hexDetail.coord[1])][tostring(hexDetail.coord[2])]
					moveSpent=sourceMove.main
					if sourceMove.tricky~=nil then moveSpent=sourceMove.tricky sourceState="tricky" end
				end

				--figure out the move cost to reach surrounding hexs
				for currentVector, vector in pairs(MOVE_DISPLAY_VECTORS) do
					local hor=hexDetail.coord[1]+vector[1]
					local vec=hexDetail.coord[2]+vector[2]
					--See if the destination hex has a recorded terrain type
					if hexMap~=nil and hexMap[tostring(hor)]~=nil and hexMap[tostring(hor)][tostring(vec)]~=nil then
						local hexCost=999
						if hexMap[tostring(hor)][tostring(vec)].hexType~=nil and gStates.moveCost[hexMap[tostring(hor)][tostring(vec)].hexType]~=nil then hexCost=gStates.moveCost[hexMap[tostring(hor)][tostring(vec)].hexType]+moveSpent end
						local wallhor=hexDetail.coord[1]+(vector[1]/2)
						local wallvec=hexDetail.coord[2]+(vector[2]/2)
						if hexMap[tostring(wallhor)]~=nil and hexMap[tostring(wallhor)][tostring(wallvec)]~=nil then hexCost=hexCost+1 end
						local recordedMoveTotal=100
						if moveMap[tostring(hor)]~=nil and moveMap[tostring(hor)][tostring(vec)]~=nil then
							recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].main
							if moveMap[tostring(hor)][tostring(vec)].tricky~=nil then recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].tricky end
						end
						if hexCost<=99 and hexCost<gStates.resourceTracker.move.move+searchLimit and hexCost<=recordedMoveTotal then
							if moveMap[tostring(hor)]==nil then moveMap[tostring(hor)]={} end
							if moveMap[tostring(hor)][tostring(vec)]==nil then moveMap[tostring(hor)][tostring(vec)]={} end
							--Don't add hex to fringe if passing a rampager
							local rampageHor={tostring(hexDetail.coord[1]+MOVE_DISPLAY_RAMPAGE_ADJACENT[currentVector][1]), tostring(hexDetail.coord[1]+MOVE_DISPLAY_RAMPAGE_ADJACENT[currentVector+2][1])}
							local rampageVec={tostring(hexDetail.coord[2]+MOVE_DISPLAY_RAMPAGE_ADJACENT[currentVector][2]), tostring(hexDetail.coord[2]+MOVE_DISPLAY_RAMPAGE_ADJACENT[currentVector+2][2])}
							local rampageWallHor={tostring(hexDetail.coord[1]+MOVE_DISPLAY_RAMPAGE_WALL[currentVector][1]), tostring(hexDetail.coord[1]+MOVE_DISPLAY_RAMPAGE_WALL[currentVector+1][1])}
							local rampageWallVec={tostring(hexDetail.coord[2]+MOVE_DISPLAY_RAMPAGE_WALL[currentVector][2]), tostring(hexDetail.coord[2]+MOVE_DISPLAY_RAMPAGE_WALL[currentVector+1][2])}
							local normalRampager=(hexMap[rampageHor[1]]~=nil and hexMap[rampageHor[1]][rampageVec[1]]~=nil and hexMap[rampageHor[1]][rampageVec[1]].hexType=="rampager" and (hexMap[rampageWallHor[1]]==nil or hexMap[rampageWallHor[1]][rampageWallVec[1]]==nil)) or
								(hexMap[rampageHor[2]]~=nil and hexMap[rampageHor[2]][rampageVec[2]]~=nil and hexMap[rampageHor[2]][rampageVec[2]].hexType=="rampager" and (hexMap[rampageWallHor[2]]==nil or hexMap[rampageWallHor[2]][rampageWallVec[2]]==nil))
							local rampageNeighbor=normalRampager or ambusherProvoked(hexDetail.coord[1], hexDetail.coord[2], hor, vec)
							local dragonLairDestination=hexMap[tostring(hor)][tostring(vec)].dragonLair==true
							local forcedCombatDestination=rampageNeighbor or dragonLairDestination
							local destinationMove=moveMap[tostring(hor)][tostring(vec)]
							local predecessor={hor=hexDetail.coord[1], vec=hexDetail.coord[2], state=sourceState, teleport=false}
							if hexCost==recordedMoveTotal then
								--Equal-cost safe routes do not change reachability, but a cleaner predecessor can
								--remove an otherwise unnecessary dual-cost label from the displayed route tree.
								if forcedCombatDestination==false then
									local existingPrev=destinationMove.tricky~=nil and destinationMove.trickyPrev or destinationMove.mainPrev
									if existingPrev~=nil and continuationPenalty(predecessor.hor,predecessor.vec,predecessor.state)<continuationPenalty(existingPrev.hor,existingPrev.vec,existingPrev.state) then
										if destinationMove.tricky~=nil then destinationMove.trickyPrev=predecessor else destinationMove.mainPrev=predecessor end
									end
								end
							else
								if forcedCombatDestination==true then
									if destinationMove.main~=nil then
										destinationMove.tricky=destinationMove.main
										destinationMove.trickyPrev=destinationMove.mainPrev
										destinationMove.trickyCombat=destinationMove.mainCombat==true
										destinationMove.main=hexCost
										destinationMove.mainPrev=predecessor
										destinationMove.mainCombat=true
									else
										destinationMove.main=hexCost
										destinationMove.mainPrev=predecessor
										destinationMove.tricky=99--combat-only route is displayable but cannot be used to continue movement
										destinationMove.trickyPrev=nil
										destinationMove.trickyCombat=false
										destinationMove.mainCombat=true
									end
								else
									if destinationMove.tricky==nil then
										destinationMove.main=hexCost
										destinationMove.mainPrev=predecessor
										destinationMove.mainCombat=false
									else
										destinationMove.tricky=hexCost
										destinationMove.trickyPrev=predecessor
										destinationMove.trickyCombat=false
									end
								end
								--Fortified sites and forced-combat destinations may be reached but never used as onward fringe.
								if forcedCombatDestination==false and hexMap[tostring(hor)][tostring(vec)].hexType~="explore" and (hexMap[tostring(hor)][tostring(vec)].fortified==nil or hexMap[tostring(hor)][tostring(vec)].fortified=="shield") then
									local fringeKey=tostring(hor)..":"..tostring(vec)
									if tempFringeSet[fringeKey]~=true then
										tempFringeSet[fringeKey]=true
										tempFringe[#tempFringe+1]={coord={hor, vec}}
										noMove=false
									end
								end
							end
						end
					end
				end

				--Dungeon Lords underground edges. Another conquered Dungeon/Tomb costs 2 Move plus the
				--shortest revealed-space distance that avoids Lakes and Swamps; tunnel travel never provokes Rampagers.
				local tunnelSourceKey=tostring(hexDetail.coord[1])..":"..tostring(hexDetail.coord[2])
				for _,tunnel in ipairs(dungeonLordsTunnelNetwork[tunnelSourceKey] or {}) do
					local hor=tunnel.hor
					local vec=tunnel.vec
					local hexCost=moveSpent+tunnel.cost
					local recordedMoveTotal=100
					if moveMap[tostring(hor)]~=nil and moveMap[tostring(hor)][tostring(vec)]~=nil then
						recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].main
						if moveMap[tostring(hor)][tostring(vec)].tricky~=nil then recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].tricky end
					end
					if hexCost<gStates.resourceTracker.move.move+searchLimit and hexCost<=recordedMoveTotal then
						if moveMap[tostring(hor)]==nil then moveMap[tostring(hor)]={} end
						if moveMap[tostring(hor)][tostring(vec)]==nil then moveMap[tostring(hor)][tostring(vec)]={} end
						local destinationMove=moveMap[tostring(hor)][tostring(vec)]
						local predecessor={hor=hexDetail.coord[1],vec=hexDetail.coord[2],state=sourceState,teleport=false,tunnel=true,tunnelPath=tunnel.path}
						if hexCost==recordedMoveTotal then
							local existingPrev=destinationMove.tricky~=nil and destinationMove.trickyPrev or destinationMove.mainPrev
							if existingPrev~=nil and continuationPenalty(predecessor.hor,predecessor.vec,predecessor.state)<continuationPenalty(existingPrev.hor,existingPrev.vec,existingPrev.state) then
								if destinationMove.tricky~=nil then destinationMove.trickyPrev=predecessor else destinationMove.mainPrev=predecessor end
							end
						else
							if destinationMove.tricky==nil then
								destinationMove.main=hexCost
								destinationMove.mainPrev=predecessor
								destinationMove.mainCombat=false
							else
								destinationMove.tricky=hexCost
								destinationMove.trickyPrev=predecessor
								destinationMove.trickyCombat=false
							end
							local fringeKey=tostring(hor)..":"..tostring(vec)
							if tempFringeSet[fringeKey]~=true then
								tempFringeSet[fringeKey]=true
								tempFringe[#tempFringe+1]={coord={hor,vec}}
								noMove=false
							end
						end
					end
				end

				--Fractured Lands teleport edges. A teleport is always a safe, non-combat route and can itself become
				--the source of later normal moves or further teleports.
				if fracturedLandsTeleport==true then
					local sourceRow=hexMap[tostring(hexDetail.coord[1])]
					local sourceHex=sourceRow~=nil and sourceRow[tostring(hexDetail.coord[2])] or nil
					local sourceTerrain=sourceHex~=nil and (sourceHex.terrainType or sourceHex.hexType) or nil
					for _, teleportHex in pairs(teleportHexesByTerrain[sourceTerrain] or {}) do
						local hor=teleportHex.coord[1]
						local vec=teleportHex.coord[2]
						if hor~=hexDetail.coord[1] or vec~=hexDetail.coord[2] then
							local hexCost=moveSpent+1
							local recordedMoveTotal=100
							if moveMap[tostring(hor)]~=nil and moveMap[tostring(hor)][tostring(vec)]~=nil then
								recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].main
								if moveMap[tostring(hor)][tostring(vec)].tricky~=nil then recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].tricky end
							end
							if hexCost<gStates.resourceTracker.move.move+searchLimit and hexCost<=recordedMoveTotal then
								if moveMap[tostring(hor)]==nil then moveMap[tostring(hor)]={} end
								if moveMap[tostring(hor)][tostring(vec)]==nil then moveMap[tostring(hor)][tostring(vec)]={} end
								local destinationMove=moveMap[tostring(hor)][tostring(vec)]
								local predecessor={hor=hexDetail.coord[1], vec=hexDetail.coord[2], state=sourceState, teleport=true}
								if hexCost==recordedMoveTotal then
									local existingPrev=destinationMove.tricky~=nil and destinationMove.trickyPrev or destinationMove.mainPrev
									if existingPrev~=nil and continuationPenalty(predecessor.hor,predecessor.vec,predecessor.state)<continuationPenalty(existingPrev.hor,existingPrev.vec,existingPrev.state) then
										if destinationMove.tricky~=nil then destinationMove.trickyPrev=predecessor else destinationMove.mainPrev=predecessor end
									end
								else
									if destinationMove.tricky==nil then
										destinationMove.main=hexCost
										destinationMove.mainPrev=predecessor
										destinationMove.mainCombat=false
									else
										destinationMove.tricky=hexCost
										destinationMove.trickyPrev=predecessor
										destinationMove.trickyCombat=false
									end
									local fringeKey=tostring(hor)..":"..tostring(vec)
									if tempFringeSet[fringeKey]~=true then
										tempFringeSet[fringeKey]=true
										tempFringe[#tempFringe+1]={coord={hor, vec}}
										noMove=false
									end
								end
							end
						end
					end
				end
			end
			fringe=tempFringe
			tempFringe={}
			tempFringeSet={}
		end
		--Draw the predecessor tree used by the displayed cheapest routes. Each retained
		--route state is walked once rather than retracing every destination back to the avatar.
		local routeLines={}
		for _, line in pairs(moveDisplayBaseVectorLines or {}) do routeLines[#routeLines+1]=line end
		local routeSegmentSeen={}
		local routeStateSeen={}
		local routeStack={}
		local function routeWorldPosition(hor, vec)
			return runtimeMapAxialToWorld(vec,hor,startTilePos,1.22)
		end
		local function addRouteSegment(fromHor, fromVec, toHor, toVec, teleport, tunnelPath)
			local function addOne(aHor,aVec,bHor,bVec,mode)
				local key=tostring(aHor)..":"..tostring(aVec)..">"..tostring(bHor)..":"..tostring(bVec)..":"..tostring(mode)
				if routeSegmentSeen[key]==true then return end
				routeSegmentSeen[key]=true
				local color={0.50,0.50,0.50}
				if mode=="teleport" then color={0.20,0.70,1.00} elseif mode=="tunnel" then color={0.72,0.45,1.00} end
				routeLines[#routeLines+1]={points={routeWorldPosition(aHor,aVec),routeWorldPosition(bHor,bVec)},color=color,thickness=0.07,rotation={0,0,0}}
			end
			if tunnelPath~=nil and #tunnelPath>1 then
				for i=1,#tunnelPath-1 do addOne(tunnelPath[i].hor,tunnelPath[i].vec,tunnelPath[i+1].hor,tunnelPath[i+1].vec,"tunnel") end
			else
				addOne(fromHor,fromVec,toHor,toVec,teleport==true and "teleport" or "normal")
			end
		end
		local function queueRouteState(hor, vec, state)
			local key=tostring(hor)..":"..tostring(vec)..":"..state
			if routeStateSeen[key]==true then return end
			routeStateSeen[key]=true
			routeStack[#routeStack+1]={hor=hor, vec=vec, state=state}
		end
		for hor, rowOfHexes in pairs(moveMap) do
			for vec, moveDetails in pairs(rowOfHexes) do
				local routeCost=moveDetails.main
				local routeState="main"
				if moveDetails.tricky~=nil and moveDetails.tricky<routeCost then routeCost=moveDetails.tricky routeState="tricky" end
				if routeCost~=nil and routeCost<=99 and routeCost<moveValue+searchLimit then queueRouteState(tonumber(hor), tonumber(vec), routeState) end
			end
		end
		while #routeStack>0 do
			local current=table.remove(routeStack)
			if current.hor~=playerHexGridHorizontal or current.vec~=playerHexGridAxial then
				local routeRow=moveMap[tostring(current.hor)]
				local routeMove=routeRow~=nil and routeRow[tostring(current.vec)] or nil
				local previous=routeMove~=nil and routeMove[current.state.."Prev"] or nil
				if previous~=nil then
					addRouteSegment(previous.hor, previous.vec, current.hor, current.vec, previous.teleport, previous.tunnelPath)
					--Only a state that lies on the retained cheapest-route tree deserves an alternate
					--slash value. Discovered-but-redundant continuations no longer create 4/5-style noise.
					local sourceRow=moveMap[tostring(previous.hor)]
					local sourceMove=sourceRow~=nil and sourceRow[tostring(previous.vec)] or nil
					if sourceMove~=nil then sourceMove[(previous.state or "main").."UsedOnward"]=1 end
					queueRouteState(previous.hor, previous.vec, previous.state or "main")
				end
			end
		end
		Global.setVectorLines(routeLines)

		--Highlight movement costs with spawned text instead of numbered image decals.
		for hor, rowOfHexes in pairs(moveMap) do
			for vec, hexCost in pairs(rowOfHexes) do
				local lowestHex=hexCost.main
				local lowestState="main"
				if hexCost.tricky~=nil and hexCost.tricky<lowestHex then lowestHex=hexCost.tricky lowestState="tricky" end
				local displayCost=tostring(lowestHex)
				local multipleCosts=false
				local dualCosts=nil
				local destinationHex=hexMap[tostring(hor)]~=nil and hexMap[tostring(hor)][tostring(vec)] or nil
				local destinationCombat=destinationHex~=nil and (destinationHex.dragonLair==true or (destinationHex.hexType~="explore" and destinationHex.fortified~=nil and destinationHex.fortified~="shield"))
				local combatMove=destinationCombat or (lowestState=="main" and hexCost.mainCombat==true) or (lowestState=="tricky" and hexCost.trickyCombat==true)
				if hexCost.main~=nil and hexCost.main<99 and hexCost.tricky~=nil and hexCost.tricky<99 and hexCost.main~=hexCost.tricky then
					local higherHex=math.max(hexCost.main, hexCost.tricky)
					local higherState=higherHex==hexCost.main and "main" or "tricky"
					if hexCost[higherState.."UsedOnward"]==1 then
						displayCost=tostring(lowestHex).."/"..tostring(higherHex)
						multipleCosts=true
						dualCosts={low=lowestHex,high=higherHex,
							lowCombat=destinationCombat or (lowestState=="main" and hexCost.mainCombat==true) or (lowestState=="tricky" and hexCost.trickyCombat==true),
							highCombat=destinationCombat or (higherState=="main" and hexCost.mainCombat==true) or (higherState=="tricky" and hexCost.trickyCombat==true)}
					end
				end
				local world=runtimeMapAxialToWorld(tonumber(vec),tonumber(hor),startTilePos,1.22)
				if world~=nil then
					local hexGridX,hexGridZ=world[1],world[3]
					local startingHex=tonumber(hor)==playerHexGridHorizontal and tonumber(vec)==playerHexGridAxial
					if startingHex==false then
						if lowestHex<=gStates.resourceTracker.move.move then
							addMoveCostText(displayCost, hexGridX, hexGridZ, true, combatMove, multipleCosts, dualCosts)
						elseif lowestHex<=99 and lowestHex<gStates.resourceTracker.move.move+searchLimit then
							addMoveCostText(displayCost, hexGridX, hexGridZ, false, combatMove, multipleCosts, dualCosts)
						end
					end
				end
			end
		end
		moveDisplayHideUnusedText(moveTextUsed)
end

end)
__bundle_register("PlayingGame.AI.Volkare", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Volkare automated turn and combat-response runtime.

--Return the legal top-tile exploration position that contains a world hex.
--This deliberately reuses the normal EXPLORE set, so Volkare obeys the same tile-placement rules as players.
local function volkareLegalExploreSpot(pos)
	if pos==nil then return end
	local best=nil
	local bestDist=999
	for _, button in pairs(terrainExploreOptions()) do
		local attributes=button.attributes
		if attributes~=nil then
			local x=tonumber(attributes.tilePosX)
			local z=tonumber(attributes.tilePosZ)
			if x~=nil and z~=nil then
				local dist=math.sqrt(((pos[1]-x)^2)+((pos[3]-z)^2))
				if dist<3.1 and dist<bestDist then best={x, 2.0, z} bestDist=dist end
			end
		end
	end
	return best
end

local function normalizeVolkareBearing(bearing)
	bearing=bearing%360
	if bearing<0 then bearing=bearing+360 end
	return bearing
end

--Plan each first-phase Volkare step from the card's original direction.
--If that step needs an illegal tile, try the closest neighbouring direction and test the movement again.
local function planVolkareExploreMove(volkarePos, originalBearing, moveCount, mapSnapshot)
	local bearings={}
	local plannedTile=nil
	local simPos={volkarePos[1], volkarePos[2], volkarePos[3]}
	local offsets={0, -60, 60, -120, 120, 180}
	for step=1, moveCount do
		local chosenBearing=nil
		local chosenPos=nil
		for _, offset in ipairs(offsets) do
			local bearing=normalizeVolkareBearing(originalBearing+offset)
			local testPos={simPos[1]-(2.39*math.cos(math.rad(bearing))), 3.5, simPos[3]-(2.39*math.sin(math.rad(bearing)))}
			local explored=terrainHexAtPosition(testPos,mapSnapshot.terrainObjects,mapSnapshot.terrainPositions,mapSnapshot.terrainRotations)~=nil
			if explored==false and plannedTile~=nil then explored=math.sqrt(((testPos[1]-plannedTile[1])^2)+((testPos[3]-plannedTile[3])^2))<3.1 end
			if explored==true then
				chosenBearing=bearing
				chosenPos=testPos
				break
			end
			if plannedTile==nil then
				local legalSpot=volkareLegalExploreSpot(testPos)
				if legalSpot~=nil then
					plannedTile=legalSpot
					chosenBearing=bearing
					chosenPos=testPos
					break
				end
			end
		end
		if chosenBearing==nil then return bearings, plannedTile end
		bearings[step]=chosenBearing
		simPos=chosenPos
	end
	return bearings, plannedTile
end


--Volkare only. Keep his existing slower state/prompt sequence independent from the fast standard Dummy.
function volkareTurn(player, mouseButton, id)
	if mouseButton~="-1" or gStates.positionMageKnight[5]~="Volkare" then return end
	if gStates.tacticShown==true then
		automatedTurnRewindStart(function()
			automatedPlayerRandomTactic()
			gStates.volkareState="Start"
			gStates.volkareAttacked={}
			nextTurnMerged("incrementTurn")
			automatedTacticRewindRelease()
		end)
		return
	end
	--Only the initial Process Volkare click creates the rewind checkpoint. Combat-response clicks
	--continue the already protected sequence without trying to save an intermediate state.
	if gStates.endRoundCalled==false and gStates.volkareState=="Start" and id~="VolkareRewindReady" then
		automatedTurnRewindStart(function() volkareTurn(player,mouseButton,"VolkareRewindReady") end)
		return
	end
	local volkareDrew={color="Blue", spell=2}--this will give Volkare a Frenzy result.
	gStates.volkareFrenzied=true
	local function volkareDrawCard()
		local stats=turnOrder[gStates.turnNumber]
		if stats==nil then return nil end
		local lastCard=automatedDeedDraw(stats.seatPos,1,1)
		if lastCard~=nil then
			gStates.volkareFrenzied=false
			local colors=dummyCardColors(lastCard)
			if colors[1]~=nil then volkareDrew.color=colors[1] elseif lastCard.getGMNotes()=="Wound" then volkareDrew.color="Wound" end
			if gameCardType(lastCard)~="Spell" then volkareDrew.spell=1 end
		end
		return lastCard
	end
	if gStates.positionMageKnight[5]=="Volkare" and gStates.endRoundCalled==false and gStates.volkareState=="Start" then
		gStates.volkareRazeCityKey=nil
