							if pairObj~=nil then local pairPos=pairObj.getPosition() local pairDist=math.sqrt(((volkarePOS[1]-pairPos[1])^2)+((volkarePOS[3]-pairPos[3])^2)) if pairDist<temp then temp=pairDist end end
