	if enemy==nil then return end
	local id=enemy.guid.."ProxyEnemyChoice"
	enemy.UI.setXmlTable({{tag="Button",attributes={id=id,onClick="global/proxyEnemyChoiceSelect",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",
		height=150,width=500,position="0 190 -10",rotation="0 0 180",scale="0.32 0.32",color="rgba(0,0,0,0.0)"},
		children={{tag="Image",attributes={id=id.."Image",image="Sliced Button/Button Object Active",type="Sliced"}},
			{tag="HorizontalLayout",attributes={padding="25 25 25 25"},children={{tag="Text",attributes={id=id.."Text",font="Fonts/MKCardText",fontSize="82",fontStyle="Normal",alignment="MiddleCenter",resizeTextForBestFit="true",resizeTextMaxSize="82",text="{en}CHOOSE FOR PROXY{ru}ВЫБОР ЗА ПРОКСИ{zh-tw}為代理玩家選擇{zh-cn}为代理玩家选择{ko}프록시 선택{es}ELEGIR POR EL PROXY{fr}CHOISIR POUR LE PROXY{pt-br}ESCOLHER PELO PROXY{de}FÜR PROXY WÄHLEN"}}}}}}})
end

function proxyEnemyChoiceClearButtons(pending)
	if pending==nil or pending.type~="enemy" then return end
	for guid,snap in pairs(pending.options or {}) do
		local enemy=getObjectFromGUID(guid)
		if enemy~=nil then
			if snap.ui~=nil and #snap.ui>0 then enemy.UI.setXmlTable(snap.ui) else setMonsterObjectButtons(enemy) end
		end
	end
end

function proxyBeginEnemyChoice(enemies,context,proxyIndex)
	if enemies==nil or #enemies<2 then return false end
	local chooser=proxyChoicePlayerIndex()
	if chooser==nil then return false end
	local pending={type="enemy",proxyIndex=proxyIndex,playerIndex=chooser,playerColor=proxyChoicePlayerColor(chooser),context=context,options={},order={}}
	local names={}
	for _,enemy in ipairs(enemies) do
		local snap=proxyEnemyChoiceSnapshot(enemy)
		if snap~=nil then
			pending.options[snap.guid]=snap
			pending.order[#pending.order+1]=snap.guid
			names[#names+1]=snap.name
		end
	end
	if #pending.order<2 then return false end
	gStates.proxyPendingChoice=pending
	for _,guid in ipairs(pending.order) do local enemy=getObjectFromGUID(guid) if enemy~=nil then proxyEnemyChoiceButton(enemy) end end
	broadcastToAll(joinLang({"{en}Proxy must choose between tied lowest-Fame enemies: {ru}Прокси должен выбрать между врагами с одинаковой наименьшей Славой: {zh-tw}代理玩家必須在聲望值同為最低的敵人中選擇：{zh-cn}代理玩家必须在声望值同为最低的敌人中选择：{ko}프록시는 명성이 공동 최저인 적 중 선택해야 합니다: {es}El Proxy debe elegir entre los enemigos empatados con la Fama más baja: {fr}Le Proxy doit choisir parmi les ennemis à égalité pour la Renommée la plus faible : {pt-br}O Proxy deve escolher entre os inimigos empatados com a menor Fama: {de}Der Proxy muss zwischen den Gegnern mit gleich niedrigstem Ruhm wählen: ",proxyLocalizedList(names,", "),". ",proxyChoicePlayerLabel(chooser),"{en} must choose one.{ru} должен выбрать одного.{zh-tw} 必須選擇一個。{zh-cn} 必须选择一个。{ko}이(가) 하나를 선택해야 합니다.{es} debe elegir uno.{fr} doit en choisir un.{pt-br} deve escolher um.{de} muss einen auswählen."}),{1,0.75,0.2})
	return proxyChoiceSetWaiting(pending)
end

function proxyResolveCitySelectedEnemy(hex,mapObjects,proxyIndex,lastSafe,selectedGUID)
	local city=proxyCityGUIDForHex(hex)
	if city==nil then return end
	local alive=proxyCityAliveEnemies(city)
	local chosen=selectedGUID
	local found=false
	for _,guid in ipairs(alive) do if guid==chosen then found=true break end end
	if found~=true then
		local lowest=proxyLowestFameEnemies(alive)
		chosen=lowest[1]~=nil and lowest[1].guid or nil
	end
	local defeatedName=nil
	if chosen~=nil then
		local enemy=getObjectFromGUID(chosen)
		if enemy~=nil then
			defeatedName=((monsterPugs[enemy.guid] or {}).name or enemy.getName() or "enemy")
			proxyDiscardMonster(enemy)
		end
		if gStates.cityMonsterQty[city]~=nil then gStates.cityMonsterQty[city][chosen]="dead" end
	end
	proxyPlaceCityShield(city)
	refreshCityDefeatState()
	local cityRemaining=#proxyCityAliveEnemies(city)
	if cityRemaining>0 then proxyTurnReportSetAction("defeated "..tostring(defeatedName or "an enemy").." in the City and retreated")
	else proxyTurnReportSetAction("conquered the City") end
	if cityRemaining>0 and lastSafe~=nil then
		local avatar=proxyAvatarObject()
		if avatar~=nil then avatar.unlock() avatar.setPositionSmooth({lastSafe.position[1],1.5,lastSafe.position[3]}) end
	end
end

function proxyResolveEnemyChoice(pending,selectedGUID)
	if pending==nil or pending.context==nil then automatedTurnRewindRelease() return end
	local hexes,mapObjects=runtimeMapHexesAndObjects()
	local hex=proxyHexByKey(hexes,pending.context.hexKey)
	if hex==nil then proxyFinishTurn(hexes,mapObjects,pending.proxyIndex) return end
	if pending.context.kind=="ruin" then
		local enemy=getObjectFromGUID(selectedGUID)
		local enemyName=enemy~=nil and ((monsterPugs[enemy.guid] or {}).name or enemy.getName() or "enemy") or "enemy"
		local lift=proxyLiftAvatarForSiteObjects(hex)
		if enemy~=nil then proxyDiscardMonster(enemy) end
		proxyRestoreAvatarAfterSiteObjects(lift,{})
		proxyTurnReportSetAction("defeated "..tostring(enemyName).." at the Ruins")
		proxyClearObjective(true)
		broadcastToAll("{en}Proxy resolved the tied Ruins enemy choice.{ru}Прокси разрешил ничью при выборе врага в Руинах.{zh-tw}代理玩家已解決遺跡敵人選擇的平手。{zh-cn}代理玩家已解决遗迹敌人选择的平手。{ko}프록시가 유적 적 선택의 동률을 해결했습니다.{es}El Proxy resolvió el empate en la elección de enemigo de las Ruinas.{fr}Le Proxy a résolu l’égalité du choix d’ennemi des Ruines.{pt-br}O Proxy resolveu o empate na escolha de inimigo das Ruínas.{de}Der Proxy hat den Gleichstand bei der Gegnerwahl in den Ruinen aufgelöst.",{1,0.75,0.2})
	elseif pending.context.kind=="city" then
		local lastSafe=proxyHexByKey(hexes,pending.context.lastSafeKey)
		proxyResolveCitySelectedEnemy(hex,mapObjects,pending.proxyIndex,lastSafe,selectedGUID)
		proxyClearObjective(true)
		broadcastToAll("{en}Proxy resolved the tied City defender choice.{ru}Прокси разрешил ничью при выборе защитника Города.{zh-tw}代理玩家已解決城市防守者選擇的平手。{zh-cn}代理玩家已解决城市防守者选择的平手。{ko}프록시가 도시 수비자 선택의 동률을 해결했습니다.{es}El Proxy resolvió el empate en la elección de defensor de la Ciudad.{fr}Le Proxy a résolu l’égalité du choix de défenseur de la Cité.{pt-br}O Proxy resolveu o empate na escolha de defensor da Cidade.{de}Der Proxy hat den Gleichstand bei der Verteidigerwahl der Stadt aufgelöst.",{1,0.75,0.2})
	end
	safeWaitTime("AI.Proxy",function()
		local freshHexes,freshObjects=runtimeMapHexesAndObjects()
		proxyFinishTurn(freshHexes,freshObjects,pending.proxyIndex)
	end,1.1)
end

function proxyEnemyChoiceSelect(player,mouseButton,id)
	if mouseButton~="-1" or gStates.proxyState~="PickEnemy" then return end
	local buttonID=tostring(id or "")
	local guid=buttonID:sub(1,6)
	local pending=gStates.proxyPendingChoice
	if buttonID:sub(7)~="ProxyEnemyChoice" or pending==nil or pending.type~="enemy" or pending.options[guid]==nil then return end
	if proxyChoiceAuthorized(player,pending)~=true then return end
	proxyEnemyChoiceClearButtons(pending)
	gStates.proxyPendingChoice=nil
	proxyChoiceResumeProcessing()
	automatedTurnRewindStart(function() proxyResolveEnemyChoice(pending,guid) end)
end

function proxyResolveRampager(target,mapObjects)
	local enemies={}
	local seen={}
	for _,enemy in ipairs(target~=nil and target.enemies or {}) do
		if enemy~=nil and seen[enemy.guid]~=true then seen[enemy.guid]=true enemies[#enemies+1]=enemy end
	end
	if #enemies==0 and target~=nil and target.enemy~=nil then enemies[1]=target.enemy end
	if #enemies==0 and target~=nil and target.hex~=nil then enemies=proxyMonstersOnHex(target.hex,mapObjects) end
	local names={}
	for _,enemy in ipairs(enemies) do
		if enemy~=nil then
			names[#names+1]=tostring(((monsterPugs[enemy.guid] or {}).name or enemy.getName() or "enemy"))
			proxyDiscardMonster(enemy)
		end
	end
	if #names<=1 then proxyTurnReportSetAction("defeated the rampaging "..tostring(names[1] or "enemy"))
	else proxyTurnReportSetAction("defeated "..tostring(#names).." rampaging enemies") end
	broadcastToAll(#names<=1 and "{en}Proxy discarded a rampaging enemy.{ru}Прокси сбросил Бродячего врага.{zh-tw}代理玩家棄掉了一個遊蕩敵人。{zh-cn}代理玩家弃掉了一个游荡敌人。{ko}프록시가 방랑 적 하나를 버렸습니다.{es}El Proxy descartó un enemigo arrasador.{fr}Le Proxy a défaussé un ennemi ravageur.{pt-br}O Proxy descartou um inimigo errante.{de}Der Proxy hat einen streunenden Gegner abgeworfen." or joinLang({"{en}Proxy discarded {ru}Прокси сбросил {zh-tw}代理玩家棄掉了 {zh-cn}代理玩家弃掉了 {ko}프록시가 방랑 적 {es}El Proxy descartó {fr}Le Proxy a défaussé {pt-br}O Proxy descartou {de}Der Proxy hat ",tostring(#names),"{en} rampaging enemies.{ru} Бродячих врагов.{zh-tw} 個遊蕩敵人。{zh-cn} 个游荡敌人。{ko}명을 버렸습니다.{es} enemigos arrasadores.{fr} ennemis ravageurs.{pt-br} inimigos errantes.{de} streunende Gegner abgeworfen."}),{1,0.75,0.2})
	proxyClearObjective(true)
	return true
end

function proxyResolveAdventure(hex,mapObjects,proxyIndex)
	local feature=string.lower(tostring(hex.feature or ""))
	local reportAction=nil
	local lift=proxyLiftAvatarForSiteObjects(hex)
	local settleGUIDs={}
	local function settle(obj) if obj~=nil then settleGUIDs[#settleGUIDs+1]=obj.guid end end
	if feature=="ruin" then
		local ruin=proxyRuinOnHex(hex,mapObjects)
		local enemies=proxyMonstersOnHex(hex,mapObjects)
		settle(ruin)
		for _,enemy in ipairs(enemies) do settle(enemy) end
		if ruin~=nil and #enemies==0 and monsterPugs[ruin.guid]~=nil and monsterPugs[ruin.guid].monsters~=nil then
			for a,pugType in ipairs(monsterPugs[ruin.guid].monsters) do
				local bag=getObjectFromGUID(monsterPiles[pugType])
				if bag~=nil and bag.getQuantity()>0 then
					local enemy=bag.takeObject({position={hex.position[1]+((a-1)*0.28),2+(a*0.15),hex.position[3]+0.25},rotation={0,180,0},smooth=false})
					if enemy~=nil then
						if enemy.is_face_down==true then enemy.flip() end
						enemies[#enemies+1]=enemy
						settle(enemy)
					end
				end
			end
		end
		if #enemies>0 then
			local lowest=proxyLowestFameEnemies(enemies)
			if #lowest>1 and proxyBeginEnemyChoice(lowest,{kind="ruin",hexKey=runtimeMapHexKey(hex)},proxyIndex)==true then
				proxyRestoreAvatarAfterSiteObjects(lift,settleGUIDs)
				return false
			end
			local defeated=lowest[1] or enemies[1]
			local defeatedName=(defeated~=nil and monsterPugs[defeated.guid]~=nil and monsterPugs[defeated.guid].name) or "enemy"
			proxyDiscardMonster(defeated)
			if #enemies==1 then
				if ruin~=nil then proxyDiscardMonster(ruin) end
				settle(proxyPlaceMapShield(hex,mapObjects))
				reportAction="defeated "..tostring(defeatedName).." and conquered the Ruins"
			else reportAction="defeated "..tostring(defeatedName).." at the Ruins" end
		else
			if ruin~=nil then proxyDiscardMonster(ruin) end
			settle(proxyPlaceMapShield(hex,mapObjects))
			reportAction="conquered the Ruins"
		end
	else
		for _,enemy in ipairs(proxyMonstersOnHex(hex,mapObjects)) do proxyDiscardMonster(enemy) end
		settle(proxyPlaceMapShield(hex,mapObjects))
		reportAction="conquered the "..proxyFeatureDisplayName(hex.feature)
	end
	proxyRestoreAvatarAfterSiteObjects(lift,settleGUIDs)
	proxyTurnReportSetAction(reportAction or ("resolved the "..proxyFeatureDisplayName(hex.feature)))
	broadcastToAll("{en}Proxy resolved an adventure site.{ru}Прокси разрешил место приключения.{zh-tw}代理玩家已完成一個冒險地點。{zh-cn}代理玩家已完成一个冒险地点。{ko}프록시가 모험 장소를 해결했습니다.{es}El Proxy resolvió un lugar de aventura.{fr}Le Proxy a résolu un site d’aventure.{pt-br}O Proxy resolveu um local de aventura.{de}Der Proxy hat einen Abenteuerort abgewickelt.",{1,0.75,0.2})
	proxyClearObjective(true)
	return true
end

function proxyResolveFortified(hex,mapObjects,proxyIndex,lastSafe)
	local fortified=proxyFortifiedType(hex,mapObjects,proxyIndex)
	if fortified=="city" then
		local city=proxyCityGUIDForHex(hex)
		local alive=proxyCityAliveEnemies(city)
		local lowest=proxyLowestFameEnemies(alive)
		if #lowest>1 and proxyBeginEnemyChoice(lowest,{kind="city",hexKey=runtimeMapHexKey(hex),lastSafeKey=lastSafe~=nil and runtimeMapHexKey(lastSafe) or nil},proxyIndex)==true then return false end
		local selected=lowest[1]~=nil and lowest[1].guid or nil
		proxyResolveCitySelectedEnemy(hex,mapObjects,proxyIndex,lastSafe,selected)
	elseif fortified~=nil then
		local lift=proxyLiftAvatarForSiteObjects(hex)
		for _,enemy in ipairs(proxyMonstersOnHex(hex,mapObjects)) do proxyDiscardMonster(enemy) end
		if fortified=="keep" then proxyRemoveOtherKeepShield(hex,mapObjects,proxyIndex) end
		local shield=proxyPlaceMapShield(hex,mapObjects)
		proxyRestoreAvatarAfterSiteObjects(lift,shield~=nil and {shield.guid} or {})
		proxyTurnReportSetAction("conquered the "..proxyFeatureDisplayName(fortified))
	end
	broadcastToAll("{en}Proxy resolved a fortified site.{ru}Прокси разрешил укреплённое место.{zh-tw}代理玩家已完成一個要塞地點。{zh-cn}代理玩家已完成一个要塞地点。{ko}프록시가 요새 장소를 해결했습니다.{es}El Proxy resolvió un lugar fortificado.{fr}Le Proxy a résolu un site fortifié.{pt-br}O Proxy resolveu um local fortificado.{de}Der Proxy hat einen befestigten Ort abgewickelt.",{1,0.75,0.2})
	proxyClearObjective(true)
	return true
end

function proxyReturnOfferCard(card)
	if card==nil then return end
	local cardType=gameCardType(card)
	local zoneByType={["Regular Unit"]=GUID.zone.regularUnit,["Elite Unit"]=GUID.zone.eliteUnit,["Advanced Action"]=GUID.zone.actionDeck,["Spell"]=GUID.zone.spellDeck}
	local zone=zoneByType[cardType]~=nil and getObjectFromGUID(zoneByType[cardType]) or nil
	card.unlock()
	if zone~=nil then
		standardDeckCycleMarkReturned(cardType,card)
		local pile=standardDeckCycleObject(cardType)
		if pile~=nil and pile.guid~=card.guid then putCardAtBottom(pile,card)
		else
			--A temporarily empty source zone has nothing to merge with; leave the returned card at the
			--source-deck position so it becomes the live one-card source pile.
			local p=zone.getPosition()
			card.setPosition({p[1],p[2]+1.0,p[3]})
			card.setRotation({0,180,180})
		end
	elseif getObjectFromGUID(trashCan)~=nil then getObjectFromGUID(trashCan).putObject(card) end
end

function proxyInteractionChoiceButton(card)
	if card==nil then return end
	local id=card.guid.."ProxyInteractionChoice"
	card.UI.setXmlTable({{tag="Button",attributes={id=id,onClick="global/proxyInteractionChoiceSelect",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",
		height=150,width=500,position="0 190 -10",rotation="0 0 180",scale="0.32 0.32",color="rgba(0,0,0,0.0)"},
		children={{tag="Image",attributes={id=id.."Image",image="Sliced Button/Button Object Active",type="Sliced"}},
			{tag="HorizontalLayout",attributes={padding="25 25 25 25"},children={{tag="Text",attributes={id=id.."Text",font="Fonts/MKCardText",fontSize="82",fontStyle="Normal",alignment="MiddleCenter",resizeTextForBestFit="true",resizeTextMaxSize="82",text="{en}CHOOSE FOR PROXY{ru}ВЫБОР ЗА ПРОКСИ{zh-tw}為代理玩家選擇{zh-cn}为代理玩家选择{ko}프록시 선택{es}ELEGIR POR EL PROXY{fr}CHOISIR POUR LE PROXY{pt-br}ESCOLHER PELO PROXY{de}FÜR PROXY WÄHLEN"}}}}}}})
end

function proxyInteractionChoiceSnapshot(choice)
	if choice==nil or choice.card==nil then return nil end
	local card=choice.card
	return {guid=card.guid,kind=choice.kind,cost=choice.cost,name=proxyCardDisplayName(card),ui=card.UI.getXmlTable() or {}}
end

function proxyInteractionChoiceClearButtons(pending)
	if pending==nil or pending.type~="card" then return end
	for guid,snap in pairs(pending.options or {}) do
		local card=getObjectFromGUID(guid)
		if card~=nil then
			if snap.ui~=nil and #snap.ui>0 then card.UI.setXmlTable(snap.ui) else card.UI.setXmlTable({{}}) end
		end
	end
end

function proxyTakeInteractionChoice(choice)
	if choice==nil or choice.card==nil then return false end
	local cardName=proxyCardDisplayName(choice.card)
	local kind=choice.kind=="unit" and "Unit" or (choice.kind=="spell" and "Spell" or "Advanced Action")
	proxyTurnReportSetAction("took "..cardName.." ("..kind..") from the offer")
	proxyReturnOfferCard(choice.card)
	if choice.kind~="unit" then safeWaitFrames("AI.Proxy",function() compactAndRefillDeedOffer() end,2) end
	proxyClearObjective(true)
	broadcastToAll(joinLang({"{en}Proxy took {ru}Прокси взял {zh-tw}代理玩家從供應中取得 {zh-cn}代理玩家从供应中取得 {ko}프록시가 제안에서 {es}El Proxy tomó {fr}Le Proxy a pris {pt-br}O Proxy pegou {de}Der Proxy nahm ",cardName,"{en} from the offer.{ru} из предложения.{zh-tw}。{zh-cn}。{ko}을(를) 가져갔습니다.{es} de la oferta.{fr} dans l’offre.{pt-br} da oferta.{de} aus dem Angebot."}),{1,0.75,0.2})
	return true
end

function proxyBeginCardChoice(choices,proxyIndex)
	if choices==nil or #choices<2 then return false end
	local chooser=proxyChoicePlayerIndex()
	if chooser==nil then return false end
	local pending={type="card",proxyIndex=proxyIndex,playerIndex=chooser,playerColor=proxyChoicePlayerColor(chooser),options={},order={}}
	local names={}
	for _,choice in ipairs(choices) do
		local snap=proxyInteractionChoiceSnapshot(choice)
		if snap~=nil and pending.options[snap.guid]==nil then
			pending.options[snap.guid]=snap
			pending.order[#pending.order+1]=snap.guid
			names[#names+1]=snap.name
		end
	end
	if #pending.order<2 then return false end
	gStates.proxyPendingChoice=pending
	for _,guid in ipairs(pending.order) do local card=getObjectFromGUID(guid) if card~=nil then proxyInteractionChoiceButton(card) end end
	broadcastToAll(joinLang({"{en}Proxy has {ru}У Прокси есть {zh-tw}代理玩家有 {zh-cn}代理玩家有 {ko}프록시에게 {es}El Proxy tiene {fr}Le Proxy a {pt-br}O Proxy tem {de}Der Proxy hat ",tostring(#pending.order),"{en} equally valid lowest-cost cards: {ru} равно допустимых карт с наименьшей стоимостью: {zh-tw} 張同樣有效且費用最低的牌：{zh-cn} 张同样有效且费用最低的牌：{ko}개의 동일하게 유효한 최저 비용 카드가 있습니다: {es} cartas de coste mínimo igualmente válidas: {fr} cartes de coût minimal également valides : {pt-br} cartas de menor custo igualmente válidas: {de} gleich gültige Karten mit den niedrigsten Kosten: ",proxyLocalizedList(names,", "),". ",proxyChoicePlayerLabel(chooser),"{en} must choose one.{ru} должен выбрать одну.{zh-tw} 必須選擇一張。{zh-cn} 必须选择一张。{ko}이(가) 하나를 선택해야 합니다.{es} debe elegir una.{fr} doit en choisir une.{pt-br} deve escolher uma.{de} muss eine auswählen."}),{1,0.75,0.2})
	return proxyChoiceSetWaiting(pending)
end

function proxyInteractionChoiceSelect(player,mouseButton,id)
	if mouseButton~="-1" or gStates.proxyState~="PickCard" then return end
	local buttonID=tostring(id or "")
	local guid=buttonID:sub(1,6)
	local pending=gStates.proxyPendingChoice
	if buttonID:sub(7)~="ProxyInteractionChoice" or pending==nil or pending.type~="card" or pending.options[guid]==nil then return end
	if proxyChoiceAuthorized(player,pending)~=true then return end
	local snap=pending.options[guid]
	proxyInteractionChoiceClearButtons(pending)
	gStates.proxyPendingChoice=nil
	proxyChoiceResumeProcessing()
	automatedTurnRewindStart(function()
		local card=getObjectFromGUID(guid)
		if card~=nil then proxyTakeInteractionChoice({card=card,kind=snap.kind,cost=snap.cost})
		else proxyTurnReportSetAction("could not find the selected offer card") proxyClearObjective(true) end
		safeWaitTime("AI.Proxy",function()
			local hexes,mapObjects=runtimeMapHexesAndObjects()
			proxyFinishTurn(hexes,mapObjects,pending.proxyIndex)
		end,1.1)
	end)
end

function proxyResolveInteraction(choice,choices,proxyIndex)
	if choices~=nil and #choices>1 and proxyBeginCardChoice(choices,proxyIndex)==true then return false end
	if choice~=nil and choice.card~=nil then proxyTakeInteractionChoice(choice)
	else
		proxyTurnReportSetAction("found no legal card to take at the interaction site")
		proxyClearObjective(true)
	end
	return true
end

function proxyResolveExplore(target)
	if target~=nil and target.predefinedTileGUID~=nil then
		local tile=getObjectFromGUID(target.predefinedTileGUID)
		if tile~=nil and tile.is_face_down==true then
			--Use the same TTS flip animation as a player. The tile leaves/re-enters the map scripting zone,
			--so the ordinary terrain-entry handler remains the single authority for population/reveal logic.
			tile.flip()
			proxyTurnReportSetAction("explored a predefined tile")
			broadcastToAll("{en}Proxy explored a predefined terrain tile.{ru}Прокси исследовал предопределённую плитку местности.{zh-tw}代理玩家探索了一個預設地形板塊。{zh-cn}代理玩家探索了一个预设地形板块。{ko}프록시가 미리 정해진 지형 타일을 탐험했습니다.{es}El Proxy exploró una loseta de terreno predefinida.{fr}Le Proxy a exploré une tuile de terrain prédéfinie.{pt-br}O Proxy explorou uma peça de terreno predefinida.{de}Der Proxy hat ein vordefiniertes Geländeplättchen erkundet.",{1,0.75,0.2})
			proxyClearObjective(true)
		end
	elseif target~=nil and target.button~=nil and target.button.attributes~=nil and target.button.attributes.id~=nil then
		exploreMap({color="Black"},"-1",target.button.attributes.id)
		proxyTurnReportSetAction("explored a new tile")
		broadcastToAll("{en}Proxy explored a new tile.{ru}Прокси исследовал новую плитку.{zh-tw}代理玩家探索了一個新板塊。{zh-cn}代理玩家探索了一个新板块。{ko}프록시가 새 타일을 탐험했습니다.{es}El Proxy exploró una nueva loseta.{fr}Le Proxy a exploré une nouvelle tuile.{pt-br}O Proxy explorou uma nova peça.{de}Der Proxy hat ein neues Plättchen erkundet.",{1,0.75,0.2})
		proxyClearObjective(true)
	end
	return true
end

function proxyFinishTurn(hexes,mapObjects,proxyIndex)
	proxyIndex=proxyIndex or gStates.turnNumber
	local stats=turnOrder[proxyIndex]
	local avatar=proxyAvatarObject()
	if stats~=nil and avatar~=nil then
		refreshAvatarLocationOnly(proxyIndex,avatar)
		portalSwap("endOfTurn",proxyIndex)
	end
	if stats~=nil then stats.dummyProcessedThisTurn=true dummyRefreshDeedState(stats.seatPos) end
	gStates.proxyState="ReadyToEnd"
	gStates.proxyPendingChoice=nil
	automatedMainPanelRefresh()
	mainUIUpdate("Proxy ready to end")
	automatedTurnRewindRelease()
end

function proxyResolveBurn(hex,mapObjects)
	if hex==nil then return true end
	local lift=proxyLiftAvatarForSiteObjects(hex)
	local shield=proxyPlaceMapShield(hex,mapObjects)
	proxyRestoreAvatarAfterSiteObjects(lift,shield~=nil and {shield.guid} or {})
	proxyTurnReportSetAction("burned the Monastery")
	proxyClearObjective(true)
	broadcastToAll("{en}Proxy burned a monastery.{ru}Прокси сжёг Монастырь.{zh-tw}代理玩家焚毀了一座修道院。{zh-cn}代理玩家焚毁了一座修道院。{ko}프록시가 수도원을 불태웠습니다.{es}El Proxy quemó un monasterio.{fr}Le Proxy a brûlé un monastère.{pt-br}O Proxy queimou um mosteiro.{de}Der Proxy hat ein Kloster niedergebrannt.",{1,0.75,0.2})
	return true
end

function proxyResolveArrival(target,hazard,lastSafe,hexes,mapObjects,proxyIndex)
	local completed=true
	if hazard~=nil then
		if hazard.action=="rampager" then completed=proxyResolveRampager(hazard,mapObjects)
		elseif hazard.action=="fortified" then completed=proxyResolveFortified(hazard.hex or (target~=nil and target.hex or nil),mapObjects,proxyIndex,lastSafe) end
	elseif target~=nil then
		if target.action=="adventure" then completed=proxyResolveAdventure(target.hex,mapObjects,proxyIndex)
		elseif target.action=="fortified" then completed=proxyResolveFortified(target.hex,mapObjects,proxyIndex,lastSafe)
		elseif target.action=="burn" then completed=proxyResolveBurn(target.hex,mapObjects)
		elseif target.action=="interact" then
			--Destination and purchase are separate decisions. Re-evaluate the offer only after the Proxy
			--actually reaches the chosen White site, then pause only if the cheapest legal cards tie.
			local crystals=proxySnapshotCrystals(turnOrder[proxyIndex])
			local choices=proxyInteractionBestChoices(proxyInteractionOptions(target.hex,mapObjects,proxyIndex,crystals,proxyInteractionOfferCache(crystals)))
			completed=proxyResolveInteraction(choices[1],choices,proxyIndex)
		elseif target.action=="explore" then completed=proxyResolveExplore(target) end
	end
	if completed~=false then safeWaitTime("AI.Proxy",function() proxyFinishTurn(hexes,mapObjects,proxyIndex) end,1.1) end
end

function proxyRevealGarrisonsAtHex(hex,hexes,mapObjects,proxyIndex)
	if hex==nil or gStates.autoFlip~=true then return end
	local revealHexes={hex}
	for _,nearHex in ipairs(hexes or {}) do
		if runtimeMapHexKey(nearHex)~=runtimeMapHexKey(hex) and runtimeMapHexesAdjacent(hex,nearHex)==true then revealHexes[#revealHexes+1]=nearHex end
	end
	local revealed=false
	for _,revealHex in ipairs(revealHexes) do
		if apocalypseQuestFeatureIsCity(revealHex.feature)==true then
			local city=proxyCityGUIDForHex(revealHex)
			for _,guid in ipairs(proxyCityAliveEnemies(city)) do
				local enemy=getObjectFromGUID(guid)
				if enemy~=nil and enemy.is_face_down==true then enemy.flip() revealed=true end
			end
		end
		if gStates.dayRound==true then
			for _,obj in pairs(mapObjects or {}) do
				if monsterPugs[obj.guid]~=nil then
					local pos=obj.getPosition()
					local dx=pos[1]-revealHex.position[1]
					local dz=pos[3]-revealHex.position[3]
					if (dx*dx)+(dz*dz)<1.25 then
						local values=obj.getRotationValues() or {}
						local second=values[2]
						local value=second~=nil and tostring(second.value or "") or ""
						if value=="Mage Tower Garrison" or value=="Keep Garrison" or value=="Marauding Elementalist" then
							if obj.is_face_down==true then obj.flip() revealed=true end
						end
					end
				end
			end
		end
	end
	if revealed==true then broadcastToAll("{en}Site Garrison Revealed{ru}Гарнизон Укрепленного места раскрыт{zh-tw}守军揭示了{zh-cn}守军揭示了{ko}수비자가 공개되었습니다.{es}Guarnición del Sitio Revelada{fr}La Garnison du Site Révélée{pt-br}Lugar de Guarnição Revelada{de}Standort Garnison aufgedeckt",{1,1,0.5}) end
end

function proxyAnimateStep(hex,hexes,mapObjects,proxyIndex,callback)
	local avatar=proxyAvatarObject()
	if avatar==nil or hex==nil then if callback~=nil then callback() end return end
	avatar.unlock()
	avatar.setPositionSmooth({hex.position[1],1.5,hex.position[3]})
	safeWaitFrames("AI.Proxy",function()
		local finished=false
		local function complete()
			if finished==true then return end
			finished=true
			if avatar~=nil then avatar.unlock() end
			if gStates.proxyTurnReport~=nil then proxyTurnReportSetMoved((gStates.proxyTurnReport.moved or 0)+1) end
			proxyRevealGarrisonsAtHex(hex,hexes,mapObjects,proxyIndex)
			if callback~=nil then callback() end
		end
		safeWaitCondition("AI.Proxy",complete,function() return avatar==nil or avatar.isSmoothMoving()==false end,3.5,complete)
	end,2)
end

function proxyAnimateRoute(route,index,target,hazard,lastSafe,hexes,mapObjects,proxyIndex)
	local avatar=proxyAvatarObject()
	if avatar==nil then proxyFinishTurn(hexes,mapObjects,proxyIndex) return end
	if route[index]==nil then
		local current=runtimeMapHexForPosition(hexes,avatar.getPosition(),mapObjects)
		if hazard~=nil or (target~=nil and current~=nil and runtimeMapHexKey(current)==runtimeMapHexKey(target.hex)) then proxyResolveArrival(target,hazard,lastSafe,hexes,mapObjects,proxyIndex)
		else
			if gStates.proxyTurnReport~=nil and gStates.proxyTurnReport.action==nil then proxyTurnReportSetAction("moved toward the "..proxyTargetDisplayName(target).."\nbut did not reach it") end
			proxyFinishTurn(hexes,mapObjects,proxyIndex)
		end
		return
	end
	proxyAnimateStep(route[index],hexes,mapObjects,proxyIndex,function() proxyAnimateRoute(route,index+1,target,hazard,lastSafe,hexes,mapObjects,proxyIndex) end)
end

function proxyContinueTowardTarget(target,proxyIndex,move,preserveMoved)
	local avatar=proxyAvatarObject()
	local hexes,mapObjects=runtimeMapHexesAndObjects()
	if avatar==nil then proxyFinishTurn(hexes,mapObjects,proxyIndex) return end
	local startHex=runtimeMapHexForPosition(hexes,avatar.getPosition(),mapObjects)
	if startHex==nil then proxyFinishTurn(hexes,mapObjects,proxyIndex) return end
	proxyRevealGarrisonsAtHex(startHex,hexes,mapObjects,proxyIndex)
	proxyTurnReportSetTarget(target)
	if preserveMoved~=true then proxyTurnReportSetMoved(0) end
	--Publish the intended destination and full allowance before physical movement begins.
	automatedMainPanelRefresh()
	local routeChoice,routeContext=proxyFindRouteChoice(startHex,target,hexes,mapObjects,proxyIndex,move or 0)
	if routeChoice~=nil and proxyBeginRouteChoice(routeChoice,target,proxyIndex,move)==true then return end
	local route,hazard,lastSafe=proxyPlanRoute(startHex,target,hexes,mapObjects,proxyIndex,move or 0,nil,routeContext)
	if #route==0 and runtimeMapHexKey(startHex)==runtimeMapHexKey(target.hex) then proxyResolveArrival(target,nil,startHex,hexes,mapObjects,proxyIndex)
	else proxyAnimateRoute(route,1,target,hazard,lastSafe,hexes,mapObjects,proxyIndex) end
end

function proxyClearPendingChoice()
	local pending=gStates.proxyPendingChoice
	if pending~=nil then
		if pending.type=="destination" or pending.type=="route" then proxyChoiceMapRefresh(nil)
		elseif pending.type=="card" then proxyInteractionChoiceClearButtons(pending)
		elseif pending.type=="enemy" then proxyEnemyChoiceClearButtons(pending) end
	end
	proxyManaChoiceUI(nil)
	gStates.proxyPendingChoice=nil
end

function proxyRestorePendingChoiceUI()
	local pending=gStates.proxyPendingChoice
	if pending==nil then proxyManaChoiceUI(nil) return end
	if pending.type=="destination" then gStates.proxyState="PickDestination"
	elseif pending.type=="route" then gStates.proxyState="PickRoute"
	elseif pending.type=="card" then gStates.proxyState="PickCard"
	elseif pending.type=="enemy" then gStates.proxyState="PickEnemy"
	elseif pending.type=="mana" then gStates.proxyState="PickMana" end
	if pending.type=="destination" or pending.type=="route" then proxyChoiceMapRefresh(pending)
	elseif pending.type=="card" then
		for _,guid in ipairs(pending.order or {}) do local card=getObjectFromGUID(guid) if card~=nil then proxyInteractionChoiceButton(card) end end
	elseif pending.type=="enemy" then
		for _,guid in ipairs(pending.order or {}) do local enemy=getObjectFromGUID(guid) if enemy~=nil then proxyEnemyChoiceButton(enemy) end end
	elseif pending.type=="mana" then proxyManaChoiceUI(pending) end
end

function proxyContinueAfterMovementSetup(proxyIndex,move,crystals)
	if gStates.turnNumber~=proxyIndex then automatedTurnRewindRelease() return end
	local avatar=proxyAvatarObject()
	local objectiveNow=proxyObjectiveObject()
	local hexes,mapObjects=runtimeMapHexesAndObjects()
	if avatar==nil or objectiveNow==nil then proxyFinishTurn(hexes,mapObjects,proxyIndex) return end
	local startHex=runtimeMapHexForPosition(hexes,avatar.getPosition(),mapObjects)
	if startHex==nil then proxyFinishTurn(hexes,mapObjects,proxyIndex) return end
	local target=proxyChooseTarget(objectiveNow,hexes,mapObjects,proxyIndex,crystals or proxySnapshotCrystals(turnOrder[proxyIndex]),startHex,move)
	if target==nil then
		proxyTurnReportSetAction("had no legal objective or exploration destination")
		if gStates.proxyTurnReport~=nil then gStates.proxyTurnReport.reason="No legal target or exploration point was available." end
		broadcastToAll("{en}Proxy has no legal objective or exploration destination.{ru}У Прокси нет допустимой цели или места исследования.{zh-tw}代理玩家沒有合法目標或探索目的地。{zh-cn}代理玩家没有合法目标或探索目的地。{ko}프록시에게 합법적인 목표나 탐험 목적지가 없습니다.{es}El Proxy no tiene objetivo legal ni destino de exploración.{fr}Le Proxy n’a aucun objectif légal ni destination d’exploration.{pt-br}O Proxy não tem objetivo válido nem destino de exploração.{de}Der Proxy hat kein gültiges Ziel oder Erkundungsziel.",{1,0.65,0.2})
		proxyFinishTurn(hexes,mapObjects,proxyIndex)
		return
	end
	--Publish the selected objective before a tied destination can pause for human input. This lets the
	--Proxy Info panel explain what they are trying to do before the Pick Destination button appears.
	proxyTurnReportSetTarget(target)
	if target.proxyChoiceTargets~=nil and #target.proxyChoiceTargets>1 then
		if proxyDestinationChoiceMattersThisTurn(target.proxyChoiceTargets,startHex,hexes,mapObjects,proxyIndex,move)==true then
			if proxyBeginDestinationChoice(target.proxyChoiceTargets,proxyIndex,move,target.proxyReason)==true then return end
		else
			target.proxyChoiceTargets=nil target.proxyChoiceCount=nil target.proxyChoiceRouteReason=nil
		end
	end
	proxyContinueTowardTarget(target,proxyIndex,move)
end

function proxyProcessTurn(proxyIndex)
	if gStates.turnNumber~=proxyIndex then automatedTurnRewindRelease() return end
	local stats=turnOrder[proxyIndex]
	if stats==nil or stats.mage~=gStates.positionMageKnight[5] then automatedTurnRewindRelease() return end
	stats.dummyProcessedThisTurn=true
	gStates.proxyState="Processing"
	gStates.proxyTurnReport=nil
	proxyClearPendingChoice()
	automatedMainPanelRefresh()
	local avatar=proxyAvatarObject()
	local hexes,mapObjects=runtimeMapHexesAndObjects()
	local portal=proxyPortalHex(hexes)
	if avatar==nil or portal==nil then gStates.proxyTurnReport={moved=0,action="could not find their Hero or Portal",reason="Setup could not provide both required objects.",allowance=0} broadcastToAll("{en}Proxy Player could not find its Hero or Portal.{ru}Прокси-игрок не смог найти своего Героя или Портал.{zh-tw}代理玩家找不到英雄或傳送門。{zh-cn}代理玩家找不到英雄或传送门。{ko}프록시 플레이어가 영웅 또는 포털을 찾지 못했습니다.{es}El jugador Proxy no pudo encontrar su Héroe o Portal.{fr}Le joueur Proxy n’a pas pu trouver son Héros ou le Portail.{pt-br}O jogador Proxy não conseguiu encontrar seu Herói ou o Portal.{de}Der Proxy-Spieler konnte seinen Helden oder das Portal nicht finden.",{1,0.25,0.25}) proxyFinishTurn(hexes,mapObjects,proxyIndex) return end
	local physicalStartHex=runtimeMapHexForPosition(hexes,avatar.getPosition(),mapObjects)
	if physicalStartHex==nil then
		avatar.unlock() avatar.setPosition({portal.position[1],1.5,portal.position[3]}) gStates.proxyAvatarOffMap=false
		stats.avatarLocation=gStates.gameScenario=="Against the Horsemen Blitz" and "glade" or "portal"
		if gStates.gameScenario=="Against the Horsemen Blitz" then stats.avatarSharedHex=againstHorsemenSharedHexKey end
	else gStates.proxyAvatarOffMap=false end
	local crystals=proxySnapshotCrystals(stats)
	local objective=proxyObjectiveObject()
	local lastCard=nil
	if objective~=nil then proxyAddObjectiveShield() lastCard=automatedDeedDraw(stats.seatPos,3,1)
	else
		objective=proxyDrawObjective(stats.seatPos)
		local drawn=0
		lastCard,drawn=automatedDeedDraw(stats.seatPos,2,1)
		if drawn==0 then lastCard=objective end
	end
	local bonus=0
	if lastCard~=nil then for _,color in ipairs(dummyCardColors(lastCard)) do bonus=bonus+(crystals[color] or 0) end end
	safeWaitTime("AI.Proxy",function()
		if bonus>0 then automatedDeedDraw(stats.seatPos,bonus,2) end
		local objectiveNow=proxyObjectiveObject()
		if objectiveNow==nil then proxyFinishTurn(hexes,mapObjects,proxyIndex) return end
		local colors=dummyCardColors(objectiveNow)
		local baseMove=proxyObjectiveBaseMove(objectiveNow)
		local shieldMove=#(gStates.proxyObjectiveShieldGUIDs or {})
		local sourceUsed,manaOptions=proxyUseSourceMana(colors)
		local willUseSource=sourceUsed==true or manaOptions~=nil
		local move=baseMove+shieldMove+(willUseSource and 1 or 0)
		proxyTurnReportBegin(objectiveNow,colors,baseMove,shieldMove,willUseSource)
		broadcastToAll(joinLang({translateWord[stats.mage],"{en} Proxy may move {ru} прокси может переместиться на {zh-tw} 代理可移動 {zh-cn} 代理可移动 {ko} 프록시는 {es} Proxy puede mover {fr} Proxy peut se déplacer de {pt-br} Proxy pode mover {de} Proxy darf sich ",tostring(move),"{en} spaces.{ru} гексов.{zh-tw} 格。{zh-cn} 格。{ko}칸 이동할 수 있습니다.{es} espacios.{fr} cases.{pt-br} espaços.{de} Felder bewegen."}),{1,0.75,0.2})
		if manaOptions~=nil and #manaOptions>1 then
			if proxyBeginManaChoice(manaOptions,proxyIndex,move,crystals)==true then return end
			proxyRerollSourceManaGUID(manaOptions[1].guid,manaOptions[1].color)
		end
		proxyContinueAfterMovementSetup(proxyIndex,move,crystals)
	end,1.4)
end

function proxyTurn(player,mouseButton,id)
	if mouseButton~="-1" or proxyPlayerIsActive()~=true then return end
	if gStates.tacticShown==true then
		automatedTurnRewindStart(function()
			automatedPlayerRandomTactic()
			gStates.proxyState="Start"
			nextTurnMerged("incrementTurn")
			automatedTacticRewindRelease()
		end)
		return
	end
	if gStates.endRoundCalled==true then return end
	local proxyIndex=gStates.turnNumber
	local stats=turnOrder[proxyIndex]
	if stats==nil or stats.mage~=gStates.positionMageKnight[5] then return end
	--The completed state is deliberately a second click, matching Volkare's visible confirmation flow.
	if gStates.proxyState=="ReadyToEnd" then
		gStates.proxyState="Start"
		nextTurnMerged("incrementTurn")
		return
	end
	if gStates.proxyState=="Processing" or gStates.proxyState=="PickDestination" or gStates.proxyState=="PickRoute" or gStates.proxyState=="PickCard" or gStates.proxyState=="PickEnemy" or gStates.proxyState=="PickMana" then return end
	if readDeedPileCardCount(stats.seatPos)==0 then dummyRefreshDeedState(stats.seatPos) PreEndRound({color="Black"},"-1","DummyButton") return end
	if stats.dummyProcessedThisTurn==true then return end
	--Give immediate visual feedback before the rewind transaction callback starts without mutating
	--the saved Proxy state until the protected transaction begins.
	automatedMainPanelRefresh(automatedProxyPanelSpec(stats,"Processing"))
	automatedTurnRewindStart(function() proxyProcessTurn(proxyIndex) end)
end

end)
__bundle_register("PlayingGame.AI.Common", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Shared automated-player helpers for Dummy, Proxy and Volkare.

--The combined-defense choice is a transient lock; it does not need to be saved with the game.
dropoutCoopDefensePrompt=false

--Get's the dummy to pick a tactic card
function dummyRefreshDeedState(seatPos)
	if seatPos==nil then return end
	local newCount=readDeedPileCardCount(seatPos)
	deedPileCardCount[seatPos]=newCount
	endRoundDeedHasCards[seatPos]=newCount>0
	if gStates.turnNumber~=nil and turnOrder[gStates.turnNumber]~=nil and turnOrder[gStates.turnNumber].seatPos==seatPos then endRoundUIStateKey=nil refreshEndRoundState() end
end

--Compatibility names for the three automated-player systems.
function automatedTurnRewindStart(andThen) return rewindTransactionStart(andThen,"Automated turn") end
function automatedTurnRewindRelease() rewindTransactionFinish("Automated turn") end

function automatedTacticRewindRelease()
	--The tactic itself moves smoothly after the turn advances, so keep rewind storage blocked briefly.
	safeWaitTime("AI.Common",automatedTurnRewindRelease,1.5)
end

function volkareReleaseRewindWhenStable()
	if rewindTransactionOwnerActive("Automated turn")~=true then return end
	local v=getObjectFromGUID(gStates.volkareModel)
	if v==nil or (v.resting and v.isSmoothMoving()==false) then automatedTurnRewindRelease() return end
	safeWaitCondition("AI.Common",automatedTurnRewindRelease,function()
		local current=getObjectFromGUID(gStates.volkareModel)
		return current==nil or (current.resting and current.isSmoothMoving()==false)
	end,8,function()
		local current=getObjectFromGUID(gStates.volkareModel)
		if current~=nil then
			current.setPosition(current.getPosition())
			current.setVelocity({0,0,0})
			current.setAngularVelocity({0,0,0})
			if gStates.volkareLock~=false then current.lock() end
		end
		automatedTurnRewindRelease()
	end)
end

--Dummy and Volkare both use the center random-Tactic button, but their actual turns are processed separately.
function automatedPlayerRandomTactic()
	local dummyTactic=nil
	local claimedCard=nil
	while dummyTactic==nil do
		dummyTactic=math.random(1,6)
		for _, obj in pairs(getObjectFromGUID(tacticZones[dummyTactic]).getObjects()) do
			if isTacticCard(obj) then claimedCard=obj break end
		end
		if claimedCard==nil then dummyTactic=nil end
	end
	broadcastToAll(joinLang({gStates.positionMageKnight[5]=="Volkare" and "{en}Volkare RANDOMLY gained Tactic for {ru}Волкар получает СЛУЧАЙНУЮ Тактику для {zh-tw}沃卡里隨機選取戰術給{zh-cn}沃卡里随机选取战术给{ko}볼케어가 무작위 전략을 가져갑니다: {es}Volkare ganó ALEATORIAMENTE Táctica para {fr}Volkare a gagné au hasard une Tactique pour {pt-br}Volkare ALEATORIAMENTE ganhou a Tática por {de}Volkare hat ZUFÄLLIG eine Taktik für " or (proxyPlayerIsActive()==true and "{en}Proxy RANDOMLY gained Tactic for {ru}Прокси получает СЛУЧАЙНУЮ Тактику для {zh-tw}代理玩家隨機選取戰術給{zh-cn}代理玩家随机选取战术给{ko}프록시가 무작위 전략을 가져갑니다: {es}Proxy ganó ALEATORIAMENTE Táctica para {fr}Le Proxy a gagné au hasard une Tactique pour {pt-br}Proxy ALEATORIAMENTE ganhou a Tática por {de}Proxy hat ZUFÄLLIG eine Taktik für " or "{en}Dummy RANDOMLY gained Tactic for {ru}Виртуальный игрок получает СЛУЧАЙНУЮ Тактику для {zh-cn}虚拟玩家随机选取战术给{ko}가상 플레이어가 무작위의 전략 카드를 가져갑니다: {es}Dummy ganada ALEATORIAMENTE Táctica para {fr}Le mannequin a gagné au hasard une Tactique pour {pt-br}Jog. Fictício ALEATORIAMENTE ganhou a Tática por {de}Dummy hat ZUFÄLLIG eine Taktik für "), translateWord[turnOrder[gStates.turnNumber].mage]}), positionToColor(gStates.turnNumber))
	if claimedCard~=nil then
		claimedCard.unlock()
		claimedCard.setPositionSmooth({getObjectFromGUID(dummyBoard).getPosition()[1], 3.0, getObjectFromGUID(dummyBoard).getPosition()[3]-5.17})
	end
	turnOrder[gStates.turnNumber].tactic=dummyTactic
end

--Draw from an automated player's Deed pile without ever calling takeObject on a Deck after it collapses to its final Card.
--The returned card is the last card actually flipped, even when fewer cards were available than requested.
function automatedDeedDraw(seatPos, cardCount, passIndex)
	if seatPos==nil or cardCount==nil or cardCount<=0 then return nil,0 end
	local deedZone=getObjectFromGUID(deedDeckZones[seatPos])
	local discardZone=getObjectFromGUID(deedDeckDiscardZones[seatPos])
	if deedZone==nil or discardZone==nil then return nil,0 end
	local pile=nil
	for _, obj in pairs(deedZone.getObjects()) do
		if obj.type=="Deck" or obj.type=="Card" then pile=obj break end
	end
	if pile==nil then return nil,0 end
	local destination=discardZone.getPosition()
	local passOffset=((passIndex or 1)-1)*4.5
	local drawn=0
	local lastCard=nil
	local function destinationFor(drawIndex) return {destination[1], destination[2]+(drawIndex*1.5)+passOffset, destination[3]} end
	if pile.type=="Card" then
		pile.setPositionSmooth(destinationFor(1))
		pile.setRotationSmooth({0,180,0})
		return pile,1
	end
	local quantity=pile.getQuantity()
	local takeCount=math.min(cardCount, math.max(quantity-1,0))
	for i=1,takeCount do
		local taken=pile.takeObject({position=destinationFor(i), rotation={0,180,0}})
		if taken==nil then break end
		drawn=drawn+1
		lastCard=taken
	end
	--Taking the second-last card destroys a TTS Deck. If this draw is meant to empty it,
	--move the spawned remainder instead of calling takeObject on the destroyed Deck reference.
	if cardCount>=quantity and drawn==quantity-1 then
		local remainder=pile.remainder
		if remainder~=nil then
			drawn=drawn+1
			remainder.setPositionSmooth(destinationFor(drawn))
			remainder.setRotationSmooth({0,180,0})
			lastCard=remainder
		end
	end
	return lastCard,drawn
end

function dummyCardColors(card)
	local colors={}
	if card~=nil and gameCards[card.guid]~=nil and type(gameCards[card.guid].color)=="table" then
		for _, color in ipairs(gameCards[card.guid].color) do if color=="Red" or color=="Green" or color=="Blue" or color=="White" then colors[#colors+1]=color end end
	end
	if #colors==0 and card~=nil then
		for color in tostring(card.getDescription()):gmatch("%a+") do if color=="Red" or color=="Green" or color=="Blue" or color=="White" then colors[#colors+1]=color end end
	end
	return colors
end

end)
__bundle_register("PlayingGame.Scoring", function(require, _LOADED, __bundle_register, __bundle_modules)
-- End-game scoring and Hero Challenge scoring runtime.

--Hero Challenges are an optional Apocalypse-rulebook overlay. Keep all scoring/objective
--math here so the underlying scenario can retain its normal victory and end conditions.
local function heroChallengeActive(playerIndex)
	return gStates~=nil and gStates.heroChallenges==true and turnOrder[playerIndex]~=nil and heroChallengesData[turnOrder[playerIndex].mage]~=nil
end

local function heroChallengeRecordCard(stats, guid)
	if stats==nil or guid==nil or stats.cardSeen[guid]==true then return end
	stats.cardSeen[guid]=true
	local card=gameCards[guid]
	if card==nil then return end
	if card.cardType=="Starting" then stats.basicActions=stats.basicActions+1 end
	if card.cardType=="Advanced Action" then
		local colors={}
		for _,color in ipairs(card.color or {}) do colors[color]=true end
		stats.aaCards[guid]=colors
	end
end

local function heroChallengeCrystalColor(obj)
	if obj==nil then return nil end
	local note=obj.getGMNotes()
	if note=="Red" or note=="Blue" or note=="Green" or note=="White" then return note end
	local name=tostring(obj.getName() or "")
	for _,color in ipairs({"Red","Blue","Green","White"}) do if name:find(color,1,true)~=nil then return color end end
	return nil
end

--Hero Challenge scoring counts only Puppets explicitly accepted by the Puppet Master system.
local function heroChallengePuppetFame(obj)
	if obj==nil or gStates.puppetMasterPuppets==nil then return nil end
	local record=gStates.puppetMasterPuppets[obj.guid]
	if record==nil or record.played==true then return nil end
	local source=record.sourceGUID~=nil and monsterPugs[record.sourceGUID] or nil
	local fame=source~=nil and tonumber(source.fame) or 0
	if fame>0 then return fame end
	return nil
end

--A dual-colour Advanced Action may satisfy only one colour. Matching four colours to four distinct
--cards implements that directly instead of simply checking whether every colour appears somewhere.
local function heroChallengeAACoversAllColors(stats)
	if stats==nil then return false end
	local colors={"Red","Blue","Green","White"}
	local used={}
	local function assign(index)
		if index>#colors then return true end
		for guid,cardColors in pairs(stats.aaCards or {}) do
			if used[guid]~=true and cardColors[colors[index]]==true then
				used[guid]=true
				if assign(index+1)==true then return true end
				used[guid]=nil
			end
		end
		return false
	end
	return assign(1)
end

local function heroChallengeFinalMapPosition(playerIndex)
	local player=turnOrder[playerIndex]
	if player==nil then return nil end
	--Shared map spaces park inactive avatars off-map. Score the logical hex, not the storage position.
	if againstHorsemenPlayerAtCentralGlade(player)==true then return againstHorsemenCentralGladePosition(1.5) end
	if player.avatarLocation=="portal" then
		local startTile=getObjectFromGUID(startTerrain.wedge) or getObjectFromGUID(startTerrain.open)
		if startTile~=nil then
			local pos=startTile.getPosition()
			pos[2]=1.5
			return pos
		end
	end
	return fracturedLandsTeleportSourcePosition(playerIndex)
end

local function heroChallengeFinalTerrainBonus(playerIndex, objectsInPlay)
	if heroChallengeActive(playerIndex)~=true or turnOrder[playerIndex].mage~="Braevalar" then return 0 end
	local pos=heroChallengeFinalMapPosition(playerIndex)
	if pos==nil then return 0 end
	local _,_,_,_,hexType=terrainHexAtPosition(pos,objectsInPlay)
	local nightCost={plains=2,hills=3,forest=5,wasteland=4,desert=3,swamp=5,lake=2,mountain=5,city=2}
	return nightCost[string.lower(tostring(hexType or ""))] or 0
end

local function heroChallengeBeatingScore(playerIndex)
	if heroChallengeActive(playerIndex)==true and turnOrder[playerIndex].mage=="Arythea" then return 0 end
	return turnOrder[playerIndex].score.Wound*2
end

local function heroChallengeKnowledgeScore(playerIndex)
	local score=turnOrder[playerIndex].score
	local mage=heroChallengeActive(playerIndex) and turnOrder[playerIndex].mage or nil
	local aaRate=mage=="Braevalar" and 2 or 1
	local spellRate=mage=="Goldyx" and 3 or 2
	return (score.AdvanceAction*aaRate)+(score.Spell*spellRate)
end

local function heroChallengeLootScore(playerIndex)
	local score=turnOrder[playerIndex].score
	local mage=heroChallengeActive(playerIndex) and turnOrder[playerIndex].mage or nil
	local artifactRate=mage=="Coral" and 4 or 2
	local crystalScore=(mage=="Goldyx" or mage=="Coral") and score.Crystal or math.floor(score.Crystal/2)
	return (score.Artifact*artifactRate)+crystalScore+score.Potion
end

local function heroChallengeLeaderScore(playerIndex)
	local score=turnOrder[playerIndex].score
	local mage=heroChallengeActive(playerIndex) and turnOrder[playerIndex].mage or nil
	local healthy=mage=="Norowas" and score.UnitsLevel*2 or score.UnitsLevel
	local wounded=mage=="Arythea" and score.WoundedUnitsRawLevel or score.WoundedUnitsLevel
	return healthy+wounded
end

local function heroChallengeAdventurerScore(playerIndex, ref)
	local score=turnOrder[playerIndex].score
	local wolfhawk=heroChallengeActive(playerIndex) and turnOrder[playerIndex].mage=="Wolfhawk"
	if ref==2 then
		return (score.DungeonTomb*4)+(score.SpawningDen+score.Ruin+score.Maze+score.ZigguratPyramid)*(wolfhawk and 4 or 2)
	end
	if ref==4 then
		return (score.ZigguratPyramid*5)+(score.SpawningDen+score.Ruin+score.Maze+score.DungeonTomb)*(wolfhawk and 4 or 2)
	end
	return (score.DungeonTomb+score.SpawningDen+score.Ruin+score.Maze+score.ZigguratPyramid)*(wolfhawk and 4 or 2)
end

local function heroChallengeConquerorScore(playerIndex)
	local score=turnOrder[playerIndex].score
	local rate=heroChallengeActive(playerIndex) and turnOrder[playerIndex].mage=="Tovak" and 4 or 2
	return ((score.Keep+score.MageTower+score.Monastery)*rate)+score.VolkareCamp
end

local function heroChallengeEvaluate(playerIndex, objectsInPlay)
	if heroChallengeActive(playerIndex)~=true then return nil end
	local playerData=turnOrder[playerIndex]
	local score=playerData.score
	local stats=playerData.heroChallengeStats or {crystalColors={},puppetFame={},basicActions=0,aaCards={}}
	local complete=false
	local details=""
	local extraBonus=0
	if playerData.mage=="Arythea" then
		local wounds=score.Wound+score.WoundedUnits
		complete=wounds>=10 details="Wounds "..tostring(wounds).." / 10"
	elseif playerData.mage=="Goldyx" then
		local colors=0 for _,color in ipairs({"Red","Blue","Green","White"}) do if stats.crystalColors[color]==true then colors=colors+1 end end
		complete=score.Spell>=4 and colors==4 details="Spells "..tostring(score.Spell).." / 4; crystal colours "..tostring(colors).." / 4"
	elseif playerData.mage=="Norowas" then
		local levels=score.UnitsLevel+score.WoundedUnitsRawLevel
		complete=levels>=10 details="Unit levels "..tostring(levels).." / 10"
	elseif playerData.mage=="Tovak" then
		local shields=score.Keep+score.MageTower+score.Monastery+score.VolkareCamp
		complete=shields>=4 details="Conqueror Shields "..tostring(shields).." / 4"
	elseif playerData.mage=="Wolfhawk" then
		local shields=score.DungeonTomb+score.SpawningDen+score.Ruin+score.Maze+score.ZigguratPyramid
		complete=shields>=4 details="Adventurer Shields "..tostring(shields).." / 4"
	elseif playerData.mage=="Krang" then
		local count=0 local highest=0
		for fame,_ in pairs(stats.puppetFame) do count=count+1 if fame>highest then highest=fame end end
		complete=count>=4 details="Puppet Master Fame values "..tostring(count).." / 4"
		extraBonus=highest+(count*2)
	elseif playerData.mage=="Braevalar" then
		local colors=heroChallengeAACoversAllColors(stats)
		complete=stats.basicActions>=16 and colors==true
		details="Basic Actions "..tostring(stats.basicActions).." / 16; four AA colours "..(colors and "yes" or "no")
		extraBonus=heroChallengeFinalTerrainBonus(playerIndex,objectsInPlay)
	elseif playerData.mage=="Coral" then
		complete=score.Artifact>=3 and score.Crystal>=4 details="Artifacts "..tostring(score.Artifact).." / 3; crystals "..tostring(score.Crystal).." / 4"
	end
	return {complete=complete,details=details,extraBonus=extraBonus}
end

scoreViewing={}
function closePanel(player, mouseButton, id)
	if mouseButton=="-1" then
		UI.setAttribute("helpButtonReal", "interactable", "true")
		UI.setAttribute("Setup", "active", "false")
		UI.setAttribute("helpButtonRealImage", "image", "Sliced Button/Button New Active")
		UI.setAttribute("helpButtonReal", "interactable", "true")
		local temp={}
		for a=1, #scoreViewing, 1 do
			if scoreViewing[a]~=player.color then temp[#temp+1]=scoreViewing[a] end
		end
		scoreViewing=temp
		if #scoreViewing<1 then
			UI.hide("ScoreBoard")
			scoreViewing={}
		else
			local visibility=""
			for a=1, #scoreViewing, 1 do
				visibility=visibility..scoreViewing[a]
				if a<#scoreViewing then visibility=visibility.."|" end
			end
			UI.setAttribute("ScoreBoard", "visibility", visibility)
		end
	end
end

function displayScore(player, mouseButton, id)
	if mouseButton=="-1" then
		--Count all objects required for scoring
		local seatRecord=5
		for a=1, #turnOrder, 1 do
			if turnOrder[a].mage==gStates.positionMageKnight[5] then
				seatRecord=turnOrder[a].seatPos
				turnOrder[a].seatPos=5
				break
			end
		end
		table.sort(turnOrder, function (k1, k2) return k1.seatPos<k2.seatPos end)
		for a=1, #turnOrder, 1 do
			if turnOrder[a].mage==gStates.positionMageKnight[5] then
				turnOrder[a].seatPos=seatRecord
				break
			end
		end
		local foundRelic=0--Not individually scored
		local coopGraveYard=0
		local objectsInPlay=getObjectFromGUID(mapArea).getObjects()
		table.sort(objectsInPlay, function (k1, k2) return k1.getPosition()[2]>k2.getPosition()[2] end)
		for a=1, #turnOrder, 1 do
			if turnOrder[a].mage~=gStates.positionMageKnight[5] then
				local obj={}
				local cardDupeCheck={}--Scoring zones can overlap; de-duplicate every physical/deck card by GUID.
				turnOrder[a].heroChallengeStats={cardSeen={},basicActions=0,aaCards={},crystalColors={},puppetFame={}}
				local heroStats=turnOrder[a].heroChallengeStats
				for b, c in pairs(objectsInPlay) do obj[#obj+1]=c end
				--Look for Cards
				for b, c in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				for b, c in pairs(getObjectFromGUID(deedDeckDiscardZones[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				for b, c in pairs(getObjectFromGUID(handZones[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				for b, c in pairs(getObjectFromGUID(playerPlayAreas[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				--look for Crystals, rewards and Hero Challenge inventory trophies
				local inventoryObjects=getObjectFromGUID(playerCrystalAreas[turnOrder[a].seatPos]).getObjects()
				for b, c in pairs(inventoryObjects) do
					obj[#obj+1]=c
					if heroChallengeActive(a)==true then
						local crystalColor=heroChallengeCrystalColor(c)
						if crystalColor~=nil then heroStats.crystalColors[crystalColor]=true end
						if turnOrder[a].mage=="Krang" then
							local puppetFame=heroChallengePuppetFame(c)
							if puppetFame~=nil then heroStats.puppetFame[puppetFame]=true end
						end
					end
				end
				--look for Units
				local playerUnits=getObjectFromGUID(playerUnitAreas[turnOrder[a].seatPos]).getObjects()
				for b, c in pairs(playerUnits) do obj[#obj+1]=c end
				--Zero out any existing scores
				local scoreVariable={"AdvanceAction", "Spell", "Artifact", "Wound", "Crystal", "Potion", "Units", "UnitsLevel", "WoundedUnits", "WoundedUnitsLevel", "WoundedUnitsRawLevel", "Keep", "Reward", "GraveYard", "Glade",
									"MageTower", "Monastery", "VolkareCamp", "DungeonTomb", "SpawningDen", "Ruin", "Maze", "Relic", "CountryMine", "CoreMine", "ZigguratPyramid", "Destroyed",
									"Zig1", "Zig2", "Zig3", "Pyr1", "Pyr2", "Pyr3"}
				for b, c in pairs(scoreVariable) do
					turnOrder[a].score[c]=0
				end
				--count found objects
				for b, c in pairs(obj) do
					--Count Card Types
					if c.type=="Card" then
						heroChallengeRecordCard(heroStats,c.guid)
						if c.getGMNotes()=="Advanced Action" and cardDupeCheck[c.guid]==nil then turnOrder[a].score.AdvanceAction=turnOrder[a].score.AdvanceAction+1 cardDupeCheck[c.guid]=1 end
						if c.getGMNotes()=="Spell" and cardDupeCheck[c.guid]==nil then turnOrder[a].score.Spell=turnOrder[a].score.Spell+1 cardDupeCheck[c.guid]=1 end
						if c.getGMNotes()=="Artifact" and cardDupeCheck[c.guid]==nil then turnOrder[a].score.Artifact=turnOrder[a].score.Artifact+1 cardDupeCheck[c.guid]=1 end
						if c.getGMNotes()=="Wound" and cardDupeCheck[c.guid]==nil then turnOrder[a].score.Wound=turnOrder[a].score.Wound+1 cardDupeCheck[c.guid]=1 end
						if gameCardType(c)=="Regular Unit" or gameCardType(c)=="Elite Unit" then
							--Look for a wound whose nearest Unit is this card. This remains unambiguous after elastic compression.
							local found=false
							for e, woundToken in pairs(playerUnits) do
								if woundToken.getGMNotes()=="Unit Wound" then
									local nearestUnit, distance=unitLayoutNearestUnit(playerUnits,woundToken.getPosition()[1])
									if nearestUnit~=nil and nearestUnit.guid==c.guid and distance<=1.7 then
										turnOrder[a].score.WoundedUnits=turnOrder[a].score.WoundedUnits+1
										turnOrder[a].score.WoundedUnitsLevel=turnOrder[a].score.WoundedUnitsLevel+math.floor(gameCards[c.guid].level/2)
										turnOrder[a].score.WoundedUnitsRawLevel=turnOrder[a].score.WoundedUnitsRawLevel+gameCards[c.guid].level
										found=true
										break
									end
								end
							end
							if found==false then
								turnOrder[a].score.Units=turnOrder[a].score.Units+1
								turnOrder[a].score.UnitsLevel=turnOrder[a].score.UnitsLevel+gameCards[c.guid].level
							end
						end
				 	end
					if c.type=="Deck" then
						for _, card in pairs(c.getObjects()) do
							heroChallengeRecordCard(heroStats,card.guid)
							if cardDupeCheck[card.guid]==nil then
								if card.gm_notes=="Advanced Action" then turnOrder[a].score.AdvanceAction=turnOrder[a].score.AdvanceAction+1 cardDupeCheck[card.guid]=1
								elseif card.gm_notes=="Spell" then turnOrder[a].score.Spell=turnOrder[a].score.Spell+1 cardDupeCheck[card.guid]=1
								elseif card.gm_notes=="Artifact" then turnOrder[a].score.Artifact=turnOrder[a].score.Artifact+1 cardDupeCheck[card.guid]=1
								elseif card.gm_notes=="Wound" then turnOrder[a].score.Wound=turnOrder[a].score.Wound+1 cardDupeCheck[card.guid]=1 end
							end
						end
					end
					--count Crystals
					if c.type=="Figurine" then
						if c.getPosition()[1]<turnOrder[a].seatPos*40-109.76 and c.getPosition()[3]<-31 then turnOrder[a].score.Crystal=turnOrder[a].score.Crystal+1 end
					end
					--count Destroyed Tokens
					if c.getGMNotes()=="Destroyed" then
						if c.getPosition()[1]<turnOrder[a].seatPos*40-109.76 and c.getPosition()[3]<-31 then turnOrder[a].score.Destroyed=turnOrder[a].score.Destroyed+1 end
					end
					--count Faction Rewards
					if c.type=="Tile" then
						if c.getPosition()[1]<turnOrder[a].seatPos*40-109.76 and c.getPosition()[3]<-31 then
							if c.getName()~="Red Potion" and c.getName()~="Blue Potion" and c.getName()~="Green Potion" and c.getName()~="White Potion" then
								if c.getGMNotes()=="Dark Crusader Reward" or c.getGMNotes()=="Elementalist Reward" or c.getGMNotes()=="Apocalypse Cult Reward" or c.getGMNotes()=="Council of the Void Reward" then turnOrder[a].score.Reward=turnOrder[a].score.Reward+1 end
							else
								turnOrder[a].score.Potion=turnOrder[a].score.Potion+1
							end
						end
					end
					--Count Shield tokens. Pursuit shields score only as Pursuits, never also as the printed site below.
					if c.getName()=="Shield" and c.getDescription()==turnOrder[a].mage then
						if volkarePursuitShieldRegistered(c)==true then
							turnOrder[a].score.VolkareCamp=turnOrder[a].score.VolkareCamp+1
						else
							local found=false
						local shieldPos=c.getPosition()
						local locatedTerrain, locatedBearing, hexCenter, hexFeature=terrainHexAtPosition(shieldPos, objectsInPlay)
						--Destroyed Sites no longer exist for gameplay, but their existing Shields still score
						--as the original printed site. Recover that saved feature for scoring only.
						if hexFeature=="destroyed" and locatedTerrain~=nil and locatedBearing~=nil then
							for _,destroyedData in pairs(gStates.destroyedSites or {}) do
								if destroyedData.terrainTile==locatedTerrain.guid and destroyedData.hexAngle==locatedBearing then
									hexFeature=destroyedData.hexFeature
									break
								end
							end
						end
						for e, terTile in pairs(objectsInPlay) do
							local tilePos=terTile.getPosition()
							local shieldToTileDist=math.sqrt(((shieldPos[1]-tilePos[1])^2)+((shieldPos[3]-tilePos[3])^2))
							if terTile==locatedTerrain then
								found=true
								if hexFeature=="keep" then turnOrder[a].score.Keep=turnOrder[a].score.Keep+1 end
								if hexFeature=="mage tower" then turnOrder[a].score.MageTower=turnOrder[a].score.MageTower+1 end
								if hexFeature=="monastery" then turnOrder[a].score.Monastery=turnOrder[a].score.Monastery+1 end
								if hexFeature=="ruin" then turnOrder[a].score.Ruin=turnOrder[a].score.Ruin+1 end
								if hexFeature=="glade" then turnOrder[a].score.Glade=turnOrder[a].score.Glade+1 end
								if hexFeature=="dungeon" or hexFeature=="tomb" then turnOrder[a].score.DungeonTomb=turnOrder[a].score.DungeonTomb+1 end
								if hexFeature=="monster den" or hexFeature=="spawning grounds" then turnOrder[a].score.SpawningDen=turnOrder[a].score.SpawningDen+1 end
								if hexFeature=="maze" or hexFeature=="labyrinth" then turnOrder[a].score.Maze=turnOrder[a].score.Maze+1 end
								if hexFeature=="ziggurat" or hexFeature=="pyramid" then
									if gStates.coop==1 then
										turnOrder[a].score.ZigguratPyramid=turnOrder[a].score.ZigguratPyramid+1
									else
										local floor=zigguratPyramidFloorFromPosition(terTile, hexCenter, shieldPos)
										if floor==1 then
											if hexFeature=="ziggurat" then turnOrder[a].score.Zig1=turnOrder[a].score.Zig1+1 else turnOrder[a].score.Pyr1=turnOrder[a].score.Pyr1+1 end
										elseif floor==3 then
											if hexFeature=="ziggurat" then turnOrder[a].score.Zig3=turnOrder[a].score.Zig3+1 else turnOrder[a].score.Pyr3=turnOrder[a].score.Pyr3+1 end
										else
											if hexFeature=="ziggurat" then turnOrder[a].score.Zig2=turnOrder[a].score.Zig2+1 else turnOrder[a].score.Pyr2=turnOrder[a].score.Pyr2+1 end
										end
										turnOrder[a].score.ZigguratPyramid=turnOrder[a].score.ZigguratPyramid+1
									end
								end
								if ((hexFeature or ""):sub(1,4)=="city" or hexFeature=="Volkare's Camp") and gStates.gameScenario=="The Lost Relic Blitz" then turnOrder[a].score.Relic=turnOrder[a].score.Relic+1 foundRelic=foundRelic+1 end
								if hexFeature=="mine" and gStates.gameScenario=="Mines Liberation" then
									if terrainTiles[terTile.guid].tileType=="core" then
										turnOrder[a].score.CoreMine=turnOrder[a].score.CoreMine+1
									else
										turnOrder[a].score.CountryMine=turnOrder[a].score.CountryMine+1
									end
								end
							end
							if shieldToTileDist<1 then
								--dungeons for Dungeon Lords
								if terTile.getRotationValues()[2]~=nil and gStates.gameScenario=="Dungeon Lords" then
									if terTile.getRotationValues()[2].value=="Dungeon Monster" or terTile.getRotationValues()[2].value=="Draconum" then
										turnOrder[a].score.DungeonTomb=turnOrder[a].score.DungeonTomb+1
										found=true
									end
								end
								--GraveYards
								if terTile.getName()=="GraveYard" then
									turnOrder[a].score.GraveYard=turnOrder[a].score.GraveYard+1
									coopGraveYard=coopGraveYard+1
									found=true
								end
							end
							if found==true then break end
						end
						end
					end
				end
				turnOrder[a].heroChallenge=heroChallengeEvaluate(a,objectsInPlay)
			else
				--count the amount of cards left in the dummy or Volkare's deck
				turnOrder[a].score.CardsLeft=0
				for b, c in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do
					if c.type=="Card" then turnOrder[a].score.CardsLeft=1 break end
					if c.type=="Deck" then turnOrder[a].score.CardsLeft=c.getQuantity() break end
				end
			end
		end
		--Figure out who leads and assisted in cities
		refreshCityControlAndScoring()
		local forTheCouncil=gStates.gameScenario=="For the Council"
		local againstHorsemen=gStates.gameScenario=="Against the Horsemen Blitz"
		local apocalypseHere=gStates.gameScenario=="Apocalypse is Here"
		local horsemenSummary=(againstHorsemen or apocalypseHere) and horsemanDefeatSummary() or {total=0,byMage={},fameByMage={}}
		local againstDragon=gStates.gameScenario=="Against the Dragon Blitz" or apocalypseHere
		local dragonScoreSummary=againstDragon and apocalypseDragonCompetitiveScoreSummary() or {defeatedHeads=0,byMage={},heads={}}
		local fracturedLandsNoCityScore=gStates.gameScenario=="The Fractured Lands Blitz"
		if againstHorsemen then
			local bestFame=0
			local bestPlayers={}
			for playerIndex,details in pairs(turnOrder) do
				details.score.HorsemenDefeated=horsemenSummary.byMage[details.mage] or 0
				details.score.HorsemenFame=horsemenSummary.fameByMage[details.mage] or 0
				details.score.gHorsemanSlayer=0
				if details.mage~=gStates.positionMageKnight[5] then
					local fame=details.score.HorsemenFame
					if fame>bestFame then bestFame=fame bestPlayers={playerIndex}
					elseif fame==bestFame and fame>0 then bestPlayers[#bestPlayers+1]=playerIndex end
				end
			end
			if gStates.coop==0 and bestFame>0 then
				local bonus=#bestPlayers==1 and 6 or 3
				for _,playerIndex in ipairs(bestPlayers) do turnOrder[playerIndex].score.gHorsemanSlayer=bonus end
			end
		end
		local function councilReputationPoints(playerIndex)
			if turnOrder[playerIndex].reputation==-7 then return -10 end
			return tonumber(reputationTable[turnOrder[playerIndex].reputation].repDisplay)
		end
		--For the Council always runs to its time limit; Reputation decides success/failure only once the game is actually over.
		local councilMissionResult=""
		if forTheCouncil and gStates.gameOver==true then
			local requiredReputation=gStates.playerCount==1 and 2 or 1
			local missionSuccessful=true
			for playerIndex, details in pairs(turnOrder) do
				if details.mage~=gStates.positionMageKnight[5] and councilReputationPoints(playerIndex)<requiredReputation then
					missionSuccessful=false
					break
				end
			end
			if missionSuccessful then
				councilMissionResult="{en}Mission Successful{ru}Mission Successful{zh-tw}Mission Successful{zh-cn}Mission Successful{ko}Mission Successful{es}Mission Successful{fr}Mission Successful{pt-br}Mission Successful{de}Mission Successful"
			else
				councilMissionResult="{en}Mission Failed{ru}Mission Failed{zh-tw}Mission Failed{zh-cn}Mission Failed{ko}Mission Failed{es}Mission Failed{fr}Mission Failed{pt-br}Mission Failed{de}Mission Failed"
			end
		end
		--find the greatest in a category for competative games
		local coopScore=0
		local coopKey={}
		local scoreMax=0
		local scoreMin=999
		local key={}
		--Lowest base score for cooperative/solo scoring.
		if gStates.coop==1 then
			for a=1, #turnOrder, 1 do
				local currentLowScore=999
				if turnOrder[a].mage~=gStates.positionMageKnight[5] then
					if forTheCouncil then currentLowScore=turnOrder[a].questScore+councilReputationPoints(a)
					else currentLowScore=turnOrder[a].fame+turnOrder[a].score.Reward end
				end
				if currentLowScore==scoreMin then key[#key+1]=a end
				if currentLowScore<scoreMin then scoreMin=currentLowScore key={a} end
			end
			if forTheCouncil then
				coopScore=scoreMin
			else
				coopScore=coopScore+turnOrder[key[1]].fame+turnOrder[key[1]].score.Reward
				coopKey.lFame=key[1]
			end
		end
		--Find Greatest in all the categories. Used to add final score for Solo and Coop games.
		local greatestTable={gKnowledge=	{function(z) return heroChallengeKnowledgeScore(z) end},
							 gLoot=			{function(z) return heroChallengeLootScore(z) end},
							 gLeader=		{function(z) return heroChallengeLeaderScore(z) end},
							 gAdventurer=	{function(z) return heroChallengeAdventurerScore(z,1) end,
											 function(z) return heroChallengeAdventurerScore(z,2) end, nil,--Dungeon Lords
											 function(z) return heroChallengeAdventurerScore(z,4) end},--Against the Apocalypse
							 gRestorer=		{function(z) return turnOrder[z].score.Destroyed*3 end, nil, nil,
											 function(z) return turnOrder[z].score.Destroyed*3 end},--Against the Apocalypse
							 gAscender=		{function(z) return turnOrder[z].score.ZigguratPyramid*0 end, nil, nil,
											 function(z) return turnOrder[z].score.Zig1+(turnOrder[z].score.Zig2*2)+(turnOrder[z].score.Zig3*3)+(turnOrder[z].score.Pyr1*2)+(turnOrder[z].score.Pyr2*4)+(turnOrder[z].score.Pyr3*6) end},--Against the Apocalypse
							 gConqueror=	{function(z) return heroChallengeConquerorScore(z) end},
							 gLiberator=	{function(z) return (turnOrder[z].score.CoreMine*7)+(turnOrder[z].score.CountryMine*4) end,
							 				 function(z) return (turnOrder[z].score.CoreMine*7)+(turnOrder[z].score.CountryMine*4) end},--Mines Liberation
							 gBeating=		{function(z) return heroChallengeBeatingScore(z) end},
							 gCityLead=		{function(z) return (turnOrder[z].score.CityLead*7)+(turnOrder[z].score.CityAssist*4) end,
							 				 function(z) return (turnOrder[z].score.CityLead*7)+(turnOrder[z].score.CityAssist*4) end},
							 gRelic=		{function(z) return turnOrder[z].score.Relic*5 end, nil ,
						 					 function(z) return turnOrder[z].score.Relic*4 end}}--The Lost Relic Blitz
		if apocalypseQuestScoringActive()==true and (forTheCouncil~=true or gStates.coop==0) then
			greatestTable.gQuest={function(z) return turnOrder[z].questScore end}
		end
		if forTheCouncil and gStates.coop==0 then
			--Offsets preserve ordering while ensuring the title is still awarded if all
			--Reputation values are negative or all Fame values are zero.
			greatestTable.gEsteem={function(z) return turnOrder[z].reputation+8 end}
			greatestTable.gRenown={function(z) return turnOrder[z].fame+1 end}
		end
		local greatestBonus={{3, 1},
							 {5, 2},--Dungeon Lords, Mines Liberation
							 {4, 2},--The Lost Relic Blitz
							 {5, 2}}--Against the Apocalypse
		for greatName, scoreMath in pairs(greatestTable) do
			local ref=1
			if gStates.gameScenario=="Mines Liberation" and greatName=="gLiberator" then ref=2 end
			if gStates.gameScenario=="Dungeon Lords" and greatName=="gAdventurer" then ref=2 end
			if gStates.gameScenario=="Against the Apocalypse Blitz" and (greatName=="gRestorer" or (greatName=="gAdventurer" and gStates.coop==1) or (greatName=="gAscender" and gStates.coop==0)) then ref=4 end
			if (gStates.gameScenario=="Conquest" or gStates.gameScenario=="Conquest Blitz" or gStates.gameScenario=="First Conquest" or gStates.gameScenario=="Ultimate Conquest" or gStates.gameScenario=="Fast Forwarded Conquest") and greatName=="gCityLead" then ref=2 end
			if gStates.gameScenario=="The Lost Relic Blitz" and gStates.coop==0 and greatName=="gRelic" then ref=3 end
			scoreMax=0
			key={}
			for playerX=1, #turnOrder, 1 do
				turnOrder[playerX].score[greatName]=0
				local currentHighScore=-1
				if turnOrder[playerX].mage~=gStates.positionMageKnight[5] then currentHighScore=scoreMath[ref](playerX) end
				if currentHighScore==scoreMax then key[#key+1]=playerX end
				if currentHighScore>scoreMax then scoreMax=currentHighScore key={playerX} end
			end
			if gStates.gameScenario=="Against the Apocalypse Blitz" and greatName=="gAdventurer" then ref=1 end
			if #key==1 and scoreMax~=0 and (gStates.coop==0 or gStates.WarOfFourComp==true) then turnOrder[key[1]].score[greatName]=greatestBonus[ref][1] end
			if #key>1 and scoreMax~=0 and (gStates.coop==0 or gStates.WarOfFourComp==true) then for a=1, #key, 1 do turnOrder[key[a]].score[greatName]=greatestBonus[ref][2] end end
			if gStates.gameScenario=="Against the Apocalypse Blitz" and greatName=="gAdventurer" then ref=4 end
			if gStates.coop==1 and forTheCouncil~=true and greatName~="gBeating" and greatName~="gCityLead" then coopScore=coopScore+scoreMath[ref](key[1]) coopKey[greatName]=key[1] end
			if gStates.coop==1 and forTheCouncil~=true and greatName=="gBeating" and greatName~="gCityLead" then coopScore=coopScore-scoreMath[ref](key[1]) coopKey[greatName]=key[1] end
		end
		--Krang and Braevalar have Hero Challenge bonuses outside the standard Achievement categories.
		--In cooperative scoring these are added once for each participating Hero; altered category rates above
		--still follow the normal cooperative rule of scoring only the best Hero in each Achievement category.
		if gStates.coop==1 and forTheCouncil~=true and gStates.heroChallenges==true then
			for playerIndex,details in pairs(turnOrder) do
				if details.mage~=gStates.positionMageKnight[5] and details.heroChallenge~=nil then coopScore=coopScore+(details.heroChallenge.extraBonus or 0) end
			end
		end

		--Update Score Card
		local scoreCardSections={	"QuestScoreHeading",		"QuestScoreData",
									"ReputationScoreHeading",	"ReputationScoreData",
									"KnowledgeScoreHeading",	"KnowledgeScoreData",
									"LootScoreHeading",			"LootScoreData",
									"LeaderScoreHeading",		"LeaderScoreData",
									"ConquerorScoreHeading",	"ConquerorScoreData",
									"AdventurerScoreHeading",	"AdventurerScoreData",
									"RestorerScoreHeading",		"RestorerScoreData",
									"LiberatorScoreHeading",	"LiberatorScoreData",
									"BeatingScoreHeading",		"BeatingScoreData",
									"RelicScoreHeading",		"RelicScoreData",
									"RewardScoreHeading",		"RewardScoreData",
									"CityScoreHeading",			"CityScoreData",
									"VolkareScoreHeading",		"VolkareScoreData",
									"TezlaScoreHeading",		"TezlaScoreData",
									"EfficiencyScoreHeading",	"EfficiencyScoreData"}
		for a, b in pairs(scoreCardSections) do
			UI.setAttribute(b, "active", "false")
		end
		local pannel=1
		local totalHeight=54+30+30
		local assembledText=""
		local lineFeed=0
		local heights={Quest=0, Reputation=0, Knowledge=0, Loot=0, Leader=0, Conqueror=0, Adventurer=0, Restorer=0, Liberator=0, Beating=0, Volkare=0, Efficiency=0, City=0, Relic=0, Tezla=0, Reward=0}

		local function appendScoreLine(text, lineCount, parts)
			local line={}
			if lineCount>0 then
				line[1]=text
				line[2]="\n"
			end
			for i=1, #parts do line[#line+1]=parts[i] end
			return joinLang(line), lineCount+1
		end

		--Display and add up score pannel heights
		function updateScorePannel(scoreName, lineFeed, assembledText)
			local pannelText=tostring(pannel)
			local textCol="rgb(0, 0, 0)"
			if coopKey["g"..scoreName]~=pannel and coopKey["g"..scoreName]~=nil and gStates.coop==1 and scoreName~="Relic" then textCol="rgb(0.2, 0.2, 0.4)" end
			if scoreName=="Volkare" or scoreName=="Efficiency" then pannelText="" end
			UI.setAttribute(scoreName..pannelText.."ScoreText", "text", "")
			UI.setAttribute(scoreName..pannelText.."ScoreCell", "active", "true")
			local scoreHieght=0
			if lineFeed>0 then scoreHieght=(lineFeed*25)-((lineFeed-1)*8) end
			if scoreHieght>heights[scoreName] then
				if lineFeed>0 then totalHeight=totalHeight+scoreHieght-heights[scoreName] end
				heights[scoreName]=scoreHieght
				UI.setAttribute(scoreName.."ScoreData", "preferredHeight", heights[scoreName])
			end
			if lineFeed>0 then
				UI.setAttribute(scoreName.."ScoreHeading", "active", "true")
				UI.setAttribute(scoreName.."ScoreData", "active", "true")
				if scoreName~="Reward" then UI.setAttribute(scoreName..pannelText.."ScoreText", "Color", textCol) end
				UI.setAttribute(scoreName..pannelText.."ScoreText", "text", assembledText)
			end
		end

		--Work out which scores to display
		for a=1, #turnOrder, 1 do
			local totalScore=0
			local challenge=turnOrder[a].heroChallenge
			local function appendHeroChallenge(scoreCategory)
				local challengeData=heroChallengesData[turnOrder[a].mage]
				if challenge==nil or challengeData==nil or challengeData.scoreCategory~=scoreCategory then return end
				local challengeStatus=challenge.complete and "Complete" or (gStates.gameOver==true and "Failed" or "Incomplete")
				assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"Hero Challenge: ",challengeStatus})
				assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"(",challenge.details,")"})
				if (challenge.extraBonus or 0)>0 then
					local bonusLabel=turnOrder[a].mage=="Krang" and "Puppet Master trophies: +" or "Final terrain: +"
					assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{bonusLabel,challenge.extraBonus})
					totalScore=totalScore+challenge.extraBonus
				end
			end
			if turnOrder[a].mage~=gStates.positionMageKnight[5] then
				if gStates.gameScenario~="Conquer and Hold" and gStates.gameScenario~="One to Return" then
					--Base Score
					if forTheCouncil~=true then
						assembledText="" lineFeed=0
						local textCol="rgb(0, 0, 0)"
						if coopKey.lFame~=a and gStates.coop==1 then textCol="rgb(0.2, 0.2, 0.4)" end
						UI.setAttribute("Reward"..pannel.."ScoreText", "Color", textCol)
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{translateWord[turnOrder[a].mage], "{en}'s Base Fame: {ru}имеет Славы: {zh-tw}的基础名望: {zh-cn}的基础名望: {ko} 의 기본 명성: {es} Fama Base: {fr} Gloire Base: {pt-br} Fama Base: {de}Basis-Ruhm: ", turnOrder[a].fame})
						totalScore=turnOrder[a].fame
						if turnOrder[a].score.Reward>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Reward, "{en} Faction Reward(s): +{ru} Жетон фракций: +{zh-tw}派系奖励: +{zh-cn}派系奖励: +{ko} 세력 보상: +{es} Recompensas Facción: +{fr} Récompenses Faction: +{pt-br} Recompensas de Facção: +{de} Fraktions-Belohnung(en): +", turnOrder[a].score.Reward})
							totalScore=totalScore+turnOrder[a].score.Reward
						end
						updateScorePannel("Reward", lineFeed, assembledText)
					end

					--Quest scoring is optional when the selected scenario does not require it.
					if apocalypseQuestScoringActive()==true then
						assembledText="" lineFeed=0
						if turnOrder[a].questScore>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].questScore, "{en} Quest Point(s): +{ru} Quest Point(s): +{zh-tw} Quest Point(s): +{zh-cn} Quest Point(s): +{ko} Quest Point(s): +{es} Quest Point(s): +{fr} Quest Point(s): +{pt-br} Quest Point(s): +{de} Quest Point(s): +", turnOrder[a].questScore})
							totalScore=totalScore+turnOrder[a].questScore
						end
						if (forTheCouncil~=true or gStates.coop==0) and turnOrder[a].score.gQuest>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Quester: +{ru}Greatest Quester: +{zh-tw}Greatest Quester: +{zh-cn}Greatest Quester: +{ko}Greatest Quester: +{es}Greatest Quester: +{fr}Greatest Quester: +{pt-br}Greatest Quester: +{de}Greatest Quester: +", turnOrder[a].score.gQuest})
							totalScore=totalScore+turnOrder[a].score.gQuest
						end
						updateScorePannel("Quest", lineFeed, assembledText)
					end

					--For the Council uses Reputation as scoring points. Greatest Renown is kept
					--here with Greatest Esteem so no separate Fame category is needed.
					if forTheCouncil then
						assembledText="" lineFeed=0
						local reputationScore=councilReputationPoints(a)
						local reputationText=tostring(reputationScore)
						if reputationScore>0 then reputationText="+"..reputationText end
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Reputation: {ru}Reputation: {zh-tw}Reputation: {zh-cn}Reputation: {ko}Reputation: {es}Reputation: {fr}Reputation: {pt-br}Reputation: {de}Reputation: ", reputationText})
						totalScore=totalScore+reputationScore
						if gStates.coop==0 and turnOrder[a].score.gEsteem>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Esteem: +{ru}Greatest Esteem: +{zh-tw}Greatest Esteem: +{zh-cn}Greatest Esteem: +{ko}Greatest Esteem: +{es}Greatest Esteem: +{fr}Greatest Esteem: +{pt-br}Greatest Esteem: +{de}Greatest Esteem: +", turnOrder[a].score.gEsteem})
							totalScore=totalScore+turnOrder[a].score.gEsteem
						end
						if gStates.coop==0 and turnOrder[a].score.gRenown>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Renown: +{ru}Greatest Renown: +{zh-tw}Greatest Renown: +{zh-cn}Greatest Renown: +{ko}Greatest Renown: +{es}Greatest Renown: +{fr}Greatest Renown: +{pt-br}Greatest Renown: +{de}Greatest Renown: +", turnOrder[a].score.gRenown})
							totalScore=totalScore+turnOrder[a].score.gRenown
						end
						updateScorePannel("Reputation", lineFeed, assembledText)
					end
					--Knowledge Score
					assembledText="" lineFeed=0
					appendHeroChallenge("Knowledge")
					if forTheCouncil~=true then
						local aaRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Braevalar" and 2 or 1
						local spellRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Goldyx" and 3 or 2
						if turnOrder[a].score.AdvanceAction>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.AdvanceAction, "{en} Advanced Action(s): +{ru} Особое действие: +{zh-tw}张高级行动卡: +{zh-cn}张高级行动卡: +{ko} 상급 액션: +{es} Acciones Avanzadas: +{fr} Actions Avancées: +{pt-br} Ações Avançadas: +{de} Fortgeschrittene Aktion(en): +", turnOrder[a].score.AdvanceAction*aaRate})
							totalScore=totalScore+(turnOrder[a].score.AdvanceAction*aaRate)
						end
						if turnOrder[a].score.Spell>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Spell, "{en} Spell(s): +{ru} Заклинание: +{zh-tw}张法术卡: +{zh-cn}张法术卡: +{ko} 마법: +{es} Hechizos: +{fr} Sorts: +{pt-br} Feitiços: +{de} Zauberspruch(e): +", (turnOrder[a].score.Spell*spellRate)})
							totalScore=totalScore+(turnOrder[a].score.Spell*spellRate)
						end

					end
					if turnOrder[a].score.gKnowledge>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Knowledge: +{ru}Великий мудрец: +{zh-tw}博古通今： +{zh-cn}博古通今： +{ko}위대한 지식: +{es}Mayor Conocimiento: +{fr}Plus Grand Connaissance: +{pt-br}Mais Conhecimento: +{de}Größtes Wissen: +", turnOrder[a].score.gKnowledge})
						totalScore=totalScore+turnOrder[a].score.gKnowledge
					end
					updateScorePannel("Knowledge", lineFeed, assembledText)

					--Loot Score
					assembledText="" lineFeed=0
					appendHeroChallenge("Loot")
					if forTheCouncil~=true then
						local artifactRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Coral" and 4 or 2
						local crystalScore=(heroChallengeActive(a)==true and (turnOrder[a].mage=="Goldyx" or turnOrder[a].mage=="Coral")) and turnOrder[a].score.Crystal or math.floor(turnOrder[a].score.Crystal/2)
						if turnOrder[a].score.Artifact>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Artifact, "{en} Artifact(s): +{ru} Артефакт: +{zh-tw}张圣器卡: +{zh-cn}张圣器卡: +{ko} 유물: +{es} Artefactos: +{fr} Artefacts: +{pt-br} Artefatos: +{de} Artefakt(e): +", (turnOrder[a].score.Artifact*artifactRate)})
							totalScore=totalScore+(turnOrder[a].score.Artifact*artifactRate)
						end
						if turnOrder[a].score.Crystal>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Crystal, "{en} Mana Crystal(s): +{ru} Кристалл маны: +{zh-tw}个未使用的魔晶: +{zh-cn}个未使用的魔晶: +{ko} 마나 수정: +{es} Cristales de Maná: +{fr} Cristaux de Mana: +{pt-br} Cristais de Mana: +{de} Manakristall(e): +", crystalScore})
							totalScore=totalScore+crystalScore
						end
						if turnOrder[a].score.Potion>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Potion, "{en} Potion(s): +{ru} Зелье: +{zh-tw}瓶药剂： +{zh-cn}瓶药剂： +{ko} 포션: +{es} Pociones: +{fr} Potion: +{pt-br} Poções: +{de} Trank(e): +", turnOrder[a].score.Potion})
							totalScore=totalScore+turnOrder[a].score.Potion
						end

					end
					if turnOrder[a].score.gLoot>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Loot: +{ru}Великая добыча: +{zh-tw}至多战利品： +{zh-cn}至多战利品： +{ko}위대한 전리품: +{es}Mayor Botín: +{fr}Plus Grand Butin: +{pt-br}Maior Saque: +{de}Größte Beute: +", turnOrder[a].score.gLoot})
						totalScore=totalScore+turnOrder[a].score.gLoot
					end
					updateScorePannel("Loot", lineFeed, assembledText)

					--Leader Score
					assembledText="" lineFeed=0
					appendHeroChallenge("Leader")
					if forTheCouncil~=true then
						local healthyScore=heroChallengeActive(a)==true and turnOrder[a].mage=="Norowas" and turnOrder[a].score.UnitsLevel*2 or turnOrder[a].score.UnitsLevel
						local woundedScore=heroChallengeActive(a)==true and turnOrder[a].mage=="Arythea" and turnOrder[a].score.WoundedUnitsRawLevel or turnOrder[a].score.WoundedUnitsLevel
						if turnOrder[a].score.Units>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Units, "{en} Healthy Unit(s): +{ru} Здоровый отряд: +{zh-tw}个健康的部队: +{zh-cn}个健康的部队: +{ko} 보유 유닛: +{es} Unidades Saludables: +{fr} Unités Saines: +{pt-br} Unidades Saudáveis: +{de} Gesunde Einheit(en): +", healthyScore})
							totalScore=totalScore+healthyScore
						end
						if turnOrder[a].score.WoundedUnits>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.WoundedUnits, "{en} Wounded Unit(s): +{ru} Раненный отряд: +{zh-tw}个受伤的部队: +{zh-cn}个受伤的部队: +{ko} 부상받은 유닛: +{es} Unidades Heridas: +{fr} Unités Blessées: +{pt-br} Unidades Feridas: +{de} Verwundete Einheit(en): +", woundedScore})
							totalScore=totalScore+woundedScore
						end

					end
					if turnOrder[a].score.gLeader>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Leader: +{ru}Великий лидер: +{zh-tw}至高领袖： +{zh-cn}至高领袖： +{ko}위대한 지도자: +{es}Mayor Líder: +{fr}Plus Grand Chef: +{pt-br}Maior Líder: +{de}Größter Anführer: +", turnOrder[a].score.gLeader})
						totalScore=totalScore+turnOrder[a].score.gLeader
					end
					updateScorePannel("Leader", lineFeed, assembledText)

					--Adventurer Score
					assembledText="" lineFeed=0
					appendHeroChallenge("Adventurer")
					if forTheCouncil~=true then
						local adventurerRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Wolfhawk" and 4 or 2
						if turnOrder[a].score.Ruin>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Ruin, "{en} Ruin(s): +{ru} Руины: +{zh-tw}个远古遗迹已探索: +{zh-cn}个远古遗迹已探索: +{ko} 유적: +{es} Ruinas: +{fr} Ruines: +{pt-br} Ruínas: +{de} Ruine(n): +", turnOrder[a].score.Ruin*adventurerRate})
							totalScore=totalScore+(turnOrder[a].score.Ruin*adventurerRate)
						end
						if turnOrder[a].score.DungeonTomb>0 then
							local b=turnOrder[a].score.DungeonTomb*adventurerRate
							if gStates.gameScenario=="Dungeon Lords" then b=turnOrder[a].score.DungeonTomb*4 end
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.DungeonTomb, "{en} Dungeon / Tomb(s): +{ru} Подземелье / Гробница: +{zh-tw}个地下城或墓穴已征服: +{zh-cn}个地下城或墓穴已征服: +{ko} 던전과 무덤: +{es} Mazmorras / Tumbas: +{fr} Donjons / Tombeaux: +{pt-br} Masmorras / Tumbas: +{de} Verlies / Grabmal(e): +", b})
							totalScore=totalScore+b
						end
						if turnOrder[a].score.SpawningDen>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.SpawningDen, "{en} Den / Spawn Grnd(s): +{ru} Логово / Проклятые земли: +{zh-tw}个怪物巢穴或孵化领地已征服： +{zh-cn}个怪物巢穴或孵化领地已征服： +{ko} 은신처와 산란지: +{es} Den / Zonas Desove: +{fr} Tanière / Frayère: +{pt-br} Covil / Nascedouro: +{de} Höhle(n) / Laichplatz(e): +", turnOrder[a].score.SpawningDen*adventurerRate})
							totalScore=totalScore+(turnOrder[a].score.SpawningDen*adventurerRate)
						end
						if turnOrder[a].score.Maze>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Maze, "{en} Maze / Labyrinth(s): +{ru} Катакомбы / Лабиринт: +{zh-tw}个迷宫或迷城已征服: +{zh-cn}个迷宫或迷城已征服: +{ko} 미로와 미궁: +{es} Maze / Laberintos: +{fr} Maze / Labyrinthes: +{pt-br} Labirintos / Dédalos: +{de} Irrgarten / Labyrinth(e): +", turnOrder[a].score.Maze*adventurerRate})
							totalScore=totalScore+(turnOrder[a].score.Maze*adventurerRate)
						end
						if turnOrder[a].score.ZigguratPyramid>0 and (gStates.gameScenario~="Against the Apocalypse Blitz" or (gStates.gameScenario=="Against the Apocalypse Blitz" and gStates.coop==1)) then
							local b=turnOrder[a].score.ZigguratPyramid*adventurerRate
							if gStates.gameScenario=="Against the Apocalypse Blitz" then b=turnOrder[a].score.ZigguratPyramid*5 end
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.ZigguratPyramid, "{en} Ziggurat / Pyramid(s): +{ru} Зиккурат / Пирамида (и): +{zh-tw} 座階梯神廟/金字塔：+{zh-cn} 座阶梯神庙/金字塔：+{ko} 지구라트 / 피라미드: +{es} Zigurat / Pirámide(s): +{fr} Ziggourat / Pyramide(s) : +{pt-br} Zigurate / Pirâmide(s): +{de} Zikkurat / Pyramide(n): +", b})
							totalScore=totalScore+b
						end
						if turnOrder[a].score.Zig1>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Zig1, "{en} Ziggurat Floor One(s): +{ru} Зиккурат, первый этаж: +{zh-tw} 座階梯神殿在第一層：+{zh-cn} 座阶梯神庙在第一层：+{ko} 지구라트 1층: +{es} Planta(s) 1 de la zigurat: +{fr} Ziggourat, 1er étage : +{pt-br} Zigurate, 1º andar(es): +{de} Zikkurat, 1. Etage: +", turnOrder[a].score.Zig1})
							totalScore=totalScore+(turnOrder[a].score.Zig1)
						end
						if turnOrder[a].score.Zig2>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Zig2, "{en} Ziggurat Floor Two(s): +{ru} Зиккурат, второй этаж: +{zh-tw} 座階梯神殿在第二層：+{zh-cn} 座阶梯神庙在第二层：+{ko} 지구라트 2층: +{es} Planta(s) 2 de la zigurat: +{fr} Ziggourat, 2e étage : +{pt-br} Zigurate, 2º andar(es): +{de} Zikkurat, 2. Etage: +", turnOrder[a].score.Zig2*2})
							totalScore=totalScore+(turnOrder[a].score.Zig2*2)
						end
						if turnOrder[a].score.Zig3>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Zig3, "{en} Ziggurat Floor Three(s): +{ru} Зиккурат, третий этаж: +{zh-tw} 座階梯神殿在第三層：+{zh-cn} 座阶梯神庙在第三层：+{ko} 지구라트 3층: +{es} Planta(s) 3 de la zigurat: +{fr} Ziggourat, 3e étage : +{pt-br} Zigurate, 3º andar(es): +{de} Zikkurat, 3. Etage: +", turnOrder[a].score.Zig3*3})
							totalScore=totalScore+(turnOrder[a].score.Zig3*3)
						end
						if turnOrder[a].score.Pyr1>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Pyr1, "{en} Pyramid Floor One(s): +{ru} Пирамида, первый этаж: +{zh-tw} 座金字塔在第一層：+{zh-cn} 座金字塔在第一层：+{ko} 피라미드 1층: +{es} Planta(s) 1 de la pirámide: +{fr} Pyramide, 1er étage : +{pt-br} Pirâmide, 1º andar(es): +{de} Pyramide, 1. Etage: +", turnOrder[a].score.Pyr1*2})
							totalScore=totalScore+(turnOrder[a].score.Pyr1*2)
						end
						if turnOrder[a].score.Pyr2>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Pyr2, "{en} Pyramid Floor Two(s): +{ru} Пирамида, второй этаж: +{zh-tw} 座金字塔在第二層：+{zh-cn} 座金字塔在第二层：+{ko} 피라미드 2층: +{es} Planta(s) 2 de la pirámide: +{fr} Pyramide, 2e étage : +{pt-br} Pirâmide, 2º andar(es): +{de} Pyramide, 2. Etage: +", turnOrder[a].score.Pyr2*4})
							totalScore=totalScore+(turnOrder[a].score.Pyr2*4)
						end
						if turnOrder[a].score.Pyr3>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Pyr3, "{en} Pyramid Floor Three(s): +{ru} Пирамида, третий этаж: +{zh-tw} 座金字塔在第三層：+{zh-cn} 座金字塔在第三层：+{ko} 피라미드 3층: +{es} Planta(s) 3 de la pirámide: +{fr} Pyramide, 3e étage : +{pt-br} Pirâmide, 3º andar(es): +{de} Pyramide, 3. Etage: +", turnOrder[a].score.Pyr3*6})
							totalScore=totalScore+(turnOrder[a].score.Pyr3*6)
						end

					end
					if turnOrder[a].score.gAdventurer>0 then
						local b="{en}Greatest Adventurer: +{ru}Великий искатель приключений: +{zh-tw}披荊斬棘：+{zh-cn}披荆斩棘：+{ko}위대한 모험가: +{es}Mayor Aventurero: +{fr}Plus Grand Aventurier: +{pt-br}Maior Aventureiro: +{de}Größter Abenteurer: +"
						if gStates.gameScenario=="Dungeon Lords" then
							b="{en}Great Dungeon Crawler: +{ru}Великий исследователь подземелий: +{zh-tw}地下城勇士：+{zh-cn}地下城勇士：+{ko}던전 탐험가: +{es}Mayor Mazmorra Orugas: +{fr}Plus Grand Donjon Crawler: +{pt-br}Maior Explorador de Masmorras: +{de}Großer Dungeon-Krabbler: +"
						end
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{b, turnOrder[a].score.gAdventurer})
						totalScore=totalScore+turnOrder[a].score.gAdventurer
					end
					if turnOrder[a].score.gAscender>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Ascender: +{ru}Величайший восходец: +{zh-tw}登峰造極：+{zh-cn}登峰造极：+{ko}위대한 등반가: +{es}El mejor escalador: +{fr}Meilleur grimpeur : +{pt-br}Maior Ascendente: +{de}Größter Aufsteiger: +", turnOrder[a].score.gAscender})
						totalScore=totalScore+turnOrder[a].score.gAscender
					end
					updateScorePannel("Adventurer", lineFeed, assembledText)--gAscender

					--Restorer Score
					assembledText="" lineFeed=0
					if forTheCouncil~=true then
						if turnOrder[a].score.Destroyed>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Destroyed, "{en} Restored Site(s): +{ru} Восстановленные объекты: +{zh-tw} 個修復地點：+{zh-cn} 个修复地点：+{ko} 복구한 장소: +{es} Lugares restaurados: +{fr} Site(s) restauré(s) : +{pt-br} Local(is) restaurado(s): +{de} Wiederhergestellte Stätte(n): +", (turnOrder[a].score.Destroyed*3)})
							totalScore=totalScore+(turnOrder[a].score.Destroyed*3)
						end

					end
					if turnOrder[a].score.gRestorer>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Restorer: +{ru}Лучший реставратор: +{zh-tw}重振山河：+{zh-cn}重振山河：+{ko}위대한 복원가: +{es}Mejor restaurador: +{fr}Meilleur restaurateur : +{pt-br}Maior restaurador: +{de}Bester Wiederhersteller: +", turnOrder[a].score.gRestorer})
						totalScore=totalScore+turnOrder[a].score.gRestorer
					end
					updateScorePannel("Restorer", lineFeed, assembledText)

					--Liberator Score
					assembledText="" lineFeed=0
					if forTheCouncil~=true then
						if turnOrder[a].score.CountryMine>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CountryMine, "{en} Country Mine(s): +{ru} Шахта на дикой земле: +{zh-tw}个深层矿山已解放: +{zh-cn}个深层矿山已解放: +{ko} 교외 광산: +{es} Minas del País: +{fr} Mines de Pays: +{pt-br} Minas de Campo: +{de} Landmine(n): +", (turnOrder[a].score.CountryMine*4)})
							totalScore=totalScore+(turnOrder[a].score.CountryMine*4)
						end
						if turnOrder[a].score.CoreMine>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CoreMine, "{en} Core Mine(s): +{ru} Шахта на развитой земле: +{zh-tw}个魔晶矿山已解放: +{zh-cn}个魔晶矿山已解放: +{ko} 중심부 광산: +{es} Minas Centrales: +{fr} Mines de Base: +{pt-br} Minas Centrais: +{de} Kernmine(n): +", (turnOrder[a].score.CoreMine*7)})
							totalScore=totalScore+(turnOrder[a].score.CoreMine*7)
						end

					end
					if turnOrder[a].score.gLiberator>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Liberator: +{ru}Великий исследователь подземелий: +{zh-tw}至善解放者： +{zh-cn}至善解放者： +{ko}위대한 해방자: +{es}Mayor Libertador: +{fr}Plus Grand Libérateur: +{pt-br}Maior Libertador: +{de}Größter Befreier: +", turnOrder[a].score.gLiberator})
						totalScore=totalScore+turnOrder[a].score.gLiberator
					end
					updateScorePannel("Liberator", lineFeed, assembledText)

					--Relic Score
					if (gStates.coop==0 or gStates.WarOfFourComp==true) then
						assembledText="" lineFeed=0
						if forTheCouncil~=true then
							if turnOrder[a].score.Relic>0 then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Relic, "{en} Relic(s) Found: +{ru} Реликвия найдена: +{zh-tw}个圣器已收集: +{zh-cn}个圣器已收集: +{ko} 발견한 유물: +{es} Reliquias Encontradas: +{fr} Reliques Trouvées: +{pt-br} Relíquias Encontradas: +{de} Relikt(e) gefunden: +", (turnOrder[a].score.Relic*4)})
								totalScore=totalScore+(turnOrder[a].score.Relic*4)
							end

						end
					if turnOrder[a].score.gRelic>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Relic Hunter: +{ru}Великий охотник за древностями: +{zh-tw}至高圣器猎手： +{zh-cn}至高圣器猎手： +{ko}위대한 유물 사냥꾼: +{es}Mayor Relic Hunter: +{fr}Plus Grand Chasseur de Reliques: +{pt-br}Maior Caçador de Relíquias: +{de}Größter Reliquienjäger: +", turnOrder[a].score.gRelic})
							totalScore=totalScore+turnOrder[a].score.gRelic
						end
						updateScorePannel("Relic", lineFeed, assembledText)
					end

					--Beating Score
					assembledText="" lineFeed=0
					appendHeroChallenge("Beating")
					if forTheCouncil~=true then
						if turnOrder[a].score.Wound>0 and not (heroChallengeActive(a)==true and turnOrder[a].mage=="Arythea") then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Wound, "{en} Wound(s): -{ru} Рана: -{zh-tw}张创伤卡: -{zh-cn}张创伤卡: -{ko} 부상: -{es} Heridas: -{fr} Blessures: -{pt-br} Ferimentos: -{de} Wunde(n): -", (turnOrder[a].score.Wound*2)})
							totalScore=totalScore-(turnOrder[a].score.Wound*2)
						end

					end
					if turnOrder[a].score.gBeating>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Beating: -{ru}Великое поражение: -{zh-tw}受伤最多的: -{zh-cn}受伤最多的: -{ko}위대한 패배자: -{es}Mayor Paliza: -{fr}Plus Grandr Battement: -{pt-br}Mais Espancado: -{de}Größter Prügler: -", turnOrder[a].score.gBeating})
						totalScore=totalScore-turnOrder[a].score.gBeating
					end
					updateScorePannel("Beating", lineFeed, assembledText)

					if (gStates.coop==0 or gStates.WarOfFourComp==true) and forTheCouncil~=true then
						--Cities Competative. Fractured Lands explicitly does not use City scoring.
						if fracturedLandsNoCityScore~=true then
							assembledText="" lineFeed=0
							if turnOrder[a].score.CityLead>0 and gStates.defeatedCities.amount>0 then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CityLead, "{en} Conquered City(s): +{ru} Захваченный Город: +{zh-tw}个城市已征服: +{zh-cn}个城市已征服: +{ko} 정복한 도시: +{es} Ciudades Conquistadas: +{fr} Villes Conquises: +{pt-br} Cidades Conquistadas: +{de} Eroberte Stadt(en): +", (turnOrder[a].score.CityLead*7)})
								totalScore=totalScore+(turnOrder[a].score.CityLead*7)
							end
							if turnOrder[a].score.CityAssist>0 and gStates.defeatedCities.amount>0 then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CityAssist, "{en} Assisted City(s): +{ru} Помощь с Городом: +{zh-tw}个城市已援助: +{zh-cn}个城市已援助: +{ko} 도와준 도시: +{es} Ciudades Asistidas: +{fr} Villes Aidées: +{pt-br} Cidades Assistidas: +{de} Unterstützte Stadt(en): +", (turnOrder[a].score.CityAssist*4)})
								totalScore=totalScore+(turnOrder[a].score.CityAssist*4)
							end
							if turnOrder[a].score.gCityLead>0 and gStates.defeatedCities.amount>0 then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest City Leader: +{ru}Великий завоеватель городов: +{zh-tw}至强城市领袖： +{zh-cn}至强城市领袖： +{ko}위대한 도시 정복자: +{es}Mayor Líder de la Ciudad: +{fr}Plus Grand Chef de la Ville: +{pt-br}Maior Líder de Cidade: +{de}Größter Stadtführer: +", turnOrder[a].score.gCityLead})
								totalScore=totalScore+turnOrder[a].score.gCityLead
							end
							updateScorePannel("City", lineFeed, assembledText)
						end

						--Tezla Faction Leaders
						assembledText="" lineFeed=0
						if (gStates.gameScenario=="Life and Death" or gStates.gameScenario=="The Realm of the Dead Blitz" or gStates.gameScenario=="The Hidden Valley Blitz" or gStates.gameScenario=="Ultimate Conquest") and turnOrder[a].score.DarkFactionLead>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Dark Crusader Enemy: +5{ru}Враг Темного легиона: +5{zh-tw}黑暗十字军敌人: +5{zh-cn}黑暗十字军敌人: +5{ko}암흑 십자군 적: +5{es}Enemigo del Cruzado Oscuro: +5{fr}Ennemi Noir Croisé: +5{pt-br}Inimigo dos Cruzados Sombrios: +5{de}Feind des dunklen Kreuzfahrers: +5"})
							totalScore=totalScore+5
						end
						if (gStates.gameScenario=="Life and Death" or gStates.gameScenario=="The Realm of the Dead Blitz" or gStates.gameScenario=="The Hidden Valley Blitz" or gStates.gameScenario=="Ultimate Conquest") and turnOrder[a].score.ElemFactionLead>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Elementalist Enemy: +5{ru}Враг Элементалистов: +5{zh-tw}元素敌人: +5{zh-cn}元素敌人: +5{ko}원소술사 적: +5{es}Enemigo Elementalista: +5{fr}Ennemi Elémentaliste: +5{pt-br}Inimigo dos Elementaristas: +5{de}Elementarmagier-Feind: +5"})
							totalScore=totalScore+5
						end
						updateScorePannel("Tezla", lineFeed, assembledText)
					end
				end

				--Conqueror Score
				if gStates.gameScenario~="One to Return" then
					assembledText="" lineFeed=0
					appendHeroChallenge("Conqueror")
					if turnOrder[a].score.Keep>0 and forTheCouncil~=true then
						local b=2
						if gStates.gameScenario=="Conquer and Hold" then b=3 end
						if heroChallengeActive(a)==true and turnOrder[a].mage=="Tovak" then b=4 end
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Keep, "{en} Keep(s): +{ru} Крепость: +{zh-tw}个要塞已占领: +{zh-cn}个要塞已占领: +{ko} 성: +{es} Mantiene: +{fr} Garde: +{pt-br} Fortes: +{de} Bergfried(e): +", turnOrder[a].score.Keep*b})
						if gStates.gameScenario=="Conquer and Hold" then totalScore=turnOrder[a].score.Keep*b else totalScore=totalScore+(turnOrder[a].score.Keep*b) end
					end
					if turnOrder[a].score.MageTower>0 and forTheCouncil~=true then
						local towerRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Tovak" and 4 or 2
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.MageTower, "{en} Mage Tower(s): +{ru} Башня мага: +{zh-tw}个法师塔已征服: +{zh-cn}个法师塔已征服: +{ko} 마법사의 탑: +{es} Torres de Magos: +{fr} Tours des Mages: +{pt-br} Torres de Mago: +{de} Magierturm(e): +", turnOrder[a].score.MageTower*towerRate})
						totalScore=totalScore+(turnOrder[a].score.MageTower*towerRate)
					end
					if gStates.gameScenario~="Conquer and Hold" then
						if turnOrder[a].score.Monastery>0 and forTheCouncil~=true then
							local monasteryRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Tovak" and 4 or 2
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Monastery, "{en} Monastery(s): +{ru} Монастырь: +{zh-tw}个修道院已焚毁: +{zh-cn}个修道院已焚毁: +{ko} 수도원: +{es} Monasterios: +{fr} Monastères: +{pt-br} Monastérios: +{de} Kloster(s): +", turnOrder[a].score.Monastery*monasteryRate})
							totalScore=totalScore+(turnOrder[a].score.Monastery*monasteryRate)
						end
						if turnOrder[a].score.VolkareCamp>0 and forTheCouncil~=true then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.VolkareCamp, "{en} Volkare Pursuits: +{ru} Охоты на Волкара: +{zh-tw}沃卡里追击： +{zh-cn}沃卡里追击： +{ko} 볼케어 진영 추적: +{es} Persecuciones de Volkare: +{fr} Volkare Poursuites: +{pt-br} Volkare Persegue: +{de} Volkare Verfolgungen: +", turnOrder[a].score.VolkareCamp})
							totalScore=totalScore+turnOrder[a].score.VolkareCamp
						end
						if turnOrder[a].score.gConqueror>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Conqueror: +{ru}Великий завоеватель: +{zh-tw}至高征服者： +{zh-cn}至高征服者： +{ko}위대한 정복자: +{es}Mayor Conquistador: +{fr}Plus Grand Conquérant: +{pt-br}Maior Conquistador: +{de}Größter Eroberer: +", turnOrder[a].score.gConqueror})
							totalScore=totalScore+turnOrder[a].score.gConqueror
						end
					end
					updateScorePannel("Conqueror", lineFeed, assembledText)
				end

				--Against the Horsemen competitive scoring: +6 per personal kill and the special Slayer title.
				if againstHorsemen and gStates.coop==0 then
					assembledText="" lineFeed=0
					local defeated=turnOrder[a].score.HorsemenDefeated or 0
					if defeated>0 then
						local horsemenLabel=defeated==1 and "{en} Horseman: +{ru} Всадник: +{zh-tw} 名騎士：+{zh-cn} 名骑士：+{ko}명의 기사: +{es} Jinete: +{fr} Cavalier : +{pt-br} Cavaleiro: +{de} Reiter: +" or "{en} Horsemen defeated: +{ru} Всадников побеждено: +{zh-tw} 名騎士被擊敗：+{zh-cn} 名骑士被击败：+{ko}명의 기사 처치: +{es} Jinetes derrotados: +{fr} Cavaliers vaincus : +{pt-br} Cavaleiros derrotados: +{de} Reiter besiegt: +"
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{defeated,horsemenLabel,defeated*6})
						totalScore=totalScore+(defeated*6)
					end
					if (turnOrder[a].score.gHorsemanSlayer or 0)>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Horseman Slayer: +{ru}Лучший истребитель Всадников: +{zh-tw}最佳騎士剋星：+{zh-cn}最佳骑士克星：+{ko}최고의 기사 처치자: +{es}Mayor cazador de Jinetes: +{fr}Meilleur tueur de Cavaliers : +{pt-br}Maior Matador de Cavaleiros: +{de}Größter Reiterbezwinger: +",turnOrder[a].score.gHorsemanSlayer})
						totalScore=totalScore+turnOrder[a].score.gHorsemanSlayer
					end
					UI.setAttribute("TezlaScoreHeadingText","text","{en}Horsemen{ru}Всадники{zh-tw}騎士{zh-cn}骑士{ko}기사{es}Jinetes{fr}Cavaliers{pt-br}Cavaleiros{de}Reiter")
					updateScorePannel("Tezla",lineFeed,assembledText)
				end

				--Against the Dragon competitive scoring. Every Shield on a coloured head is one
				--level reduced and therefore +1 score. Each head also awards one +5 Greatest Slayer.
				if againstDragon and gStates.coop==0 then
					assembledText="" lineFeed=0
					local dragonPlayer=dragonScoreSummary.byMage[turnOrder[a].mage] or {levels=0,slayerBonus=0,slayerHeads={}}
					if dragonPlayer.levels>0 then
						local dragonScoreLabel=apocalypseHere and "{en} Head Slayer score: +{ru} Счёт истребителя голов: +{zh-tw} 龍首剋星分數：+{zh-cn} 龙首克星分数：+{ko} 용 머리 처치 점수: +{es} Puntuación de cazador de cabezas: +{fr} Score de tueur de têtes : +{pt-br} Pontuação de matador de cabeças: +{de} Kopfbezwinger-Wertung: +" or "{en} Dragon Head Level(s) Reduced: +{ru} Снижено уровней голов Дракона: +{zh-tw} 降低的巨龍頭部等級：+{zh-cn} 降低的巨龙头部等级：+{ko} 감소시킨 드래곤 머리 레벨: +{es} Niveles de cabezas del Dragón reducidos: +{fr} Niveaux de têtes du Dragon réduits : +{pt-br} Níveis de cabeças do Dragão reduzidos: +{de} Reduzierte Drachenkopf-Stufen: +"
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{dragonPlayer.levels,dragonScoreLabel,dragonPlayer.levels})
						totalScore=totalScore+dragonPlayer.levels
					end
					if dragonPlayer.slayerBonus>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{#dragonPlayer.slayerHeads,"{en} Greatest Head Slayer bonus(es): +{ru} Бонус лучшего истребителя голов: +{zh-tw} 最佳龍首剋星獎勵：+{zh-cn} 最佳龙首克星奖励：+{ko} 최고의 용 머리 처치자 보너스: +{es} Bonificación del mejor cazador de cabezas: +{fr} Bonus du meilleur tueur de têtes : +{pt-br} Bônus do maior matador de cabeças: +{de} Bonus des größten Kopfbezwingers: +",dragonPlayer.slayerBonus})
						totalScore=totalScore+dragonPlayer.slayerBonus
					end
					UI.setAttribute("TezlaScoreHeadingText","text",apocalypseHere and "{en}Head Slayer score{ru}Счёт истребителя голов{zh-tw}龍首剋星分數{zh-cn}龙首克星分数{ko}용 머리 처치 점수{es}Puntuación de cazador de cabezas{fr}Score de tueur de têtes{pt-br}Pontuação de matador de cabeças{de}Kopfbezwinger-Wertung" or "{en}Dragon{ru}Дракон{zh-tw}巨龍{zh-cn}巨龙{ko}드래곤{es}Dragón{fr}Dragon{pt-br}Dragão{de}Drache")
					updateScorePannel("Tezla",lineFeed,assembledText)
				end

				--Total Score
				if (gStates.coop==0 or gStates.WarOfFourComp==true) then
					UI.setAttribute("CompScoreData", "active", "true")
					UI.setAttribute("Total"..pannel.."ScoreCell", "active", "true")
					if forTheCouncil then
						local resultSuffix=councilMissionResult~="" and joinLang({"\n", councilMissionResult}) or ""
						UI.setAttribute("Total"..pannel.."ScoreText", "text", joinLang({translateWord[turnOrder[a].mage], "{en}'s Final Score: {ru}'s Final Score: {zh-tw}'s Final Score: {zh-cn}'s Final Score: {ko}'s Final Score: {es}'s Final Score: {fr}'s Final Score: {pt-br}'s Final Score: {de}'s Final Score: ", totalScore, resultSuffix}))
					else
						UI.setAttribute("Total"..pannel.."ScoreText", "text", joinLang({translateWord[turnOrder[a].mage], "{en}'s Final Fame: {ru} имеет итого Славы: {zh-tw}的最终名望： {zh-cn}的最终名望： {ko} 의 최종 명성: {es} Fama Final: {fr} Gloire Finale: {pt-br} Fama Final: {de}End-Ruhm: ", totalScore}))
					end
					if gStates.gameScenario=="Conquer and Hold" then UI.setAttribute("Total"..pannel.."ScoreText", "text", joinLang({translateWord[turnOrder[a].mage], "{en}'s Final VP: {ru} имеет итого ПО: {zh-tw}的最终分数： {zh-cn}的最终分数： {ko} 의 최종 승점: {es} Vicepresidente Final: {fr} Vice-Président Final de: {pt-br} Pontos de Vitória Final: {de}s End-VP: ", totalScore})) end
					turnOrder[a].score.finalScore=totalScore
				end
				pannel=pannel+1
			else
				if forTheCouncil~=true then
					assembledText="" lineFeed=0
					if gStates.positionMageKnight[5]~="Volkare" then
						--First Reconnaissance uses normal Achievement scoring only; it does not use Solo Conquest efficiency bonuses.
						if gStates.gameScenario~="First Reconnaissance" then
						--Efficiency
						if gStates.currentRound<gStates.rounds and gStates.gameScenario~="The Lost Relic Blitz" then
							local c=30
							if gStates.gameScenario=="The Gauntlet" then c=40 end
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{gStates.rounds-gStates.currentRound, "{en} Round(s) still to go: +{ru} Оставшиеся Раунды: +{zh-tw}个未开始的轮次： +{zh-cn}个未开始的轮次： +{ko} 남은 라운드: +{es} Rondas Aún por Hacer: +{fr} Rounds Encore à Faire: +{pt-br} Rodadas ainda a completar: +{de} Noch ausstehende Runde(n): +", ((gStates.rounds-gStates.currentRound)*c)})
							coopScore=coopScore+((gStates.rounds-gStates.currentRound)*c)
						end
						if turnOrder[a].score.CardsLeft>0 then
							local c=1
							if gStates.gameScenario=="The Gauntlet" then c=2 end
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CardsLeft, "{en} Dummy Card(s) Left: +{ru} Карт у виртуального игрока: +{zh-tw}虚拟玩家剩余牌池量： +{zh-cn}虚拟玩家剩余牌池量： +{ko} 남은 가상 플레이어의 카드: + {es} Cartas Falsas Restantes: +{fr} Cartes Factices Restantes: +{pt-br} Cartas Restantes do Jog. Fic.: +{de} Dummy-Karte(n) links: +", turnOrder[a].score.CardsLeft*c})
							coopScore=coopScore+turnOrder[a].score.CardsLeft*c
						end
						if gStates.endRoundCalled==false then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Round End Not Called: +5{ru}Конец последнего Раунда не был объявлен: +5{zh-tw}最后一轮中没有声明本轮结束： +5{zh-cn}最后一轮中没有声明本轮结束： +5{ko}라운드 종료 선언되지 않음: +5{es}Final de Ronda no Llamado: +5{fr}Fin de Manche non Appelée: +5{pt-br}Rodada final Não chamada: +5{de}Rundenende nicht ausgerufen: +5"})
							coopScore=coopScore+5
						end
						if gStates.gameScenario=="Druid Nights" and gStates.playerCount==1 then
							local rituals=0
							for _,details in pairs(turnOrder) do if details.mage~=gStates.positionMageKnight[5] then rituals=details.druidNightsRitualCount or 0 break end end
							if rituals>0 then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{rituals,"{en} Incantation(s): +{ru} Incantation(s): +{zh-tw} Incantation(s): +{zh-cn} Incantation(s): +{ko} Incantation(s): +{es} Incantation(s): +{fr} Incantation(s): +{pt-br} Incantation(s): +{de} Incantation(s): +",rituals*15})
								coopScore=coopScore+(rituals*15)
							end
						end
						if gStates.gameScenario=="Against the Apocalypse Blitz" and gStates.coop==1 and gStates.endGameAchieved=="true" then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Beat the Scenario: +15{ru}Прохождение сценария: +15{zh-tw}通關劇本：+15{zh-cn}通关剧本：+15{ko}시나리오 클리어: +15{es}Superar el escenario: +15{fr}Victoire dans le scénario : +15{pt-br}Superou o cenário: +15{de}Szenario gemeistert: +15"})
							coopScore=coopScore+15
						end
						updateScorePannel("Efficiency", lineFeed, assembledText)
						end
					else
						--Volkare
						if gStates.volkareWon~=true then
							local volkareCombatLevel={"Daring", "Heroic", "Legendary"}
							local volkareRaceLevel={"Fair", "Tight", "Thrilling"}
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{translateWord[volkareCombatLevel[gStates.volkareCombatLevel]], "{en} Volkare Combat Level: +(({ru} Уровень битвы Волкара: +(({zh-tw}沃卡里战斗等级： +（（{zh-cn}沃卡里战斗等级： +（（{ko} 볼케어 전투 레벨: +(({es} Nivel de Combate Volkare: +(({fr} Niveau de Combat Volkare: +(({pt-br} Nível de Combate de Volkare: +(({de} Volkare Kampfstufe: +((", (gStates.volkareCombatLevel*10)+20})
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CardsLeft, "{en} Volkare Card(s) Left: +{ru} Карт у Волкара: +{zh-tw}沃卡里卡池剩余： +{zh-cn}沃卡里卡池剩余： +{ko} 남은 볼케어 카드: +{es} Cartas Volkare Restantes: +{fr} Cartes Volkare Restantes: +{pt-br} Cartas de Volkare Restantes: +{de} Volkare Karte(n) übrig: +", (turnOrder[a].score.CardsLeft*2), ")"})
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{translateWord[volkareRaceLevel[gStates.volkareRaceLevel]], "{en} Volkare Race Level: x{ru} Уровень гонки Волкара: x{zh-tw}沃卡里移动等级： x{zh-cn}沃卡里移动等级： x{ko} 볼케어 레이스 레벨: x{es} Nivel de Carrera Volkare: x{fr} Niveau de Course Volkare: x{pt-br} Nível de Corrida de Volkare: +{de} Volkare Ethnie Stufe: x", (((gStates.volkareRaceLevel-1)/2)+1), ")"})
							coopScore=coopScore+((((gStates.volkareCombatLevel*10)+20)+(turnOrder[a].score.CardsLeft*2))*(((gStates.volkareRaceLevel-1)/2)+1))
							updateScorePannel("Volkare", lineFeed, assembledText)
						end
					end

					--Against the Horsemen cooperative/solo scenario bonuses. Standard cooperative Achievement
					--scoring above already supplies the lowest Fame base and the best score in each category.
					if againstHorsemen then
						assembledText="" lineFeed=0
						if horsemenSummary.total>0 then
							local horsemenLabel=horsemenSummary.total==1 and "{en} Horseman: +{ru} Всадник: +{zh-tw} 名騎士：+{zh-cn} 名骑士：+{ko}명의 기사: +{es} Jinete: +{fr} Cavalier : +{pt-br} Cavaleiro: +{de} Reiter: +" or "{en} Horsemen defeated: +{ru} Всадников побеждено: +{zh-tw} 名騎士被擊敗：+{zh-cn} 名骑士被击败：+{ko}명의 기사 처치: +{es} Jinetes derrotados: +{fr} Cavaliers vaincus : +{pt-br} Cavaleiros derrotados: +{de} Reiter besiegt: +"
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{horsemenSummary.total,horsemenLabel,horsemenSummary.total*4})
							coopScore=coopScore+(horsemenSummary.total*4)
						end
						if gStates.playerCount>1 and horsemanEveryScoringPlayerDefeatedOne(horsemenSummary)==true then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Each player defeated a Horseman: +6{ru}Каждый игрок победил Всадника: +6{zh-tw}每位玩家都擊敗了一名騎士：+6{zh-cn}每位玩家都击败了一名骑士：+6{ko}각 플레이어가 기사를 한 명씩 처치: +6{es}Cada jugador derrotó a un Jinete: +6{fr}Chaque joueur a vaincu un Cavalier : +6{pt-br}Cada jogador derrotou um Cavaleiro: +6{de}Jeder Spieler besiegte einen Reiter: +6"})
							coopScore=coopScore+6
						end
						if horsemenSummary.total>=4 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All Horsemen defeated: +15{ru}Все Всадники побеждены: +15{zh-tw}所有騎士皆被擊敗：+15{zh-cn}所有骑士皆被击败：+15{ko}모든 기사 처치: +15{es}Todos los Jinetes derrotados: +15{fr}Tous les Cavaliers vaincus : +15{pt-br}Todos os Cavaleiros derrotados: +15{de}Alle Reiter besiegt: +15"})
							coopScore=coopScore+15
						end
						UI.setAttribute("TezlaScoreHeadingText","text","{en}Horsemen{ru}Всадники{zh-tw}騎士{zh-cn}骑士{ko}기사{es}Jinetes{fr}Cavaliers{pt-br}Cavaleiros{de}Reiter")
						local temp=pannel
						pannel=1
						UI.setAttribute("Tezla1ScoreCell","columnSpan","4")
						UI.setAttribute("Tezla1ScoreText","alignment","MiddleCenter")
						updateScorePannel("Tezla",lineFeed,assembledText)
						pannel=temp
					end

					--Against the Dragon cooperative/solo goal scoring. Generic efficiency scoring above
					--already handles early Rounds, Dummy cards left, and the uncalled End-of-Round +5.
					if againstDragon then
						assembledText="" lineFeed=0
						if apocalypseHere and horsemenSummary.total>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{horsemenSummary.total,"{en} Horsemen defeated: +{ru} Всадников побеждено: +{zh-tw} 名騎士被擊敗：+{zh-cn} 名骑士被击败：+{ko}명의 기사 처치: +{es} Jinetes derrotados: +{fr} Cavaliers vaincus : +{pt-br} Cavaleiros derrotados: +{de} Reiter besiegt: +",horsemenSummary.total*3})
							coopScore=coopScore+(horsemenSummary.total*3)
						end
						if apocalypseHere and gStates.playerCount>1 and horsemanEveryScoringPlayerDefeatedOne(horsemenSummary)==true then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Each player defeated a Horseman: +5{ru}Каждый игрок победил Всадника: +5{zh-tw}每位玩家都擊敗一名騎士：+5{zh-cn}每位玩家都击败一名骑士：+5{ko}각 플레이어가 기사를 한 명씩 처치: +5{es}Cada jugador derrotó a un Jinete: +5{fr}Chaque joueur a vaincu un Cavalier : +5{pt-br}Cada jogador derrotou um Cavaleiro: +5{de}Jeder Spieler besiegte einen Reiter: +5"})
							coopScore=coopScore+5
						end
						if dragonScoreSummary.defeatedHeads>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{dragonScoreSummary.defeatedHeads,"{en} Dragon Head(s) Defeated: +{ru} Побеждено голов Дракона: +{zh-tw} 擊敗的巨龍頭部：+{zh-cn} 击败的巨龙头部：+{ko} 처치한 드래곤 머리: +{es} Cabezas del Dragón derrotadas: +{fr} Têtes du Dragon vaincues : +{pt-br} Cabeças do Dragão derrotadas: +{de} Besiegte Drachenköpfe: +",dragonScoreSummary.defeatedHeads*5})
							coopScore=coopScore+(dragonScoreSummary.defeatedHeads*5)
						end
						if dragonScoreSummary.defeatedHeads>=4 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All Dragon Heads defeated: +15{ru}Все головы Дракона побеждены: +15{zh-tw}所有巨龍頭部都已擊敗：+15{zh-cn}所有巨龙头部都已击败：+15{ko}모든 드래곤 머리 처치: +15{es}Todas las cabezas del Dragón derrotadas: +15{fr}Toutes les têtes du Dragon vaincues : +15{pt-br}Todas as cabeças do Dragão derrotadas: +15{de}Alle Drachenköpfe besiegt: +15"})
							coopScore=coopScore+15
						end
						UI.setAttribute("TezlaScoreHeadingText","text",apocalypseHere and "{en}Apocalypse{ru}Апокалипсис{zh-tw}末日{zh-cn}末日{ko}아포칼립스{es}Apocalipsis{fr}Apocalypse{pt-br}Apocalipse{de}Apokalypse" or "{en}Dragon{ru}Дракон{zh-tw}巨龍{zh-cn}巨龙{ko}드래곤{es}Dragón{fr}Dragon{pt-br}Dragão{de}Drache")
						local temp=pannel
						pannel=1
						UI.setAttribute("Tezla1ScoreCell","columnSpan","4")
						UI.setAttribute("Tezla1ScoreText","alignment","MiddleCenter")
						updateScorePannel("Tezla",lineFeed,assembledText)
						pannel=temp
					end

					--Relic Score
					if gStates.gameScenario=="The Lost Relic Blitz" then
						assembledText="" lineFeed=0
						if foundRelic>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{foundRelic, "{en} Relic(s) Found: +{ru} Реликвия найдена: +{zh-tw}个圣器已收集: +{zh-cn}个圣器已收集: +{ko} 발견한 유물: +{es} Reliquias Encontradas: +{fr} Reliques Trouvées: +{pt-br} Relíquias Encontradas: +{de} Relikt(e) gefunden: +", (foundRelic*5)})
							coopScore=coopScore+(foundRelic*5)
						end
						if gStates.playersRef~=5 then
							local EveryRelic=true
							for b=1, #turnOrder, 1 do
								if turnOrder[b].mage~=gStates.positionMageKnight[5] then
									if turnOrder[b].score.Relic==0 then EveryRelic=false break end
								end
							end
							if EveryRelic==true then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Every player collected a Relic: +5{ru}Каждый игрок собрал реликвию: +5{zh-tw}每位玩家收集一件圣器: +5{zh-cn}每位玩家收集一件圣器: +5{ko}모든 플레이어 유물 수집: +5{es}Cada Jugador Recogió una Reliquia: +5{fr}Chaque Joueur a Récupéré une Relique: +5{pt-br}Cada Jogador coletou uma Relíquia: +5{de}Jeder Spieler hat eine Reliquie gesammelt: +5"})
								coopScore=coopScore+5
							end
						end
						if foundRelic==gStates.cityTiles then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All relics collected: +10{ru}Все реликвии собраны: +10{zh-tw}收集所有圣器: +10{zh-cn}收集所有圣器: +10{ko}모든 유물 수집됨: +10{es}Todas las Reliquias Recolectadas: +10{fr}Toutes les Reliques Collectées: +10{pt-br}Todas Relíquias Coletadas: +10{de}Alle gesammelten Reliquien: +10"})
							coopScore=coopScore+10
						end
						local temp=pannel
						pannel=1
						UI.setAttribute("Relic1ScoreCell", "columnSpan", "4")
						UI.setAttribute("Relic1ScoreText", "alignment", "MiddleCenter")
						updateScorePannel("Relic", lineFeed, assembledText)
						pannel=temp
					end

					--City Coop Score. Fractured Lands explicitly does not use City scoring.
					if fracturedLandsNoCityScore~=true and (gStates.defeatedCities.amount>0 or gStates.gameScenario=="The Gauntlet") then
						assembledText="" lineFeed=0
						local cityValue=10
						if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" then cityValue=20 end
						if gStates.gameScenario=="Volkare's Quest" then cityValue=5 end
						if gStates.gameScenario~="The Gauntlet" then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{gStates.defeatedCities.amount, "{en} Conquered City(s): +{ru} Захваченный Город: +{zh-tw}个城市已征服: +{zh-cn}个城市已征服: +{ko} 정복한 도시: +{es} Ciudades Conquistadas: +{fr} Villes Conquises: +{pt-br} Cidades Conquistadas: +{de} Eroberte Stadt(en): +", (gStates.defeatedCities.amount*cityValue)})
							coopScore=coopScore+(gStates.defeatedCities.amount*cityValue)
						end
						if gStates.gameScenario~="Volkare's Return" and gStates.gameScenario~="Volkare's Return Blitz" and gStates.gameScenario~="Volkare's Quest" then
							if gStates.playersRef~=5 and gStates.allLeaderCheck==true then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Each Player is a Leader of a City: +10{ru}Каждый игрок владеет Городом: +10{zh-tw}每个玩家都是一个城市的领袖: +10{zh-cn}每个玩家都是一个城市的领袖: +10{ko}각 플레이어가 도시 지도자: +10{es}Cada Jugador es un Líder de una Ciudad: +10{fr}Chaque Joueur est un Chef de Ville: +10{pt-br}Cada jogador é um líder de uma cidade: +10{de}Jeder Spieler ist ein Anführer einer Stadt: +10"})
								coopScore=coopScore+10
							end
							if gStates.defeatedCities.amount==gStates.cityTiles then--+gStates.megapolis
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All Cities are Conquered: +15{ru}Все города захвачены: +15{zh-tw}征服了所有城市: +15{zh-cn}征服了所有城市: +15{ko}모든 도시 정복됨: +15{es}Todas las Ciudades son Conquistadas: +15{fr}Toutes les Villes Sont Conquises: +15{pt-br}Todas Cidades Conquistadas: +15{de}Alle Städte sind erobert: +15"})
								coopScore=coopScore+15
							end
						end
						if gStates.gameScenario=="The Gauntlet" and gStates.endGameAchieved=="true" then
							assembledText="{en}Entered the Red City: +10\nBought the Artifact: +10{ru}Красный город посещен: +10\nАртефакт куплен: +10{zh-tw}进入红色城市： +10\n购买圣器： +10{zh-cn}进入红色城市： +10\n购买圣器： +10{ko}적색 도시 입장: +10\n유물 구입: +10{es}Entró en la Ciudad Roja: +10\nCompró la Reliquia: +10{fr}Entrée dans la Ville Rouge: +10\nAcheté la Relique: +10{pt-br}Entrou na Cidade Vermelha:+10\nComprou a Relíquia: +10{de}Die Rote Stadt betreten: +10\nKaufte das Artefakt: +10"
							lineFeed=2
							coopScore=coopScore+20
						end

						local temp=pannel
						pannel=1
						UI.setAttribute("City1ScoreCell", "columnSpan", "4")
						UI.setAttribute("City1ScoreText", "alignment", "MiddleCenter")
						updateScorePannel("City", lineFeed, assembledText)
						pannel=temp
					end

					--Faction Leader Coop Score. Horsemen and Dragon scenarios reuse this UI row for
					--their scenario scoring above, so do not clear or relabel it afterward.
					if againstHorsemen~=true and againstDragon~=true then
					assembledText="" lineFeed=0
					if (gStates.gameScenario=="Life and Death" or gStates.gameScenario=="Ultimate Conquest") and gStates.coop==1 and gStates.defeatedFaction>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{gStates.defeatedFaction, "{en} Leader(s) Defeated: +{ru} Лидер побежден: +{zh-tw}个领袖已击败: +{zh-cn}个领袖已击败: +{ko} 처치한 지도자: +{es} Líderes Derrotados: +{fr} Chefs Vaincus: +{pt-br} Líderes Derrotados: +{de} Anführer besiegt: +", (gStates.defeatedFaction*10)})
						coopScore=coopScore+(gStates.defeatedFaction*10)
						if gStates.defeatedFaction==2 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Both Leaders are defeated: +15{ru}Оба Лидера побеждены: +15{zh-tw}两位领袖都被击败: +15{zh-cn}两位领袖都被击败: +15{ko}모든 지도자 처치됨: +15{es}Ambos Líderes son Derrotados: +15{fr}Les deux Chefs sont Vaincus: +15{pt-br}Ambos líderes derrotados: +15{de}Beide Anführer sind besiegt: +15"})
							coopScore=coopScore+15
							if gStates.playersRef~=5 then
								if gStates.allPlayersFoughtAFactionLeaderCheck==true then
									assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Every player helped defeat a Leader: +10{ru}Каждый игрок помог победить Лидера: +10{zh-tw}每个玩家都帮助击败了一个领袖: +10{zh-cn}每个玩家都帮助击败了一个领袖: +10{ko}모든 플레이어가 지도자 처치에 참여: +10{es}Cada Jugador Ayudó a Derrotar a un Líder: +10{fr}Chaque Joueur a Aidé à Vaincre un Leader: +10{pt-br}Cada Jogador ajudou a derrotar um Líder: +10{de}Jeder Spieler hat geholfen, einen Anführer zu besiegen: +10"})
									coopScore=coopScore+10
								end
								if gStates.allPlayersFoughtBothFactionLeaderCheck==true then
									assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Every player helped defeat Both Leaders: +10{ru}Каждый игрок помог победить обоих Лидеров: +10{zh-tw}每个玩家都帮助击败了两个领袖: +10{zh-cn}每个玩家都帮助击败了两个领袖: +10{ko}모든 플레이어가 두 지도차 처치에 참여: +10{es}Cada Jugador Ayudó a Derrotar a Ambos Líderes: +10{fr}Chaque Joueur a Aidé à Vaincre les Deux Leaders: +10{pt-br}Cada Jogador ajudou a derrotar ambos Líderes: +10{de}Jeder Spieler hat geholfen, beide Anführer zu besiegen: +10"})
									coopScore=coopScore+10
								end
							end
						end
					end
					if gStates.gameScenario=="The Realm of the Dead Blitz" and gStates.coop==1 then
						if gStates.defeatedFaction>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Necromancer is Defeated: +10{ru}Некромант побежден: +10{zh-tw}亡灵法师被击败: +10{zh-cn}亡灵法师被击败: +10{ko}네크로맨서 처치됨: +10{es}Nigromante es Derrotado: +10{fr}Nécromancien est Vaincu: +10{pt-br}Necromante derrotado: +10{de}Nekromant ist besiegt: +10"})
							coopScore=coopScore+10
						end
						if coopGraveYard>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{coopGraveYard, "{en} Graveyard(s) sealed: +{ru} Кладбище запечатано: +{zh-tw}个墓穴已封印: +{zh-cn}个墓穴已封印: +{ko} 봉인된 묘지: +{es} Cementerios Sellados: +{fr} Cimetières Scellés: +{pt-br} Cemitérios Selados: +{de} Friedhof(e) versiegelt: +", (coopGraveYard*5)})
							coopScore=coopScore+(coopGraveYard*5)
						end
						if gStates.defeatedFaction>0 and coopGraveYard>=gStates.playerCount+1 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Necromancer defeated & Graveyards sealed: +10{ru}Некромант побежден & Кладбища запечатаны: +10{zh-tw}亡灵法师被击败并封印墓穴: +10{zh-cn}亡灵法师被击败并封印墓穴: +10{ko}네크로맨서 처치 & 묘지 봉인됨: +10{es}Nigromante derrotado y Cementerios sellados: +10{fr}Nécromancien vaincu & Cimetières scellés: +10{pt-br}Necromante derrotado e Cemitérios Selados: +10{de}Nekromant besiegt & Friedhöfe versiegelt: +10"})
							coopScore=coopScore+10
						end
					end
					if (gStates.gameScenario=="The Realm of the Dead Blitz" or gStates.gameScenario=="The Hidden Valley Blitz") and gStates.coop==1 and gStates.playersRef~=5 and gStates.allPlayersFoughtAFactionLeaderCheck==true and gStates.defeatedFaction>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Every player helped defeat the Leader: +20{ru}Каждый игрок помог победить Лидера: +20{zh-tw}所有玩家都帮助击败了首领: +20{zh-cn}所有玩家都帮助击败了首领: +20{ko}모든 플레이어가 지도자 처치에 참여: +20{es}Todos los Jugadores Ayudaron a Derrotar al Líder: +20{fr}Chaque Joueur a Aidé à Vaincre le Leader: +20{pt-br}Cada Jogador ajudou a derrotar o Líder: +20{de}Jeder Spieler hat geholfen, den Anführer zu besiegen: +20"})
						coopScore=coopScore+20
					end
					if gStates.gameScenario=="The Hidden Valley Blitz" and gStates.coop==1 and gStates.defeatedFaction>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Defeated the High Priestess: +20{ru}Верховная Жрица побеждена: +20{zh-tw}击败高阶祭司: +20{zh-cn}击败高阶祭司: +20{ko}하이 프리스트 처치됨: +20{es}Derrota a la Suma Sacerdotisa: +20{fr}Vaincre la Grande Prêtresse: +20{pt-br}Derrotou a Alta Sacerdotiza: +20{de}Die Hohepriesterin besiegt: +20"})
						coopScore=coopScore+20
					end
					local temp=pannel
					pannel=1
					UI.setAttribute("TezlaScoreHeadingText", "text", "{en}Faction Scoring{ru}Подсчет очков фракций{zh-tw}派系得分{zh-cn}派系得分{ko}세력 점수{es}Puntuación de Facción{fr}Décompte des Factions{pt-br}Pontuação de Facção{de}Faction-Wertung")
					UI.setAttribute("Tezla1ScoreCell", "columnSpan", "4")
					UI.setAttribute("Tezla1ScoreText", "alignment", "MiddleCenter")
					updateScorePannel("Tezla", lineFeed, assembledText)
					pannel=temp
					end
				end
				--Total Score
				UI.setAttribute("CoopScoreData", "active", "true")
				if forTheCouncil then
					local resultSuffix=councilMissionResult~="" and joinLang({"\n", councilMissionResult}) or ""
					UI.setAttribute("CoopScoreText", "text", joinLang({"{en}Final Score: {ru}Final Score: {zh-tw}Final Score: {zh-cn}Final Score: {ko}Final Score: {es}Final Score: {fr}Final Score: {pt-br}Final Score: {de}Final Score: ", coopScore, resultSuffix}))
				else
					UI.setAttribute("CoopScoreText", "text", joinLang({"{en}Final Fame: {ru}Итого Славы: {zh-tw}最终名望: {zh-cn}最终名望: {ko}최종 명성: {es}Fama Final: {fr}Gloire Finale: {pt-br}Fama Final: {de}Endgültiger Ruhm: ", coopScore}))
				end
				for count=1, #turnOrder-1 ,1 do
					turnOrder[count].score.finalScore=coopScore
				end
			end
		end

		--final scoreboard tweaks
		UI.show("ScoreBoard")
		local visibility=""
		if player~="all" then
			scoreViewing[#scoreViewing+1]=player.color
			for a=1, #scoreViewing, 1 do
				visibility=visibility..scoreViewing[a]
				if a<#scoreViewing then visibility=visibility.."|" end
			end
		end
		UI.setAttribute("ScoreBoard", "visibility", visibility)
		for a, b in pairs(heights) do
			if b>24 and a~="Reward" then totalHeight=totalHeight+30 end
		end
		UI.setAttribute("ScoreBoard", "height", totalHeight)
		UI.setAttribute("ScoreBoard", "width", (pannel-1)*280)
		if gStates.playersRef==5 then
			UI.setAttribute("ScoreBoard", "width", 400)
			UI.setAttribute("ScoreBoardTable", "columnWidths", "400")
		end
		if gameOver==true and gStates.scoreRecorded==false then UI.show("SendScoreRequest") gStates.scoreRecorded=true end
		table.sort(turnOrder, function (k1, k2) return k1.tactic<k2.tactic end)
	end
end

-- Final claimed-card layout
function layoutClaimedCards()
	--A Time Bending set aside on the victorious final round still belongs to its owner and must be present for scoring.
	if gStates~=nil and gStates.timeBendingRemovedSeat~=nil then if reclaimTimeBending(layoutClaimedCards)==true then return end end
	--Never dismantle live deed decks/hands while the active turn is still waiting
	--for Rewards Claimed. The final boundary must be crossed first.
	if gStates~=nil and gStates.preEndTurn==true then
		log("layoutClaimedCards ignored: Rewards Claimed is still pending.")
		return
	end
	--Score the untouched deck/discard/hand/play-area state before dismantling Deck objects.
	--TTS zone membership can lag behind takeObject/setPosition by a frame, and Deck remainders below
	--are deliberately moved later, so scoring after the layout could temporarily miss claimed cards.
	displayScore("all", "-1", nil)
	for _, turnDetails in pairs(turnOrder) do
		if turnDetails.mage~=gStates.positionMageKnight[5] then
			local obj={}
			local OffsetX={["Advanced Action"]=0, ["Spell"]=0, ["Artifact"]=0, ["Wound"]=0}
			local OffsetY={["Advanced Action"]=0, ["Spell"]=0, ["Artifact"]=0, ["Wound"]=0}
			local OffsetZ={["Advanced Action"]=0, ["Spell"]=0, ["Artifact"]=0, ["Wound"]=0}
			local OffsetStart={["Advanced Action"]=-97, ["Spell"]=-91, ["Artifact"]=-85, ["Wound"]=-103}
			local xOffset=0.4
			local yOffset=0.04
			local zOffset=0.8
			--Look for Cards
			for _, c in pairs(getObjectFromGUID(deedDeckZones[turnDetails.seatPos]).getObjects()) do obj[#obj+1]=c end
			for _, c in pairs(getObjectFromGUID(deedDeckDiscardZones[turnDetails.seatPos]).getObjects()) do obj[#obj+1]=c end
			for _, c in pairs(getObjectFromGUID(handZones[turnDetails.seatPos]).getObjects()) do obj[#obj+1]=c end
			for _, c in pairs(obj) do
				if c.type=="Deck" then
					for _, card in pairs(c.getObjects()) do
						if c.remainder~=nil and (card.gm_notes=="Advanced Action" or card.gm_notes=="Spell" or card.gm_notes=="Artifact" or card.gm_notes=="Wound") then
							local lastCard=c.remainder
							safeWaitFrames("Scoring",function()
								lastCard.setPosition({(turnDetails.seatPos*40)+OffsetStart[card.gm_notes]+OffsetX[card.gm_notes], 1.1+OffsetY[card.gm_notes], -39.4-OffsetZ[card.gm_notes]})
								OffsetX[card.gm_notes]=OffsetX[card.gm_notes]+xOffset
								OffsetY[card.gm_notes]=OffsetY[card.gm_notes]+yOffset
								OffsetZ[card.gm_notes]=OffsetZ[card.gm_notes]+zOffset
								if OffsetZ[card.gm_notes]>4.8 then OffsetZ[card.gm_notes]=0 end
							end, 10)
							break
						end
						if card.gm_notes=="Advanced Action" or card.gm_notes=="Spell" or card.gm_notes=="Artifact" or card.gm_notes=="Wound" then
							c.takeObject({position={(turnDetails.seatPos*40)+OffsetStart[card.gm_notes]+OffsetX[card.gm_notes], 1.1+OffsetY[card.gm_notes], -39.4-OffsetZ[card.gm_notes]}, rotation={0, 180, 0}, guid=card.guid, smooth=false})
							OffsetX[card.gm_notes]=OffsetX[card.gm_notes]+xOffset
							OffsetY[card.gm_notes]=OffsetY[card.gm_notes]+yOffset
							OffsetZ[card.gm_notes]=OffsetZ[card.gm_notes]+zOffset
							if OffsetZ[card.gm_notes]>4.8 then OffsetZ[card.gm_notes]=0 end
						end
					end
				end
				if c.type=="Card" and (c.getGMNotes()=="Advanced Action" or c.getGMNotes()=="Spell" or c.getGMNotes()=="Artifact" or c.getGMNotes()=="Wound") then
					c.setPosition({(turnDetails.seatPos*40)+OffsetStart[c.getGMNotes()]+OffsetX[c.getGMNotes()], 1.1+OffsetY[c.getGMNotes()], -39.4-OffsetZ[c.getGMNotes()]})
					OffsetX[c.getGMNotes()]=OffsetX[c.getGMNotes()]+xOffset
					OffsetY[c.getGMNotes()]=OffsetY[c.getGMNotes()]+yOffset
					OffsetZ[c.getGMNotes()]=OffsetZ[c.getGMNotes()]+zOffset
					if OffsetZ[c.getGMNotes()]>4.8 then OffsetZ[c.getGMNotes()]=0 end
				end
			end
		end
	end
end

--Swap Day and Night items

end)
__bundle_register("PlayingGame.Horsemen", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Horsemen-private helpers. Predeclared so forward references keep resolving locally.
local horsemanDefeatedInventoryPosition, horsemanMarkDefeatedToken

-- Shared Four Horsemen entity/combat helpers.
-- Scenario-specific reveal, movement, ritual and AI rules remain in Scenario.lua.

--Four Horsemen helpers. The Horsemen use one persistent Custom_Tile GUID each; setHorsemanLevel()
--swaps only the front image (once level art is supplied) and replaces that GUID's normal monster data.
--Cards/neutral level Shields are therefore not required by the scripted implementation.
function horsemanDataFor(ref)
	if ref==nil or horsemanData==nil then return nil, nil end
	local key=tostring(ref)
	if horsemanData[key]~=nil then return horsemanData[key], key end
	local name=horsemanTokenToName~=nil and horsemanTokenToName[key] or nil
	if name~=nil then return horsemanData[name], name end
	return nil, nil
end

function horsemanMonsterData(ref, level)
	local data,name=horsemanDataFor(ref)
	level=math.max(1,math.min(6,tonumber(level) or 1))
	local levelData=data~=nil and data.levels~=nil and data.levels[level] or nil
	if data==nil or levelData==nil then return nil end
	---@type table<string, any>
	local abilities={
		name="Horseman - "..name,
		pugType="horseman",
		horseman=name,
		fame=levelData.fame,
		armour=levelData.armour,
		attack={[data.attackType]={[1]=levelData.attack}},
		reward=1,
		faction="Apoc",
	}
	for ability,value in pairs(data.abilities or {}) do abilities[ability]=value end
	return abilities
end

function setHorsemanLevel(ref, level, hideIdentity)
	local data,name=horsemanDataFor(ref)
	level=math.max(1,math.min(6,tonumber(level) or 1))
	local levelData=data~=nil and data.levels~=nil and data.levels[level] or nil
	if data==nil or name==nil or levelData==nil then return false end
	local token=getObjectFromGUID(data.tokenGUID)
	if token~=nil then
		--The physical rotation now hides an unrevealed Horseman's face, so load the real level art
		--from setup onward instead of swapping to a separate blank image.
		local displayName=hideIdentity==true and "" or (name.." Level "..tostring(level))
		local imageURL=levelData.tokenImg
		if type(imageURL)=="string" and imageURL~="" then
			token.setCustomObject({image=imageURL})
			token.setName(displayName)
			token.reload()
		else
			token.setName(displayName)
		end
	end
	monsterPugs[data.tokenGUID]=horsemanMonsterData(name,level)
	if gStates.horsemen==nil then gStates.horsemen={} end
	local state=gStates.horsemen[name] or {}
	state.level=level
	state.tokenGUID=data.tokenGUID
	if state.defeated==nil then state.defeated=false end
	gStates.horsemen[name]=state
	return true
end

--Rebuild shared Horseman combat state after loading/rewinding a current save.
function horsemanRestoreRuntimeState()
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") then return end
	if type(gStates.horsemenDefeatedBy)~="table" then gStates.horsemenDefeatedBy={} end
	for name,state in pairs(gStates.horsemen or {}) do
		local data=horsemanData~=nil and horsemanData[name] or nil
		if data~=nil and state~=nil then
			if state.defeated==true or state.retired==true then
				monsterPugs[data.tokenGUID]=nil
				if gStates.monsterPerks~=nil then gStates.monsterPerks[data.tokenGUID]=nil end
			else
				monsterPugs[data.tokenGUID]=horsemanMonsterData(name,state.level)
			end
		end
	end
	if gStates.gameScenario=="Against the Horsemen Blitz" and againstHorsemenRestoreScenarioState~=nil then againstHorsemenRestoreScenarioState() end
	if gStates.gameScenario=="Apocalypse is Here" and apocalypseIsHereRestoreScenarioState~=nil then apocalypseIsHereRestoreScenarioState() end
end

--Scenario scoring uses the actual Horseman defeats rather than inventory reward tokens. This remains
--stable if a reward token is temporarily unavailable, and also preserves exactly who earned each kill.
function horsemanDefeatSummary()
	local summary={total=0,byMage={},fameByMage={}}
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") then return summary end
	for name,state in pairs(gStates.horsemen or {}) do
		if state~=nil and state.defeated==true then
			summary.total=summary.total+1
			local mage=state.defeatedBy or (gStates.horsemenDefeatedBy~=nil and gStates.horsemenDefeatedBy[name] or nil)
			if mage~=nil then
				summary.byMage[mage]=(summary.byMage[mage] or 0)+1
				local data=horsemanData~=nil and horsemanData[name] or nil
				local level=math.max(1,math.min(6,tonumber(state.level) or 1))
				local fame=data~=nil and data.levels~=nil and data.levels[level]~=nil and tonumber(data.levels[level].fame) or 0
				summary.fameByMage[mage]=(summary.fameByMage[mage] or 0)+fame
			end
		end
	end
	return summary
end

--The all-players-Horseman cooperative bonus is scenario-specific: +6 in Against the Horsemen and
--+5 in Apocalypse is Here. This helper only checks whether the scoring Mage Knights qualify;
--the standard Dummy/optional Proxy never counts toward that requirement.
function horsemanEveryScoringPlayerDefeatedOne(summary)
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") or gStates.playerCount<=1 then return false end
	summary=summary or horsemanDefeatSummary()
	local found=false
	for _,details in pairs(turnOrder or {}) do
		if details.mage~=nil and details.mage~="nobody" and details.mage~=gStates.positionMageKnight[5] then
			found=true
			if (summary.byMage[details.mage] or 0)<1 then return false end
		end
	end
	return found
end

--Defeated Horsemen are trophies as well as saved scoring state. Keep a tidy 2x2 group in the
--slayer's Inventory and make their defeated status obvious without changing the level artwork.
horsemanDefeatedInventoryPosition=function(playerIndex,name)
	local player=turnOrder[playerIndex]
	local state=name~=nil and gStates.horsemen~=nil and gStates.horsemen[name] or nil
	if player==nil then return {55,2,20} end
	local slot=math.max(1,math.min(4,tonumber(state~=nil and state.mapSlot) or 1))
	local col=(slot-1)%2
	local row=math.floor((slot-1)/2)
	return {(player.seatPos*40)-115.8+(col*3.2),1.35,-32.7-(row*2.7)}
end

horsemanMarkDefeatedToken=function(token,name,playerIndex,smooth)
	local state=name~=nil and gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local player=turnOrder[playerIndex]
	if token==nil or state==nil or player==nil then return false end
	local level=math.max(1,math.min(6,tonumber(state.level) or 1))
	mapTokenReleaseObject(token)
	token.setName("DEFEATED - "..name.." Level "..tostring(level))
	token.setDescription("Defeated by "..tostring(player.mage))
	token.setGMNotes("Defeated Horseman")
	token.setRotation({0,180,0})
	local destination=horsemanDefeatedInventoryPosition(playerIndex,name)
	if smooth==false then token.setPosition(destination) else token.setPositionSmooth(destination,false) end
	return true
end

--A revealed Horseman is a same-space attack option in both Horseman scenarios.
--Against the Horsemen disables these individual attacks once the Round-4 ritual begins; the central
--Glade assault then owns combat against every surviving Horseman instead.
function horsemanAttackOptions(playerIndex,mapPosition)
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") or (gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted==true) then return {} end
	local player=turnOrder[playerIndex]
	if player==nil or player.mage==nil then return {} end
	if gStates.gameScenario=="Against the Horsemen Blitz" then againstHorsemenRefreshReveals() end
	local avPos=mapPosition or mageKnightAvatarPositionByName(player.mage)
	--City/Volkare-Camp avatars can be physically parked on their shared city card. Convert that
	--parking position back to the actual map location just as addAvatarButtons does for site attacks.
	if mapPosition==nil and player.avatarLocation~=nil and (player.avatarLocation:sub(1,4)=="city" or player.avatarLocation=="Volkare's Camp") then
		for zoneGUID,citySearch in pairs(cityScriptZones) do
			local zoneObj=getObjectFromGUID(zoneGUID)
			if zoneObj~=nil then
				local found=false
				for _,obj in pairs(zoneObj.getObjects()) do if obj.getName()==player.mage then found=true break end end
				if found==true then
					local cityObj=nil
					if zoneGUID==volkare.discZone and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") then cityObj=getObjectFromGUID(gStates.volkareModel)
					else cityObj=getObjectFromGUID(citySearch.cityGUID) end
					if cityObj~=nil then avPos=cityObj.getPosition() end
					break
				end
			end
		end
	end
	if avPos==nil then return {} end
	local avTerrain,avBearing,avHexCenter=terrainHexAtPosition(avPos)
	if avTerrain==nil or avBearing==nil then return {} end
	local here={}
	for name,state in pairs(gStates.horsemen or {}) do
		local data=horsemanData~=nil and horsemanData[name] or nil
		local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
		if state~=nil and data~=nil and state.defeated~=true and state.retired~=true and state.revealed==true and token~=nil then
			local tokenPos=token.getPosition()
			local terrain,bearing=terrainHexAtPosition(tokenPos)
			local sameHex=terrain~=nil and terrain.guid==avTerrain.guid and tostring(bearing)==tostring(avBearing)
			--Occupied sites can physically nudge the Horseman when the Mage Knight is dropped on top.
			--Allow a small centre tolerance without reaching the neighbouring hex 2.39 units away.
			if sameHex~=true and avHexCenter~=nil then
				sameHex=((tokenPos[1]-avHexCenter[1])^2)+((tokenPos[3]-avHexCenter[3])^2)<2.25
			end
			if sameHex==true then here[#here+1]={name=name,guid=data.tokenGUID,slot=tonumber(state.mapSlot) or 99} end
		end
	end
	table.sort(here,function(a,b) if a.slot==b.slot then return a.name<b.name end return a.slot<b.slot end)
	local options={}
	for _,entry in ipairs(here) do options[#options+1]={key=entry.guid,name=entry.name,label=entry.name:sub(1,1),targets={[entry.guid]=true}} end
	return options
end

function horsemanAttackAction(playerDud,mouseButton,id)
	if mouseButton~="-1" then return end
	local key,mage=tostring(id or ""):match("^Horse|([^|]+)|(.+)$")
	if key==nil or mage==nil then return end
	local playerIndex=nil
	for index,details in pairs(turnOrder) do if details.mage==mage then playerIndex=index break end end
	if playerIndex==nil or playerIndex~=gStates.turnNumber then return end
	local player=turnOrder[playerIndex]
	--"Avatar" means a first defender has already been staged, but further optional enemies may still
	--be added to that combat. Only "Both" closes the Horseman choice completely.
	if player==nil or player.combatIconHide=="Both" then return end
	local turnToken=getObjectFromGUID(player.turnOrderTokenGUID)
	if turnToken==nil or turnToken.is_face_down==true then return end
	if playerDud~=nil and playerDud.color~=nil and legalPlayerCheck(playerDud.color,player.seatPos)~=true then return end
	local chosen=nil
	for _,option in ipairs(horsemanAttackOptions(playerIndex)) do if option.key==key then chosen=option break end end
	if chosen==nil then addAvatarButtons() return end
	gStates.horsemanAttackSelection={player=playerIndex,targets=chosen.targets}
	attackLocation(playerDud,mouseButton,"Attack"..mage)
end

--Horseman tokens are persistent Custom Tiles, so normal monster-discard logic must not treat them as
--Faction Leaders. A face-up Horseman at cleanup was defeated: record the slayer, award the Apocalypse
--Faction token, and keep the marked Horseman as a trophy in that player's Inventory. Failed face-down
--combats use monsterPlayLocation and the existing undefeated-monster return path instead.
function horsemanResolveDefeat(token,playerIndex,coopCombatReward)
	local name=horsemanTokenToName~=nil and horsemanTokenToName[token~=nil and token.guid or ""] or nil
	local state=name~=nil and gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local player=turnOrder[playerIndex]
	if token==nil or name==nil or state==nil or player==nil then return false end
	if state.defeated==true then
		horsemanMarkDefeatedToken(token,name,playerIndex,true)
		return true
	end
	state.defeated=true
	state.defeatedLevel=tonumber(state.level) or 1
	state.defeatedBy=player.mage
	state.defeatedRound=gStates.currentRound
	state.atCentralGlade=false
	if gStates.horsemenDefeatedBy==nil then gStates.horsemenDefeatedBy={} end
	gStates.horsemenDefeatedBy[name]=player.mage
	local rewardBag=getObjectFromGUID(monsterPiles.rewardApoc)
	if rewardBag~=nil and rewardBag.getQuantity()>0 then
		if coopCombatReward~=nil then
			coopCombatReward.factionRewards.apocalypse=(coopCombatReward.factionRewards.apocalypse or 0)+1
			if coopCombatReward.factionRewardsGiven==true then rewardBag.takeObject({position={(player.seatPos*40)-117.2+(math.random()*6.5),2,-35+(math.random()*3.2)}}) end
		else
			rewardBag.takeObject({position={(player.seatPos*40)-117.2+(math.random()*6.5),2,-35+(math.random()*3.2)}})
		end
	else
		broadcastToAll("{en}Sorry, there are no more Apocalypse Faction Reward Tokens. Use a reminder and collect one when a token becomes available.{ru}Жетоны наград фракции Апокалипсиса закончились. Используйте напоминание и возьмите жетон, когда он станет доступен.{zh-tw}末日陣營獎勵標記已用完。請放置提醒，待標記可用時再領取。{zh-cn}末日阵营奖励标记已用完。请放置提醒，待标记可用时再领取。{ko}아포칼립스 진영 보상 토큰이 더 이상 없습니다. 알림을 사용하고 토큰이 생기면 수령하십시오.{es}No quedan fichas de Recompensa de Facción del Apocalipsis. Usa un recordatorio y recoge una cuando haya una disponible.{fr}Il ne reste plus de jetons de Récompense de Faction de l’Apocalypse. Utilisez un rappel et prenez-en un lorsqu’un jeton sera disponible.{pt-br}Não há mais fichas de Recompensa de Facção do Apocalipse. Use um lembrete e pegue uma quando houver ficha disponível.{de}Es sind keine Apokalypse-Fraktionsbelohnungsmarker mehr verfügbar. Verwende eine Erinnerung und nimm einen Marker, sobald wieder einer verfügbar ist.",positionToColor(playerIndex))
	end
	if gStates.monsterPlayLocation~=nil then gStates.monsterPlayLocation[token.guid]=nil end
	if gStates.monsterPerks~=nil then gStates.monsterPerks[token.guid]=nil end
	if gStates.attackedMonsters~=nil then gStates.attackedMonsters[token.guid]=nil end
	monsterPugs[token.guid]=nil
	horsemanMarkDefeatedToken(token,name,playerIndex,true)
	broadcastToAll(joinLang({translateWord[player.mage] or player.mage,"{en} defeated {ru} победил {zh-tw} 擊敗了 {zh-cn} 击败了 {ko}이(가) {es} derrotó a {fr} a vaincu {pt-br} derrotou {de} besiegte ",name,"{en}. The Horseman has been placed in their Inventory.{ru}. Жетон Всадника помещён в его Инвентарь.{zh-tw}。騎士已放入其庫存。{zh-cn}。骑士已放入其库存。{ko}을(를) 쓰러뜨렸습니다. 기사 토큰이 인벤토리에 놓였습니다.{es}. El Jinete se ha colocado en su Inventario.{fr}. Le Cavalier a été placé dans son Inventaire.{pt-br}. O Cavaleiro foi colocado no Inventário.{de}. Der Reiter wurde in das Inventar gelegt."}),positionToColor(playerIndex))
	return true
end

end)
__bundle_register("PlayingGame.ApocalypseDragon", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Apocalypse Dragon-private helpers. Predeclared so forward references keep resolving locally.
local apocalypseDragonStartingLevel, apocalypseDragonHeadTokenPosition, apocalypseDragonPositionHeadToken, apocalypseDragonCopyAttack, apocalypseDragonRefreshRuntimeData
local apocalypseDragonDeployHeadToken, apocalypseDragonLevelMarkerPosition, apocalypseDragonLockLevelMarker, apocalypseDragonDefeatedHeadCount, apocalypseDragonSyncControlLevel
local apocalypseDragonCheckAndResolveDefeat, apocalypseDragonHeadStateChanged, apocalypseDragonGroundReduction, apocalypseDragonGroundMarkedThroughOne, apocalypseDragonGroundControlGUIDs
local apocalypseDragonGroundReductionAdjust, apocalypseDragonGroundPrepareColoredHead, apocalypseDragonGroundPrepareControl, apocalypseDragonNewGroundCombat, apocalypseDragonGroundTokenInPlayerArea
local apocalypseDragonCoopAdjacentPlayers, apocalypseDragonAssaultOriginData, apocalypseDragonGroundApplyFinalLevels, apocalypseDragonGroundCleanupRuntime

-- Shared Apocalypse Dragon entity, head-level and landed-combat helpers.
-- Scenario-specific AI/turn rules remain in Scenario.lua.

function syncDragonHeadAttackBonusDecal(tokenGUID,bonus)
	local token=tokenGUID~=nil and getObjectFromGUID(tokenGUID) or nil
	if token==nil then return false end
	--The head tokens sit at 180 degrees, so positive local X is visually left.
	--Keep the Control bonus centred vertically rather than using the Quest possessed-token offset.
	combatSyncNamedAttackBonusDecal(token,"DragonAllAttack+",bonus,{1.1,0.15,0})
	return true
end

function apocalypseDragonPossessSummonedEnemy(enemyGUID,target)
	local enemy=getObjectFromGUID(enemyGUID)
	if target==nil then
		if enemy==nil then return false end
		local p=enemy.getPosition()
		target={p[1],p[2],p[3]}
	end
	local bag=getObjectFromGUID(GUID.bag.possessed)
	if bag==nil or bag.getQuantity()==0 then
		tokenRefill()
		bag=getObjectFromGUID(GUID.bag.possessed)
	end
	if bag==nil or bag.getQuantity()==0 then return false end
	--Match the working Quest possessed-enemy path: draw both tokens to the same X/Z, with the
	--Possessed token above the enemy. Falling through the player scripting zone performs the link.
	local possessed=bag.takeObject({position={target[1],target[2]+1.10,target[3]},rotation={0,180,0},smooth=true})
	if possessed==nil then return false end
	gStates.apocalypsePossessedFactionByToken=gStates.apocalypsePossessedFactionByToken or {}
	gStates.apocalypsePossessedFactionByToken[possessed.guid]="Apoc"
	--Control-head summons are temporary enemies: neither the summoned monster nor its Possessed
	--token may award Fame or a Faction Reward. Mark the attachment with the same summoned state
	--used by ordinary monster cleanup so every reward path treats both pieces consistently.
	gStates.summonStates=gStates.summonStates or {}
	gStates.summonStates[possessed.guid]="summoned"
	return true
end

function apocalypseDragonScenario()
	return gStates~=nil and (gStates.gameScenario=="Against the Dragon Blitz" or gStates.gameScenario=="Apocalypse is Here" or gStates.gameScenario=="Fury of the Apocalypse Dragon")
end

apocalypseDragonStartingLevel=function()
	if apocalypseDragonScenario()~=true then return nil end
	if gStates.gameScenario=="Fury of the Apocalypse Dragon" then
		if gStates.playerCount==1 then return 1 end
		return gStates.coop==1 and gStates.playerCount or gStates.playerCount-1
	end
	if gStates.playerCount==1 then
		if gStates.gameScenario=="Against the Dragon Blitz" then return 4 end
		return 5
	end
	if gStates.gameScenario=="Against the Dragon Blitz" then
		return gStates.playerCount+(gStates.coop==1 and 3 or 1)
	end
	return gStates.playerCount+(gStates.coop==1 and 4 or 2)
end

function apocalypseDragonHeadData(headName)
	for _,headData in ipairs(apocalypseDragon.heads) do if headData.name==headName then return headData end end
	return nil
end

function apocalypseDragonCurrentLevelData(headName,level)
	local data=apocalypseDragonLevelData~=nil and apocalypseDragonLevelData[headName] or nil
	level=math.floor(tonumber(level) or 0)
	if data==nil or level<1 or level>12 then return nil end
	return data.levels~=nil and data.levels[level] or nil
end

apocalypseDragonHeadTokenPosition=function(headData)
	if headData==nil or headData.position==nil then return nil end
	return {headData.position[1],headData.position[2]+0.12,headData.position[3]}
end

apocalypseDragonPositionHeadToken=function(headData)
	if headData==nil or headData.tokenGUID==nil then return false end
	local token=getObjectFromGUID(headData.tokenGUID)
	local target=apocalypseDragonHeadTokenPosition(headData)
	if token==nil or target==nil then return false end
	local pos=token.getPosition()
	local moved=math.abs(pos[1]-target[1])>0.03 or math.abs(pos[2]-target[2])>0.03 or math.abs(pos[3]-target[3])>0.03
	token.setLock(false)
	if moved==true then token.setPosition(target) end
	token.setRotation({0,180,0})
	token.setLock(true)
	return moved
end

apocalypseDragonCopyAttack=function(attack,bonus)
	if type(attack)~="table" then return nil end
	local copied={}
	for attackType,values in pairs(attack) do
		if type(values)=="table" then
			copied[attackType]={}
			for _,value in ipairs(values) do copied[attackType][#copied[attackType]+1]=(tonumber(value) or 0)+(bonus or 0) end
		end
	end
	return copied
end

function apocalypseDragonMonsterData(headName,level)
	local levelData=apocalypseDragonCurrentLevelData(headName,level)
	if levelData==nil then return nil end
	local data={name="Apocalypse Dragon - "..headName,pugType="dragonHead",dragonHead=headName,dragonHeadLevel=level}
	for key,value in pairs(levelData) do
		if key~="image" and key~="attackBonus" and key~="possessedSummon" then
			if key=="attack" then data.attack=apocalypseDragonCopyAttack(value,0)
			elseif key=="monsters" then
				data.monsters={}
				for _,monsterColor in ipairs(value) do data.monsters[#data.monsters+1]=monsterColor end
			else data[key]=value end
		end
	end
	return data
end

--Refresh the persistent small head token stats. Printed level data lives in monsterPugs; Control's
--whole-head Attack bonus is a runtime monsterPerks attack override so every displayed attack gets it.
apocalypseDragonRefreshRuntimeData=function()
	if gStates==nil then return end
	local monsterPerks=gStates.monsterPerks
	if monsterPerks==nil then
		monsterPerks={}
		gStates.monsterPerks=monsterPerks
	end
	for _,headData in ipairs(apocalypseDragon.heads) do
		local tokenGUID=headData.tokenGUID
		if tokenGUID~=nil then
			local level=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[headData.name] or 0) or 0
			if level>0 then monsterPugs[tokenGUID]=apocalypseDragonMonsterData(headData.name,level) else monsterPugs[tokenGUID]=nil end
			local perks=monsterPerks[tokenGUID]
			if perks~=nil and perks.dragonControlBonus~=nil then
				perks.attack=nil
				perks.dragonControlBonus=nil
				if next(perks)==nil then monsterPerks[tokenGUID]=nil end
			end
			if headData.name~="Control" then syncDragonHeadAttackBonusDecal(tokenGUID,0) end
		end
	end
	local headLevels=gStates.apocalypseDragonHeadLevels or {}
	local controlLevel=tonumber(headLevels.Control) or 0
	local controlData=apocalypseDragonCurrentLevelData("Control",controlLevel)
	local bonus=controlData~=nil and tonumber(controlData.attackBonus) or 0
	if bonus>0 then
		for _,headName in ipairs(apocalypseDragonColoredHeads or {}) do
			local headData=apocalypseDragonHeadData(headName)
			if headData~=nil and headData.tokenGUID~=nil then
				local tokenGUID=headData.tokenGUID
				local printed=monsterPugs[tokenGUID]
				if printed~=nil and printed.attack~=nil then
					local perks=monsterPerks[tokenGUID] or {}
					perks.attack=apocalypseDragonCopyAttack(printed.attack,bonus)
					perks.dragonControlBonus=bonus
					monsterPerks[tokenGUID]=perks
					syncDragonHeadAttackBonusDecal(tokenGUID,bonus)
				end
			end
		end
	end
end

function apocalypseDragonApplyHeadLevel(headName,level)
	local headData=apocalypseDragonHeadData(headName)
	local tokenData=apocalypseDragonLevelData~=nil and apocalypseDragonLevelData[headName] or nil
	if headData==nil or tokenData==nil then return false end
	level=math.max(0,math.min(12,math.floor(tonumber(level) or 0)))
	local token=getObjectFromGUID(headData.tokenGUID)
	local levelData=level>0 and apocalypseDragonCurrentLevelData(headName,level) or nil
	local image=levelData~=nil and levelData.image or tokenData.blank
	if token~=nil then
		token.setLock(false)
		if type(image)=="string" and image~="" then token.setCustomObject({image=image}) end
		token.setName(level>0 and (headName.." Dragon Head Level "..tostring(level)) or (headName.." Dragon Head Defeated"))
		token.reload()
		safeWaitFrames("Scenario",function()
			local current=getObjectFromGUID(headData.tokenGUID)
			if current~=nil then apocalypseDragonPositionHeadToken(headData) end
		end,1)
	end
	apocalypseDragonRefreshRuntimeData()
	return true
end

apocalypseDragonDeployHeadToken=function(headData,bag)
	if headData==nil or headData.tokenGUID==nil then return nil end
	local target=apocalypseDragonHeadTokenPosition(headData)
	if target==nil then return nil end
	local token=getObjectFromGUID(headData.tokenGUID)
	if token==nil and bag~=nil then
		token=bag.takeObject({guid=headData.tokenGUID,position=target,rotation={0,180,0},smooth=false})
	elseif token~=nil then
		token.setLock(false)
		token.setPosition(target)
		token.setRotation({0,180,0})
	end
	if token~=nil then token.setLock(true) end
	return token
end

--The Dragon heads use the same 12-position circular level layout as the Shades of Tezla leader discs.
--Level 1 is at the top, then levels advance clockwise in 30-degree steps.
apocalypseDragonLevelMarkerPosition=function(head,level)
	if head==nil or level==nil or level<1 then return nil end
	local angle=math.rad(120-(30*level))
	local pos=head.getPosition()
	return {pos[1]+(math.cos(angle)*apocalypseDragon.levelMarkerRadius),1.12,pos[3]+(math.sin(angle)*apocalypseDragon.levelMarkerRadius)}
end

apocalypseDragonLockLevelMarker=function(marker,target)
	if marker==nil or target==nil then return end
	marker.setLock(false)
	marker.setPosition(target)
	marker.setRotation({0,180,0})
	marker.setLock(true)
end


function apocalypseDragonColoredHeadsDefeated()
	if gStates==nil or type(gStates.apocalypseDragonHeadLevels)~="table" then return false end
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		if tonumber(gStates.apocalypseDragonHeadLevels[headName])~=0 then return false end
	end
	return true
end

apocalypseDragonDefeatedHeadCount=function()
	if gStates==nil or type(gStates.apocalypseDragonHeadLevels)~="table" then return 0 end
	local count=0
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		if tonumber(gStates.apocalypseDragonHeadLevels[headName])==0 then count=count+1 end
	end
	return count
end

apocalypseDragonSyncControlLevel=function()
	if gStates==nil or type(gStates.apocalypseDragonHeadLevels)~="table" then return false end
	local highest=0
	local found=false
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		local level=tonumber(gStates.apocalypseDragonHeadLevels[headName])
		if level~=nil then
			found=true
			if level>highest then highest=level end
		end
	end
	if found~=true then return false end
	if tonumber(gStates.apocalypseDragonHeadLevels.Control)==highest then return false end
	return apocalypseDragonSetHeadLevel("Control",highest)
end

apocalypseDragonCheckAndResolveDefeat=function()
	if gStates==nil or (gStates.gameScenario~="Against the Dragon Blitz" and gStates.gameScenario~="Apocalypse is Here") or gStates.apocalypseDragonDefeated==true then return false end
	if apocalypseDragonColoredHeadsDefeated()~=true then return false end

	gStates.apocalypseDragonDefeated=true
	gStates.apocalypseDragonDefeatedRound=gStates.currentRound
	gStates.apocalypseDragonLairAttacked=true
	if tonumber(gStates.apocalypseDragonHeadLevels.Control)~=0 then apocalypseDragonSetHeadLevel("Control",0) end

	local dragon=getObjectFromGUID(apocalypseDragon.model)
	if dragon~=nil then
		local trash=getObjectFromGUID(trashCan)
		if trash~=nil then trash.putObject(dragon) else dragon.destruct() end
	end

	broadcastToAll("{en}The Apocalypse Dragon has been defeated! All players have one final turn.{ru}The Apocalypse Dragon has been defeated! All players have one final turn.{zh-tw}The Apocalypse Dragon has been defeated! All players have one final turn.{zh-cn}The Apocalypse Dragon has been defeated! All players have one final turn.{ko}The Apocalypse Dragon has been defeated! All players have one final turn.{es}The Apocalypse Dragon has been defeated! All players have one final turn.{fr}The Apocalypse Dragon has been defeated! All players have one final turn.{pt-br}The Apocalypse Dragon has been defeated! All players have one final turn.{de}The Apocalypse Dragon has been defeated! All players have one final turn.",{1,1,0.5})
	local coopDragon=gStates.coopAssaultPhase=="combat" and coopAssaultTargetType~=nil and coopAssaultTargetType()=="dragon"
	if coopDragon==true then gStates.coopAssaultScenarioEndPending=true
	elseif gStates.endGameAchieved=="false" then markScenarioEndAchieved() end
	return true
end

apocalypseDragonHeadStateChanged=function(headName)
	if headName~="Control" then apocalypseDragonSyncControlLevel() end
	if gStates~=nil and (gStates.gameScenario=="Against the Dragon Blitz" or gStates.gameScenario=="Apocalypse is Here") then apocalypseDragonCheckAndResolveDefeat() end
end

--Read the physical player Shields on the four large coloured head boards.
--Against the Dragon and Apocalypse is Here both use this shared scoring summary; a one-off getAllObjects() scan is acceptable.
function apocalypseDragonCompetitiveScoreSummary()
	local summary={defeatedHeads=apocalypseDragonDefeatedHeadCount(),byMage={},heads={}}
	local mageToPlayer={}
	for playerIndex,details in ipairs(turnOrder or {}) do
		if details~=nil and details.mage~=gStates.positionMageKnight[5] then
			mageToPlayer[details.mage]=playerIndex
			summary.byMage[details.mage]={levels=0,slayerBonus=0,slayerHeads={}}
		end
	end

	local slots={}
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		local headData=apocalypseDragonHeadData(headName)
		local head=headData~=nil and getObjectFromGUID(headData.guid) or nil
		local headSummary={countByMage={},highestByMage={},winner=nil}
		summary.heads[headName]=headSummary
		if head~=nil then
			for level=1,12 do
				local pos=apocalypseDragonLevelMarkerPosition(head,level)
				if pos~=nil then slots[#slots+1]={head=headName,level=level,pos=pos} end
			end
		end
	end

	for _,obj in ipairs(getAllObjects()) do
		if obj.getName()=="Shield" then
			local mage=obj.getDescription()
			if mageToPlayer[mage]~=nil then
				local pos=obj.getPosition()
				local nearest=nil
				local best=0.72
				for _,slot in ipairs(slots) do
					local dist=math.sqrt(((pos[1]-slot.pos[1])^2)+((pos[3]-slot.pos[3])^2))
					if dist<best then best=dist nearest=slot end
				end
				if nearest~=nil then
					local headSummary=summary.heads[nearest.head]
					headSummary.countByMage[mage]=(headSummary.countByMage[mage] or 0)+1
					headSummary.highestByMage[mage]=math.max(headSummary.highestByMage[mage] or 0,nearest.level)
				end
			end
		end
	end

	if gStates.gameScenario=="Apocalypse is Here" then
		for _,headName in ipairs(apocalypseDragonColoredHeads) do
			local state=gStates.horsemen~=nil and gStates.horsemen[headName] or nil
			local mage=state~=nil and (state.defeatedBy or (gStates.horsemenDefeatedBy~=nil and gStates.horsemenDefeatedBy[headName] or nil)) or nil
			local headSummary=summary.heads[headName]
			if state~=nil and state.defeated==true and mage~=nil and summary.byMage[mage]~=nil and headSummary~=nil then
				local bonus=math.max(1,math.min(6,tonumber(state.defeatedLevel or state.level) or 1))
				headSummary.countByMage[mage]=(headSummary.countByMage[mage] or 0)+bonus
			end
		end
	end

	for headName,headSummary in pairs(summary.heads) do
		local bestCount=0
		local bestHighest=0
		local winner=nil
		for mage,_ in pairs(mageToPlayer) do
			local count=headSummary.countByMage[mage] or 0
			local highest=headSummary.highestByMage[mage] or 0
			if count>bestCount or (count==bestCount and count>0 and highest>bestHighest) then
				bestCount=count
				bestHighest=highest
				winner=mage
			elseif count==bestCount and count>0 and highest==bestHighest then
				--A genuine game cannot place two different player Shields on the same highest level.
				--If a malformed board does, leave the +5 unresolved rather than inventing a tiebreaker.
				winner=nil
			end
		end
		headSummary.winner=winner
		for mage,data in pairs(summary.byMage) do
			data.levels=data.levels+(headSummary.countByMage[mage] or 0)
			if winner==mage then
				data.slayerBonus=data.slayerBonus+5
				data.slayerHeads[#data.slayerHeads+1]=headName
			end
		end
	end
	return summary
end

function apocalypseDragonSetHeadLevel(headName,level)
	local headData=apocalypseDragonHeadData(headName)
	local head=headData~=nil and getObjectFromGUID(headData.guid) or nil
	if head==nil then return false end
	level=math.max(0,math.min(12,math.floor(tonumber(level) or 0)))
	gStates.apocalypseDragonHeadLevels=gStates.apocalypseDragonHeadLevels or {}
	gStates.apocalypseDragonLevelMarkers=gStates.apocalypseDragonLevelMarkers or {}
	gStates.apocalypseDragonHeadLevels[headName]=level
	local markerGUID=gStates.apocalypseDragonLevelMarkers[headName]
	local marker=markerGUID~=nil and getObjectFromGUID(markerGUID) or nil
	if level==0 then
		if marker~=nil then marker.destruct() end
		gStates.apocalypseDragonLevelMarkers[headName]=nil
		apocalypseDragonApplyHeadLevel(headName,level)
		apocalypseDragonHeadStateChanged(headName)
		return true
	end
	local target=apocalypseDragonLevelMarkerPosition(head,level)
	if target==nil then return false end
	if marker==nil then
		local shieldBag=getObjectFromGUID(GUID.bag.neutralShield)
		if shieldBag==nil then return false end
		marker=shieldBag.takeObject({position=target,rotation={0,180,0},smooth=false})
		if marker==nil then return false end
		gStates.apocalypseDragonLevelMarkers[headName]=marker.guid
	end
	--The Dragon head boards are fixed, so use the tested table height directly.
	target=apocalypseDragonLevelMarkerPosition(head,level)
	marker.setName(headName.." Dragon Head Level "..level)
	apocalypseDragonLockLevelMarker(marker,target)
	apocalypseDragonApplyHeadLevel(headName,level)
	apocalypseDragonHeadStateChanged(headName)
	return true
end

function setupApocalypseDragonHeads()
	if apocalypseDragonScenario()~=true then return end
	local startingLevel=apocalypseDragonStartingLevel()
	gStates.apocalypseDragonHeadsSetupReady=false
	gStates.apocalypseDragonHeadLevels={}
	gStates.apocalypseDragonLevelMarkers={}
	local bag=getObjectFromGUID(GUID.bag.apocalypseDragon)
	if gStates.gameScenario=="Against the Dragon Blitz" then
		local roundToken=getObjectFromGUID(apocalypseDragon.roundOrder)
		local roundPos={-1.90,0.97,-22.20}
		if roundToken==nil and bag~=nil then
			roundToken=bag.takeObject({guid=apocalypseDragon.roundOrder,position=roundPos,rotation={0,180,0},smooth=false})
		elseif roundToken~=nil then
			roundToken.setPosition(roundPos)
			roundToken.setRotation({0,180,0})
		end
		if roundToken~=nil then roundToken.lock() end
	end
	for _,headData in ipairs(apocalypseDragon.heads) do
		local head=getObjectFromGUID(headData.guid)
		if head==nil and bag~=nil then
			head=bag.takeObject({guid=headData.guid,position=headData.position,rotation={0,180,0},smooth=false})
		elseif head~=nil then
			head.setPosition(headData.position)
			head.setRotation({0,180,0})
		end
		if head~=nil then head.lock() end
		apocalypseDragonDeployHeadToken(headData,bag)
	end
	if gStates.gameScenario~="Fury of the Apocalypse Dragon" then
		local dragon=getObjectFromGUID(apocalypseDragon.model)
		if dragon==nil and bag~=nil then
			dragon=bag.takeObject({guid=apocalypseDragon.model,position=apocalypseDragon.modelPosition,rotation={0,180,180},smooth=false})
		elseif dragon~=nil then
			dragon.setPosition(apocalypseDragon.modelPosition)
			dragon.setRotation({0,180,180})
		end
		if dragon~=nil then dragon.setLock(false) end
	end

	local function dragonHeadSetupObjectsReady()
		if startingLevel>0 and getObjectFromGUID(GUID.bag.neutralShield)==nil then return false end
		for _,headData in ipairs(apocalypseDragon.heads) do
			if getObjectFromGUID(headData.guid)==nil or getObjectFromGUID(headData.tokenGUID)==nil then return false end
		end
		if gStates.gameScenario~="Fury of the Apocalypse Dragon" and getObjectFromGUID(apocalypseDragon.model)==nil then return false end
		return true
	end
	local function dragonHeadLevelsSettled()
		for _,headData in ipairs(apocalypseDragon.heads) do
			local head=getObjectFromGUID(headData.guid)
			local token=getObjectFromGUID(headData.tokenGUID)
			local target=apocalypseDragonHeadTokenPosition(headData)
			if head==nil or token==nil or target==nil or head.spawning==true or token.spawning==true or head.resting~=true or token.resting~=true then return false end
			local pos=token.getPosition()
			if math.abs(pos[1]-target[1])>0.03 or math.abs(pos[2]-target[2])>0.03 or math.abs(pos[3]-target[3])>0.03 then return false end
		end
		return true
	end
	local function markDragonHeadSetupReady()
		positionApocalypseDragonHeads()
		gStates.apocalypseDragonHeadsSetupReady=true
	end
	local function finishDragonHeadSetup()
		for _,headData in ipairs(apocalypseDragon.heads) do
			if apocalypseDragonSetHeadLevel(headData.name,startingLevel)~=true then
				error("SetupGame could not set the initial level for Apocalypse Dragon head "..tostring(headData.name)..".",2)
			end
		end
		--Each level change reloads the small head token and repositions it one frame later. Do not let
		--the setup coordinator continue until those replacement objects are genuinely usable.
		safeWaitCondition("Scenario",markDragonHeadSetupReady,dragonHeadLevelsSettled,10,function()
			error("SetupGame timed out waiting for Apocalypse Dragon head reloads to settle.",2)
		end)
	end
	if dragonHeadSetupObjectsReady()==true then
		finishDragonHeadSetup()
	else
		safeWaitCondition("Scenario",finishDragonHeadSetup,dragonHeadSetupObjectsReady,10,function()
			error("SetupGame timed out waiting for Apocalypse Dragon setup objects.",2)
		end)
	end
end

function apocalypseDragonLockModelWhenSettled()
	local guid=apocalypseDragon.model
	local function lockDragon()
		local dragon=getObjectFromGUID(guid)
		if dragon~=nil then dragon.lock() end
	end
	safeWaitCondition("Scenario",lockDragon,function()
		local dragon=getObjectFromGUID(guid)
		return dragon==nil or dragon.resting==true
	end,5,lockDragon)
end

--Against the Dragon: Core non-City tile 3 reveals the Dragon's three-space lair.
--The Dragon keeps its normal map orientation. Its model origin is the centre of the front hex,
--so it is placed directly on the main/centre hex and the two rear hexes fall behind it.
--Random Tile Orientation rotates the printed hexes underneath this fixed footprint.
function apocalypseDragonLairContainsPosition(pos)
	if pos==nil or gStates==nil or gStates.apocalypseDragonLairRevealed~=true or gStates.apocalypseDragonLair==nil then return false end
	for _,hex in ipairs(gStates.apocalypseDragonLair.hexes or {}) do
		local p=hex.position
		if p~=nil and ((pos[1]-p[1])^2)+((pos[3]-p[3])^2)<2.25 then return true end
	end
	return false
end

function apocalypseDragonGroundCombatForPlayer(playerIndex)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or combat.finished==true then return false end
	if combat.coop==true then return combat.players~=nil and combat.players[playerIndex]==true and (combat.finishedPlayers==nil or combat.finishedPlayers[playerIndex]~=true) end
	return combat.playerIndex==playerIndex
end

function apocalypseDragonGroundHeadNameForGUID(guid)
	if guid==nil then return nil end
	for _,headData in ipairs(apocalypseDragon.heads) do if headData.tokenGUID==guid then return headData.name end end
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat~=nil and combat.controlClones~=nil and combat.controlClones[guid]~=nil then return "Control" end
	return nil
end

function apocalypseDragonGroundHeadOwner(headName)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or headName==nil then return nil end
	if combat.headOwners~=nil and combat.headOwners[headName]~=nil then return combat.headOwners[headName] end
	return combat.playerIndex
end

function apocalypseDragonGroundHeadToken(guid)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	local headName=apocalypseDragonGroundHeadNameForGUID(guid)
	if combat==nil or headName==nil then return false,headName end
	if headName=="Control" and combat.controlClones~=nil and combat.controlClones[guid]~=nil then return false,headName end
	return combat.deployed~=nil and combat.deployed[headName]==true,headName
end

function apocalypseDragonGroundControlToken(guid)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or guid==nil then return false,nil end
	local controlData=apocalypseDragonHeadData("Control")
	if controlData~=nil and guid==controlData.tokenGUID and combat.deployed~=nil and combat.deployed.Control==true then return true,combat.playerIndex end
	if combat.controlClones~=nil and combat.controlClones[guid]~=nil then return true,combat.controlClones[guid] end
	return false,nil
end

function apocalypseDragonGroundCombatToken(guid)
	local active,headName=apocalypseDragonGroundHeadToken(guid)
	if active==true then return true,headName,apocalypseDragonGroundHeadOwner(headName) end
	local control,owner=apocalypseDragonGroundControlToken(guid)
	if control==true then return true,"Control",owner end
	return false,nil,nil
end

function apocalypseDragonGroundTokenPosition(playerIndex,slot)
	local details=turnOrder[playerIndex]
	if details==nil then return nil end
	--Keep the Dragon fight clear of the normal left-side combat controls: two enemy slots right.
	return {(details.seatPos*40)-100+((slot-1)*2.5),1.5,-39.25}
end

apocalypseDragonGroundReduction=function(headName)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or combat.reductions==nil then return 1 end
	return math.max(1,math.floor(tonumber(combat.reductions[headName]) or 1))
end

apocalypseDragonGroundMarkedThroughOne=function(headName)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil then return false end
	if combat.headMarkedToOne~=nil and combat.headMarkedToOne[headName]==true then return true end
	local level=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[headName] or 0) or 0
	if level<=0 then return true end
	local headData=apocalypseDragonHeadData(headName)
	local token=headData~=nil and getObjectFromGUID(headData.tokenGUID) or nil
	if token==nil or combat.processedTokens~=nil and combat.processedTokens[token.guid]==true then return false end
	--Future co-op participants cannot suppress the current player's Control attack by pre-adjusting
	--their head before their own combat. Only resolved earlier heads plus the current participant count.
	local owner=apocalypseDragonGroundHeadOwner(headName)
	if combat.coop==true and owner~=gStates.turnNumber then return false end
	return token.is_face_down==false and apocalypseDragonGroundReduction(headName)>=level
end

apocalypseDragonGroundControlGUIDs=function()
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	local guids={}
	if combat==nil then return guids end
	local controlData=apocalypseDragonHeadData("Control")
	if controlData~=nil and combat.deployed~=nil and combat.deployed.Control==true then guids[#guids+1]=controlData.tokenGUID end
	for guid,_ in pairs(combat.controlClones or {}) do guids[#guids+1]=guid end
	return guids
end

function apocalypseDragonRefreshGroundAttackSuppression()
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil then return false end
	gStates.monsterPerks=gStates.monsterPerks or {}
	local controlLevel=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels.Control or 0) or 0
	local controlLevelData=apocalypseDragonCurrentLevelData("Control",controlLevel)
	local controlBonus=controlLevelData~=nil and tonumber(controlLevelData.attackBonus) or 0
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		local headData=apocalypseDragonHeadData(headName)
		local level=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[headName] or 0) or 0
		if level>0 then
			if headData~=nil and combat.deployed~=nil and combat.deployed[headName]==true then
				local printed=apocalypseDragonMonsterData(headName,level)
				if printed~=nil then
					--The head remains at its entered-combat level until cleanup. The player decides combat
					--phase timing manually, so the reduction dial never changes/suppresses its printed stats.
					printed.fame=1
					monsterPugs[headData.tokenGUID]=printed
				end
				local perks=gStates.monsterPerks[headData.tokenGUID] or {}
				perks.attack=nil
				perks.dragonControlBonus=nil
				if controlBonus>0 and printed~=nil and printed.attack~=nil then
					perks.attack=apocalypseDragonCopyAttack(printed.attack,controlBonus)
					perks.dragonControlBonus=controlBonus
				end
				gStates.monsterPerks[headData.tokenGUID]=perks
				syncDragonHeadAttackBonusDecal(headData.tokenGUID,(controlBonus>0 and printed~=nil and printed.attack~=nil) and controlBonus or 0)
			end
		end
	end
	for _,guid in ipairs(apocalypseDragonGroundControlGUIDs()) do
		local control=getObjectFromGUID(guid)
		if control~=nil and controlLevel>0 then
			local printed=apocalypseDragonMonsterData("Control",controlLevel)
			if printed~=nil then
				printed.fame=0
				monsterPugs[guid]=printed
			end
			local perks=gStates.monsterPerks[guid] or {}
			perks.dragonGround=true
			perks.dragonGroundLevel=controlLevel
			perks.dragonLevelFame=nil
			gStates.monsterPerks[guid]=perks
			setMonsterObjectButtons(control)
		end
	end
	return true
end

apocalypseDragonGroundReductionAdjust=function(player,mouseButton,id)
	if mouseButton~="-1" then return end
	local guid=tostring(id or ""):sub(1,6)
	local active,headName=apocalypseDragonGroundHeadToken(guid)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if active~=true or combat==nil or headName==nil or headName=="Control" then return end
	local owner=apocalypseDragonGroundHeadOwner(headName)
	if owner==nil then return end
	if combat.finishedPlayers~=nil and combat.finishedPlayers[owner]==true then return end
	local color=player~=nil and player.color or nil
	local allowed=positionToColor(owner)
	if color~="Black" and color~=allowed then return end
	local current=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[headName] or 0) or 0
	if current<1 then return end
	local value=apocalypseDragonGroundReduction(headName)
	if id:find("GroundOverkillUp",1,true)~=nil and value<current then value=value+1 end
	if id:find("GroundOverkillDown",1,true)~=nil and value>1 then value=value-1 end
	local reductions=combat.reductions or {}
	combat.reductions=reductions
	reductions[headName]=value
	local token=getObjectFromGUID(guid)
	if token~=nil then token.UI.setAttribute(guid.."GroundOverkill","text",tostring(value)) end
	apocalypseDragonRefreshGroundAttackSuppression()
	apocalypseDragonRefreshGroundFameGain(owner)
	mainUIUpdate("Dragon Head Reduction")
end

function apocalypseDragonGroundHeadButtons(obj)
	local active,headName=apocalypseDragonGroundHeadToken(obj~=nil and obj.guid or nil)
	if active~=true or headName==nil or headName=="Control" then return {} end
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat~=nil and combat.processedTokens~=nil and combat.processedTokens[obj.guid]==true then return {} end
	local value=apocalypseDragonGroundReduction(headName)
	return {
		{tag="Button",attributes={id=obj.guid.."GroundOverkillUp",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",onClick="global/apocalypseDragonGroundReductionAdjust",height=50/0.9,width=50/0.9,color="rgba(0,0,0,0.0)",position="-62 "..tostring(-120/0.9).." "..tostring(-15/0.9),rotation="0 0 180"},children={{tag="Image",attributes={id=obj.guid.."GroundOverkillUpImage",image="Overkill Up"}}}},
		{tag="Image",attributes={image="Overkill Text",height=50/0.9,width=55/0.9,position="0 "..tostring(-120/0.9).." "..tostring(-15/0.9),rotation="0 0 180"},children={{tag="Text",attributes={id=obj.guid.."GroundOverkill",color="rgb(0,0,0)",fontSize="45",fontStyle="Bold",alignment="MiddleCenter",text=tostring(value)}}}},
		{tag="Button",attributes={id=obj.guid.."GroundOverkillDown",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",onClick="global/apocalypseDragonGroundReductionAdjust",height=50/0.9,width=50/0.9,color="rgba(0,0,0,0.0)",position="62 "..tostring(-120/0.9).." "..tostring(-15/0.9),rotation="0 0 180"},children={{tag="Image",attributes={id=obj.guid.."GroundOverkillDownImage",image="Overkill Down"}}}}
	}
end

apocalypseDragonGroundPrepareColoredHead=function(combat,headName,playerIndex)
	local headData=apocalypseDragonHeadData(headName)
	local level=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[headName] or 0) or 0
	if headData==nil or level<=0 then return false end
	local token=getObjectFromGUID(headData.tokenGUID)
	if token==nil then return false end
	combat.deployed[headName]=true
	combat.headOwners[headName]=playerIndex
	combat.reductions[headName]=1
	local printed=apocalypseDragonMonsterData(headName,level)
	if printed~=nil then
		printed.fame=1
		if combat.fortifiedPlayers~=nil and combat.fortifiedPlayers[playerIndex]==true then printed.fortified=true end
		monsterPugs[headData.tokenGUID]=printed
	end
	local perks=gStates.monsterPerks[headData.tokenGUID] or {}
	perks.dragonGround=true
	perks.dragonGroundLevel=level
	perks.dragonLevelFame=1
	gStates.monsterPerks[headData.tokenGUID]=perks
	gStates.monsterPlayLocation[headData.tokenGUID]=apocalypseDragonHeadTokenPosition(headData)
	token.setLock(false)
	token.setRotation({0,180,0})
	setMonsterObjectButtons(token)
	return true
end

apocalypseDragonGroundPrepareControl=function(combat,playerIndex,slot,useOriginal)
	local controlData=apocalypseDragonHeadData("Control")
	local level=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels.Control or 0) or 0
	if controlData==nil or level<=0 then return nil end
	local original=getObjectFromGUID(controlData.tokenGUID)
	if original==nil then return nil end
	local target=apocalypseDragonGroundTokenPosition(playerIndex,slot)
	local token=original
	if useOriginal~=true then
		token=original.clone({position=target,rotation={0,180,0},smooth=false})
		if token==nil then return nil end
		combat.controlClones[token.guid]=playerIndex
	else
		combat.deployed.Control=true
		gStates.monsterPlayLocation[controlData.tokenGUID]=apocalypseDragonHeadTokenPosition(controlData)
		original.setLock(false)
		original.setRotation({0,180,0})
		if target~=nil then original.setPositionSmooth(target,false,true) end
	end
	local printed=apocalypseDragonMonsterData("Control",level)
	if printed~=nil then printed.fame=0 monsterPugs[token.guid]=printed end
	local perks=gStates.monsterPerks[token.guid] or {}
	perks.dragonGround=true
	perks.dragonGroundLevel=level
	perks.dragonLevelFame=nil
	gStates.monsterPerks[token.guid]=perks
	token.setLock(false)
	token.setRotation({0,180,0})
	if useOriginal~=true and target~=nil then token.setPosition(target) end
	safeWaitFrames("Scenario",function() local current=getObjectFromGUID(token.guid) if current~=nil then setMonsterObjectButtons(current) end end,2)
	return token
end

apocalypseDragonNewGroundCombat=function(coop)
	return {coop=coop==true,players={},headOwners={},deployed={},reductions={},processedTokens={},headMarkedToOne={},fameByPlayer={},previewFameByPlayer={},finishedPlayers={},controlClones={},fortifiedPlayers={},finished=false,levelsApplied=false}
end

apocalypseDragonGroundTokenInPlayerArea=function(tokenGUID,playerIndex)
	local details=turnOrder[playerIndex]
	if tokenGUID==nil or details==nil then return false end
	for _,obj in pairs(playerCombatObjects(details.seatPos)) do if obj.guid==tokenGUID then return true end end
	return false
end

function apocalypseDragonRefreshGroundFameGain(playerIndex)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	local details=turnOrder[playerIndex]
	if combat==nil or details==nil or combat.finished==true then return false end
	--Resolved heads stay earned while unprocessed heads behave like faction leaders: they only
	--contribute while face up and physically inside their owner's Play/Unit combat area.
	local total=tonumber(combat.fameByPlayer~=nil and combat.fameByPlayer[playerIndex] or 0) or 0
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		if apocalypseDragonGroundHeadOwner(headName)==playerIndex and combat.deployed~=nil and combat.deployed[headName]==true then
			local headData=apocalypseDragonHeadData(headName)
			local token=headData~=nil and getObjectFromGUID(headData.tokenGUID) or nil
			if token~=nil and (combat.processedTokens==nil or combat.processedTokens[token.guid]~=true) and token.is_face_down==false
				and apocalypseDragonGroundTokenInPlayerArea(token.guid,playerIndex)==true then
				total=total+apocalypseDragonGroundReduction(headName)
			end
		end
	end
	combat.previewFameByPlayer=combat.previewFameByPlayer or {}
	local previous=tonumber(combat.previewFameByPlayer[playerIndex]) or 0
	if total~=previous then
		details.fameGain=(details.fameGain or 0)+(total-previous)
		if details.fameGain<0 then details.fameGain=0 end
		combat.previewFameByPlayer[playerIndex]=total
	end
	return true
end

function apocalypseDragonBeginGroundCombat(playerIndex)
	if apocalypseDragonScenario()~=true or gStates.apocalypseDragonLairRevealed~=true or gStates.apocalypseDragonDefeated==true then return false end
	if gStates.apocalypseDragonGroundCombat~=nil then return apocalypseDragonGroundCombatForPlayer(playerIndex) end
	local details=turnOrder[playerIndex]
	if details==nil or details.mage==gStates.positionMageKnight[5] then return false end
	gStates.apocalypseDragonLairAttacked=true --from the first lair attack onward the Dragon takes no more automated turns
	local combat=apocalypseDragonNewGroundCombat(false)
	combat.playerIndex=playerIndex
	combat.mage=details.mage
	combat.players[playerIndex]=true
	if gStates.apocalypseDragonAssaultFortifiedInitiator==true then combat.fortifiedPlayers[playerIndex]=true end
	gStates.apocalypseDragonGroundCombat=combat
	gStates.monsterPerks=gStates.monsterPerks or {}
	--Control is always the first/left-most Dragon head; coloured heads follow it.
	apocalypseDragonGroundPrepareControl(combat,playerIndex,1,true)
	local slot=2
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		if apocalypseDragonGroundPrepareColoredHead(combat,headName,playerIndex)==true then
			local headData=apocalypseDragonHeadData(headName)
			local token=headData~=nil and getObjectFromGUID(headData.tokenGUID) or nil
			local target=apocalypseDragonGroundTokenPosition(playerIndex,slot)
			if token~=nil and target~=nil then token.setPositionSmooth(target,false,true) end
			slot=slot+1
		end
	end
	apocalypseDragonRefreshGroundAttackSuppression()
	apocalypseDragonRefreshGroundFameGain(playerIndex)
	combatCameraFocus(playerIndex)
	mainUIUpdate("Apocalypse Dragon Ground Combat")
	broadcastToAll(joinLang({translateWord[details.mage] or tostring(details.mage),"{en} attacks the landed Apocalypse Dragon. Each coloured head is a separate enemy; use the +/- control on a face-up head to record how many levels your attack reduced. Flip a coloured head face down if you did not reduce it. The Control head cannot be attacked.{ru} атакует приземлившегося Дракона Апокалипсиса. Каждая цветная голова считается отдельным врагом; используйте +/- на открытой голове, чтобы записать, на сколько уровней её снизила атака. Переверните цветную голову лицом вниз, если вы не снизили её уровень. Голову Контроля атаковать нельзя.{zh-tw} 攻擊已落地的末日巨龍。每個彩色龍首都是獨立敵人；用正面龍首上的 +/- 控制記錄攻擊降低了多少等級。若未降低某個彩色龍首的等級，將其翻至背面。控制龍首不能被攻擊。{zh-cn} 攻击已落地的末日巨龙。每个彩色龙首都是独立敌人；用正面龙首上的 +/- 控制记录攻击降低了多少等级。若未降低某个彩色龙首的等级，将其翻至背面。控制龙首不能被攻击。{ko}이(가) 착륙한 아포칼립스 드래곤을 공격합니다. 각 색깔 머리는 별도의 적입니다. 앞면인 머리의 +/-를 사용해 공격으로 낮춘 레벨 수를 기록하십시오. 레벨을 낮추지 못한 색깔 머리는 뒷면으로 뒤집으십시오. 제어 머리는 공격할 수 없습니다.{es} ataca al Dragón del Apocalipsis aterrizado. Cada cabeza de color es un enemigo separado; usa el control +/- de una cabeza boca arriba para registrar cuántos niveles redujo tu ataque. Voltea boca abajo una cabeza de color si no redujiste su nivel. La cabeza de Control no puede ser atacada.{fr} attaque le Dragon de l’Apocalypse au sol. Chaque tête colorée est un ennemi distinct ; utilisez le contrôle +/- d’une tête face visible pour noter le nombre de niveaux retirés par votre attaque. Retournez une tête colorée face cachée si vous n’avez réduit aucun niveau. La tête de Contrôle ne peut pas être attaquée.{pt-br} ataca o Dragão do Apocalipse pousado. Cada cabeça colorida é um inimigo separado; use o controle +/- em uma cabeça virada para cima para registrar quantos níveis seu ataque reduziu. Vire uma cabeça colorida para baixo se você não reduziu seu nível. A cabeça de Controle não pode ser atacada.{de} greift den gelandeten Apokalypse-Drachen an. Jeder farbige Kopf ist ein eigener Gegner; verwende die +/- Steuerung eines offenen Kopfes, um festzuhalten, um wie viele Stufen dein Angriff ihn reduziert hat. Drehe einen farbigen Kopf verdeckt, wenn du ihn nicht reduziert hast. Der Kontrollkopf kann nicht angegriffen werden."}),positionToColor(playerIndex))
	return true
end

apocalypseDragonCoopAdjacentPlayers=function(playerIndex)
	local result={}
	if gStates==nil or gStates.apocalypseDragonLair==nil then return result end
	for candidate,details in ipairs(turnOrder or {}) do
		if candidate~=playerIndex and details~=nil and details.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(candidate)==false then
			local pos=fracturedLandsTeleportSourcePosition~=nil and fracturedLandsTeleportSourcePosition(candidate) or nil
			if pos==nil then local avatar=coopAssaultAvatarObject(candidate) if avatar~=nil then pos=avatar.getPosition() end end
			local adjacent=false
			if pos~=nil then
				for _,hex in ipairs(gStates.apocalypseDragonLair.hexes or {}) do
					local p=hex.position
					if p~=nil then
						local d=((pos[1]-p[1])^2)+((pos[3]-p[3])^2)
						if d>4.2 and d<7.4 then adjacent=true break end
					end
				end
			end
			if adjacent==true then result[#result+1]={mage=details.mage,turn=candidate} end
		end
	end
	return result
end

apocalypseDragonAssaultOriginData=function(approachPosition)
	local origin={avatarLocation="",avatarSharedHex=nil,avatarSwapCity=nil,position=nil}
	if approachPosition~=nil then
		origin.position={approachPosition[1],approachPosition[2],approachPosition[3]}
		local terrain,bearing,_,feature=terrainHexAtPosition(approachPosition)
		if terrain~=nil and bearing~=nil then origin.avatarLocation=feature or "" end
	end
	return origin
end

function apocalypseDragonBeginLairAssault(playerIndex,approachPosition)
	if apocalypseDragonScenario()~=true or gStates.apocalypseDragonLairRevealed~=true or gStates.apocalypseDragonDefeated==true then return false end
	if gStates.coopAssaultPhase~=nil or gStates.apocalypseDragonGroundCombat~=nil then return false end
	local player=turnOrder[playerIndex]
	if player==nil or playerIndex~=gStates.turnNumber or playerDropoutInactive(playerIndex)==true then return false end
	local endHorsemenOnStart=gStates.gameScenario=="Apocalypse is Here" and gStates.apocalypseDragonLairAttacked~=true and apocalypseIsHereEndHorsemen~=nil
	gStates.apocalypseDragonAssaultFortifiedInitiator=gStates.gameScenario=="Apocalypse is Here" and apocalypseIsHereDragonCitySpacePlayer~=nil and apocalypseIsHereDragonCitySpacePlayer(playerIndex)==true
	local liveHeads={}
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		local level=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[headName] or 0) or 0
		local headData=apocalypseDragonHeadData(headName)
		if level>0 and headData~=nil and getObjectFromGUID(headData.tokenGUID)~=nil then liveHeads[#liveHeads+1]=headData.tokenGUID end
	end
	if #liveHeads<1 then return false end
	local nearby=apocalypseDragonCoopAdjacentPlayers(playerIndex)
	if #liveHeads<2 or #nearby<1 then
		local started=apocalypseDragonBeginGroundCombat(playerIndex)
		if started==true and endHorsemenOnStart==true then apocalypseIsHereEndHorsemen() end
		return started
	end

	gStates.apocalypseDragonAssaultOrigin=apocalypseDragonAssaultOriginData(approachPosition)
	gStates.assaultData={[player.mage]={primary={},secondary={},UIPos={1},joined=true}}
	for _,guid in ipairs(liveHeads) do
		gStates.assaultData[player.mage].primary[#gStates.assaultData[player.mage].primary+1]=guid
		local headName=apocalypseDragonGroundHeadNameForGUID(guid)
		local headData=headName~=nil and apocalypseDragonHeadData(headName) or nil
		if headData~=nil then gStates.monsterPlayLocation[guid]=apocalypseDragonHeadTokenPosition(headData) end
	end
	local count=1
	for _,candidate in ipairs(nearby) do
		count=count+1
		gStates.assaultData[candidate.mage]={primary={},secondary={},UIPos={count},joined=false}
	end
	gStates.coopAssaultUnassigned={primary={},secondary={}}
	gStates.coopAssaultCityGUID=apocalypseDragon.model
	gStates.coopAssaultLocation="apocalypse dragon"
	gStates.coopAssaultType="dragon"
	gStates.coopAssaultInitiator=playerIndex
	player.combatIconHide="Avatar"
	locationAttacked=true
	applyColorBarButtons()
	coopAssaultUIUpdate()
	if endHorsemenOnStart==true then apocalypseIsHereEndHorsemen() end
	return true
end

function apocalypseDragonBeginCoopGroundCombat()
	if gStates==nil or gStates.coopAssaultPhase~="combat" or coopAssaultTargetType()~="dragon" then return false end
	if gStates.apocalypseDragonGroundCombat~=nil then return true end
	local combat=apocalypseDragonNewGroundCombat(true)
	combat.initiator=gStates.coopAssaultInitiator or gStates.turnNumber
	if gStates.apocalypseDragonAssaultFortifiedInitiator==true then combat.fortifiedPlayers[combat.initiator]=true end
	gStates.apocalypseDragonGroundCombat=combat
	gStates.apocalypseDragonLairAttacked=true
	gStates.monsterPerks=gStates.monsterPerks or {}
	for playerIndex,_ in pairs(gStates.coopAssaultParticipants or {}) do combat.players[playerIndex]=true combat.fameByPlayer[playerIndex]=0 end
	for playerIndex,details in ipairs(turnOrder or {}) do
		local assigned=details~=nil and gStates.assaultData~=nil and gStates.assaultData[details.mage] or nil
		if assigned~=nil and assigned.joined==true then
			local assignedCount=0
			for _,army in ipairs({"primary","secondary"}) do
				for _,guid in ipairs(assigned[army] or {}) do
					local headName=apocalypseDragonGroundHeadNameForGUID(guid)
					if headName~=nil and headName~="Control" and apocalypseDragonGroundPrepareColoredHead(combat,headName,playerIndex)==true then assignedCount=assignedCount+1 end
				end
			end
			apocalypseDragonGroundPrepareControl(combat,playerIndex,1,false)
		end
	end
	apocalypseDragonRefreshGroundAttackSuppression()
	for playerIndex,_ in pairs(combat.players or {}) do apocalypseDragonRefreshGroundFameGain(playerIndex) end
	broadcastToAll("{en}The cooperative assault on the Apocalypse Dragon begins. The coloured heads have been divided between the participating Mage Knights; every participant also faces the Control head.{ru}Начинается совместный штурм Дракона Апокалипсиса. Цветные головы распределены между участвующими Рыцарями-магами; каждый участник также сражается с головой Контроля.{zh-tw}對末日巨龍的合作攻城開始。彩色龍首已分配給參戰的魔法騎士；每名參戰者也都要面對控制龍首。{zh-cn}对末日巨龙的合作攻城开始。彩色龙首已分配给参战的魔法骑士；每名参战者也都要面对控制龙首。{ko}아포칼립스 드래곤 협동 공격이 시작됩니다. 색깔 머리는 참가한 마법 기사들에게 나뉘어 배정되며, 모든 참가자는 제어 머리도 상대합니다.{es}Comienza el asalto cooperativo al Dragón del Apocalipsis. Las cabezas de colores se han repartido entre los Caballeros Mago participantes; cada participante también se enfrenta a la cabeza de Control.{fr}L’assaut coopératif contre le Dragon de l’Apocalypse commence. Les têtes colorées ont été réparties entre les Chevaliers-Mages participants ; chacun affronte également la tête de Contrôle.{pt-br}Começa o assalto cooperativo ao Dragão do Apocalipse. As cabeças coloridas foram divididas entre os Cavaleiros-Magos participantes; cada participante também enfrenta a cabeça de Controle.{de}Der kooperative Angriff auf den Apokalypse-Drachen beginnt. Die farbigen Köpfe wurden auf die teilnehmenden Magieritter verteilt; jeder Teilnehmer stellt sich außerdem dem Kontrollkopf.",{1,0.75,0.2})
	return true
end

function apocalypseDragonGroundResolveToken(obj)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or obj==nil or combat.processedTokens[obj.guid]==true then return false end
	local active,headName,owner=apocalypseDragonGroundCombatToken(obj.guid)
	if active~=true or headName==nil or owner==nil then return false end
	combat.processedTokens=combat.processedTokens or {}
	combat.processedTokens[obj.guid]=true
	obj.UI.setXmlTable({{}})
	if headName=="Control" then
		local controlData=apocalypseDragonHeadData("Control")
		if controlData~=nil and obj.guid==controlData.tokenGUID then
			local home=apocalypseDragonHeadTokenPosition(controlData)
			obj.setLock(false)
			obj.setRotation({0,180,0})
			if home~=nil then obj.setPositionSmooth(home,false,true) end
		else
			--Do not destroy the clone while the normal end-turn loop still owns this userdata.
			--Move it out of the play area now, then clear the temporary monster registration next frame.
			local cloneGUID=obj.guid
			if combat.controlClones~=nil then combat.controlClones[cloneGUID]=nil end
			obj.setPosition({0,-20,0})
			safeWaitFrames("Scenario",function()
				local clone=getObjectFromGUID(cloneGUID)
				if clone~=nil then clone.destruct() end
				if gStates.monsterPerks~=nil then gStates.monsterPerks[cloneGUID]=nil end
				if gStates.summonStates~=nil then gStates.summonStates[cloneGUID]=nil end
				monsterPugs[cloneGUID]=nil
			end,1)
		end
		return true
	end

	if obj.is_face_down==false and apocalypseDragonGroundTokenInPlayerArea(obj.guid,owner)==true then
		local headLevels=gStates.apocalypseDragonHeadLevels or {}
		local current=tonumber(headLevels[headName]) or 0
		local reduction=math.min(current,apocalypseDragonGroundReduction(headName))
		combat.reductions=combat.reductions or {}
		combat.fameByPlayer=combat.fameByPlayer or {}
		combat.headMarkedToOne=combat.headMarkedToOne or {}
		combat.reductions[headName]=reduction
		combat.fameByPlayer[owner]=(combat.fameByPlayer[owner] or 0)+reduction
		combat.headMarkedToOne[headName]=reduction>=current and current>0
		local headData=apocalypseDragonHeadData(headName)
		local disc=headData~=nil and getObjectFromGUID(headData.guid) or nil
		if disc~=nil then
			for step=0,reduction-1 do
				local target=apocalypseDragonLevelMarkerPosition(disc,current-step)
				if target~=nil then dropShield({target[1],2+(step*0.15),target[3]},false) end
			end
		end
	else
		combat.reductions=combat.reductions or {}
		combat.headMarkedToOne=combat.headMarkedToOne or {}
		combat.reductions[headName]=0
		combat.headMarkedToOne[headName]=false
	end
	local headData=apocalypseDragonHeadData(headName)
	local home=headData~=nil and apocalypseDragonHeadTokenPosition(headData) or nil
	obj.setLock(false)
	obj.setRotation({0,180,0})
	if home~=nil then obj.setPositionSmooth(home,false,true) end
	apocalypseDragonRefreshGroundAttackSuppression()
	return true
end

function apocalypseDragonGroundPlayerFinished(playerIndex)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or combat.coop~=true or combat.players[playerIndex]~=true then return false end
	combat.finishedPlayers[playerIndex]=true
	return true
end

apocalypseDragonGroundApplyFinalLevels=function(combat)
	for _,headName in ipairs(apocalypseDragonColoredHeads) do
		local reduction=tonumber(combat.reductions[headName]) or 0
		if reduction>0 then
			local current=tonumber(gStates.apocalypseDragonHeadLevels[headName]) or 0
			apocalypseDragonSetHeadLevel(headName,math.max(0,current-reduction))
		end
	end
	apocalypseDragonSyncControlLevel()
end

function apocalypseDragonGroundTryApplyLevelsBeforeRewards(playerIndex)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or combat.coop==true or combat.playerIndex~=playerIndex or combat.levelsApplied==true then return false end
	for headName,_ in pairs(combat.deployed or {}) do
		local headData=apocalypseDragonHeadData(headName)
		local guid=headData~=nil and headData.tokenGUID or nil
		if guid~=nil and (combat.processedTokens==nil or combat.processedTokens[guid]~=true) then return false end
	end
	combat.levelsApplied=true
	apocalypseDragonGroundApplyFinalLevels(combat)
	apocalypseDragonCheckAndResolveDefeat()
	mainUIUpdate("Apocalypse Dragon Levels Resolved")
	return true
end

apocalypseDragonGroundCleanupRuntime=function(combat)
	for guid,_ in pairs(combat.controlClones or {}) do
		local clone=getObjectFromGUID(guid)
		if clone~=nil then clone.destruct() end
		monsterPugs[guid]=nil
		if gStates.monsterPerks~=nil then gStates.monsterPerks[guid]=nil end
		if gStates.summonStates~=nil then gStates.summonStates[guid]=nil end
	end
	for _,headData in ipairs(apocalypseDragon.heads) do
		if gStates.summonStates~=nil then gStates.summonStates[headData.tokenGUID]=nil end
		if gStates.monsterPerks~=nil and gStates.monsterPerks[headData.tokenGUID]~=nil then
			gStates.monsterPerks[headData.tokenGUID].dragonGround=nil
			gStates.monsterPerks[headData.tokenGUID].dragonGroundLevel=nil
			gStates.monsterPerks[headData.tokenGUID].dragonLevelFame=nil
			gStates.monsterPerks[headData.tokenGUID].dragonControlBonus=nil
		end
		local token=getObjectFromGUID(headData.tokenGUID)
		local home=apocalypseDragonHeadTokenPosition(headData)
		if token~=nil then
			token.UI.setXmlTable({{}})
			token.setLock(false)
			token.setRotation({0,180,0})
			if home~=nil then token.setPositionSmooth(home,false,true) end
		end
		local level=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[headData.name] or 0) or 0
		apocalypseDragonApplyHeadLevel(headData.name,level)
		gStates.monsterPlayLocation[headData.tokenGUID]=nil
		if gStates.attackedMonsters~=nil then gStates.attackedMonsters[headData.tokenGUID]=nil end
	end
end

function apocalypseDragonFinalizeGroundCombat(playerIndex)
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or combat.coop==true or combat.playerIndex~=playerIndex or combat.finished==true then return false end
	combat.finished=true
	for headName,_ in pairs(combat.deployed or {}) do
		local headData=apocalypseDragonHeadData(headName)
		local token=headData~=nil and getObjectFromGUID(headData.tokenGUID) or nil
		if token~=nil and combat.processedTokens[token.guid]~=true then apocalypseDragonGroundResolveToken(token) end
	end
	if combat.levelsApplied~=true then
		apocalypseDragonGroundApplyFinalLevels(combat)
		combat.levelsApplied=true
	end
	local fame=tonumber(combat.fameByPlayer[playerIndex]) or 0
	apocalypseDragonGroundCleanupRuntime(combat)
	gStates.apocalypseDragonGroundCombat=nil
	if fame>0 then broadcastToAll(joinLang({translateWord[turnOrder[playerIndex].mage] or tostring(turnOrder[playerIndex].mage),"{en} reduced the Apocalypse Dragon by {ru} снизил уровень Дракона Апокалипсиса суммарно на {zh-tw} 總共降低末日巨龍 {zh-cn} 总共降低末日巨龙 {ko}이(가) 아포칼립스 드래곤의 총 레벨을 {es} redujo al Dragón del Apocalipsis un total de {fr} a réduit le Dragon de l’Apocalypse de {pt-br} reduziu o Dragão do Apocalipse em um total de {de} hat den Apokalypse-Drachen insgesamt um ",tostring(fame),"{en} total level(s) and gains {ru} уровней и получает {zh-tw} 個等級，並獲得 {zh-cn} 个等级，并获得 {ko}만큼 낮추고 명성 {es} nivel(es) y gana {fr} niveau(x) au total et gagne {pt-br} nível(is) e ganha {de} Stufe(n) reduziert und erhält ",tostring(fame),"{en} Fame.{ru} Славы.{zh-tw} 聲望值。{zh-cn} 声望值。{ko}을(를) 얻습니다.{es} de Fama.{fr} de Renommée.{pt-br} de Fama.{de} Ruhm."}),positionToColor(playerIndex)) end
	apocalypseDragonCheckAndResolveDefeat()
	mainUIUpdate("Apocalypse Dragon Ground Combat Complete")
	return true
end

function finalizeCoopDragonCombat()
	local combat=gStates~=nil and gStates.apocalypseDragonGroundCombat or nil
	if combat==nil or combat.coop~=true or combat.finished==true then return false end
	combat.finished=true
	--All reductions should already have been recorded by each participant's normal combat cleanup.
	--If a persistent head token somehow escaped that cleanup, treat it as unreduced and return it home.
	for headName,_ in pairs(combat.deployed or {}) do
		if headName~="Control" then
			local headData=apocalypseDragonHeadData(headName)
			local token=headData~=nil and getObjectFromGUID(headData.tokenGUID) or nil
			if token~=nil and combat.processedTokens[token.guid]~=true then
				combat.reductions[headName]=0
				combat.headMarkedToOne[headName]=false
				local home=apocalypseDragonHeadTokenPosition(headData)
				token.UI.setXmlTable({{}})
				token.setRotation({0,180,0})
				if home~=nil then token.setPositionSmooth(home,false,true) end
			end
		end
	end
	apocalypseDragonGroundApplyFinalLevels(combat)
	combat.levelsApplied=true
	--Dragon Fame was already in each player's fameGain when the co-op reward snapshot was made.
	for playerIndex,fame in pairs(combat.fameByPlayer or {}) do
		if fame>0 and turnOrder[playerIndex]~=nil then broadcastToAll(joinLang({translateWord[turnOrder[playerIndex].mage] or tostring(turnOrder[playerIndex].mage),"{en} reduced the Apocalypse Dragon by {ru} снизил уровень Дракона Апокалипсиса суммарно на {zh-tw} 總共降低末日巨龍 {zh-cn} 总共降低末日巨龙 {ko}이(가) 아포칼립스 드래곤의 총 레벨을 {es} redujo al Dragón del Apocalipsis un total de {fr} a réduit le Dragon de l’Apocalypse de {pt-br} reduziu o Dragão do Apocalipse em um total de {de} hat den Apokalypse-Drachen insgesamt um ",tostring(fame),"{en} total level(s) and will gain {ru} уровней и получит {zh-tw} 個等級，並將在合作獎勵階段獲得 {zh-cn} 个等级，并将在合作奖励阶段获得 {ko}만큼 낮추고 협동 보상 단계에서 명성 {es} nivel(es) y ganará {fr} niveau(x) au total et gagnera {pt-br} nível(is) e ganhará {de} Stufe(n) reduziert und erhält in der kooperativen Belohnungsphase ",tostring(fame),"{en} Fame in the cooperative reward phase.{ru} Славы на этапе совместной награды.{zh-tw} 聲望值。{zh-cn} 声望值。{ko}을(를) 얻습니다.{es} de Fama en la fase de recompensa cooperativa.{fr} de Renommée pendant la phase de récompense coopérative.{pt-br} de Fama na fase de recompensa cooperativa.{de} Ruhm."}),positionToColor(playerIndex)) end
	end
	apocalypseDragonGroundCleanupRuntime(combat)
	gStates.apocalypseDragonGroundCombat=nil
	apocalypseDragonCheckAndResolveDefeat()
	return true
end


function apocalypseDragonChoicePlayerIndex()
	local chosen=nil
	for index,details in ipairs(turnOrder or {}) do
		local human=details~=nil and (details.seatPos or 99)<=4 and details.mage~=gStates.positionMageKnight[5]
		if human==true and playerDropoutInactive(index)==false then
			if chosen==nil or (details.tactic or 99)<(turnOrder[chosen].tactic or 99) then chosen=index end
		end
	end
	return chosen
end

function apocalypseDragonChoicePlayerLabel(index)
	if index==nil or turnOrder[index]==nil then return "the player with the lowest-numbered Tactic" end
	local color=positionToColor(index)
	local mage=tostring(turnOrder[index].mage or "player")
	if color~=nil and color~="Black" then return color.." ("..mage..")" end
	return mage
end

function apocalypseDragonChoiceAuthorized(player,pending)
	if pending==nil then return false end
	local color=type(player)=="string" and player or (player~=nil and player.color or nil)
	local allowed=pending.playerIndex~=nil and positionToColor(pending.playerIndex) or nil
	if color=="Black" or color==allowed then return true end
	if color~=nil then
		broadcastToAll(joinLang({apocalypseDragonChoicePlayerLabel(pending.playerIndex),"{en} has the lowest-numbered Tactic and must make this Dragon choice. A player seated Black may also choose.{ru} имеет Тактику с наименьшим номером и должен сделать этот выбор Дракона. Игрок на чёрном месте также может выбрать.{zh-tw} 擁有編號最低的戰術，必須做出此巨龍選擇。坐在黑色席位的玩家也可以選擇。{zh-cn} 拥有编号最低的战术，必须做出此巨龙选择。坐在黑色席位的玩家也可以选择。{ko}이(가) 가장 낮은 번호의 전술을 가지고 있어 이 드래곤 선택을 해야 합니다. 검은색 자리에 앉은 플레이어도 선택할 수 있습니다.{es} tiene la Táctica con el número más bajo y debe realizar esta elección del Dragón. Un jugador sentado en Negro también puede elegir.{fr} possède la Tactique au numéro le plus bas et doit effectuer ce choix du Dragon. Un joueur assis en Noir peut également choisir.{pt-br} tem a Tática de menor número e deve fazer esta escolha do Dragão. Um jogador sentado no Preto também pode escolher.{de} hat die Taktik mit der niedrigsten Nummer und muss diese Drachenwahl treffen. Ein Spieler auf Schwarz darf ebenfalls wählen."}),warningColor)
	end
	return false
end

function positionApocalypseDragonHeads()
	if apocalypseDragonScenario()~=true then return false end
	local moved=false
	for _,headData in ipairs(apocalypseDragon.heads) do
		local head=getObjectFromGUID(headData.guid)
		if head~=nil then
			local pos=head.getPosition()
			if math.abs(pos[1]-headData.position[1])>0.05 or math.abs(pos[3]-headData.position[3])>0.05 then
				head.setPositionSmooth(headData.position)
				moved=true
			end
			head.lock()
			if apocalypseDragonPositionHeadToken(headData)==true then moved=true end
		end
	end
	return moved
end

-- Shared interstitial Dragon-turn shell used by Against the Dragon and Fury.
function apocalypseDragonTurnOrdinal(turnNumber)
	local n=tonumber(turnNumber) or 1
	if n==1 then return "1st" end
	if n==2 then return "2nd" end
	if n==3 then return "3rd" end
	if n==4 then return "4th" end
	return tostring(n).."th"
end

function apocalypseDragonMainUIPanelSpec()
	if gStates==nil or gStates.apocalypseDragonTurnActive~=true then return nil end
	local pending=gStates.apocalypseDragonPendingAttack
	local turnNumber=tonumber(gStates.apocalypseDragonTurn) or 1
	local ordinal=apocalypseDragonTurnOrdinal(turnNumber)
	local mainText=joinLang({"{en}<size=25>Apocalypse Dragon's Turn</size><size=6>\n\n</size><size=18>Round {ru}<size=25>Ход Дракона Апокалипсиса</size><size=6>\n\n</size><size=18>Раунд {zh-tw}<size=25>末日巨龍回合</size><size=6>\n\n</size><size=18>回合輪 {zh-cn}<size=25>末日巨龙回合</size><size=6>\n\n</size><size=18>回合轮 {ko}<size=25>아포칼립스 드래곤의 턴</size><size=6>\n\n</size><size=18>라운드 {es}<size=25>Turno del Dragón del Apocalipsis</size><size=6>\n\n</size><size=18>Ronda {fr}<size=25>Tour du Dragon de l'Apocalypse</size><size=6>\n\n</size><size=18>Manche {pt-br}<size=25>Turno do Dragão do Apocalipse</size><size=6>\n\n</size><size=18>Rodada {de}<size=25>Zug des Apokalypse-Drachen</size><size=6>\n\n</size><size=18>Runde ",tostring(gStates.currentRound or 1),"{en} - Dragon turn {ru} — ход Дракона {zh-tw}－巨龍回合 {zh-cn}－巨龙回合 {ko} - 드래곤 턴 {es} - turno del Dragón {fr} - tour du Dragon {pt-br} - turno do Dragão {de} - Drachenzug ",tostring(turnNumber),"</size><size=4>\n</size>"})
	if pending~=nil then
		if pending.phase=="choose" then
			return {actor="dragon",mainText=mainText,notes=gStates.apocalypseDragonTurnReport or "Resolve the Apocalypse Dragon attack.",onClick="apocalypseDragonProcessUI",label="{en}Resolve Dragon Attack{ru}Разрешите атаку Дракона{zh-tw}處理巨龍攻擊{zh-cn}处理巨龙攻击{ko}드래곤 공격 해결{es}Resolver Ataque del Dragón{fr}Résoudre l'Attaque du Dragon{pt-br}Resolver Ataque do Dragão{de}Drachenangriff abhandeln",interactable=false,responseSpec=againstDragonAttendanceResponseSpec()}
		end
		return {actor="dragon",panelActive=false}
	end
	local state=gStates.apocalypseDragonUIState
	local label="{en}Processing Dragon...{ru}Дракон действует...{zh-tw}巨龍行動處理中...{zh-cn}巨龙行动处理中...{ko}드래곤 처리 중...{es}Procesando Dragón...{fr}Traitement du Dragon...{pt-br}Processando Dragão...{de}Drache wird verarbeitet..."
	local active=false
	if state=="ReadyToProcess" then label="{en}Process Dragon{ru}Ход Дракона{zh-tw}執行巨龍行動{zh-cn}执行巨龙行动{ko}드래곤 진행{es}Procesar Dragón{fr}Traiter le Dragon{pt-br}Processar Dragão{de}Drache aktivieren" active=true
	elseif state=="ReadyToEnd" then label="{en}Dragon Processed{ru}Дракон обработан{zh-tw}巨龍行動結束{zh-cn}巨龙行动结束{ko}드래곤 처리 완료{es}Dragón Procesado{fr}Dragon traité{pt-br}Dragão Processado{de}Drache verarbeitet" active=true
	elseif state=="WaitingChoice" then label="{en}Pick Target{ru}Выберите цель{zh-tw}選擇目標{zh-cn}选择目标{ko}대상 선택{es}Elige Objetivo{fr}Choisir la Cible{pt-br}Escolha o Alvo{de}Ziel wählen"
	elseif state=="WaitingCombat" then label="{en}Combat Resolved{ru}Бой завершён{zh-tw}戰鬥已解決{zh-cn}战斗已解决{ko}전투 해결 완료{es}Combate resuelto{fr}Combat résolu{pt-br}Combate resolvido{de}Kampf beendet" active=true end
	return {actor="dragon",mainText=mainText,notes=gStates.apocalypseDragonTurnReport or joinLang({"{en}The Apocalypse Dragon is preparing its {ru}Дракон Апокалипсиса готовится к своему {zh-tw}末日巨龍正在準備第 {zh-cn}末日巨龙正在准备第 {ko}아포칼립스 드래곤이 {es}El Dragón del Apocalipsis prepara su {fr}Le Dragon de l’Apocalypse prépare son {pt-br}O Dragão do Apocalipse está preparando seu {de}Der Apokalypse-Drache bereitet seinen ",ordinal,"{en} turn.{ru} ходу.{zh-tw} 個回合。{zh-cn} 个回合。{ko}번째 턴을 준비하고 있습니다.{es} turno.{fr} tour.{pt-br} turno.{de} Zug vor."}),onClick="apocalypseDragonProcessUI",label=label,interactable=active}
end

function apocalypseDragonMainUIRefresh()
	local spec=apocalypseDragonMainUIPanelSpec()
	if spec==nil then return false end
	return automatedMainPanelApply(spec)
end

function apocalypseDragonProcessUI(player,mouseButton,id)
	if mouseButton~="-1" or gStates==nil or gStates.apocalypseDragonTurnActive~=true then return end
	local state=gStates.apocalypseDragonUIState
	if state=="ReadyToEnd" then
		apocalypseDragonFinishTurn()
		return
	end
	if furyDragonIsActive~=nil and furyDragonIsActive()==true then
		furyDragonProcessTurn()
		return
	end
	if state~="ReadyToProcess" then return end
	local action=gStates.apocalypseDragonTurnAction
	gStates.apocalypseDragonTurnReportPrefix=nil
	if action=="attack" then
		againstDragonSetTurnReport("The Apocalypse Dragon is determining which player to attack.","Processing")
		againstDragonBeginAttack()
	elseif action=="destroy" then
		againstDragonSetTurnReport("The Apocalypse Dragon is determining what it will destroy.","Processing")
		againstDragonBeginDestroy()
	else
		local ordinal=apocalypseDragonTurnOrdinal(gStates.apocalypseDragonTurn)
		againstDragonSetTurnReport("The Apocalypse Dragon took no action on its "..ordinal.." turn.","Processing")
		safeWaitFrames("Scenario",function() againstDragonCompleteTurn() end,1)
	end
end

function apocalypseDragonFinishTurn(force)
	if gStates==nil or gStates.apocalypseDragonTurnActive~=true then return false end
	if force~=true and gStates.apocalypseDragonUIState~="ReadyToEnd" then return false end
	apocalypseDragonTurnChoiceClearButtons()
	againstDragonAttackControlUI(false)
	UI.setAttribute("DummyTurn","active","false")
	automatedAttackResponseUI(nil)
	gStates.apocalypseDragonTurnActive=false
	local resume=gStates.apocalypseDragonResumeTurn
	local fullAttendPlayer=gStates.apocalypseDragonFullAttendPlayer
	gStates.apocalypseDragonResumeTurn=nil
	gStates.apocalypseDragonPendingChoice=nil
	gStates.apocalypseDragonPendingAttack=nil
	gStates.apocalypseDragonFullAttendPlayer=nil
	gStates.apocalypseDragonUIState=nil
	gStates.apocalypseDragonTurnAction=nil
	gStates.apocalypseDragonTurnReport=nil
	gStates.apocalypseDragonTurnReportPrefix=nil
	if resume~=nil and mergedTurnCommit~=nil then
		local resumeTurn=resume.turnNumber
		if fullAttendPlayer~=nil and resumeTurn==fullAttendPlayer and gStates.skipTurn[fullAttendPlayer]==true then
			gStates.skipTurn[fullAttendPlayer]=nil
			local skipped=turnOrder[fullAttendPlayer]
			local token=skipped~=nil and getObjectFromGUID(skipped.turnOrderTokenGUID) or nil
			if token~=nil and token.is_face_down==true then token.flip() end
			if skipped~=nil then broadcastToAll(joinLang({translateWord[skipped.mage] or tostring(skipped.mage),"{en} skips their normal turn because they fully attended the Dragon attack.{ru} пропускает обычный ход, потому что полностью участвовал в атаке Дракона.{zh-tw} 因完全參與巨龍攻擊而跳過正常回合。{zh-cn} 因完全参与巨龙攻击而跳过正常回合。{ko}은(는) 드래곤 공격에 완전히 참가했으므로 일반 턴을 건너뜁니다.{es} se salta su turno normal porque participó por completo en el ataque del Dragón.{fr} saute son tour normal car il a pleinement participé à l’attaque du Dragon.{pt-br} pula seu turno normal porque participou completamente do ataque do Dragão.{de} überspringt den normalen Zug, weil vollständig am Drachenangriff teilgenommen wurde."}),positionToColor(fullAttendPlayer)) end
			for _=1,#turnOrder do
				resumeTurn=resumeTurn+1
				if resumeTurn>#turnOrder then resumeTurn=1 end
				if playerDropoutInactive(resumeTurn)==false then
					if gStates.skipTurn[resumeTurn]==true then
						gStates.skipTurn[resumeTurn]=nil
						local skippedDetails=turnOrder[resumeTurn]
						local skippedToken=skippedDetails~=nil and getObjectFromGUID(skippedDetails.turnOrderTokenGUID) or nil
						if skippedToken~=nil and skippedToken.is_face_down==true then skippedToken.flip() end
						if skippedDetails~=nil then broadcastToAll(joinLang({translateWord[skippedDetails.mage] or tostring(skippedDetails.mage),"{en} skips their turn. They already played out of order.{ru} пропускает ход: он уже сыграл вне очереди.{zh-tw} 跳過回合，因為已經提前行動過。{zh-cn} 跳过回合，因为已经提前行动过。{ko}은(는) 이미 순서를 벗어나 턴을 진행했으므로 이번 턴을 건너뜁니다.{es} se salta su turno. Ya jugó fuera de orden.{fr} saute son tour. Il a déjà joué hors ordre.{pt-br} pula seu turno. Já jogou fora de ordem.{de} überspringt den Zug. Es wurde bereits außerhalb der Reihenfolge gespielt."}),positionToColor(resumeTurn)) end
					else
						break
					end
				end
			end
		end
		mergedTurnCommit(resumeTurn,resume.newOutOfTurn,resume.sameTurn)
	else
		mainUIUpdate("Dragon Turn Complete")
	end
	return true
end

function apocalypseDragonTurnChoiceClearButtons()
	againstDragonTargetChoiceClearButtons()
	againstDragonOffMapChoiceClearButtons()
end

end)
