					--Day Board, 5 Weather Tokens, weather deck
		local found=false
		for _, ruinGUID in pairs(ruinPugs) do
			local ruin=getObjectFromGUID(ruinGUID)
			if ruin~=nil and ruin.is_face_down==true then
				revealRuinAfterArrival(ruinGUID)
