	pastedRegisterFailed="{en}The pasted Enemy could not be registered as a Puppet and was removed.{ru}Не удалось зарегистрировать вставленного Врага как Марионетку, поэтому он был удалён.{zh-tw}無法將貼上的敵人登記為傀儡，因此已將其移除。{zh-cn}无法将粘贴的敌人登记为傀儡，因此已将其移除。{ko}붙여넣은 적을 꼭두각시로 등록할 수 없어 제거했습니다.{es}No se pudo registrar el Enemigo pegado como Marioneta y se eliminó.{fr}L'Ennemi collé n'a pas pu être enregistré comme Marionnette et a été supprimé.{pt-br}O Inimigo colado não pôde ser registrado como Fantoche e foi removido.{de}Der eingefügte Gegner konnte nicht als Marionette registriert werden und wurde entfernt.",
	ownerUnknown="{en}The Puppet's owner could not be identified.{ru}Не удалось определить владельца Марионетки.{zh-tw}無法確定傀儡的擁有者。{zh-cn}无法确定傀儡的拥有者。{ko}꼭두각시의 소유자를 확인할 수 없습니다.{es}No se pudo identificar al propietario de la Marioneta.{fr}Le propriétaire de la Marionnette n'a pas pu être identifié.{pt-br}Não foi possível identificar o dono do Fantoche.{de}Der Besitzer der Marionette konnte nicht ermittelt werden.",
	ownerCombat="{en}A stored Puppet can only be played into its owner's combat area.{ru}Сохранённую Марионетку можно разыграть только в боевую зону её владельца.{zh-tw}已保留的傀儡只能打出到其擁有者的戰鬥區。{zh-cn}已保留的傀儡只能打出到其拥有者的战斗区。{ko}보관한 꼭두각시는 소유자의 전투 영역에만 사용할 수 있습니다.{es}Una Marioneta guardada solo puede jugarse en la zona de combate de su propietario.{fr}Une Marionnette conservée ne peut être jouée que dans la zone de combat de son propriétaire.{pt-br}Um Fantoche guardado só pode ser jogado na área de combate do seu dono.{de}Eine aufbewahrte Marionette kann nur in den Kampfbereich ihres Besitzers gespielt werden.",
	played="{en} was played; no Enemy can be kept with Puppet Master this turn.{ru} разыграна; в этом ходу с помощью «Кукловода» больше нельзя сохранить Врага.{zh-tw}已打出；本回合不能再用「傀儡大師」保留敵人。{zh-cn}已打出；本回合不能再用“傀儡大师”保留敌人。{ko}을(를) 사용했습니다. 이번 차례에는 꼭두각시 조종자로 적을 보관할 수 없습니다.{es} se jugó; este turno no se puede guardar ningún Enemigo con Maestro de Marionetas.{fr} a été jouée ; aucun Ennemi ne peut être conservé avec Maître des Marionnettes pendant ce tour.{pt-br} foi jogado; nenhum Inimigo pode ser mantido com Mestre dos Fantoches neste turno.{de} wurde gespielt; in diesem Zug kann mit Puppenmeister kein Gegner behalten werden."
}

local function puppetMasterDisplayName(name,fallback)
	if name~=nil and translateWord~=nil and translateWord[name]~=nil then return translateWord[name] end
	if name~=nil and tostring(name)~="" then return tostring(name) end
	return fallback
end

function puppetMasterPlayerIndexForSeat(seatPos)
	if seatPos==nil then return nil end
	for playerIndex, details in pairs(turnOrder or {}) do
		if details.seatPos==seatPos and details.mage~=gStates.positionMageKnight[5] then return playerIndex end
	end
	return nil
end

function puppetMasterPlayerIndexForMage(mage)
	if mage==nil then return nil end
	for playerIndex, details in pairs(turnOrder or {}) do if details.mage==mage then return playerIndex end end
	return nil
end

function puppetMasterSeatForColor(playerColor)
	if playerColor==nil or playerColor=="Black" or playerColor=="Grey" then return nil end
	local player=Player[playerColor]
	if player==nil or player.seated~=true or player.getHandTransform()==nil then return nil end
	return math.ceil((player.getHandTransform().position[1]+97.59)/40)
end

function puppetMasterColorCanMovePlayer(playerColor, playerIndex)
	if playerColor=="Black" then return true end
	local details=turnOrder[playerIndex]
	return details~=nil and puppetMasterSeatForColor(playerColor)==details.seatPos
end

function puppetMasterObjectInZone(objectGUID, zoneGUID)
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==objectGUID then return true end end
	return false
end

function puppetMasterCombatAreaPlayer(objectGUID)
	for playerIndex, details in pairs(turnOrder or {}) do
		if details.seatPos~=nil and details.mage~=gStates.positionMageKnight[5] then
			if puppetMasterObjectInZone(objectGUID,playerPlayAreas[details.seatPos])==true or puppetMasterObjectInZone(objectGUID,playerUnitAreas[details.seatPos])==true then return playerIndex end
		end
	end
	return nil
end

function puppetMasterInventoryPlayer(objectGUID)
	for playerIndex, details in pairs(turnOrder or {}) do
		if details.seatPos~=nil and details.mage~=gStates.positionMageKnight[5] and puppetMasterObjectInZone(objectGUID,playerCrystalAreas[details.seatPos])==true then return playerIndex end
	end
	return nil
end

function puppetMasterOwnsSkill(playerIndex)
	local details=turnOrder[playerIndex]
	local skillPos=gStates.mageSkills~=nil and gStates.mageSkills[puppetMasterSkillGUID] or nil
	if details==nil or skillPos==nil or skillPos[1]==nil or skillPos[3]==nil then return false end
	--Claimed Skills keep their home position in the owner's Skill column even while a Turn Skill is in play.
	local skillX=(details.seatPos*40)-107.45
	return skillPos[3]<-35 and math.abs(skillPos[1]-skillX)<2
end

function puppetMasterEnemyEligible(enemy)
	if enemy==nil then return false end
	local details=monsterPugs[enemy.guid]
	return details~=nil and details.name~="Ruin" and details.pugType~="possessed"
end

function puppetMasterWarn(playerIndex,message,controllerColor)
	local text=joinLang({puppetMasterText.skill,": ",message})
	local color=controllerColor
	if color==nil or Player[color]==nil or Player[color].seated~=true then
		color=playerIndex~=nil and positionToColor(playerIndex) or nil
	end
	if color~=nil and Player[color]~=nil and Player[color].seated==true then
		broadcastToColor(text,color,warningColor)
	elseif Player["Black"]~=nil and Player["Black"].seated==true then
		broadcastToColor(text,"Black",warningColor)
	else
		broadcastToAll(text,warningColor)
	end
end

function puppetMasterReturnToPickup(obj,pickup,message)
	if pickup==nil then return end
	if message~=nil then puppetMasterWarn(pickup.player,message,pickup.color) end
	puppetMasterPickup[obj~=nil and obj.guid or ""]=nil
	if obj==nil then return end
	if pickup.rotation~=nil then obj.setRotation(pickup.rotation) end
	if pickup.position~=nil then obj.setPosition(pickup.position) end
end

function puppetMasterApplyDecal(puppet)
	if puppet==nil or puppetMasterDecalURL==nil or puppetMasterDecalURL=="" then return end
	--Replace the marker rather than returning when one already exists, so saved Puppets also pick up
	--future size/position changes to the Puppet Master decal. Preserve any unrelated decals.
	local decals={}
	for _, decal in pairs(puppet.getDecals() or {}) do if decal.name~="Puppet Master" then table.insert(decals,decal) end end
	puppet.setDecals(decals)
	puppet.addDecal({name="Puppet Master",url=puppetMasterDecalURL,position={0,0.15,0},rotation={90,180,0},scale={0.96,0.96,1}})
end


function puppetMasterHalfAttacks(attack)
	if type(attack)~="table" then return nil end
	local result={}
	for attackType, values in pairs(attack) do
		local halved={}
		if type(values)=="table" then
			for _, value in ipairs(values) do if type(value)=="number" then halved[#halved+1]=math.ceil(value/2) end end
		elseif type(values)=="number" then
			halved[1]=math.ceil(values/2)
		end
		if #halved>0 then result[attackType]=halved end
	end
	return next(result)~=nil and result or nil
end

--Puppets are one-use Attack/Block effects, not enemies or Units. Keep only the values Puppet Master
--actually uses in monsterPerks so the normal monster hover renderer can display them. Enemy abilities,
--Fame, rewards and Physical Resistance deliberately do not carry over.
function puppetMasterPerksForData(data)
	local perks={}
	if type(data)~="table" then return perks end
	local attack=puppetMasterHalfAttacks(data.attack)
	if attack~=nil then perks.attack=attack end
	if type(data.armour)=="number" then
		local blockType="P"
		--Puppet Master reverses a single elemental resistance for Block; both become Cold Fire Block.
		if data.fResist~=nil and data.iResist~=nil then blockType="IF"
		elseif data.fResist~=nil then blockType="I"
		elseif data.iResist~=nil then blockType="F" end
		perks.block={[blockType]={math.ceil(data.armour/2)}}
	end
	return perks
end

function puppetMasterRefreshPresentation(puppet,record)
	if puppet==nil then return end
	puppetMasterApplyDecal(puppet)
	local _,data=puppetMasterDataForSourceGUID(record~=nil and record.sourceGUID or nil)
	if gStates.monsterPerks==nil then gStates.monsterPerks={} end
	gStates.monsterPerks[puppet.guid]=puppetMasterPerksForData(data)
	puppet.setDescription("")
end

function puppetMasterObjectImage(obj)
	if obj==nil then return nil end
	local custom=obj.getCustomObject()
	if custom==nil then return nil end
	return custom.image or custom.image_url or custom.ImageURL or custom.diffuse or custom.DiffuseURL
end

function puppetMasterDataForSourceGUID(sourceGUID)
	if sourceGUID==nil then return nil,nil end
	local details=monsterPugs[sourceGUID]
	if details==nil then return nil,nil end
	local puppetData=details
	if sourceGUID==darkCrusader.token or sourceGUID==elementalist.token then
		local leader=sourceGUID==darkCrusader.token and darkCrusader or elementalist
		if leaderData[leader.terrainHex]~=nil and leaderData[leader.terrainHex][1]~=nil and leaderData[leader.terrainHex][1].abilities~=nil then puppetData=leaderData[leader.terrainHex][1].abilities end
	end
	return details,puppetData
end

function puppetMasterDataForEnemy(enemy)
	if enemy==nil then return nil,nil end
	return puppetMasterDataForSourceGUID(enemy.guid)
end

function puppetMasterPreparePuppet(puppet)
	if puppet==nil then return end
	--Possession/buff attachments and combat controls belong to the real Enemy, never to the kept Puppet.
	if #puppet.getAttachments()>0 then for _, attachment in pairs(puppet.removeAttachments() or {}) do attachment.destruct() end end
	puppet.clearButtons()
	puppet.UI.setXmlTable({{}})
	puppet.setDecals({})
	puppet.setGMNotes("Puppet Master")
	puppet.setDescription("")
end

function puppetMasterRegisterPuppet(puppet,enemy,playerIndex,controllerColor)
	local playerData=turnOrder[playerIndex]
	local details,puppetData=puppetMasterDataForEnemy(enemy)
	if puppet==nil or playerData==nil or details==nil or puppetData==nil then return false end
	puppetMasterPreparePuppet(puppet)
	if gStates.puppetMasterPuppets==nil then gStates.puppetMasterPuppets={} end
	gStates.puppetMasterPuppets[puppet.guid]={ownerMage=playerData.mage,ownerSeat=playerData.seatPos,sourceGUID=enemy.guid,name=puppetData.name or details.name,location="inventory",played=false}
	puppetMasterRefreshPresentation(puppet,gStates.puppetMasterPuppets[puppet.guid])
	playerData.puppetMasterUsed=true
	puppetMasterWarn(playerIndex,joinLang({puppetMasterDisplayName(details.name,puppetMasterText.enemy),puppetMasterText.kept}),controllerColor)
	return true
end

function puppetMasterRegisterClone(enemy,pickup)
	local dropPos=enemy.getPosition()
	local dropRot=enemy.getRotation()
	--Object.clone() gives the new token a brief physics/autoraise kick even when spawned at its final
	--position. Build the Puppet from the Enemy's ObjectState instead and keep it locked for its first
	--couple of frames so there is never a clone-separation "pop".
	local puppetData=enemy.getData()
	if puppetData==nil then return false end
	puppetData.GUID=nil
	puppetData.Locked=true
	if pickup.rotation~=nil then enemy.setRotation(pickup.rotation) end
	if pickup.position~=nil then enemy.setPosition(pickup.position) end
	local puppet=spawnObjectData({data=puppetData,position={dropPos[1],dropPos[2],dropPos[3]},rotation={dropRot[1],dropRot[2],dropRot[3]}})
	if puppet==nil then return false end
	puppet.setVelocity({0,0,0})
	puppet.setAngularVelocity({0,0,0})
	puppet.setPosition(dropPos)
	puppet.setRotation(dropRot)
	if puppetMasterRegisterPuppet(puppet,enemy,pickup.player,pickup.color)~=true then puppet.destruct() return false end
	local puppetGUID=puppet.guid
	safeWaitFrames("PlayerBoard.PuppetMaster",function()
		local live=getObjectFromGUID(puppetGUID)
		if live~=nil then
			live.setPosition(dropPos)
			live.setRotation(dropRot)
			live.setVelocity({0,0,0})
			live.setAngularVelocity({0,0,0})
			live.unlock()
		end
	end,2)
	puppetMasterPickup[enemy.guid]=nil
	return true
end

--Deleting or trashing a Puppet immediately after claiming it is treated as undo while the exact real
--Enemy used to create it is still in that Mage Knight's combat area. Once normal combat cleanup has
--removed the source Enemy, disposing of the Puppet is just an ordinary Puppet deletion.
function puppetMasterUndoFreshClaim(puppetGUID,controllerColor)
	local record=gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[puppetGUID] or nil
	if record==nil or record.sourceGUID==nil or record.played==true then return false end
	local owner=puppetMasterRecordOwnerIndex(record)
	local source=getObjectFromGUID(record.sourceGUID)
	if owner==nil or source==nil or puppetMasterCombatAreaPlayer(source.guid)~=owner then return false end
	gStates.puppetMasterPuppets[puppetGUID]=nil
	if gStates.monsterPerks~=nil then gStates.monsterPerks[puppetGUID]=nil end
	puppetMasterPickup[puppetGUID]=nil
	if turnOrder[owner]~=nil then turnOrder[owner].puppetMasterUsed=false end
	puppetMasterWarn(owner,joinLang({puppetMasterDisplayName(record.name,puppetMasterText.puppet),puppetMasterText.undo}),controllerColor)
	return true
end

function puppetMasterUseReason(playerIndex)
	local playerData=turnOrder[playerIndex]
	if playerData==nil then return puppetMasterText.ownerUnknown end
	if gStates.turnNumber~=playerIndex then return puppetMasterText.duringTurn end
	if gStates.preEndTurn==true then return puppetMasterText.turnCleanup end
	if puppetMasterOwnsSkill(playerIndex)~=true then return joinLang({puppetMasterDisplayName(playerData.mage,tostring(playerData.mage)),puppetMasterText.doesNotOwn}) end
	if playerData.puppetMasterUsed==true then return joinLang({puppetMasterText.skill,puppetMasterText.alreadyUsed}) end
	return nil
end

function puppetMasterClaimReason(enemy,pickup,destinationPlayer)
	local playerData=pickup~=nil and turnOrder[pickup.player] or nil
	if playerData==nil or destinationPlayer~=pickup.player then return puppetMasterText.ownerInventory end
	if pickup.fromCombat~=true then return puppetMasterText.fromCombat end
	if puppetMasterEnemyEligible(enemy)~=true then return puppetMasterText.eligible end
	if pickup.faceUp~=true or enemy.is_face_down==true then return puppetMasterText.defeatedFaceUp end
	if enemy.guid==darkCrusader.token or enemy.guid==elementalist.token then
		local leaderLevel=enemy.guid==darkCrusader.token and gStates.darkCrusaderLevel or gStates.elementalistLevel
		if leaderLevel~=nil and ((gStates.leaderReduction or 0)+(gStates.leaderOverkill or 0))<leaderLevel then return puppetMasterText.leaderDefeated end
	end
	return puppetMasterUseReason(pickup.player)
end

function puppetMasterResolveEnemyDrop(enemy,pickup)
	local inventoryPlayer=puppetMasterInventoryPlayer(enemy.guid)
	if inventoryPlayer==nil then puppetMasterPickup[enemy.guid]=nil return end
	local reason=puppetMasterClaimReason(enemy,pickup,inventoryPlayer)
	if reason~=nil then puppetMasterReturnToPickup(enemy,pickup,reason) return end
	if puppetMasterRegisterClone(enemy,pickup)~=true then puppetMasterReturnToPickup(enemy,pickup,puppetMasterText.copyFailed) end
end

--Manual copy/paste remains a supported Puppet Master interaction. A pasted token has a new GUID,
--so match its face image to the real defeated Enemy still sitting in that player's combat area.
function puppetMasterManualCopySource(copy,playerIndex)
	local playerData=turnOrder[playerIndex]
	local image=puppetMasterObjectImage(copy)
	if playerData==nil or image==nil or image=="" then return nil end
	for _, enemy in pairs(playerCombatObjects(playerData.seatPos)) do
		if enemy.guid~=copy.guid and puppetMasterEnemyEligible(enemy)==true and puppetMasterObjectImage(enemy)==image then return enemy end
	end
	return nil
end

function puppetMasterResolveManualCopy(copy)
	if copy==nil or copy.guid==nil or monsterPugs[copy.guid]~=nil then return false end
	if gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[copy.guid]~=nil then return false end
	local owner=puppetMasterInventoryPlayer(copy.guid)
	if owner==nil then return false end
	local enemy=puppetMasterManualCopySource(copy,owner)
	if enemy==nil then return false end
	local pickup={kind="manualCopy",player=owner,fromCombat=true,faceUp=enemy.is_face_down==false}
	local reason=puppetMasterClaimReason(enemy,pickup,owner)
	if reason~=nil then
		puppetMasterWarn(owner,joinLang({reason,puppetMasterText.pastedRemoved}))
		copy.destruct()
		return true
	end
	if puppetMasterRegisterPuppet(copy,enemy,owner)~=true then
		puppetMasterWarn(owner,puppetMasterText.pastedRegisterFailed)
		copy.destruct()
	end
	return true
end

function puppetMasterCheckManualCopyWhenResting(obj)
	if obj==nil or obj.guid==nil or monsterPugs[obj.guid]~=nil then return end
	if gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[obj.guid]~=nil then return end
	if puppetMasterObjectImage(obj)==nil then return end
	local guid=obj.guid
	safeWaitCondition("PlayerBoard.PuppetMaster",function()
		local live=getObjectFromGUID(guid)
		if live~=nil then puppetMasterResolveManualCopy(live) end
	end,function()
		local live=getObjectFromGUID(guid)
		return live==nil or live.resting==true
	end)
end

function puppetMasterRecordOwnerIndex(record)
	if record==nil then return nil end
	local playerIndex=puppetMasterPlayerIndexForMage(record.ownerMage)
	if playerIndex~=nil then return playerIndex end
	return puppetMasterPlayerIndexForSeat(record.ownerSeat)
end

function puppetMasterResolvePuppetDrop(puppet,pickup)
	local record=gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[puppet.guid] or nil
	if record==nil then puppetMasterPickup[puppet.guid]=nil return end
	local owner=puppetMasterRecordOwnerIndex(record)
	if owner==nil then puppetMasterReturnToPickup(puppet,pickup,puppetMasterText.ownerUnknown) return end
	local inventoryPlayer=puppetMasterInventoryPlayer(puppet.guid)
	if inventoryPlayer==owner then
		record.location="inventory"
		record.lastInventoryPosition={puppet.getPosition()[1],puppet.getPosition()[2],puppet.getPosition()[3]}
		record.lastInventoryRotation={puppet.getRotation()[1],puppet.getRotation()[2],puppet.getRotation()[3]}
		puppetMasterPickup[puppet.guid]=nil
		return
	end
	local combatPlayer=puppetMasterCombatAreaPlayer(puppet.guid)
	if combatPlayer~=owner then puppetMasterReturnToPickup(puppet,pickup,puppetMasterText.ownerCombat) return end
	local playerData=turnOrder[owner]
	local reason=puppetMasterUseReason(owner)
	if reason~=nil then puppetMasterReturnToPickup(puppet,pickup,reason) return end
	playerData.puppetMasterUsed=true
	record.played=true
	record.location="played"
	puppetMasterPickup[puppet.guid]=nil
	puppetMasterWarn(owner,joinLang({puppetMasterDisplayName(record.name,puppetMasterText.puppet),puppetMasterText.played}),pickup.color)
end

function puppetMasterTrackPickup(playerColor,obj)
	if obj==nil or obj.guid==nil then return end
	puppetMasterPickup[obj.guid]=nil
	local puppetRecord=gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[obj.guid] or nil
	if puppetRecord~=nil and puppetRecord.played~=true and puppetRecord.location=="inventory" then
		local owner=puppetMasterRecordOwnerIndex(puppetRecord)
		if owner~=nil and puppetMasterColorCanMovePlayer(playerColor,owner)==true then
			puppetMasterPickup[obj.guid]={kind="puppet",player=owner,color=playerColor,position={obj.getPosition()[1],obj.getPosition()[2],obj.getPosition()[3]},rotation={obj.getRotation()[1],obj.getRotation()[2],obj.getRotation()[3]}}
		end
		return
	end
	if puppetMasterEnemyEligible(obj)~=true then return end
	local combatPlayer=puppetMasterCombatAreaPlayer(obj.guid)
	if combatPlayer==nil or puppetMasterColorCanMovePlayer(playerColor,combatPlayer)~=true then return end
	puppetMasterPickup[obj.guid]={kind="enemy",player=combatPlayer,color=playerColor,fromCombat=true,faceUp=obj.is_face_down==false,position={obj.getPosition()[1],obj.getPosition()[2],obj.getPosition()[3]},rotation={obj.getRotation()[1],obj.getRotation()[2],obj.getRotation()[3]}}
end

function puppetMasterDropped(obj)
	if obj==nil or obj.guid==nil then return false end
	local pickup=puppetMasterPickup[obj.guid]
	if pickup==nil then return false end
	local guid=obj.guid
	safeWaitCondition("PlayerBoard.PuppetMaster",function()
		local live=getObjectFromGUID(guid)
		if live==nil or puppetMasterPickup[guid]~=pickup then return end
		if pickup.kind=="enemy" then puppetMasterResolveEnemyDrop(live,pickup)
		elseif pickup.kind=="puppet" then puppetMasterResolvePuppetDrop(live,pickup)
		else puppetMasterPickup[guid]=nil end
	end,function()
		local live=getObjectFromGUID(guid)
		return live==nil or puppetMasterPickup[guid]~=pickup or live.resting==true
	end)
	return true
end

function puppetMasterCleanupPlayedPuppets(playerIndex)
	local details=turnOrder[playerIndex]
	if details==nil or gStates.puppetMasterPuppets==nil then return end
	for guid, record in pairs(gStates.puppetMasterPuppets) do
		if record.ownerMage==details.mage and record.played==true then
			local puppet=getObjectFromGUID(guid)
			gStates.puppetMasterPuppets[guid]=nil
			if gStates.monsterPerks~=nil then gStates.monsterPerks[guid]=nil end
			puppetMasterPickup[guid]=nil
			if puppet~=nil then puppet.destruct() end
		end
	end
end


end)
__bundle_register("PlayingGame.PlayerBoard.Skills", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Player-board Skills runtime.

function refreshMageSkillLocations()
	local double={}
	for skillGUID, _ in pairs(skillTokens) do
		local skill=getObjectFromGUID(skillGUID)
		if skill~=nil then
			local objPos=skill.getPosition()
			if gStates.mageSkills[skillGUID]==nil then gStates.mageSkills[skillGUID]={objPos[1], objPos[2], objPos[3]} end
			local skillPos=gStates.mageSkills[skillGUID]
			local key=(math.floor(skillPos[1]/0.3)*0.3)..(math.floor(skillPos[3]/0.3)*0.3)
			if double[key]~=nil then
				skillPos[1]=skillPos[1]+0.4
				skillPos[3]=skillPos[3]-0.4
				key=(math.floor(skillPos[1]/0.3)*0.3)..(math.floor(skillPos[3]/0.3)*0.3)
			end
			double[key]=true
		end
	end
end

--Update the text in the Main User Interface

--Alternating reward highlights show the two legal Skill + Advanced Action pairings without enforcing either choice.
rewardSkillHighlightWait=nil
rewardSkillHighlightReadyWait=nil
rewardSkillHighlightPhase=false
rewardSkillHighlighted={}
rewardSkillHighlightColor={1,0.9,0}

function clearRewardSkillChoiceHighlights(keepFirstAction)
	local keepGUID=nil
	if keepFirstAction==true then
		local firstAction=mainOfferFirstCardByType("Advanced Action")
		if firstAction~=nil then keepGUID=firstAction.guid end
	end
	local kept={}
	for guid, _ in pairs(rewardSkillHighlighted) do
		if guid==keepGUID then kept[guid]=true
		else
			local obj=getObjectFromGUID(guid)
			if obj~=nil then obj.highlightOff(rewardSkillHighlightColor) end
		end
	end
	rewardSkillHighlighted=kept
end

function addRewardSkillChoiceHighlight(obj)
	if obj==nil or rewardSkillHighlighted[obj.guid]==true then return end
	--Explicitly clear highlights between phases; no timed expiry means the first AA can remain highlighted across both legal pairings.
	obj.highlightOn(rewardSkillHighlightColor)
	rewardSkillHighlighted[obj.guid]=true
end

function rewardSkillChoiceActionCards()
	return mainOfferCardsByType("Advanced Action")
end

function rewardSkillChoiceActionHighlights(allCards)
	local actionCards=rewardSkillChoiceActionCards()
	if allCards==true then
		for _,card in ipairs(actionCards) do addRewardSkillChoiceHighlight(card) end
	elseif actionCards[1]~=nil then
		addRewardSkillChoiceHighlight(actionCards[1])
	end
end

function rewardSkillChoiceForeignSkillExists()
	--Hero Challenges never permit the Common Skills alternative after the forced first Skill.
	if gStates.heroChallenges==true then return false end
	if gStates.mageSkills==nil or gStates.skillButtons==nil or gStates.skillButtons<=0 then return false end
	for skillGUID, skillPos in pairs(gStates.mageSkills) do
		local skill=getObjectFromGUID(skillGUID)
		if skill~=nil and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]>-30 then
			local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
			if skillColumn+1~=gStates.skillButtons then return true end
		end
	end
	return false
end

function rewardSkillChoiceCurrentSkills()
	local currentPlayerSkills={}
	if gStates.mageSkills==nil or gStates.skillButtons==nil or gStates.skillButtons<=0 then return currentPlayerSkills end
	for skillGUID, skillPos in pairs(gStates.mageSkills) do
		local skill=getObjectFromGUID(skillGUID)
		if skill~=nil and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]>-30 then
			local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
			if skillColumn+1==gStates.skillButtons then currentPlayerSkills[#currentPlayerSkills+1]={obj=skill, z=skillPos[3]} end
		end
	end
	table.sort(currentPlayerSkills, function(a,b) return a.z>b.z end)
	return currentPlayerSkills
end

function rewardSkillChoiceHighlightsReady()
	if rewardSkillChoiceForeignSkillExists()==false then return false end
	local currentPlayerSkills=rewardSkillChoiceCurrentSkills()
	if currentPlayerSkills[1]==nil or currentPlayerSkills[2]==nil or currentPlayerSkills[1].obj.resting==false or currentPlayerSkills[2].obj.resting==false then return false end
	local actionCards=rewardSkillChoiceActionCards()
	--Do not start while the Advanced Action offer is still being dealt/slid into place.
	if #actionCards<(gStates.offerSize or 3) then return false end
	for _, card in ipairs(actionCards) do if card.resting==false then return false end end
	return true
end

function rewardSkillChoiceSkillHighlights(ownSkills)
	if gStates.mageSkills==nil or gStates.skillButtons==nil or gStates.skillButtons<=0 then return end
	local currentPlayerSkills=rewardSkillChoiceCurrentSkills()
	local playerLevel=0
	for _, details in pairs(turnOrder) do if details.seatPos==gStates.skillButtons then playerLevel=details.level or 0 break end end
	if ownSkills==true then
		if currentPlayerSkills[1]~=nil then addRewardSkillChoiceHighlight(currentPlayerSkills[1].obj) end
		if currentPlayerSkills[2]~=nil and playerLevel<=10 then addRewardSkillChoiceHighlight(currentPlayerSkills[2].obj) end
	else
		for skillGUID, skillPos in pairs(gStates.mageSkills) do
			local skill=getObjectFromGUID(skillGUID)
			if skill~=nil and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]>-30 then
				local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
				if skillColumn+1~=gStates.skillButtons then addRewardSkillChoiceHighlight(skill) end
			end
		end
	end
end

function stopRewardSkillChoiceHighlights()
	if rewardSkillHighlightReadyWait~=nil then Wait.stop(rewardSkillHighlightReadyWait) rewardSkillHighlightReadyWait=nil end
	if rewardSkillHighlightWait~=nil then Wait.stop(rewardSkillHighlightWait) rewardSkillHighlightWait=nil end
	clearRewardSkillChoiceHighlights()
end

function beginRewardSkillChoiceHighlights()
	if gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillChoiceForeignSkillExists()==false then return end
	rewardSkillHighlightPhase=false
	local function alternateHighlights()
		if gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillChoiceForeignSkillExists()==false then stopRewardSkillChoiceHighlights() return end
		--The first Advanced Action belongs to both pairings, so keep it highlighted across the phase switch.
		clearRewardSkillChoiceHighlights(true)
		rewardSkillHighlightPhase=not rewardSkillHighlightPhase
		if rewardSkillHighlightPhase==true then
			--Foreign Skill choice: only the first Advanced Action is paired with it.
			rewardSkillChoiceActionHighlights(false)
			rewardSkillChoiceSkillHighlights(false)
		else
			--Own Skill choice: every Advanced Action in the offer is paired with it.
			rewardSkillChoiceActionHighlights(true)
			rewardSkillChoiceSkillHighlights(true)
		end
	end
	alternateHighlights()
	rewardSkillHighlightWait=safeWaitTime("PlayerBoard.Skills",alternateHighlights, 2, -1)
end

function startRewardSkillChoiceHighlights()
	if gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillHighlightWait~=nil or rewardSkillHighlightReadyWait~=nil then return end
	--On the first Skill claim there are no foreign Skills, so the reminder has nothing useful to explain.
	if rewardSkillChoiceForeignSkillExists()==false then return end
	if rewardSkillChoiceHighlightsReady()==true then beginRewardSkillChoiceHighlights() return end
	rewardSkillHighlightReadyWait=safeWaitCondition("PlayerBoard.Skills",function()
		rewardSkillHighlightReadyWait=nil
		if rewardSkillChoiceHighlightsReady()==true then beginRewardSkillChoiceHighlights() end
	end, function()
		return gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillChoiceForeignSkillExists()==false or rewardSkillChoiceHighlightsReady()==true
	end)
end

--Moves claimed skill to player location
masterOfChaosPause=false
function __skillMove_raw(player, mouseButton, id, rewindReady)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, gStates.skillButtons)==true then--and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5]
			local skillRewindOwner="Skill claim "..tostring(gStates.skillButtons)
			stopRewardSkillChoiceHighlights()
			--The Claim button already contains the exact Skill GUID. Use that as the authority instead of
			--decoding the communal row/column number back into approximate coordinates; the old decode was
			--fragile if the pool shifted and was wrong on row numbers 8/16/24/32.
			local claimedGUID=id:sub(1, 6)
			local claimedSkill=getObjectFromGUID(claimedGUID)
			local claimedHome=gStates.mageSkills~=nil and gStates.mageSkills[claimedGUID] or nil
			--A live Claim button also carries its 1..32 offer slot. Normally the saved GUID location is
			--present, but keep a correctly decoded fallback so damaged bookkeeping cannot deadlock the reward.
			if claimedHome==nil then
				local source=tonumber(id:sub(7, string.len(id)))
				if source~=nil and source>=1 and source<=32 then
					local column=math.floor((source-1)/8)
					local row=((source-1)%8)+1
					claimedHome={(column*3.7)+11,2,(row*1.35)-25.3}
				end
			end
			if gStates.heroChallenges==true and claimedSkill~=nil and claimedHome~=nil and claimedHome[3]>-30 then
				local claimedColumn=math.ceil((claimedHome[1]-12.85)/3.7)+1
				if claimedColumn~=gStates.skillButtons then
					claimedSkill.unlock()
					claimedSkill.setPositionSmooth(claimedHome)
					broadcastToColor("{en}Hero Challenges: choose one of your two newly flipped Skills.{ru}Испытания героев: выберите один из двух только что открытых навыков.{zh-tw}英雄挑戰：從你剛翻開的兩個技能中選擇一個。{zh-cn}英雄挑战：从你刚翻开的两个技能中选择一个。{ko}영웅 도전: 방금 공개한 두 스킬 중 하나를 선택하세요.{es}Desafíos de Héroe: elige una de tus dos Habilidades recién reveladas.{fr}Défis de Héros : choisissez l'une des deux Compétences que vous venez de révéler.{pt-br}Desafios de Herói: escolha uma das duas Habilidades recém-reveladas.{de}Heldenherausforderungen: Wähle eine deiner beiden gerade aufgedeckten Fertigkeiten.",player.color or "Black",{1,0.6,0.2})
					if rewindReady==true then rewindTransactionFinish(skillRewindOwner) end
					return
				end
			end
			--Skill claiming rewrites the saved skill-location table while several tokens are still moving.
			--Take the rewind point before that transaction begins, then release after the layout has settled.
			if rewindReady~=true then
				if rewindTransactionOwnerActive(skillRewindOwner)==true then return end
				rewindTransactionStart(function() skillMove(player,mouseButton,id,true) end,skillRewindOwner)
				return
			end
			if claimedSkill==nil or claimedHome==nil or claimedHome[1]==nil or claimedHome[3]==nil then
				rewindTransactionFinish(skillRewindOwner)
				skillButtonActivate()
				return
			end
			local communalHome={claimedHome[1], claimedHome[2] or 2, claimedHome[3]}
			--update skill location register with a free spot on player board
			local count=0
			for skillGUID, skillPos in pairs(gStates.mageSkills) do
				if skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]<-36.9 and math.floor(skillPos[1])==math.floor(((gStates.skillButtons*40)-107.45)) then count=count+1 end
			end
			gStates.mageSkills[claimedGUID]={((gStates.skillButtons*40)-107.45), 1.1, -38.67-(1.48*count)}
			--Bonds of Loyalty goes to unit area
			if claimedGUID==GUID.skill.bondsOfLoyalty then
				local bondsX=unitLayoutNextCommandX(gStates.skillButtons)
				gStates.mageSkills[claimedGUID]={bondsX,1.1,-31.19}
				scheduleUnitLayoutRefresh(gStates.skillButtons)
				addRegularUnitsToOffer(2)
				broadcastToAll("{en}Two more Regular units added to the Unit Offer for this round.{ru}Два дополнительных обычных отряда доступны в этом раунде{zh-tw}本輪的部隊供應區增加兩個常規部隊。{zh-cn}本轮增加了两个部队供应{ko}일반 유닛 두 개를 공급처에 추가합니다{es}Se agregaron dos unidades regulares más a la oferta de unidades para esta ronda.{fr}Deux autres unités régulières ajoutées à l'offre d'unités pour ce tour.{pt-br}2 unidades Regulares a mais adicionadas a Oferta de Unidades por esta Rodada{de}Zwei weitere reguläre Einheiten wurden dem Einheitenangebot für diese Runde hinzugefügt.", {1,1,0.5})
			end
			--Master of Chaos
			if claimedGUID==GUID.skill.masterOfChaos then masterOfChaosSetup(gStates.skillButtons) end
			--move selected skill
			claimedSkill.unlock()
			claimedSkill.setPositionSmooth(gStates.mageSkills[claimedGUID])
			if gStates.motivationSkill[claimedGUID]~=nil then
				gStates.motivationSkill[claimedGUID].pos=gStates.skillButtons
				gStates.motivationSkill[claimedGUID].state="active"
				mainUIUpdate("Skill Claimed")
			end
			--move remaining skills in the claimed communal column down. Missing/stale GUIDs are ignored;
			--they must never be able to strand a completed claim with gStates.skillButtons still active.
			for skillGUID, skillPos in pairs(gStates.mageSkills) do
				if skillGUID~=claimedGUID and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil
					and math.floor(communalHome[1])==math.floor(skillPos[1]) and skillPos[3]>communalHome[3] then
					local remainingSkill=getObjectFromGUID(skillGUID)
					if remainingSkill~=nil then
						gStates.mageSkills[skillGUID][3]=gStates.mageSkills[skillGUID][3]-1.35
						remainingSkill.unlock()
						remainingSkill.setPositionSmooth(gStates.mageSkills[skillGUID])
						local remainingGUID=skillGUID
						safeWaitTime("PlayerBoard.Skills",function()
							safeWaitCondition("PlayerBoard.Skills",function()
								local obj=getObjectFromGUID(remainingGUID)
								if obj~=nil then obj.unlock() end
							end, function()
								local obj=getObjectFromGUID(remainingGUID)
								return obj==nil or obj.resting
							end)
						end, 1)
					end
				end
			end
			--Lock Reward claim check button

			--limit advanced action selection if another players skill chosen

			--deploy a dummy skill for next level up.
			if gStates.playersRef==5 then
				local exist=0
				local dummyPos=0
				for a=1, #turnOrder, 1 do
					if turnOrder[a].mage==gStates.positionMageKnight[5] then dummyPos=a break end
				end
				if dummyPos>0 and turnOrder[dummyPos]~=nil then
					for skillGUID, skillPos in pairs(gStates.mageSkills) do
						if skillPos~=nil and skillPos[1]~=nil and math.floor(skillPos[1])==math.floor((turnOrder[dummyPos].seatPos*3.7)+7.3) then exist=exist+1 end
					end
					local pos={(turnOrder[dummyPos].seatPos*3.7)+7.3, 2.00, -23.95+(exist*1.35)}
					local b=nil
					local allSkillsBag=getObjectFromGUID(GUID.bag.allSkills)
					if allSkillsBag~=nil then--use "all Skills" bag if it exists
						b=allSkillsBag.takeObject({position=pos, rotation={0, 180, 0}})
					else
						local dummySkillBag=getObjectFromGUID(turnOrder[dummyPos].skillBagGUID)
						if dummySkillBag~=nil then b=dummySkillBag.takeObject({position=pos, rotation={0, 180, 0}}) end
					end
					if b~=nil then
						safeWaitCondition("PlayerBoard.Skills",function() if b~=nil then b.lock() end end, function() return b==nil or b.resting end)
						gStates.mageSkills[b.guid]=pos
					end
				end
			end
			--turn off skill claim buttons
			local found=false
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==gStates.skillButtons and turnOrder[a].levelUp>0 then processPlayerLevelUps(a) found=true end
			end
			if found==false then
				gStates.skillButtons=0
				stopRewardSkillChoiceHighlights()
				safeWaitFrames("PlayerBoard.Skills",function()
					for skillGUID, _ in pairs(gStates.mageSkills) do
						local skill=getObjectFromGUID(skillGUID)
						if skill~=nil then skill.UI.setXmlTable({{}}) end
					end
				end, 5)
			end
			safeWaitTime("PlayerBoard.Skills",function() rewindTransactionFinish(skillRewindOwner) end,2.0)
		else
			if rewindReady==true then rewindTransactionFinish("Skill claim "..tostring(gStates.skillButtons)) end
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				broadcastToAll("{en}Dummy doesn't claim skill!{ru}Виртуальный игрок не получает навыков!{zh-tw}虛擬玩家不會獲得技能！{zh-cn}虚拟玩家不会选技能{ko}가상 플레이어는 스킬을 얻지 않습니다!{es}¡Dummy no dice tener habilidad!{fr}Le mannequin ne réclame pas de compétence !{pt-br}Jog. Fictício não clama habilidades{de}Dummy beansprucht keine Fertigkeit!", warningColor)
			end
		end
	end
end

--Removes all claim buttons and re-activates only buttons with cards
function claimButtonRefresh()
	--Remove buttons if dummy is choosing
	getObjectFromGUID("483ed5").UI.setXmlTable({{}})
	if gStates.tacticShown==false or turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
		for zoneGUID, cardSource in pairs(tacticClaimingZones) do
			for _, obj in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
				if isTacticCard(obj) then
					obj.UI.setXmlTable({{}})
				end
			end
		end
	end
	--Add buttons
	safeWaitTime("PlayerBoard.Skills",function()
		if gStates.tacticShown==true then
			--Tactic card claim buttons
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				getObjectFromGUID("483ed5").UI.setXmlTable({createClaimButton("483ed5", "tactic7")})
			else
				for zoneGUID, cardSource in pairs(tacticClaimingZones) do
					if getObjectFromGUID(zoneGUID).getObjects()~=nil then
						for _, obj in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
							for a=1, 12, 1 do
								if obj.guid==tacticCard[a] then
									obj.UI.setXmlTable({createClaimButton(obj.guid, cardSource)})
									break
								end
							end
						end
					end
				end
			end
		end
		if gStates.tacticRemove==true then
			--Remove Tactic Claim Button
			if gStates.discardTactics==2 then
				getObjectFromGUID("483ed5").UI.setXmlTable({createClaimButton("483ed5", "removeTactic5")})
			else
				for zoneGUID, cardSource in pairs(tacticClaimingZones) do
					if cardSource:sub(1,6)=="tactic" then
						local cardSourceRemove="removeTactic"..cardSource:sub(7,8)
						local card=getObjectFromGUID(zoneGUID).getObjects()
						if #card>=1 then
							card[1].UI.setXmlTable({createClaimButton(card[1].guid, cardSourceRemove)})
						end
					end
				end
			end
		end
		if gStates.tacticRemove==false and gStates.tacticShown==false then
			--offer buttons
			for zoneGUID, _ in pairs(cardClaimingZones) do
				local zone=getObjectFromGUID(zoneGUID)
				if zone~=nil then
					for _, card in pairs(zone.getObjects()) do
						local cardSource=offerClaimSource(zoneGUID,card)
						if card.type=="Card" and gameCards[card.guid]~=nil and cardSource~=nil then
							card.UI.setXmlTable({{}})
							if gStates.preEndTurn==false or cardSource~="monastery" then
								card.UI.setXmlTable({createClaimButton(card.guid, cardSource)})
							end
						end
					end
				end
			end
			--artifact buttons
			local count=0
			if gStates.dealtArtifacts~=nil then
				for guid, state in pairs(gStates.dealtArtifacts) do
					if state==true then
						count=count+1
						local artifact=getObjectFromGUID(guid)
						if artifact~=nil then artifact.UI.setXmlTable({createClaimButton(guid, "artifactReward")}) end
					end
				end
			end
			if count==0 then
				local artifactDeck=getObjectFromGUID(GUID.deck.artifact)
				if artifactDeck~=nil then
					artifactDeck.UI.setAttribute("ac75c4ArtifactDown", "active", "true")
					artifactDeck.UI.setAttribute("ac75c4ArtifactOffer", "active", "true")
					artifactDeck.UI.setAttribute("ac75c4ArtifactUp", "active", "true")
					artifactDeck.UI.setAttribute("ac75c4ArtifactDownImage", "image", "Overkill Down")
					artifactDeck.UI.setAttribute("ac75c4ArtifactOfferImage", "image", "Sliced Button/Button Object Active")
					artifactDeck.UI.setAttribute("ac75c4ArtifactUpImage", "image", "Overkill Up")
				end
			end
		end
	end, 0.3)
end

local function skillPositionCopy(position)
	if position==nil then return nil end
	return {position[1], position[2], position[3]}
end

local function coopCompSkillActivationTable()
	if gStates.coopCompSkillActivation==nil then gStates.coopCompSkillActivation={} end
	return gStates.coopCompSkillActivation
end

local function coopCompSkillOwnedAreaPlayer(position)
	if position==nil or position[3]>=-35 then return nil end
	for playerIndex, details in pairs(turnOrder) do
		if details.seatPos~=nil and math.abs(position[1]-((details.seatPos*40)-107.45))<2 then return playerIndex end
	end
	return nil
end

local function coopCompSkillPoolPosition(position)
	return position~=nil and position[3]>-25
end

local function coopCompSkillBroadcast(message, playerIndex)
	if playerIndex~=nil and turnOrder[playerIndex]~=nil then broadcastToAll(message, positionToColor(playerIndex))
	else broadcastToAll(message, {1,1,0.5}) end
end

local function deactivateCoopCompSkill(skillGUID, showBroadcast)
	local active=coopCompSkillActivationTable()
	local record=active[skillGUID]
	if record==nil then return false end
	active[skillGUID]=nil
	if showBroadcast~=false then coopCompSkillBroadcast("{en}Skill Deactivated{ru}Навык деактивирован{zh-tw}技能已停用{zh-cn}技能已停用{ko}스킬 비활성화됨{es}Habilidad desactivada{fr}Compétence désactivée{pt-br}Habilidade desativada{de}Fertigkeit deaktiviert", record.player) end
	return true
end

--A Tome swap is inferred from an owned Skill being physically dropped in the common Skill area. This
--also lets a replacement go straight from the pool into the Play Area without losing its new home.
local function tomeSkillSwapTable()
	if gStates.tomeSkillSwapPending==nil then gStates.tomeSkillSwapPending={} end
	return gStates.tomeSkillSwapPending
end

--Motivation ownership is normally assigned by the Skill claim button. Tome/Circlet swaps are physical,
--so mirror that ownership here and refresh only the Out of Turn Actions menu.
local function tomeMotivationSnapshot(skillGUID)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	if stats==nil then return nil end
	return {pos=stats.pos, state=stats.state}
end

local function tomeRestoreMotivation(skillGUID, snapshot)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	if stats==nil or snapshot==nil then return false end
	stats.pos=snapshot.pos
	stats.state=snapshot.state
	return true
end

local function tomeAssignMotivation(skillGUID, playerIndex)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	local player=turnOrder[playerIndex]
	if stats==nil or player==nil or player.seatPos==nil then return false end
	stats.pos=player.seatPos
	stats.state="active"
	return true
end

local function tomeRemoveMotivationOwner(skillGUID)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	if stats==nil then return false end
	stats.pos=0
	return true
end

local function tomeRefreshMotivationUI(changed)
	if changed==true and refreshOutOfTurnActions~=nil then refreshOutOfTurnActions(nil, nil, true, false) end
end

local function tomeRestoreReplacement(pending, deactivateReplacement)
	if pending==nil or pending.replacementGUID==nil then return end
	local replacementGUID=pending.replacementGUID
	if pending.replacementPoolHome~=nil then gStates.mageSkills[replacementGUID]=skillPositionCopy(pending.replacementPoolHome) end
	local replacement=getObjectFromGUID(replacementGUID)
	if replacement~=nil and pending.replacementPoolHome~=nil then
		replacement.unlock()
		replacement.setPositionSmooth(pending.replacementPoolHome)
	end
	local motivationChanged=tomeRestoreMotivation(replacementGUID, pending.replacementMotivation)
	if deactivateReplacement==true then
		local record=coopCompSkillActivationTable()[replacementGUID]
		if record~=nil and record.tomeReplacement==true and gStates.doingTheRounds[replacementGUID]==nil then deactivateCoopCompSkill(replacementGUID, true) end
	end
	pending.replacementGUID=nil
	pending.replacementPoolHome=nil
	pending.replacementMotivation=nil
	tomeRefreshMotivationUI(motivationChanged)
end

local function tomeUndoSkillSwap(playerIndex)
	local swaps=tomeSkillSwapTable()
	local pending=swaps[playerIndex]
	if pending==nil then return false end
	tomeRestoreReplacement(pending, true)
	if pending.oldSkill~=nil and pending.ownerHome~=nil then
		gStates.mageSkills[pending.oldSkill]=skillPositionCopy(pending.ownerHome)
		local oldSkill=getObjectFromGUID(pending.oldSkill)
		if oldSkill~=nil then
			oldSkill.unlock()
			oldSkill.setPositionSmooth(pending.ownerHome)
		end
	end
	local motivationChanged=tomeRestoreMotivation(pending.oldSkill, pending.oldMotivation)
	swaps[playerIndex]=nil
	tomeRefreshMotivationUI(motivationChanged)
	return true
end

local function tomeAssignReplacement(skillGUID, playerIndex)
	local pending=tomeSkillSwapTable()[playerIndex]
	if pending==nil or skillGUID==pending.oldSkill then return false end
	if pending.replacementGUID==skillGUID then return true end
	local currentHome=gStates.mageSkills[skillGUID]
	if coopCompSkillPoolPosition(currentHome)~=true then return false end
	tomeRestoreReplacement(pending, true)
	pending.replacementGUID=skillGUID
	pending.replacementPoolHome=skillPositionCopy(currentHome)
	pending.replacementMotivation=tomeMotivationSnapshot(skillGUID)
	gStates.mageSkills[skillGUID]=skillPositionCopy(pending.ownerHome)
	tomeRefreshMotivationUI(tomeAssignMotivation(skillGUID, playerIndex))
	return true
end

function tomeSkillEnteredPlay(skillGUID, playerIndex)
	local pending=tomeSkillSwapTable()[playerIndex]
	if pending==nil then return end
	if skillGUID==pending.oldSkill then tomeUndoSkillSwap(playerIndex)
	else tomeAssignReplacement(skillGUID, playerIndex) end
end

--Run immediately on human drop, before the older resting/home-position update, so a quick physical
--swap cannot put the replacement into the Play Area before we remember which owned Skill was traded.
function tomeSkillDropped(skillGUID, position)
	if skillGUID==nil or skillTokens[skillGUID]==nil or position==nil then return end
	local swaps=tomeSkillSwapTable()

	--Returning a tentative replacement to the pool means the player changed their choice.
	if coopCompSkillPoolPosition(position)==true then
		for _, pending in pairs(swaps) do
			if pending.replacementGUID==skillGUID then
				tomeRestoreReplacement(pending, true)
				break
			end
		end
	end

	--Dropping the original Skill back into its owner's Skill column cancels the physical swap.
	local droppedOwner=coopCompSkillOwnedAreaPlayer(position)
	if droppedOwner~=nil then
		local pending=swaps[droppedOwner]
		if pending~=nil then
			if pending.oldSkill==skillGUID then tomeUndoSkillSwap(droppedOwner) return
			elseif tomeAssignReplacement(skillGUID, droppedOwner)==true then return end
		end
	end

	--An owned Skill entering the common offer begins/replaces the pending Tome transaction. A temporary
	--Circlet Skill already has a pool home, so it deliberately does not satisfy this test.
	if coopCompSkillPoolPosition(position)==true then
		local oldHome=gStates.mageSkills[skillGUID]
		local owner=coopCompSkillOwnedAreaPlayer(oldHome)
		if owner~=nil then
			local existing=swaps[owner]
			if existing~=nil and existing.oldSkill~=skillGUID then tomeUndoSkillSwap(owner) end
			swaps[owner]={player=owner, oldSkill=skillGUID, ownerHome=skillPositionCopy(oldHome), oldPoolHome=skillPositionCopy(position), oldMotivation=tomeMotivationSnapshot(skillGUID)}
			--Commit the traded Skill's new home immediately; the older resting callback will refine the exact Y/Z later.
			gStates.mageSkills[skillGUID]=skillPositionCopy(position)
			tomeRefreshMotivationUI(tomeRemoveMotivationOwner(skillGUID))
		end
	end
end

function activateCoopCompSkill(skillGUID, playerIndex)
	local details=skillTokens[skillGUID]
	if details==nil or (details.skillType~="Coop" and details.skillType~="Comp") then return end
	local active=coopCompSkillActivationTable()
	local record=active[skillGUID]
	if record==nil then
		local afterBoundary=coopCompSkillBoundaryActive~=nil and coopCompSkillBoundaryActive()==true
		record={player=playerIndex, round=gStates.currentRound, location="play"}
		local pending=tomeSkillSwapTable()[playerIndex]
		if pending~=nil and pending.replacementGUID==skillGUID then record.tomeReplacement=true end
		active[skillGUID]=record
		coopCompSkillBroadcast("{en}Skill Activated{ru}Навык активирован{zh-tw}技能已啟動{zh-cn}技能已激活{ko}스킬 활성화됨{es}Habilidad activada{fr}Compétence activée{pt-br}Habilidade ativada{de}Fertigkeit aktiviert", playerIndex)
		if afterBoundary==true then
			coopCompSkillBroadcast("{en}End of Round / Scenario End has already been called. Interactive Skill timing may be rules-sensitive. The script will continue; players decide whether this use is allowed.{ru}Конец раунда / конец сценария уже объявлен. Время использования интерактивного навыка может зависеть от трактовки правил. Скрипт продолжит обработку; игроки решают, разрешено ли это использование.{zh-tw}已宣布回合結束／劇本結束。互動技能的使用時機可能取決於規則解讀。腳本會繼續處理，由玩家決定此次使用是否允許。{zh-cn}已宣布回合结束／剧本结束。互动技能的使用时机可能取决于规则解读。脚本会继续处理，由玩家决定此次使用是否允许。{ko}라운드 종료 / 시나리오 종료가 이미 선언되었습니다. 상호작용 스킬의 사용 시점은 규칙 해석에 따라 달라질 수 있습니다. 스크립트는 계속 처리하며, 사용 가능 여부는 플레이어가 결정합니다.{es}Ya se ha declarado el Fin de Ronda / Fin del Escenario. El momento de uso de una Habilidad interactiva puede depender de la interpretación de las reglas. El script continuará; los jugadores deciden si este uso está permitido.{fr}La Fin de Manche / Fin du Scénario a déjà été annoncée. Le moment d'utilisation d'une Compétence interactive peut dépendre de l'interprétation des règles. Le script continuera ; les joueurs décident si cette utilisation est autorisée.{pt-br}O Fim da Rodada / Fim do Cenário já foi declarado. O momento de uso de uma Habilidade interativa pode depender da interpretação das regras. O script continuará; os jogadores decidem se este uso é permitido.{de}Rundenende / Szenarioende wurde bereits ausgerufen. Der Zeitpunkt für interaktive Fertigkeiten kann von der Regelauslegung abhängen. Das Skript fährt fort; die Spieler entscheiden, ob diese Nutzung erlaubt ist.", playerIndex)
		end
		refreshCoopCompSkillWarnings()
	else
		if record.player==nil then record.player=playerIndex end
		record.location="play"
		record.detached=nil
		record.leftPlayArea=nil
	end
end

function coopCompSkillLeftPlayArea(skillGUID, playerIndex)
	local record=coopCompSkillActivationTable()[skillGUID]
	if record==nil then return end
	record.leftPlayArea=true
	record.leftPlayer=playerIndex
	record.location="moving"
end

function coopCompSkillDropped(skillGUID, position)
	local record=coopCompSkillActivationTable()[skillGUID]
	if record==nil then return end
	if coopCompSkillPoolPosition(position)==true then
		--A tentative Tome replacement being put back is an undo, not a surviving activation.
		if record.tomeReplacement==true then return end
		if record.location~="pool" then coopCompSkillBroadcast("{en}Skill Still Activated{ru}Навык всё ещё активен{zh-tw}技能仍然啟動{zh-cn}技能仍然激活{ko}스킬이 아직 활성화되어 있습니다{es}La Habilidad sigue activada{fr}La Compétence est toujours activée{pt-br}A Habilidade continua ativada{de}Fertigkeit ist weiterhin aktiviert", record.player) end
		record.location="pool"
		record.detached=true
		record.leftPlayArea=nil
		return
	end
	if coopCompSkillOwnedAreaPlayer(position)~=nil then
		if gStates.doingTheRounds[skillGUID]~=nil and doingTheRounds~=nil then doingTheRounds(skillGUID, "", 0, true)
		else deactivateCoopCompSkill(skillGUID, true) end
	end
end

local function commitTomeSkillSwap(playerIndex)
	local swaps=tomeSkillSwapTable()
	local pending=swaps[playerIndex]
	if pending==nil then return end
	if pending.replacementGUID~=nil then
		local record=coopCompSkillActivationTable()[pending.replacementGUID]
		if record~=nil then record.tomeReplacement=nil end
	end
	swaps[playerIndex]=nil
end

local function unlockCommonSkillPoolTokens()
	for skillGUID, position in pairs(gStates.mageSkills or {}) do
		if coopCompSkillPoolPosition(position)==true then
			local skill=getObjectFromGUID(skillGUID)
			if skill~=nil then skill.unlock() end
		end
	end
end

--End of Round / Scenario End is an advisory timing boundary for Interactive skills.
--The script keeps automating the physical skill lifecycle and leaves ambiguous legality calls to the players.
function coopCompSkillBoundaryActive()
	return gStates.endRoundCalled==true or (gStates.endGameAchieved~=nil and gStates.endGameAchieved~="false")
end

function coopCompSkillPlayAreaPlayer(skillGUID)
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.seatPos~=nil then
			local playArea=getObjectFromGUID(playerPlayAreas[playerDetails.seatPos])
			if playArea~=nil then
				for _, obj in pairs(playArea.getObjects()) do if obj.guid==skillGUID then return playerIndex end end
			end
		end
	end
	return nil
end

function coopCompSkillWarningClick() end
local function clearCoopCompSkillWarning(skill)
	local remove={}
	for _, button in pairs(skill.getButtons() or {}) do
		if button.click_function=="coopCompSkillWarningClick" or button.click_function=="coopCompSkillXClick" then remove[#remove+1]=button.index end
	end
	table.sort(remove, function(a,b) return a>b end)
	for _, index in ipairs(remove) do skill.removeButton(index) end
end

function refreshCoopCompSkillWarnings()
	local boundaryActive=coopCompSkillBoundaryActive()
	for skillGUID, details in pairs(skillTokens) do
		if details.skillType=="Coop" or details.skillType=="Comp" then
			local skill=getObjectFromGUID(skillGUID)
			if skill~=nil then
				clearCoopCompSkillWarning(skill)
				local inRotation=gStates.doingTheRounds[skillGUID]~=nil
				if boundaryActive==true and inRotation==false then
					skill.createButton({click_function="coopCompSkillWarningClick", function_owner=Global, label="!", position={0,0.25,0}, rotation={0,0,0}, width=0, height=0, font_size=800, font_color={1,0.65,0.1}, tooltip="End of Round / Scenario End has been called. Interactive Skill timing may be restricted; the script will not prevent this play."})
				end
			end
		end
	end
end

--Competitive skill clones are reminders only and are never registered as skills. Source Freeze and Mana Suppression stay played for their owner reward.
sharedSkillAboveZone={	["725de9"]="40ef14",--Krang's Coop Skill
							["818aea"]="8fc095",--Tovak's Coop Skill
							["c4546c"]="d28865",--Tovak's Comp Skill
							[GUID.skill.manaSuppression]="22b866"}--Krang's Comp Skill
local competitiveOwnerReward={ ["3bd08e"]=true, [GUID.skill.manaSuppression]=true }

local function lockCompetitiveSkillCloneWhenSettled(clone)
	if clone==nil then return end
	local cloneGUID=clone.guid
	clone.unlock()
	safeWaitFrames("PlayerBoard.Skills",function() safeWaitCondition("PlayerBoard.Skills",function()
		local obj=getObjectFromGUID(cloneGUID)
		if obj~=nil then obj.lock() end
	end, function()
		local obj=getObjectFromGUID(cloneGUID)
		return obj==nil or obj.resting
	end) end, 5)
end

local function competitiveSkillPlayerForSeat(seatPos)
	for playerIndex, details in pairs(turnOrder) do
		if details.seatPos==seatPos and details.seatPos<5 and details.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false then return playerIndex end
	end
	return nil
end

local function competitiveSkillReminderCount(seatPos)
	local count=0
	for _, record in pairs(gStates.competitiveSkillReminders or {}) do
		for reminderGUID, reminderSeat in pairs(record.reminders or {}) do
			if reminderSeat==seatPos and getObjectFromGUID(reminderGUID)~=nil then count=count+1 end
		end
	end
	return count
end

local basicManaToken={ ["Red Mana"]=true, ["Blue Mana"]=true, ["Green Mana"]=true, ["White Mana"]=true }

local function competitiveSkillReminderForSeat(record, seatPos)
	for reminderGUID, reminderSeat in pairs(record.reminders or {}) do
		if reminderSeat==seatPos then
			local reminder=getObjectFromGUID(reminderGUID)
			if reminder~=nil then return reminder end
		end
	end
	return nil
end

local function nextCompetitiveSkillReminder(record, fromSeat, nextPlayer)
	if nextPlayer~=nil and turnOrder[nextPlayer]~=nil and turnOrder[nextPlayer].seatPos~=fromSeat then
		local reminder=competitiveSkillReminderForSeat(record, turnOrder[nextPlayer].seatPos)
		if reminder~=nil then return reminder end
	end
	local currentPlayer=gStates.turnNumber
	for playerIndex, details in pairs(turnOrder) do if details.seatPos==fromSeat then currentPlayer=playerIndex break end end
	local best=nil
	local bestDistance=nil
	for reminderGUID, seatPos in pairs(record.reminders or {}) do
		local reminder=getObjectFromGUID(reminderGUID)
		local playerIndex=seatPos~=fromSeat and competitiveSkillPlayerForSeat(seatPos) or nil
		if reminder~=nil and playerIndex~=nil then
			local distance=playerIndex-currentPlayer
			if distance<=0 then distance=distance+#turnOrder end
			if bestDistance==nil or distance<bestDistance then best=reminder bestDistance=distance end
		end
	end
	return best or getObjectFromGUID(GUID.skill.manaSuppression)
end

local function manaSuppressionTokensAtReminder(record, seatPos)
	local tokens={}
	local reminder=record~=nil and competitiveSkillReminderForSeat(record, seatPos) or nil
	local playArea=playerPlayAreas[seatPos]~=nil and getObjectFromGUID(playerPlayAreas[seatPos]) or nil
	if reminder==nil or playArea==nil then return tokens, reminder end
	local reminderPos=reminder.getPosition()
	for _, token in pairs(playArea.getObjects()) do
		if basicManaToken[token.getName()]==true then
			local tokenPos=token.getPosition()
			if math.abs(tokenPos[1]-reminderPos[1])<=1 and math.abs(tokenPos[3]-reminderPos[3])<=0.65 then tokens[#tokens+1]=token end
		end
	end
	return tokens, reminder
end

local function passManaSuppressionTokens(record, fromSeat, nextPlayer)
	local moved={}
	local tokens, reminder=manaSuppressionTokensAtReminder(record, fromSeat)
	local destination=record~=nil and nextCompetitiveSkillReminder(record, fromSeat, nextPlayer) or nil
	if reminder==nil or destination==nil or destination.guid==reminder.guid then return moved end
	local destinationPos=destination.getPosition()
	local spacing=0.45
	local start=-((#tokens-1)*spacing)/2
	for index, token in ipairs(tokens) do
		token.unlock()
		token.setPositionSmooth({destinationPos[1]+start+((index-1)*spacing), 2+(index*0.25), destinationPos[3]})
		moved[token.guid]=true
	end
	return moved
end

local function clearCompetitiveSkillSeat(skillGUID, seatPos, nextPlayer)
	local record=gStates.competitiveSkillReminders~=nil and gStates.competitiveSkillReminders[skillGUID] or nil
	if record==nil then return {} end
	local moved=skillGUID==GUID.skill.manaSuppression and passManaSuppressionTokens(record, seatPos, nextPlayer) or {}
	for reminderGUID, reminderSeat in pairs(record.reminders or {}) do
		if reminderSeat==seatPos then
			local reminder=getObjectFromGUID(reminderGUID)
			if reminder~=nil then reminder.destruct() end
			record.reminders[reminderGUID]=nil
		end
	end
	for markerGUID, details in pairs(record.markers or {}) do
		if details.seat==seatPos then
			local marker=getObjectFromGUID(markerGUID)
			if marker~=nil then marker.destruct() end
			record.markers[markerGUID]=nil
		end
	end
	return moved
end

function clearCompetitiveSkillReminders(skillGUID)
	if gStates.competitiveSkillReminders==nil then return end
	local record=gStates.competitiveSkillReminders[skillGUID]
	if record==nil then return end
	if skillGUID==GUID.skill.manaSuppression then
		local clearedSeats={}
		for _, seatPos in pairs(record.reminders or {}) do
			if clearedSeats[seatPos]~=true then
				local tokens=manaSuppressionTokensAtReminder(record, seatPos)
				for _, token in pairs(tokens) do getObjectFromGUID(trashCan).putObject(token) end
				clearedSeats[seatPos]=true
			end
		end
	end
	for reminderGUID, _ in pairs(record.reminders or {}) do
		local reminder=getObjectFromGUID(reminderGUID)
		if reminder~=nil then reminder.destruct() end
	end
	for markerGUID, _ in pairs(record.markers or {}) do
		local marker=getObjectFromGUID(markerGUID)
		if marker~=nil then marker.destruct() end
	end
	gStates.competitiveSkillReminders[skillGUID]=nil
end

local function refreshCompetitiveSkillReminderMarkers(skillGUID)
	local record=gStates.competitiveSkillReminders~=nil and gStates.competitiveSkillReminders[skillGUID] or nil
	local zoneGUID=sharedSkillAboveZone[skillGUID]
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if record==nil then return end
	local seatsToClear={}
	for reminderGUID, seatPos in pairs(record.reminders or {}) do
		if getObjectFromGUID(reminderGUID)==nil or competitiveSkillPlayerForSeat(seatPos)==nil then seatsToClear[seatPos]=true end
	end
	for seatPos, _ in pairs(seatsToClear) do clearCompetitiveSkillSeat(skillGUID, seatPos) end
	if zone==nil then return end
	local originals={}
	for _, marker in pairs(zone.getObjects()) do if marker.type=="Figurine" then originals[marker.guid]=marker end end
	for cloneGUID, details in pairs(record.markers or {}) do
		local clone=getObjectFromGUID(cloneGUID)
		local reminderExists=false
		for reminderGUID, seatPos in pairs(record.reminders or {}) do
			if seatPos==details.seat and getObjectFromGUID(reminderGUID)~=nil then reminderExists=true break end
		end
		if clone==nil then record.markers[cloneGUID]=nil
		elseif reminderExists==false or (competitiveOwnerReward[skillGUID]==true and originals[details.source]==nil) then clone.destruct() record.markers[cloneGUID]=nil end
	end
	local zonePos=zone.getPosition()
	for reminderGUID, seatPos in pairs(record.reminders or {}) do
		local reminder=getObjectFromGUID(reminderGUID)
		if reminder~=nil then
			local reminderPos=reminder.getPosition()
			for sourceGUID, marker in pairs(originals) do
				local found=false
				for cloneGUID, details in pairs(record.markers or {}) do
					if details.source==sourceGUID and details.seat==seatPos and getObjectFromGUID(cloneGUID)~=nil then found=true break end
				end
				if found==false then
					local markerPos=marker.getPosition()
					local clone=marker.clone({position={reminderPos[1]+zonePos[1]-markerPos[1], 2, reminderPos[3]+zonePos[3]-markerPos[3]}, rotation=marker.getRotation()})
					clone.setGMNotes("Competitive Skill Marker:"..skillGUID..":"..sourceGUID..":"..seatPos)
					clone.interactable=false
					lockCompetitiveSkillCloneWhenSettled(clone)
					record.markers[clone.guid]={source=sourceGUID, seat=seatPos}
				end
			end
		end
	end
end

function createCompetitiveSkillReminders(skillGUID, owner)
	if skillTokens[skillGUID]==nil or skillTokens[skillGUID].skillType~="Comp" then return end
	local skill=getObjectFromGUID(skillGUID)
	if skill==nil then return end
	if gStates.competitiveSkillReminders==nil then gStates.competitiveSkillReminders={} end
	local record=gStates.competitiveSkillReminders[skillGUID]
	if record==nil then record={owner=owner, reminders={}, markers={}} gStates.competitiveSkillReminders[skillGUID]=record end
	record.owner=owner record.reminders=record.reminders or {} record.markers=record.markers or {}
	local physicalPlayer=coopCompSkillPlayAreaPlayer(skillGUID)
	if physicalPlayer~=nil and physicalPlayer~=owner and turnOrder[owner]~=nil then
		local target={turnOrder[owner].seatPos*40-109.5, 1.5, -39.41}
		local zoneGUID=sharedSkillAboveZone[skillGUID]
		local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
		if zone~=nil then
			local zonePos=zone.getPosition()
			for _, marker in pairs(zone.getObjects()) do
				if marker.type=="Figurine" then marker.setPositionSmooth({target[1]+zonePos[1]-marker.getPosition()[1], 2, target[3]+zonePos[3]-marker.getPosition()[3]}) end
			end
			zone.setPosition({target[1], 1.4, target[3]})
		end
		skill.setPositionSmooth(target)
	end
	local targetSeats={}
	for playerIndex, details in pairs(turnOrder) do
		if details.seatPos~=nil and details.seatPos<5 and details.mage~=gStates.positionMageKnight[5] and playerIndex~=owner and playerDropoutInactive(playerIndex)==false then targetSeats[details.seatPos]=true end
	end
	for reminderGUID, seatPos in pairs(record.reminders) do
		if targetSeats[seatPos]~=true or getObjectFromGUID(reminderGUID)==nil then clearCompetitiveSkillSeat(skillGUID, seatPos) end
	end
	for seatPos, _ in pairs(targetSeats) do
		local found=false
		for reminderGUID, reminderSeat in pairs(record.reminders) do if reminderSeat==seatPos and getObjectFromGUID(reminderGUID)~=nil then found=true break end end
		if found==false then
			local count=competitiveSkillReminderCount(seatPos)
			local reminder=skill.clone({position={seatPos*40-105, 1.5, -39.41-(1.48*count)}, rotation={0,180,0}})
			reminder.setGMNotes("Competitive Skill Reminder:"..skillGUID..":"..seatPos)
			reminder.clearButtons()
			reminder.UI.setXml("")
			lockCompetitiveSkillCloneWhenSettled(reminder)
			record.reminders[reminder.guid]=seatPos
		end
	end
	refreshCompetitiveSkillReminderMarkers(skillGUID)
	if competitiveOwnerReward[skillGUID]~=true and gStates.mageSkills[skillGUID]~=nil then
		skill.setPositionSmooth({gStates.mageSkills[skillGUID][1], 1.5, gStates.mageSkills[skillGUID][3]})
		skill.setRotationSmooth({0,180,180})
	end
end

local function finishCompetitiveSkill(skillGUID, reset)
	clearCompetitiveSkillReminders(skillGUID)
	local skill=getObjectFromGUID(skillGUID)
	if skill~=nil and gStates.mageSkills[skillGUID]~=nil then
		skill.setPositionSmooth({gStates.mageSkills[skillGUID][1], 1.5, gStates.mageSkills[skillGUID][3]})
		if reset~=true then skill.setRotationSmooth({0,180,180}) end
	end
	gStates.doingTheRounds[skillGUID]=nil
	gStates.soloCoop[skillGUID]=nil
	if gStates.doingTheRoundsVisited~=nil then gStates.doingTheRoundsVisited[skillGUID]=nil end
	deactivateCoopCompSkill(skillGUID, true)
	local zoneGUID=sharedSkillAboveZone[skillGUID]
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if zone~=nil then for _, marker in pairs(zone.getObjects()) do if marker.type=="Figurine" then getObjectFromGUID(trashCan).putObject(marker) end end end
end

--Move cooperative skills to the next player. Competitive reminders are removed as each affected player's turn finishes.
function doingTheRounds(skillGUID, nextPlayer, count, reset)
	local keepSafe={}
	local skillDetails=skillTokens[skillGUID]
	if skillDetails~=nil and skillDetails.skillType=="Comp" then
		local owner=gStates.doingTheRounds[skillGUID]
		if reset==true then finishCompetitiveSkill(skillGUID, true) return {keepSafe, count} end
		if owner==nil then return {keepSafe, count} end
		if gStates.competitiveSkillReminders==nil or gStates.competitiveSkillReminders[skillGUID]==nil then createCompetitiveSkillReminders(skillGUID, owner) end
		local ownerRewardPending=gStates.soloCoop[skillGUID]==true
		local extraTurnStarted=(gStates.tacticSixState=="Started" or gStates.timeBending=="Started") and gStates.turnNumber==gStates.realTurn
		local currentSeat=turnOrder[gStates.turnNumber]~=nil and turnOrder[gStates.turnNumber].seatPos or nil
		if currentSeat~=nil and extraTurnStarted==false then
			local moved=clearCompetitiveSkillSeat(skillGUID, currentSeat, nextPlayer)
			for tokenGUID, _ in pairs(moved) do keepSafe[tokenGUID]=true end
		end
		refreshCompetitiveSkillReminderMarkers(skillGUID)
		local record=gStates.competitiveSkillReminders~=nil and gStates.competitiveSkillReminders[skillGUID] or nil
		local remindersLeft=0
		if record~=nil then for reminderGUID, _ in pairs(record.reminders or {}) do if getObjectFromGUID(reminderGUID)~=nil then remindersLeft=remindersLeft+1 end end end
		if ownerRewardPending==true and gStates.turnNumber==owner and extraTurnStarted==false then finishCompetitiveSkill(skillGUID, false) return {keepSafe, count}
		elseif ownerRewardPending==false and remindersLeft==0 then
			if gStates.playerCount<=1 or competitiveOwnerReward[skillGUID]==true then gStates.soloCoop[skillGUID]=true
			else finishCompetitiveSkill(skillGUID, false) return {keepSafe, count} end
		end
		local zoneGUID=sharedSkillAboveZone[skillGUID]
		local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
		if zone~=nil and competitiveOwnerReward[skillGUID]==true then for _, marker in pairs(zone.getObjects()) do if marker.type=="Figurine" then keepSafe[marker.guid]=true end end end
		if record~=nil and currentSeat~=nil then
			for markerGUID, details in pairs(record.markers or {}) do if details.seat==currentSeat and getObjectFromGUID(markerGUID)~=nil then keepSafe[markerGUID]=true end end
		end
		return {keepSafe, count}
	end

	if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
	local roundSkill=skillDetails~=nil and skillDetails.skillType=="Coop"
	local roundVisitedLoop=false
	if roundSkill and reset~=true then
		if gStates.doingTheRoundsVisited[skillGUID]==nil then
			gStates.doingTheRoundsVisited[skillGUID]={}
			if gStates.doingTheRounds[skillGUID]~=nil then gStates.doingTheRoundsVisited[skillGUID][gStates.doingTheRounds[skillGUID]]=true end
		end
		--Out-of-order turns such as co-op assaults can skip the original return marker. Reaching any player
		--already visited means a Coop skill has completed one circuit. Same-player extra turns do not count.
		roundVisitedLoop=nextPlayer~=gStates.turnNumber and gStates.doingTheRoundsVisited[skillGUID][nextPlayer]==true
	end
	if gStates.doingTheRounds[skillGUID]==nextPlayer or roundVisitedLoop==true or gStates.soloCoop[skillGUID]==true or reset==true then
		if gStates.playerCount>1 or gStates.soloCoop[skillGUID]==true or reset==true then
			--Return the completed skill when its physical token/home still exists. A stale rotation record must
			--never abort the whole round reset; clear the logical circulation state either way.
			local skill=getObjectFromGUID(skillGUID)
			local skillHome=gStates.mageSkills~=nil and gStates.mageSkills[skillGUID] or nil
			if skill~=nil and skillHome~=nil and skillHome[1]~=nil and skillHome[3]~=nil then
				skill.setPositionSmooth({skillHome[1], 1.5, skillHome[3]},false,false)
				if reset~=true then skill.setRotationSmooth({0.0, 180.0, 180.0},false,false) end
			end
			gStates.doingTheRounds[skillGUID]=nil
			gStates.soloCoop[skillGUID]=nil
			if gStates.doingTheRoundsVisited~=nil then gStates.doingTheRoundsVisited[skillGUID]=nil end
			deactivateCoopCompSkill(skillGUID, true)
			local zoneGUID=sharedSkillAboveZone[skillGUID]
			local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
			local trash=getObjectFromGUID(trashCan)
			if zone~=nil and trash~=nil then
				for _, b in pairs(zone.getObjects()) do if b.type=="Figurine" then trash.putObject(b) end end
			end
		else
			--place next to owner skill for solo cooperative play
			if sharedSkillAboveZone[skillGUID]~=nil then
				for _, b in pairs(getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getObjects()) do
					if b.type=="Figurine" then
						local offsetX=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[1]-b.getPosition()[1]
						local offsetZ=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[3]-b.getPosition()[3]
						b.setPositionSmooth({turnOrder[nextPlayer].seatPos*40-109.5+offsetX , 2.0, -39.41+offsetZ})
						keepSafe[b.guid]=true
					end
				end
			end
			getObjectFromGUID(skillGUID).setPositionSmooth({turnOrder[nextPlayer].seatPos*40-109.5 , 1.5, -39.41})
			gStates.soloCoop[skillGUID]=true
		end
	else
		--move cooperative token to next player board
		local position={109.5, 1.48}
		if sharedSkillAboveZone[skillGUID]~=nil then
			for _, b in pairs(getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getObjects()) do
				if b.type=="Figurine" then
					local offsetX=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[1]-b.getPosition()[1]
					local offsetZ=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[3]-b.getPosition()[3]
					b.setPositionSmooth({turnOrder[nextPlayer].seatPos*40-position[1]+offsetX , 2.0, -39.41+(position[2]*count)+offsetZ})
					keepSafe[b.guid]=true
				end
			end
		end
		getObjectFromGUID(skillGUID).setPositionSmooth({turnOrder[nextPlayer].seatPos*40-position[1] , 1.5, -39.41+(position[2]*count)})
		if roundSkill then
			if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
			if gStates.doingTheRoundsVisited[skillGUID]==nil then gStates.doingTheRoundsVisited[skillGUID]={} end
			gStates.doingTheRoundsVisited[skillGUID][nextPlayer]=true
		end
		count=count+1
	end
	return {keepSafe, count}
end

--End-turn cleanup for a Skill played in the main Play Area. Combat owns the timing boundary;
--Skills owns state replacement, rotation, return-home and Coop/Comp circulation rules.
function cleanupPlayedSkillAtEndTurn(playAreaObj, cleanupPlayer)
	if playAreaObj==nil then return false end
	local originalSkillGUID=playAreaObj.guid
	local cleanupSkillGUID=(skillStateReplacement~=nil and skillStateReplacement[originalSkillGUID]) or originalSkillGUID
	local cleanupSkillDetails=skillTokens[cleanupSkillGUID] or skillTokens[originalSkillGUID]
	if cleanupSkillDetails==nil then return false end
	local cleanupSkill=getObjectFromGUID(cleanupSkillGUID)
	local cleanupSkillHome=gStates.mageSkills~=nil and gStates.mageSkills[cleanupSkillGUID] or nil

	if cleanupSkill~=nil and cleanupSkillDetails.skillType=="Round" then
		cleanupSkill.setRotationSmooth({0.0,180.0,180.0},false,false)
	end
	if cleanupSkill~=nil and cleanupSkillHome~=nil and (cleanupSkillDetails.skillType=="Round" or cleanupSkillDetails.skillType=="Turn") then
		cleanupSkill.setPositionSmooth({cleanupSkillHome[1],1.5,cleanupSkillHome[3]},false,false)
	end
	if cleanupSkillHome~=nil and gStates.motivationSkill[cleanupSkillGUID]~=nil then gStates.motivationSkill[cleanupSkillGUID].state="used" end

	if cleanupSkillGUID==GUID.skill.masterOfChaos and cleanupSkill~=nil then
		gStates.masterOfChaos=gStates.masterOfChaos+1
		if gStates.masterOfChaos==7 then gStates.masterOfChaos=1 end
		cleanupSkill.setDescription(masterOfChaosData[gStates.masterOfChaos].description)
		if turnOrder[cleanupPlayer]~=nil then turnOrder[cleanupPlayer].masterOfChaos="incremented in turn" end
	end

	if cleanupSkillDetails.skillType=="Coop" or cleanupSkillDetails.skillType=="Comp" then
		if gStates.doingTheRounds[cleanupSkillGUID]==nil then
			gStates.doingTheRounds[cleanupSkillGUID]=cleanupPlayer
			if cleanupSkillDetails.skillType=="Comp" then createCompetitiveSkillReminders(cleanupSkillGUID,cleanupPlayer)
			else
				if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
				gStates.doingTheRoundsVisited[cleanupSkillGUID]={[cleanupPlayer]=true}
			end
		elseif cleanupSkillDetails.skillType=="Coop" then
			gStates.doingTheRounds[cleanupSkillGUID]=nextTurnMerged("nextMageSkipDummy")
		end
	end
	return true
end

--Refresh all played Skills at the end-turn circulation boundary and return the reminder GUIDs
--that must survive generic Play Area figurine cleanup.
function prepareEndTurnSkillRotation(cleanupPlayer, nextPlayer)
	local count=0
	local keepSafe={}
	for skillGUID, zoneGUID in pairs(sharedSkillAboveZone) do
		local skill=getObjectFromGUID(skillGUID)
		local zone=getObjectFromGUID(zoneGUID)
		if skill~=nil and zone~=nil then
			local pos=skill.getPosition()
			zone.setPosition({pos[1],1.4,pos[3]})
		end
	end
	registerDetachedCoopCompSkills(cleanupPlayer)
	for skillGUID, skillDetails in pairs(skillTokens) do
		local skill=getObjectFromGUID(skillGUID)
		if skill~=nil then
			if skillDetails.skillType=="Turn" and skill.is_face_down==true then skill.flip() end
			if gStates.doingTheRounds[skillGUID]~=nil then
				local data=doingTheRounds(skillGUID,nextPlayer,count)
				count=data[2]
				for saveObjGuid, _ in pairs(data[1]) do keepSafe[saveObjGuid]=true end
			end
		end
	end
	refreshCoopCompSkillWarnings()
	return keepSafe
end

--A Skill used as a Unit reminder follows the same circulation rules as one in the Play Area.
function cleanupUnitAreaSkillAtEndTurn(unitAreaObj, cleanupPlayer)
	if unitAreaObj==nil then return false end
	local details=skillTokens[unitAreaObj.guid]
	if details==nil then return false end
	if details.skillType=="Coop" or details.skillType=="Comp" then
		if gStates.doingTheRounds[unitAreaObj.guid]==nil then
			gStates.doingTheRounds[unitAreaObj.guid]=cleanupPlayer
			if details.skillType=="Comp" then createCompetitiveSkillReminders(unitAreaObj.guid,cleanupPlayer)
			else
				if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
				gStates.doingTheRoundsVisited[unitAreaObj.guid]={[cleanupPlayer]=true}
			end
		elseif details.skillType=="Coop" then
			gStates.doingTheRounds[unitAreaObj.guid]=nextTurnMerged("nextMageSkipDummy")
		end
	end
	if unitAreaObj.guid~=GUID.skill.bondsOfLoyalty and gStates.mageSkills[unitAreaObj.guid]~=nil and gStates.doingTheRounds[unitAreaObj.guid]==nil then
		local skillHome=gStates.mageSkills[unitAreaObj.guid]
		if skillHome[1]~=nil and skillHome[2]~=nil and skillHome[3]~=nil then
			unitAreaObj.setPositionSmooth({skillHome[1],skillHome[2],skillHome[3]},false,false)
			unitAreaObj.setRotationSmooth({0,180,0},false,false)
		end
	end
	return true
end

--Recover a played Interactive skill that Tome moved to the common offer before the normal play-area scan.
--Competitive effects can continue from their remembered activation. Cooperative secondary effects require
--the real token, and Source Freeze explicitly works only while its real token remains in the Source.
function registerDetachedCoopCompSkills(playerIndex)
	local toDeactivate={}
	for skillGUID, record in pairs(coopCompSkillActivationTable()) do
		local details=skillTokens[skillGUID]
		if record.player==playerIndex and record.round==gStates.currentRound and record.location=="pool" and details~=nil and gStates.doingTheRounds[skillGUID]==nil then
			if details.skillType=="Comp" and skillGUID~="3bd08e" then
				gStates.doingTheRounds[skillGUID]=playerIndex
				createCompetitiveSkillReminders(skillGUID, playerIndex)
				record.rotationStarted=true
			else
				toDeactivate[#toDeactivate+1]=skillGUID
			end
		end
	end
	for _, skillGUID in ipairs(toDeactivate) do deactivateCoopCompSkill(skillGUID, true) end
	commitTomeSkillSwap(playerIndex)
end

--drop a shield

function heroChallengeClaimReservedSkill(playerIndex,higherLevel)
	if gStates.heroChallenges~=true or turnOrder[playerIndex]==nil then return false end
	local playerData=turnOrder[playerIndex]
	local challenge=heroChallengesData[playerData.mage]
	if challenge==nil then return false end
	--The prescribed GUID is the source of truth. Reservations are keyed by Mage Knight because turnOrder
	--changes order during the game; an array-index reservation can otherwise point at another Hero's Skill.
	local reserved=(gStates.heroChallengeReservedSkills or {})[playerData.mage]
	local guid=reserved==challenge.skillGUID and reserved or challenge.skillGUID
	local skillDetails=skillTokens[guid]
	if skillDetails==nil or skillDetails.mage~=playerData.mage then
		print("HERO CHALLENGE SKILL ERROR: "..tostring(challenge.skillName).." does not belong to "..tostring(playerData.mage)..".")
		return false
	end
	local skill=getObjectFromGUID(guid)
	if skill==nil then print("HERO CHALLENGE SKILL ERROR: "..tostring(challenge.skillName).." could not be found.") return false end
	local count=0
	local skillX=(playerData.seatPos*40)-107.45
	for _,skillPos in pairs(gStates.mageSkills or {}) do if skillPos[3]<-36.9 and math.abs(skillPos[1]-skillX)<1 then count=count+1 end end
	local target={skillX,1.1,-38.67-(1.48*count)}
	if guid==GUID.skill.bondsOfLoyalty then
		local bondsX=unitLayoutNextCommandX(playerData.seatPos)
		target={bondsX,1.1,-31.19}
		scheduleUnitLayoutRefresh(playerData.seatPos)
		if higherLevel==true then
			local unitDeck=getObjectFromGUID(GUID.zone.regularUnit).getObjects()[1]
			for _=1,2 do
				standardDeckCycleShuffleIfReached("Regular Unit",unitDeck)
				unitDeck=getObjectFromGUID(GUID.zone.regularUnit).getObjects()[1]
				unitDeck.takeObject({position={(playerData.seatPos*40)-101,3.0,-48.4},smooth=true,rotation={0,180,0}})
			end
			gStates.bondsOfLoyalty[playerIndex]=5
			UI.setAttribute("Mage"..playerData.seatPos.."influenceTotalText","Text",joinLang({"{en}Influence to Spend : {ru}Доступно влияния: {zh-tw}可花費影響力：{zh-cn}影响力额度：{ko}주어진 영향력: {es}Influencia para Gastar : {fr}Influence à Dépenser : {pt-br}Influência para Gastar : {de}Einfluss zum Ausgeben : ",(playerData.influence*playerData.level)+gStates.bondsOfLoyalty[playerIndex]}))
		else
			addRegularUnitsToOffer(2)
		end
	end
	gStates.mageSkills[guid]=target
	skill.unlock()
	skill.setPositionSmooth(target)
	skill.UI.setXmlTable({{}})
	if gStates.motivationSkill[guid]~=nil then gStates.motivationSkill[guid].state="active" gStates.motivationSkill[guid].pos=playerData.seatPos end
	broadcastToAll(joinLang({translateWord[playerData.mage] or playerData.mage, "{en} gained {ru} получил навык {zh-tw}獲得了{zh-cn}获得了{ko}이(가) {es} obtuvo {fr} a obtenu {pt-br} obteve {de} erhielt ", translateWord[challenge.skillName] or challenge.skillName, "{en} from Hero Challenges.{ru} благодаря Испытаниям героев.{zh-tw}（英雄挑戰）。{zh-cn}（英雄挑战）。{ko} 스킬을 영웅 도전으로 획득했습니다.{es} de Desafíos de Héroe.{fr} grâce aux Défis de Héros.{pt-br} dos Desafios de Herói.{de} aus den Heldenherausforderungen."}),positionToColor(playerIndex))
	return true
end

--perform Level Up
function processPlayerLevelUps(playerTurnSequence)
	if turnOrder[playerTurnSequence].levelUp>0 then
		--The prescribed level-2 Hero Challenge Skill is automatic, so it does not need the normal
		--end-turn "Gained a New Skill Token" reminder. Reset this for every live level-up sequence;
		--a later normal Skill level in the same sequence turns the reminder back on.
		turnOrder[playerTurnSequence].skipHeroChallengeSkillReminder=false
		local multiSkill=false
		local loops=turnOrder[playerTurnSequence].levelUp
		for a=1, loops, 1 do
			if ((turnOrder[playerTurnSequence].level)+1)%2==0 then --Skill and Advanced Action Level Up
				local nextLevel=turnOrder[playerTurnSequence].level+1
				if gStates.heroChallenges==true and nextLevel==2 and heroChallengesData[turnOrder[playerTurnSequence].mage]~=nil then
					if heroChallengeClaimReservedSkill(playerTurnSequence,false)==true then
						turnOrder[playerTurnSequence].skipHeroChallengeSkillReminder=true
					end
					broadcastToAll(joinLang({translateWord[turnOrder[playerTurnSequence].mage] or turnOrder[playerTurnSequence].mage, "{en} may gain any one Advanced Action card.{ru} может получить любую одну карту Особого действия.{zh-tw}可以獲得任意一張高級行動卡。{zh-cn}可以获得任意一张高级行动卡。{ko}은(는) 원하는 고급 액션 카드 한 장을 얻을 수 있습니다.{es} puede obtener cualquier carta de Acción Avanzada.{fr} peut gagner n'importe quelle carte d'Action Avancée.{pt-br} pode ganhar qualquer carta de Ação Avançada.{de} darf eine beliebige Erweiterte Aktionskarte erhalten."}),positionToColor(playerTurnSequence))
				elseif multiSkill==false then
					--This is a normal Skill choice, so keep the standard reminder even if level 2 was also
					--crossed earlier in an unusual multi-level jump.
					turnOrder[playerTurnSequence].skipHeroChallengeSkillReminder=false
					--draw two skills to communal
					local exist=0
					local drawnSkillGUIDs={}
					for skillGUID, skillPos in pairs(gStates.mageSkills) do
						if math.floor(skillPos[1])==math.floor((turnOrder[playerTurnSequence].seatPos*3.7)+7.3) then exist=exist+1 end
					end
					for b=0, 1, 1 do
						local pos={(turnOrder[playerTurnSequence].seatPos*3.7)+7.3, 2.00, -23.95+(b*1.35)+(exist*1.35)}
						local skillDrawn=nil
						local usedFallback=false
						if getObjectFromGUID(turnOrder[playerTurnSequence].skillBagGUID).getQuantity()>=1 then
							skillDrawn=getObjectFromGUID(turnOrder[playerTurnSequence].skillBagGUID).takeObject({position=pos, smooth=true, rotation={0, 180, 0}})
						else
							skillDrawn=getObjectFromGUID("70c31f").clone({position=pos, rotation={0, 180, 0}})
							usedFallback=true
						end
						if skillDrawn~=nil then
							gStates.mageSkills[skillDrawn.guid]=pos
							drawnSkillGUIDs[#drawnSkillGUIDs+1]=skillDrawn.guid
						end
						if usedFallback==true then break end
					end
					--activate claim buttons only after every newly dealt Skill has actually settled.
					gStates.skillButtons=turnOrder[playerTurnSequence].seatPos
					safeWaitCondition("PlayerBoard.Skills",function()
						for _, guid in ipairs(drawnSkillGUIDs) do local skill=getObjectFromGUID(guid) if skill~=nil then skill.unlock() end end
						skillButtonActivate()
					end, function()
						if #drawnSkillGUIDs==0 then return true end
						for _, guid in ipairs(drawnSkillGUIDs) do local skill=getObjectFromGUID(guid) if skill==nil or skill.resting~=true then return false end end
						return true
					end, 10, function() skillButtonActivate() end)
					--Highlight reminder starts from the same synchronized skillButtonActivate refresh.
					--Look at skill Area
					broadcastToAll(joinLang({translateWord[turnOrder[playerTurnSequence].mage], "{en} needs to gain a new Skill and Advanced Action card.{ru} должен получить новый Навык и карту Особых действий.{zh-tw}需要獲得一個新技能和一張高級行動卡。{zh-cn}需要获得新技能和高级行动卡{ko}: 스킬과 상급 액션을 선택하세요.{es} necesita obtener una nueva tarjeta de Habilidad y Acción Avanzada.{fr} doit gagner une nouvelle carte de compétence et d'action avancée.{pt-br} precisa ganhar uma nova Carta de ação e Habilidade.{de} muss eine neue Fertigkeit und eine erweiterte Aktionskarte erhalten."}), positionToColor(playerTurnSequence))
					multiSkill=true
				else
					break
				end
			else --odd number levels
				--Command Token Deploy. Bonus Command sources can already occupy the printed row, so use the shared elastic layout.
				local commandSeat=turnOrder[playerTurnSequence].seatPos
				local xPlayLocation=unitLayoutNextCommandX(commandSeat)
				getObjectFromGUID(turnOrder[playerTurnSequence].commandGUID).takeObject({position={xPlayLocation,2.00,-31.2}, rotation={0,180,180}})
				scheduleUnitLayoutRefresh(commandSeat)
				broadcastToAll(joinLang({translateWord[turnOrder[playerTurnSequence].mage], "{en} gained a new Command token.{ru} получает новый Жетон командования.{zh-tw}獲得一個新的指揮標記。{zh-cn}增加一个新的部队控制标记{ko}: 새 지휘 토큰 획득{es} ganó una nueva ficha de Comando.{fr} gagné un nouveau jeton Commandement.{pt-br} ganhou uma nova FIcha de Comando.{de} hat ein neues Befehlsplättchen erhalten."}), positionToColor(playerTurnSequence))
				--Hand Size Increase
				if (turnOrder[playerTurnSequence].level)+1==5 or (turnOrder[playerTurnSequence].level)+1==9 then
					turnOrder[playerTurnSequence].baseHand=turnOrder[playerTurnSequence].baseHand+1
					turnOrder[playerTurnSequence].hand=turnOrder[playerTurnSequence].hand+1
					broadcastToAll(joinLang({translateWord[turnOrder[playerTurnSequence].mage], "{en}'s hand size increased by one.{ru} имеет увеличенный предел карт на 1.{zh-tw}的手牌上限增加 1。{zh-cn}的手牌上限增加了1{ko}: 카드 보유 제한 1 증가{es}'s tamaño de la mano aumenta en uno.{fr}'s la taille de la main a augmenté de un.{pt-br}'s tamanho de mão aumentado em 1.{de} die Handgröße des Spielers wurde um eins erhöht."}), positionToColor(playerTurnSequence))
				end
			end
			turnOrder[playerTurnSequence].level=turnOrder[playerTurnSequence].level+1
			turnOrder[playerTurnSequence].levelUp=turnOrder[playerTurnSequence].levelUp-1
		end
		if turnOrder[playerTurnSequence].levelUp==0 then levelUpcalled=false end
	end
end

--put skill buttons on skills when appropiate
function skillButtonActivate()
	refreshMageSkillLocations()
	unlockCommonSkillPoolTokens()
	if gStates.skillButtons~=nil and gStates.skillButtons>0 then startRewardSkillChoiceHighlights() end
	safeWaitTime("PlayerBoard.Skills",function()
		--blank existing claim buttons
		for skillGUID, x in pairs(gStates.mageSkills) do
			if getObjectFromGUID(skillGUID)~=nil then getObjectFromGUID(skillGUID).UI.setXmlTable({{}}) end
		end
		if gStates.tacticShown==false and gStates.tacticRemove==false then
			--Work out which skills exist where.
			local skillSort={currentPlayer={}}
			if gStates.skillButtons>0 then
				for skillGUID, skillPos in pairs(gStates.mageSkills) do
					if skillPos[3]>-30 then
						local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
						local skillRow=math.ceil((skillPos[3]+24.625)/1.35)
						if gStates.skillButtons~=skillColumn+1 then
							skillSort[(skillColumn*8)+skillRow]=skillGUID
						else
							skillSort.currentPlayer[#skillSort.currentPlayer+1]={skillGUID, skillPos[3], (skillColumn*8)+skillRow}
						end
					end
				end
			end
			--Add claim buttons for skills that are legal
			table.sort(skillSort.currentPlayer, function (k1, k2) return k1[2] > k2[2] end)
			for buttonNumber=1, 32, 1 do
				if gStates.skillButtons>0 then
					if math.ceil(buttonNumber/8)~=gStates.skillButtons then
						if gStates.heroChallenges~=true and skillSort[buttonNumber]~=nil then
							local skill=getObjectFromGUID(skillSort[buttonNumber])
							if skill~=nil then skill.UI.setXmlTable({createClaimButton(skillSort[buttonNumber], tostring(buttonNumber))}) end
						end
					else
						if skillSort.currentPlayer[1]~=nil and buttonNumber==skillSort.currentPlayer[1][3] then
							local skill=getObjectFromGUID(skillSort.currentPlayer[1][1])
							if skill~=nil then skill.UI.setXmlTable({createClaimButton(skillSort.currentPlayer[1][1], tostring(buttonNumber))}) end
						end
						if skillSort.currentPlayer[2]~=nil and buttonNumber==skillSort.currentPlayer[2][3] and turnOrder[gStates.turnNumber].level<=10 then
							local skill=getObjectFromGUID(skillSort.currentPlayer[2][1])
							if skill~=nil then skill.UI.setXmlTable({createClaimButton(skillSort.currentPlayer[2][1], tostring(buttonNumber))}) end
						end
					end
				end
			end
		end
	end, 0.5)
end

--Players may leave the game between turns. Pending dropouts can still be undone until normal turn order advances.

function masterOfChaosSetup(position)
	masterOfChaosPause=true
	for a=1, #turnOrder, 1 do
		if turnOrder[a].seatPos==position then
			turnOrder[a].masterOfChaos="first played"
			break
		end
	end
	safeWaitFrames("PlayerBoard.Skills",function() masterOfChaosPause=false end, 80)
	safeWaitFrames("PlayerBoard.Skills",function() safeWaitCondition("PlayerBoard.Skills",function()
		gStates.masterOfChaos=math.random(1,6)
		getObjectFromGUID(GUID.skill.masterOfChaos).setCustomObject({image=masterOfChaosData[gStates.masterOfChaos].image})
		getObjectFromGUID(GUID.skill.masterOfChaos).setDescription(masterOfChaosData[gStates.masterOfChaos].description)
		getObjectFromGUID(GUID.skill.masterOfChaos).reload()
		broadcastToAll("{en}'Master of Chaos' start Randomly picked.{ru}Старт «Мастер магии Хаоса» выбирается случайным образом.{zh-tw}「混亂大師」的起始位置已隨機選擇。{zh-cn}“混乱大师”开始随机挑选{ko}스킬 '혼돈의 달인'의 첫 칸이 무작위로 결정되었습니다.{es}Inicio de 'Master of Chaos' Elegido al azar.{fr}Début de 'Master of Chaos' Choisi au hasard.{pt-br}Início de 'Mestre do Caos' é aleatóriamente escolhido.{de}Meister des Chaos' startet Zufällig gewählt.", {1,1,0.5})
	end, function() return getObjectFromGUID(GUID.skill.masterOfChaos).resting end) end, 5)
end

--masterOfChaos
function masterOfChaos(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, tonumber(id:sub(14, 14)))==true then
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==tonumber(id:sub(14, 14)) then
					broadcastToAll(joinLang({translateWord[turnOrder[a].mage], "{en} incremented 'Master of Chaos' skill.{ru} передвигает навык «Мастер магии Хаоса».{zh-tw}推進了「混亂大師」技能。{zh-cn}增加了混乱大师技能{ko}: '혼돈의 달인' 스킬 칸 이동{es} se incrementó la habilidad de 'Maestro del Caos'.{fr} compétence 'Maître du Chaos' incrémentée.{pt-br} incrementou a Habilidade 'Mestre do Caos'{de} hat die Fertigkeit 'Meister des Chaos' erhöht."}), positionToColor(a))
					--change skill to next image
					gStates.masterOfChaos=gStates.masterOfChaos+1
					if gStates.masterOfChaos==7 then gStates.masterOfChaos=1 end
					getObjectFromGUID(GUID.skill.masterOfChaos).setCustomObject({image=masterOfChaosData[gStates.masterOfChaos].image})
					getObjectFromGUID(GUID.skill.masterOfChaos).setDescription(masterOfChaosData[gStates.masterOfChaos].description)
					getObjectFromGUID(GUID.skill.masterOfChaos).reload()
					--only allow once per turn
					turnOrder[a].masterOfChaos="incremented out of turn"
					mainUIUpdate()
					break
				end
			end
		end
	end
end

--Quick Witted remains Set Aside at the bottom of Coral's physical Deed Deck.
--While another Deed card remains above it, the containing Deck is returned so the draw-choice UI can offer Quick Witted.

-- Coral Tales site shields
function coralTalesSiteShield(siteType)
	local playerDetails=turnOrder[gStates.turnNumber]
	if playerDetails==nil or playerDetails.mage~="Coral" then return end
	local adventureSites={['monster den']=true, ['spawning grounds']=true, maze=true, labyrinth=true, ruin=true, dungeon=true, tomb=true, ziggurat=true, pyramid=true}
	local skillGUID=nil
	if adventureSites[siteType]==true then skillGUID="9cf272"--Tales of Adventure
	elseif siteType=="keep" or siteType=="mage tower" then skillGUID="de5b04" end--Tales of Conquest
	if skillGUID==nil then return end
	local skill=getObjectFromGUID(skillGUID)
	local recordedPos=gStates.mageSkills~=nil and gStates.mageSkills[skillGUID] or nil
	if skill==nil or recordedPos==nil then return end
	--Claimed skills live in the owner's skill column; communal/pool skills are recorded elsewhere.
	local claimedX=(playerDetails.seatPos*40)-107.45
	if math.abs(recordedPos[1]-claimedX)>2 or recordedPos[3]>-35 then return end
	local shieldContainer=nil
	for _, details in pairs(mageKnights) do if details.mage=="Coral" then shieldContainer=getObjectFromGUID(details.shieldContainer) break end end
	if shieldContainer==nil then return end
	local location=skill.getPosition()
	local snapPoints=skill.getSnapPoints()
	if snapPoints~=nil and snapPoints[1]~=nil then location=skill.positionToWorld(snapPoints[1].position) end
	--Drop above the snap point so the first shield snaps to the skill and later shields can stack naturally.
	location={location[1], skill.getPosition()[2]+2.5, location[3]}
	shieldContainer.takeObject({position=location, rotation={0, skill.getRotation()[2], 0}, smooth=false})
end

--Claim the Skill reserved by Hero Challenges. higherLevel=true mirrors the Start-at-Higher-Level
--Bonds of Loyalty setup rather than adding cards to the live Unit Offer.

-- Motivation skill runtime
function skillsMotivationBase(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, tonumber(id:sub(18, 18)))==true then
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==tonumber(id:sub(18, 18)) then
					broadcastToAll(joinLang({translateWord[turnOrder[a].mage], "{en} used a Motivation skill.{ru} использует навык Мотивация.{zh-tw}使用了激励技能{zh-cn}使用了激励技能{ko}: 스킬 '동기 부여' 사용{es} usó una habilidad de Motivación.{fr} utilisé une compétence de Motivation.{pt-br} usou uma Habilidade de Motivação{de} eine Motivationsfertigkeit eingesetzt."}), positionToColor(a))
					--One exact two-card request keeps the whole Motivation draw inside one Quick Witted choice flow.
					drawExactDeedCards(a, 2, "DrawOne")
					--Gain Fame or mana token
					local lowestFame=1
					for b=2, #turnOrder, 1 do
						if turnOrder[b].mage~=gStates.positionMageKnight[5] then
							if turnOrder[b].fame<turnOrder[lowestFame].fame or turnOrder[lowestFame].mage==gStates.positionMageKnight[5] then lowestFame=b end
						end
					end
					for b=1, #turnOrder, 1 do if turnOrder[b].fame==turnOrder[lowestFame].fame and b~=lowestFame then lowestFame=0 break end end--find ties
					if lowestFame~=0 and turnOrder[lowestFame].seatPos==tonumber(id:sub(18, 18)) then
						local params={position={(gStates.motivationSkill[id:sub(1, 6)].pos*40)-101, 1.65, -39}, rotation={0, 0, 0}, smooth=false}
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 13)=="Red" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.red),params)
							broadcastToAll("{en}Also gained a Red Mana Token.{ru}Также получает Красный жетон маны.{zh-tw}同时增加了一个红色魔晶{zh-cn}同时增加了一个红色魔晶{ko}빨간색 마나 추가 획득.{es}También ganó una ficha de Maná Roja.{fr}A également gagné un jeton de Mana Rouge.{pt-br}Também ganhou um Marcador de Mana Vermelha.{de}Außerdem erhielt er ein rotes Mana-Plättchen.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 14)=="Blue" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.blue),params)
							broadcastToAll("{en}Also gained a Blue Mana Token.{ru}Также получает Синий жетон маны.{zh-tw}同时增加了一个蓝色魔晶{zh-cn}同时增加了一个蓝色魔晶{ko}파란색 마나 추가 획득.{es}También ganó una ficha de Maná Azul.{fr}A également gagné un jeton de Mana Bleu.{pt-br}Também ganhou um Marcador de Mana Azul.{de}Außerdem ein blaues Mana-Plättchen erhalten.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 15)=="White" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.white),params)
							broadcastToAll("{en}Also gained a White Mana Token.{ru}Также получает Белый жетон маны.{zh-tw}同时增加了一个白色魔晶{zh-cn}同时增加了一个白色魔晶{ko}흰색 마나 추가 획득.{es}También ganó una ficha de Maná Blanca.{fr}A également gagné un jeton de Mana Blanc.{pt-br}Também ganhou um Marcador de Mana Branca.{de}Außerdem erhielt er ein weißes Mana-Plättchen.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 15)=="Green" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.green),params)
							broadcastToAll("{en}Also gained a Green Mana Token.{ru}Также получает Зеленый жетон маны.{zh-tw}同时增加了一个绿色魔晶{zh-cn}同时增加了一个绿色魔晶{ko}녹색 마나 추가 획득.{es}También ganó una ficha de Maná Verde.{fr}A également gagné un jeton de Mana Vert.{pt-br}Também ganhou um Marcador de Mana Verde.{de}Hat auch ein grünes Mana-Plättchen erhalten.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 14)=="Fame" then
							local startingFameToLevel=math.floor(math.sqrt((turnOrder[a].fame-(gStates.scoreIfLooped*turnOrder[a].scoreLoop))+1))
							local newFame=turnOrder[a].fame+1-(gStates.scoreIfLooped*turnOrder[a].scoreLoop)
							local scoreLooped=false
							if newFame>=gStates.scoreIfLooped then newFame=newFame-gStates.scoreIfLooped scoreLooped=true end
							local fameToLevel=math.floor(math.sqrt(newFame+1))
							local startPosition=(newFame-(fameToLevel*fameToLevel))+2
							if scoreLooped==false then startPosition=startPosition+((fameToLevel-startingFameToLevel)*gStates.blitz) end
							local levelRowFameQuantity=(((fameToLevel-1)*cellGainPerLevel)+normalCellAmount)
							local levelRowLength=((fameToLevel-1)*gStates.rowLengthGainPerLevel)+gStates.normalRowLength
							local xOffset=(1/levelRowFameQuantity*levelRowLength)/2
							local yOffset=(heightOfFameBoard/gStates.rowsOnBoard)/2
							local horizontalValue=leftOfFameBoard+(startPosition/levelRowFameQuantity*levelRowLength)-xOffset
							local verticalValue=(topOfFameBoard-((fameToLevel/gStates.rowsOnBoard)*heightOfFameBoard))+yOffset-0.25
							getObjectFromGUID(turnOrder[a].fameGUID).setPosition({horizontalValue, 1.5, verticalValue+((turnOrder[a].seatPos-2.5)/5)})
							recordPlayerFameChange(a, 1)
							broadcastToAll("{en}and gained a Fame also{ru}и получает Славу{zh-tw}也增加了1名望{zh-cn}也增加了1名望{ko}명성 1 추가 획득.{es}y ganó Fama también{fr}et a également gagné une renommée{pt-br}e também ganhou uma Fama.{de}und auch einen Ruhmespunkt gewonnen", positionToColor(a))
						end
					end
					--flip skill down.
					getObjectFromGUID(id:sub(1, 6)).setRotationSmooth({0, 180, 180})
					getObjectFromGUID(id:sub(1, 6)).setPositionSmooth({gStates.mageSkills[id:sub(1, 6)][1], 1.5, gStates.mageSkills[id:sub(1, 6)][3]})
					--only allow once per round
					gStates.motivationSkill[id:sub(1, 6)].state="used"
					mainUIUpdate("Motivation Skill activated")
					break
				end
			end
		end
	end
end

-- Motivation's post-award Fame synchronization is coordinated by FameReputation.
function motivation(player, mouseButton, id)
	return fameReputationMotivation(player, mouseButton, id)
end

end)
__bundle_register("PlayingGame.ManaSource", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Mana Source-private helpers. Predeclared so forward references keep resolving locally.
local manaSourceDieGUID, mirrorSourceBusy, manaSourceZoneHasDie, scheduleReturnedSourceMirror, scheduleMirrorSourceUpdate
local mirrorSourceState, mirrorSourcePlayers, mirrorSourceSyncExisting, mirrorSourceFaceSync

-- Mana Source-private helpers. Predeclared so forward references keep resolving locally.
local manaSourceDieGUID, mirrorSourceBusy, manaSourceZoneHasDie, scheduleReturnedSourceMirror, scheduleMirrorSourceUpdate
local mirrorSourceState, mirrorSourcePlayers, mirrorSourceSyncExisting, mirrorSourceFaceSync

-- Mirrored Mana Source runtime.

--Keep every scripted mana crystal/token draw at the same display angle as a manual bag draw.
--Preserve any intentional X/Z rotation supplied by the caller, but normalize Y to 30 degrees.
function takeManaCrystal(bag,params)
	if bag==nil then return nil end
	params=params or {}
	local rotation=params.rotation or {0,0,0}
	params.rotation={rotation[1] or rotation.x or 0,30,rotation[3] or rotation.z or 0}
	return bag.takeObject(params)
end

-- Shared Mana Source mirrors
exitWaitID={}
mirrorSpawnEnterIgnore={}
mirrorDestroyIgnore={}
mirrorSourceClaim={}
mirrorFaceWaitID={}
mirrorSourceRefreshWait=nil
mirrorManualRandomize={}
mirrorRepositionIgnore={}
spentMirrorDice={}
manaSourceDieGUID=function(guid)
	if guid==nil or gStates.manaSource==nil then return false end
	for _, die in pairs(gStates.manaSource) do if die.manaDie==guid then return true end end
	return false
end
mirrorSourceBusy=function()
	for _, waitfunction in pairs(exitWaitID) do if waitfunction~=nil then return true end end
	for _, claim in pairs(mirrorSourceClaim) do if claim~=nil then return true end end
	for _, sourceGUID in pairs(mirrorManualRandomize) do if sourceGUID~=nil then return true end end
	return false
end
manaSourceZoneHasDie=function(guid)
	local zone=getObjectFromGUID(GUID.zone.mana)
	if zone==nil or guid==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==guid then return true end end
	return false
end
scheduleReturnedSourceMirror=function(sourceDie)
	if sourceDie==nil or sourceDie.guid==nil then return end
	local sourceGUID=sourceDie.guid
	--Do not make mirror restoration depend solely on the generic zone-enter callback. As soon as this exact
	--returned die is physically inside the real Source, rebuild the missing copies; correct its face again after settling.
	safeWaitCondition("ManaSource",function()
		local die=getObjectFromGUID(sourceGUID)
		if die==nil then return end
		mirrorSourceUpdate("returned die entered real Source")
		safeWaitCondition("ManaSource",function()
			if getObjectFromGUID(sourceGUID)~=nil then mirrorSourceUpdate("returned die settled in real Source") end
		end, function()
			local current=getObjectFromGUID(sourceGUID)
			return current==nil or current.resting
		end)
	end, function()
		return getObjectFromGUID(sourceGUID)==nil or manaSourceZoneHasDie(sourceGUID)==true
	end)
end
scheduleMirrorSourceUpdate=function(from, delay)
	if mirrorSourceRefreshWait~=nil then Wait.stop(mirrorSourceRefreshWait) end
	mirrorSourceRefreshWait=safeWaitTime("ManaSource",function()
		mirrorSourceRefreshWait=nil
		if mirrorSourceBusy()==true then
			mirrorSourceRefreshWait=safeWaitCondition("ManaSource",function()
				mirrorSourceRefreshWait=nil
				mirrorSourceUpdate(from)
			end, function() return mirrorSourceBusy()==false end)
		else
			mirrorSourceUpdate(from)
		end
	end, delay or 0.1)
end
mirrorSourceState=function()
	local colorConvert={["Blue Mana"]=1, ["White Mana"]=2, ["Green Mana"]=3, ["Red Mana"]=4, ["Gold Mana"]=5, ["Black Mana"]=6}
	if gStates.dayRound==false then colorConvert["Gold Mana"]=6 colorConvert["Black Mana"]=5 end
	local colorRotate={{0, 0, 0}, {0, 0, 270}, {0, 0, 90}, {0, 0, 180}, {90, 0, 0}, {270, 0, 0}}
	if gStates.dayRound==false then colorRotate[5]={270, 0, 0} colorRotate[6]={90, 0, 0} end
	local sourceDice={}
	local seperate=0
	for _, manaDie in pairs(getObjectFromGUID(GUID.zone.mana).getObjects()) do
		local color=manaDie.type=="Dice" and colorConvert[manaDie.getRotationValue()] or nil
		if color~=nil then
			sourceDice[#sourceDice+1]={manaDie=manaDie.guid, color=color}
			if color==6 then seperate=0.25 end
		end
	end
	table.sort(sourceDice, function(k1, k2) return k1.color<k2.color end)
	return sourceDice, colorRotate, seperate
end

mirrorSourcePlayers=function()
	local players={}
	for playerIndex, playerDetails in ipairs(turnOrder) do
		if playerDetails.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false then players[#players+1]=playerDetails end
	end
	table.sort(players, function(a, b) return (a.seatPos or 99)<(b.seatPos or 99) end)
	return players
end

--Face changes do not need new physical dice. Reuse the existing copies, update their faces and
--slide them into the same sorted positions a rebuild would have produced. If the Source set changed,
--return false so mirrorSourceUpdate can fall back to the structural rebuild.
mirrorSourceSyncExisting=function(sourceDice, colorRotate, seperate)
	if gStates.manaMirror==nil then return false end
	local players=mirrorSourcePlayers()
	local expected=#sourceDice*#players
	local sourceSet={}
	local mirrorsBySource={}
	for _, die in ipairs(sourceDice) do sourceSet[die.manaDie]=true mirrorsBySource[die.manaDie]={} end
	local mirrorCount=0
	for mirrorGUID, sourceGUID in pairs(gStates.manaMirror) do
		local mirror=getObjectFromGUID(mirrorGUID)
		if mirror==nil or sourceSet[sourceGUID]~=true then return false end
		mirrorCount=mirrorCount+1
		mirrorsBySource[sourceGUID][#mirrorsBySource[sourceGUID]+1]=mirror
	end
	if mirrorCount~=expected then return false end
	for _, die in ipairs(sourceDice) do if #mirrorsBySource[die.manaDie]~=#players then return false end end
	if expected==0 then gStates.manaSource=sourceDice return true end

	local used={}
	for _, playerDetails in ipairs(players) do
		local spacing=0
		local first=false
		local localSeperate=seperate
		for pos, die in ipairs(sourceDice) do
			if die.color==6 and first==false then
				spacing=0.5 first=true
				if pos==1 then localSeperate=0 spacing=0 end
			end
			local target={-105+(40*playerDetails.seatPos)+((1.5*pos)+spacing)+(((8-gStates.diceNeeded)/2)*1.5)-localSeperate, 1.57, -28.1}
			local best=nil
			local bestDist=99999
			for _, mirror in ipairs(mirrorsBySource[die.manaDie]) do
				if used[mirror.guid]~=true then
					local p=mirror.getPosition()
					local dist=math.abs(p[1]-target[1])
					if dist<bestDist then best=mirror bestDist=dist end
				end
			end
			if best==nil then return false end
			used[best.guid]=true
			mirrorRepositionIgnore[best.guid]=true
			best.setRotation(colorRotate[die.color])
			local p=best.getPosition()
			if math.abs(p[1]-target[1])>0.02 or math.abs(p[2]-target[2])>0.08 or math.abs(p[3]-target[3])>0.02 then best.setPosition(target) end
			local mirrorGUID=best.guid
			safeWaitFrames("ManaSource",function() mirrorRepositionIgnore[mirrorGUID]=nil end, 3)
		end
	end
	gStates.manaSource=sourceDice
	return true
end

function mirrorSourceUpdate(from)
	--Never alter mirror dice while a player is physically resolving one.
	if mirrorSourceBusy()==true then scheduleMirrorSourceUpdate(from, 0.05) return end
	if getObjectFromGUID(GUID.zone.mana)==nil or getObjectFromGUID(GUID.bag.spareDice)==nil then return end
	local sourceDice, colorRotate, seperate=mirrorSourceState()
	--The normal fast path: same Source GUIDs, so only update/re-sort the existing physical copies.
	if mirrorSourceSyncExisting(sourceDice, colorRotate, seperate)==true then return end

	--Structural change (die spent/returned/added, player set changed, stale save): rebuild the mirror set.
	if gStates.manaMirror~=nil then
		for dieDel, _ in pairs(gStates.manaMirror) do
			mirrorSpawnEnterIgnore[dieDel]=nil
			mirrorRepositionIgnore[dieDel]=nil
			mirrorDestroyIgnore[dieDel]=true
			mirrorManualRandomize[dieDel]=nil
			if mirrorFaceWaitID[dieDel]~=nil then Wait.stop(mirrorFaceWaitID[dieDel]) mirrorFaceWaitID[dieDel]=nil end
			if exitWaitID~=nil and exitWaitID[dieDel]~=nil then Wait.stop(exitWaitID[dieDel]) exitWaitID[dieDel]=nil end
			local oldDie=getObjectFromGUID(dieDel)
			if oldDie~=nil then oldDie.destruct() end
			local oldGUID=dieDel
			safeWaitFrames("ManaSource",function() mirrorDestroyIgnore[oldGUID]=nil end, 3)
		end
	end
	gStates.manaMirror={}
	gStates.manaSource=sourceDice
	mirrorSourceClaim={}
	local players=mirrorSourcePlayers()
	for _, playerDetails in ipairs(players) do
		local spacing=0
		local first=false
		local localSeperate=seperate
		for pos, die in ipairs(sourceDice) do
			if die.color==6 and first==false then
				spacing=0.5 first=true
				if pos==1 then localSeperate=0 spacing=0 end
			end
			local mirrorDie=getObjectFromGUID(GUID.bag.spareDice).takeObject({position={-105+(40*playerDetails.seatPos)+((1.5*pos)+spacing)+(((8-gStates.diceNeeded)/2)*1.5)-localSeperate, 1.57, -28.1}, rotation=colorRotate[die.color], smooth=false})
			gStates.manaMirror[mirrorDie.guid]=die.manaDie
			mirrorSpawnEnterIgnore[mirrorDie.guid]=true
			local mirrorGUID=mirrorDie.guid
			safeWaitFrames("ManaSource",function() mirrorSpawnEnterIgnore[mirrorGUID]=nil end, 3)
		end
	end
end

mirrorSourceFaceSync=function(diceGUID, sourceGUID, from)
	mirrorFaceWaitID[diceGUID]=nil
	local dice=getObjectFromGUID(diceGUID)
	local source=getObjectFromGUID(sourceGUID)
	if dice==nil or source==nil or gStates.manaMirror==nil or gStates.manaMirror[diceGUID]~=sourceGUID then return end
	source.setRotation(dice.getRotation())
	mirrorSourceUpdate(from)
end
function scheduleMirrorFaceSync(dice, from)
	if dice==nil or dice.guid==nil or gStates.manaMirror==nil then return false end
	if mirrorRepositionIgnore[dice.guid]==true then return true end
	local sourceGUID=gStates.manaMirror[dice.guid]
	if sourceGUID==nil then return false end
	--Once a physical copy has started taking this shared die, face-change shortcuts on any copy must not alter the Source.
	if mirrorSourceClaim[sourceGUID]~=nil then return true end
	if mirrorFaceWaitID[dice.guid]~=nil then Wait.stop(mirrorFaceWaitID[dice.guid]) end
	local diceGUID=dice.guid
	mirrorFaceWaitID[diceGUID]=safeWaitFrames("ManaSource",function() mirrorSourceFaceSync(diceGUID, sourceGUID, from) end, 2)
	return true
end
function scheduleMirrorRandomizeSync(dice, from)
	if dice==nil or dice.guid==nil or gStates.manaMirror==nil then return false end
	local sourceGUID=gStates.manaMirror[dice.guid]
	if sourceGUID==nil then return false end
	--If this Source die is already being physically taken, R applies only to that held copy; do not cancel the spend.
	if mirrorSourceClaim[sourceGUID]~=nil then return true end
	local diceGUID=dice.guid
	mirrorManualRandomize[diceGUID]=sourceGUID
	if exitWaitID[diceGUID]~=nil then Wait.stop(exitWaitID[diceGUID]) exitWaitID[diceGUID]=nil end
	if mirrorFaceWaitID[diceGUID]~=nil then Wait.stop(mirrorFaceWaitID[diceGUID]) end
	local function finishRandomize()
		mirrorFaceWaitID[diceGUID]=nil
		mirrorManualRandomize[diceGUID]=nil
		mirrorSourceFaceSync(diceGUID, sourceGUID, from)
	end
	mirrorFaceWaitID[diceGUID]=safeWaitFrames("ManaSource",function()
		mirrorFaceWaitID[diceGUID]=safeWaitCondition("ManaSource",finishRandomize, function()
			local die=getObjectFromGUID(diceGUID)
			return die==nil or die.resting
		end, 10, finishRandomize)
	end, 2)
	return true
end
function scheduleRealSourceRefresh(dice, from, waitForRest)
	if dice==nil or dice.guid==nil or manaSourceDieGUID(dice.guid)~=true then return false end
	local diceGUID=dice.guid
	if mirrorFaceWaitID[diceGUID]~=nil then Wait.stop(mirrorFaceWaitID[diceGUID]) end
	local function refresh()
		mirrorFaceWaitID[diceGUID]=nil
		if getObjectFromGUID(diceGUID)~=nil then mirrorSourceUpdate(from) end
	end
	if waitForRest==true then
		mirrorFaceWaitID[diceGUID]=safeWaitFrames("ManaSource",function()
			mirrorFaceWaitID[diceGUID]=safeWaitCondition("ManaSource",refresh, function()
				local die=getObjectFromGUID(diceGUID)
				return die==nil or die.resting
			end, 10, refresh)
		end, 2)
	else
		mirrorFaceWaitID[diceGUID]=safeWaitFrames("ManaSource",refresh, 2)
	end
	return true
end
function diceResting(dice, state)
	if dice==nil or dice.type~="Dice" or dice.guid==nil then return end
	if gStates~=nil and gStates.apocalypseQuestRollDice~=nil and gStates.apocalypseQuestRollDice[dice.guid]==true then return end
	--Script-driven mirror destruction can emit collision exits; never interpret those as spending Source mana.
	if mirrorDestroyIgnore[dice.guid]==true then return end
	--In-place mirror face/order synchronization may briefly cross the collision surface.
	if mirrorRepositionIgnore[dice.guid]==true then return end
	--A mirror being randomized can leave/re-enter the collision surface while it rolls. That is a face change, not spending the die.
	if mirrorManualRandomize[dice.guid]~=nil then return end
	--New mirror dice naturally fire one collision-enter as they land. Ignore only that event.
	if state=="enter" and mirrorSpawnEnterIgnore[dice.guid]==true then return end
	if exitWaitID[dice.guid]~=nil then Wait.stop(exitWaitID[dice.guid]) exitWaitID[dice.guid]=nil end
	local sourceGUID=gStates.manaMirror~=nil and gStates.manaMirror[dice.guid] or nil
	--Only a die that actually spent a mirrored Source entry may be returned here. Other dice can
	--touch the collision surface without being destroyed or creating a new real Source die.
	if sourceGUID==nil then
		if state~="enter" or spentMirrorDice[dice.guid]~=true then return end
		local diceGUID=dice.guid
		local function returnDieToSource()
			exitWaitID[diceGUID]=nil
			local currentDice=getObjectFromGUID(diceGUID)
			local spareDice=getObjectFromGUID(GUID.bag.spareDice)
			if currentDice==nil or spareDice==nil then return end
			local returnedSource=spareDice.takeObject({position={-12.5+(math.random()*7), 1.5 , -24.0+(math.random()*3.5)}, rotation=currentDice.getRotation(), smooth=false})--Mana Dice Container
			spentMirrorDice[diceGUID]=nil
			scheduleReturnedSourceMirror(returnedSource)
			onObjectRandomize({type="Dice"})
			currentDice.destruct()
		end
		exitWaitID[diceGUID]=safeWaitCondition("ManaSource",returnDieToSource, function()
			local currentDice=getObjectFromGUID(diceGUID)
			return currentDice==nil or currentDice.resting
		end, 10, returnDieToSource)
		return
	end
	--Only one physical mirror may be taking a shared Source die at a time. A second simultaneous copy stays stale until the first action resolves/rebuilds.
	if state=="exit" then
		if mirrorSourceClaim[sourceGUID]~=nil and mirrorSourceClaim[sourceGUID]~=dice.guid then return end
		mirrorSourceClaim[sourceGUID]=dice.guid
	elseif state=="enter" then
		if mirrorSourceClaim[sourceGUID]~=nil and mirrorSourceClaim[sourceGUID]~=dice.guid then return end
		if mirrorSourceClaim[sourceGUID]==dice.guid then mirrorSourceClaim[sourceGUID]=nil end
	end
	local diceGUID=dice.guid
	local function updateDice()
		exitWaitID[diceGUID]=nil
		local currentDice=getObjectFromGUID(diceGUID)
		local mappedSource=gStates.manaMirror~=nil and gStates.manaMirror[diceGUID] or nil
		if mappedSource~=sourceGUID then return end
		--Removed a die from a mirrored Source: spend the one shared real Source die.
		if state=="exit" then
			local source=getObjectFromGUID(sourceGUID)
			if source~=nil then source.destruct() end
			spentMirrorDice[diceGUID]=true
			gStates.manaMirror[diceGUID]=nil
			mirrorSourceClaim[sourceGUID]=nil
		else--Returned/changed a die while still on a mirrored Source.
			local source=getObjectFromGUID(sourceGUID)
			if source~=nil and currentDice~=nil then source.setRotation(currentDice.getRotation()) end
		end
		local moreDice=false
		for _, waitfunction in pairs(exitWaitID) do if waitfunction~=nil then moreDice=true break end end
		if moreDice==false then exitWaitID={} scheduleMirrorSourceUpdate("last dice resting in mirror", 0.05) end
	end
	exitWaitID[diceGUID]=safeWaitCondition("ManaSource",updateDice, function()
		local currentDice=getObjectFromGUID(diceGUID)
		return currentDice==nil or currentDice.resting
	end, 10, updateDice)
end

end)
__bundle_register("PlayingGame.Offers", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Offer-private helpers. Predeclared so forward references keep resolving locally.
local unitOfferLayoutX, unitOfferCardScale, unitOfferPosition, volkareUnitCrystalRefreshPositions, unitOfferIsUnit
local monasteryOfferIsCard, refreshUnitOfferSnapPoints, unitOfferCards, reflowUnitOffer, monasteryOfferFirstEmptySlot

-- Offer-private helpers. Predeclared so forward references keep resolving locally.
local unitOfferLayoutX, unitOfferCardScale, unitOfferPosition, volkareUnitCrystalRefreshPositions, unitOfferIsUnit
local monasteryOfferIsCard, refreshUnitOfferSnapPoints, unitOfferCards, reflowUnitOffer, monasteryOfferFirstEmptySlot

-- Artifact, Unit, Monastery and deed-offer runtime.

-- Artifact reward offer
--Adjust artifact rewards claim amount
function artifactAdjust(player, mouseButton, id)
	if mouseButton=="-1" then
		if id=="ac75c4ArtifactDown" then
			gStates.artifactRewards=gStates.artifactRewards-1
			if gStates.artifactRewards<1 then gStates.artifactRewards=1 end
		else
			gStates.artifactRewards=gStates.artifactRewards+1
			if gStates.artifactRewards>4 then gStates.artifactRewards=4 end
		end
		getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOfferText", "text", joinLang({"{en}Reward {ru}Награда {zh-tw}獎勵{zh-cn}奖励{ko}보상 {es}Premiar {fr}Reward {pt-br}Premiar {de}Belohnung ", gStates.artifactRewards}))
	end
end

--Deploys artifacts to be claimed
function offerArtifacts(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then
			--check if the game is in a state to claim artifacts
			if gStates.tacticShown~=true and gStates.tacticRemove~=true then
				--deal out cards
				local artifactDeck=getObjectFromGUID(GUID.deck.artifact)
				gStates.dealtArtifacts={}
				local hide={}
				if gStates.coop==0 then
					for _, seatColor in pairs(Player.getColors()) do
						if seatColor~=player.color then hide[#hide+1]=seatColor end
					end
				end
				for a=1, gStates.artifactRewards+1, 1 do
					standardDeckCycleShuffleIfReached("Artifact", artifactDeck)
					local dealtArtifact=artifactDeck.takeObject({position={artifactDeck.getPosition()[1]+(((artifactDeck.getScale()[1]/1.5)*4.8)*a), 2.0, artifactDeck.getPosition()[3]}, rotation={0, 180, 0}, smooth=true})
					dealtArtifact.setHiddenFrom(hide)
					dealtArtifact.UI.setXmlTable({createClaimButton(dealtArtifact.guid, "artifactReward")})
					safeWaitCondition("Offers",function() dealtArtifact.lock() end, function() return dealtArtifact.resting end)
					gStates.dealtArtifacts[dealtArtifact.guid]=true
				end
				--remove reward and arrow buttons.
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactDown", "active", "false")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOffer", "active", "false")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactUp", "active", "false")
			else
				broadcastToAll("{en}Choose a tactic first{ru}Сперва выберите Тактику{zh-tw}先选一张战术卡吧{zh-cn}先选一张战术卡吧{ko}먼저 전략 카드를 고르세요{es}Elige una táctica primero{fr}Choisissez d'abord une tactique{pt-br}Escolha uma Tática primeiro{de}Wähle zuerst eine Taktik",warningColor)
			end
		else
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				broadcastToAll("{en}Dummy doesn't claim artifacts{ru}Виртуальный игрок не получает артефактов{zh-tw}虚拟玩家不选择圣器{zh-cn}虚拟玩家不选择圣器{ko}가상 플레이어는 유물을 얻지 않습니다!{es}Dummy no reclama artefactos{fr}Le mannequin ne revendique pas d'artefacts{pt-br}Jog. Fictício não clama Artefatos{de}Dummy beansprucht keine Artefakte",warningColor)
			end
		end
	end
end

--Unit Offer uses eight printed positions spanning X=36.0 to X=2.4.
--Overflow (normally Bonds of Loyalty) compresses extra cards inside those fixed endpoints. The
--snap points are rebuilt to the same centres, while one broad scripting zone handles every Unit card.
unitOfferLayoutConfig={nativeSlots=8,firstX=36.0,lastX=2.4,y=0.98,z=-4.2,cardScale=1.5}

-- Unit offer layout and refill
unitOfferLayoutX=function(slot,count)
	local displayCount=math.max(unitOfferLayoutConfig.nativeSlots,count or unitOfferLayoutConfig.nativeSlots)
	local spacing=(unitOfferLayoutConfig.firstX-unitOfferLayoutConfig.lastX)/(displayCount-1)
	return unitOfferLayoutConfig.firstX-((slot-1)*spacing)
end

unitOfferCardScale=function(count)
	if count==nil or count<=unitOfferLayoutConfig.nativeSlots then return unitOfferLayoutConfig.cardScale end
	return unitOfferLayoutConfig.cardScale*((unitOfferLayoutConfig.nativeSlots-1)/(count-1))
end

unitOfferPosition=function(slot,count,y)
	return {unitOfferLayoutX(slot,count),y or unitOfferLayoutConfig.y,unitOfferLayoutConfig.z}
end

volkareUnitCrystalRefreshPositions=function(count)
	if gStates==nil or gStates.volkareUnitCrystals==nil then return end
	local displayCount=math.max(unitOfferLayoutConfig.nativeSlots,tonumber(count) or tonumber(gStates.unitOfferDisplayCount) or tonumber(gStates.totalUnitCount) or unitOfferLayoutConfig.nativeSlots)
	for _,details in pairs(gStates.volkareUnitCrystals) do
		if type(details)=="table" and details.slot~=nil and details.crystalGUID~=nil then
			local crystal=getObjectFromGUID(details.crystalGUID)
			if crystal~=nil then
				crystal.setPositionSmooth({unitOfferLayoutX(details.slot,displayCount),1.29,-1.15})
			end
		end
	end
end

--Advanced Action and Spell rows share one resizable scripting zone. Derive slot order from the
--cards themselves so expanding/shrinking the offer never needs matching per-slot zones.
function mainOfferCardsByType(cardType)
	local cards={}
	local zone=getObjectFromGUID(GUID.zone.offer)
	if zone~=nil then
		for _,obj in pairs(zone.getObjects()) do
			if obj.type=="Card" and gameCardType(obj)==cardType then cards[#cards+1]=obj end
		end
	end
	table.sort(cards,function(a,b) return a.getPosition()[1]<b.getPosition()[1] end)
	return cards
end

function mainOfferFirstCardByType(cardType)
	return mainOfferCardsByType(cardType)[1]
end

unitOfferIsUnit=function(obj)
	if obj==nil or obj.type~="Card" then return false end
	local cardType=gameCardType(obj)
	return cardType=="Regular Unit" or cardType=="Elite Unit"
end

monasteryOfferIsCard=function(obj)
	if obj==nil or obj.type~="Card" or gameCardType(obj)~="Advanced Action" then return false end
	return math.abs(obj.getPosition()[3]+10.2)<=1
end

function monasteryOfferCards()
	local cards={}
	local zone=getObjectFromGUID(GUID.zone.unitOffer)
	if zone~=nil then
		for _,obj in pairs(zone.getObjects()) do
			if monasteryOfferIsCard(obj) then cards[#cards+1]=obj end
		end
	end
	--Smallest X is the highest-numbered printed slot, matching the old reverse zone scan.
	table.sort(cards,function(a,b) return a.getPosition()[1]<b.getPosition()[1] end)
	return cards
end

--Offer claims use two broad scripting zones. The upper zone distinguishes Units from Monastery
--Advanced Actions by card type/row; the lower zone already covers both Advanced Actions and Spells.
function offerClaimSource(zoneGUID,obj)
	local source=cardClaimingZones[zoneGUID]
	if source~="unitOffer" then return source end
	if unitOfferIsUnit(obj) then return "unit" end
	if monasteryOfferIsCard(obj) then return "monastery" end
	return nil
end

local function unitOfferSnapWorld(owner,point,isGlobal)
	if point==nil or point.position==nil then return nil end
	if isGlobal==true then return point.position end
	return owner.positionToWorld(point.position)
end

local function unitOfferSnapInRow(worldPos)
	if worldPos==nil then return false end
	local x=worldPos.x or worldPos[1]
	local z=worldPos.z or worldPos[3]
	if x==nil or z==nil then return false end
	return x>=unitOfferLayoutConfig.lastX-0.4 and x<=unitOfferLayoutConfig.firstX+0.4 and math.abs(z-unitOfferLayoutConfig.z)<=0.5
end

--The eight offer snaps may be global table snaps or attached to the offer mat. Find whichever owns
--the row, preserve every unrelated snap, then rebuild this row at the same dynamic centres as the cards.
local function unitOfferSnapTarget()
	local snaps=Global.getSnapPoints() or {}
	local matches=0
	for _,point in ipairs(snaps) do if unitOfferSnapInRow(point.position) then matches=matches+1 end end
	if matches>=unitOfferLayoutConfig.nativeSlots then return Global,snaps,true end
	for _,obj in ipairs(getAllObjects()) do
		local objSnaps=obj.getSnapPoints() or {}
		if #objSnaps>=unitOfferLayoutConfig.nativeSlots then
			matches=0
			for _,point in ipairs(objSnaps) do
				if unitOfferSnapInRow(unitOfferSnapWorld(obj,point,false)) then matches=matches+1 end
			end
			if matches>=unitOfferLayoutConfig.nativeSlots then return obj,objSnaps,false end
		end
	end
	return nil,nil,nil
end

refreshUnitOfferSnapPoints=function(count)
	local displayCount=math.max(unitOfferLayoutConfig.nativeSlots,count or unitOfferLayoutConfig.nativeSlots)
	gStates.unitOfferDisplayCount=displayCount
	volkareUnitCrystalRefreshPositions(displayCount)
	local owner,snaps,isGlobal=unitOfferSnapTarget()
	if owner==nil then return false end
	local kept={}
	local template=nil
	local templateWorld=nil
	for _,point in ipairs(snaps) do
		local world=unitOfferSnapWorld(owner,point,isGlobal)
		if unitOfferSnapInRow(world) then
			if template==nil then template=point templateWorld=world end
		else
			kept[#kept+1]=point
		end
	end
	if template==nil or templateWorld==nil then return false end
	local y=templateWorld.y or templateWorld[2] or 0
	local z=templateWorld.z or templateWorld[3] or unitOfferLayoutConfig.z
	for slot=1,displayCount do
		local world={unitOfferLayoutX(slot,displayCount),y,z}
		local position=world
		if isGlobal~=true then position=owner.positionToLocal(world) end
		kept[#kept+1]={position=position,rotation=template.rotation,rotation_snap=template.rotation_snap,tags=template.tags}
	end
	owner.setSnapPoints(kept)
	return true
end

unitOfferCards=function()
	local cards={}
	local zone=getObjectFromGUID(GUID.zone.unitOffer)
	if zone~=nil then
		for _,obj in pairs(zone.getObjects()) do
			if unitOfferIsUnit(obj) then cards[#cards+1]=obj end
		end
	end
	table.sort(cards,function(a,b) return a.getPosition()[1]>b.getPosition()[1] end)
	return cards
end

--Resolve a physical Unit-offer slot without collapsing gaps left by claimed or removed cards.
--This also follows the compressed spacing used when more than eight Units are displayed.
function unitOfferCardAtSlot(slot,count)
	slot=tonumber(slot)
	if slot==nil then return nil end
	local displayCount=math.max(unitOfferLayoutConfig.nativeSlots,tonumber(count) or tonumber(gStates.unitOfferDisplayCount) or tonumber(gStates.totalUnitCount) or unitOfferLayoutConfig.nativeSlots)
	if slot<1 or slot>displayCount then return nil end
	local spacing=(unitOfferLayoutConfig.firstX-unitOfferLayoutConfig.lastX)/(displayCount-1)
	local targetX=unitOfferLayoutX(slot,displayCount)
	local tolerance=math.max(0.45,spacing*0.45)
	local best=nil
	local bestDistance=nil
	for _,card in ipairs(unitOfferCards()) do
		local pos=card.getPosition()
		local x=pos.x or pos[1]
		local z=pos.z or pos[3]
		if x~=nil and z~=nil and math.abs(z-unitOfferLayoutConfig.z)<=0.8 then
			local distance=math.abs(x-targetX)
			if distance<=tolerance and (bestDistance==nil or distance<bestDistance) then
				best=card
				bestDistance=distance
			end
		end
	end
	return best
end

local function moveUnitOfferCard(obj,slot,count)
	if obj==nil then return end
	local guid=obj.guid
	local pos=obj.getPosition()
	local scale=unitOfferCardScale(count)
	obj.unlock()
	obj.setScale({scale,1,scale})
	obj.setPositionSmooth(unitOfferPosition(slot,count,pos[2]))
	safeWaitCondition("Offers",function()
		local card=getObjectFromGUID(guid)
		if card~=nil then card.lock() end
	end,function()
		local card=getObjectFromGUID(guid)
		return card==nil or card.resting
	end)
end

reflowUnitOffer=function(targetCount)
	local cards=unitOfferCards()
	local displayCount=math.max(targetCount or #cards,#cards)
	refreshUnitOfferSnapPoints(displayCount)
	for slot,obj in ipairs(cards) do moveUnitOfferCard(obj,slot,displayCount) end
	safeWaitTime("Offers",function() if claimButtonRefresh~=nil then claimButtonRefresh() end end,0.5)
	return #cards,displayCount
end

function addRegularUnitsToOffer(amount)
	amount=math.max(0,math.floor(amount or 0))
	if amount==0 then return 0 end
	local cards=unitOfferCards()
	local existing=#cards
	local finalCount=existing+amount
	refreshUnitOfferSnapPoints(finalCount)
	for slot,obj in ipairs(cards) do moveUnitOfferCard(obj,slot,finalCount) end
	local added=0
	for slot=existing+1,finalCount do
		standardDeckCycleShuffleIfReached("Regular Unit")
		local zone=getObjectFromGUID(GUID.zone.regularUnit)
		local deck=nil
		if zone~=nil then
			for _,obj in pairs(zone.getObjects()) do if obj.type=="Deck" or obj.type=="Card" then deck=obj break end end
		end
		if deck~=nil then
			local scale=unitOfferCardScale(finalCount)
			safeTakeObject("Offers",deck,{
				position=unitOfferPosition(slot,finalCount,1.25),
				rotation={0,180,0},
				smooth=true,
				callback_function=function(drawnCard)
					drawnCard.setScale({scale,1,scale})
					safeWaitCondition("Offers",function() if drawnCard~=nil then drawnCard.lock() end end,function() return drawnCard==nil or drawnCard.resting end)
				end
			})
			added=added+1
		end
	end
	safeWaitTime("Offers",function() if claimButtonRefresh~=nil then claimButtonRefresh() end end,0.5)
	return added
end

--Unit and Monastery Offer update
function unitOffer()
	refreshUnitOfferSnapPoints(gStates.totalUnitCount)
	local monasteryPlace=	{{36.0, 0.98, -10.2}, {31.2, 0.98, -10.2}, {26.4, 0.98, -10.2}, {21.6, 0.98, -10.2}, {16.8, 0.98, -10.2}, {12.0, 0.98, -10.2}}
	local drawDecks=		{["Regular Unit"]=GUID.zone.regularUnit, ["Elite Unit"]=GUID.zone.eliteUnit, ["Advanced Action"]=GUID.zone.actionDeck}--Zone covering Regular units draw deck, Elite Units Draw Deck, Advanced Actions Draw Deck
	local skip=false
	--Place existing cards under raised decks
	for _, offerCards in pairs(getObjectFromGUID("a3d99b").getObjects()) do--Zone where units and monastery cards are played
		local offerCardType=gameCardType(offerCards)
		if offerCards.type=="Card" and drawDecks[offerCardType]~=nil then
			offerCards.unlock()
			if offerCardType=="Regular Unit" or offerCardType=="Elite Unit" then offerCards.setScale({unitOfferLayoutConfig.cardScale,1,unitOfferLayoutConfig.cardScale}) end
			standardDeckCycleMarkReturned(offerCardType, offerCards)
			getObjectFromGUID(getObjectFromGUID(drawDecks[offerCardType]).getObjects()[1].guid).putObject(offerCards)
		end
		if offerCards.type=="Deck" then
			for j=1, offerCards.getQuantity(), 1 do
				local pos=offerCards.getPosition()
				local params={position={pos.x-j*0.85+1, pos.y+0.15, pos.z}}
				offerCards.takeObject(params)
			end
			broadcastToAll("{en}Sorry, I seem to have double dealt. Manual cleaning of Offer required{ru}Извините, что-то пошло не так. Требуется ручное исправление доступных карт{zh-tw}抱歉，我可能做了双重结算，请手动清除部队供应区{zh-cn}抱歉，我可能做了双重结算，请手动清除部队供应区{ko}죄송합니다, 공급처가 이중으로 겹쳐진 모양이네요. 직접 정리 부탁드립니다.{es}Lo siento, parece que he hecho un doblete. Se requiere limpieza manual de la Oferta{fr}Désolé, j'ai l'impression d'avoir joué deux fois. Nettoyage manuel de l'offre requis{pt-br}Desculpe, Parece que ofertei em dobro. Limpeza Manual da Oferta requerida.{de}Entschuldigung, ich habe wohl doppelt gehandelt. Manuelle Bereinigung des Angebots erforderlich", warningColor)
			skip=true
		end
	end
	if skip==false then
		local params={smooth=true, rotation={0, 180, 0}}
		standardDeckCycleShuffleIfReached("Regular Unit")
		standardDeckCycleShuffleIfReached("Elite Unit")
		standardDeckCycleShuffleIfReached("Advanced Action")
		--Place Unit Cards
		local function getUnitDrawList(drawDecks)
			local unitsInOffer={}
			local deckInfo={}
			local drawList={}
			--Prepare a deck's contents the first time we need it
			local function getDeckInfo(zoneGUID)
				if deckInfo[zoneGUID]~=nil then return deckInfo[zoneGUID] end
				local zone=getObjectFromGUID(zoneGUID)
				local deck=nil
				for _, obj in ipairs(zone.getObjects()) do
					if obj.type=="Deck" or obj.type=="Card" then deck=obj break end
				end
				if deck==nil then return nil end
				local cards={}
				if deck.type=="Deck" then cards=deck.getObjects() else cards={{guid=deck.guid}}	end
				deckInfo[zoneGUID]={deck=deck, cards=cards, nextCard=1, rejected={}}
				return deckInfo[zoneGUID]
			end

			--Find the next unit whose name is not already in the offer
			local function getNextUniqueUnit(zoneGUID, deckName)
				local info=getDeckInfo(zoneGUID)
				if info==nil then return nil end
				while info.nextCard<=#info.cards do
					local card=info.cards[info.nextCard]
					info.nextCard=info.nextCard+1
					local unitData=gameCards[card.guid]
					--Fallback to GUID if this card isn't in gameCards
					local unitName=card.guid
					if unitData~=nil and unitData.name~=nil and unitData.name[1]~=nil then unitName=unitData.name[1] end
					if unitsInOffer[unitName]~=true then
						if standardDeckCycleShuffleIfReached(deckName, info.deck, card.guid)==true then
							info.cards=info.deck.type=="Deck" and info.deck.getObjects() or {{guid=info.deck.guid}}
							info.nextCard=1
						else
							unitsInOffer[unitName]=true
							return {deck=info.deck, guid=card.guid}
						end
					end
				end
				return nil
			end

			--Work out every unit we want BEFORE physically drawing anything
			for a=1, gStates.totalUnitCount do
				local drawDeckName="Regular Unit"
				if gStates.eliteUnitsUsed==true	and (a==1 or a==3 or a==5 or a==7 or a==9) then drawDeckName="Elite Unit" end
				local drawDeckType=drawDecks[drawDeckName]
				local chosenUnit=getNextUniqueUnit(drawDeckType, drawDeckName)
				if chosenUnit~=nil then drawList[a]=chosenUnit else broadcastToAll("{en}Could not find enough unique units for the offer.{ru}Не удалось найти достаточно уникальных отрядов для предложения.{zh-tw}找不到足夠不同的部隊來填滿供應。{zh-cn}找不到足够不同的部队来填满供应。{ko}제안에 필요한 서로 다른 유닛을 충분히 찾지 못했습니다.{es}No se pudieron encontrar suficientes unidades diferentes para la oferta.{fr}Impossible de trouver suffisamment d’unités différentes pour l’offre.{pt-br}Não foi possível encontrar unidades diferentes suficientes para a oferta.{de}Es konnten nicht genügend unterschiedliche Einheiten für das Angebot gefunden werden.",	warningColor) break end
			end
			return drawList, deckInfo
		end
		local unitDrawList=getUnitDrawList(drawDecks)
		for a, draw in ipairs(unitDrawList) do
			safeTakeObject("Offers",draw.deck,{
				guid=draw.guid,
				position=unitOfferPosition(a,gStates.totalUnitCount),
				rotation={0,180,0},
				smooth=true,
				callback_function=function(drawnCard)
					local scale=unitOfferCardScale(gStates.totalUnitCount)
					drawnCard.setScale({scale,1,scale})
					safeWaitCondition("Offers",function()
						drawnCard.lock()
					end, function() return drawnCard.resting end)
				end
			})
		end
		--Place Monastery offer cards
		for i=1, gStates.monasteryCount, 1 do
			params.position=monasteryPlace[i]
			standardDeckCycleShuffleIfReached("Advanced Action")
			local drawnCard=getObjectFromGUID(getObjectFromGUID(drawDecks["Advanced Action"]).getObjects()[1].guid).takeObject(params)
			safeWaitCondition("Offers",function() drawnCard.lock() end, function() return drawnCard.resting end)
		end
	end
end

-- Monastery offer
monasteryOfferFirstEmptySlot=function()
	local occupied={}
	local zone=getObjectFromGUID(GUID.zone.unitOffer)
	if zone~=nil then
		for _,obj in pairs(zone.getObjects()) do
			if obj.type=="Card" or obj.type=="Deck" then
				local pos=obj.getPosition()
				if math.abs(pos[3]+10.2)<=1 then
					local slot=math.floor(((40.8-pos[1])/4.8)+0.5)
					if slot>=1 and slot<=6 then occupied[slot]=true end
				end
			end
		end
	end
	for slot=1,6 do if occupied[slot]~=true then return slot end end
	return nil
end

function handleMonasteryRevealed()
	gStates.monasteryCount=gStates.monasteryCount+1
	--Initial terrain reveals happen before the starting offers are built. Record the monastery now,
	--then let the first unitOffer() deal its Advanced Action once so setup does not deal-and-return it.
	if startingMapSetup==true then return end
	if gStates.monasteryCount>=0 then
		--Find the first free printed Monastery slot directly from the broad offer zone.
		local slot=monasteryOfferFirstEmptySlot()
		if slot==nil then return end
		local params={rotation={0,180,0},position={40.8-slot*4.8,0.98,-10.2}}
		--Play an advanced action card. Deck-cycle cleanup can briefly leave the draw zone without
		--a Card/Deck, so wait on the real source instead of spinning a Lua while loop around a callback.
		standardDeckCycleShuffleIfReached("Advanced Action")
		local function drawMonasteryAdvancedAction()
			local source=standardDeckCycleObject("Advanced Action")
			if source==nil then return false end
			local drawnCard=nil
			if source.type=="Deck" then
				drawnCard=safeTakeObject("Offers",source,params)
			elseif source.type=="Card" then
				drawnCard=source
				drawnCard.unlock()
				drawnCard.setPositionSmooth(params.position,false,false)
				drawnCard.setRotationSmooth(params.rotation,false,false)
			end
			if drawnCard==nil then return false end
			safeWaitCondition("Offers",function() if drawnCard~=nil then drawnCard.lock() end end,function()
				return drawnCard==nil or drawnCard.resting==true
			end,5,function() if drawnCard~=nil then drawnCard.lock() end end)
			broadcastToAll("{en}Monastery is teaching a new Advanced Action{ru}Монастырь обучает новому Особому действию{zh-tw}修道院现在传授新的高级行动{zh-cn}修道院现在传授新的高级行动{ko}수도원에 새로운 상급 액션이 추가되었습니다{es}El Monasterio está enseñando una nueva Acción Avanzada{fr}Le Monastère enseigne une nouvelle Action Avancée{pt-br}Monastério está encinsando uma nova Ação Avançada{de}Das Kloster lehrt eine neue fortgeschrittene Aktion", {1,1,0.5})
			return true
		end
		if drawMonasteryAdvancedAction()~=true then
			safeWaitCondition("Offers",function()
				if drawMonasteryAdvancedAction()~=true then error("Monastery Advanced Action source disappeared before it could be drawn.",2) end
			end,function()
				return standardDeckCycleObject("Advanced Action")~=nil
			end,5,function()
				error("Timed out waiting for the Monastery Advanced Action draw source.",2)
			end)
		end
	end
end

-- Main deed offer resizing
local OfferPause=false
function offerAdjust(player, mouseButton, id)
	if mouseButton=="-1" and OfferPause==false then
		OfferPause=true
		--update Offer size expected.
		if id=="e4372aOfferUp" then gStates.offerSize=gStates.offerSize+1 else gStates.offerSize=gStates.offerSize-1 end
		--move both decks and their detecting Zones, drop the decks onto existing cards.
		getObjectFromGUID(GUID.deck.spell).setPositionSmooth({(4.8*(gStates.offerSize+1))+21.6, 2.5, -22.2})
		getObjectFromGUID(GUID.deck.action).setPositionSmooth({(4.8*(gStates.offerSize+1))+21.6, 2.5, -16.2})
		getObjectFromGUID(GUID.zone.spellDeck).setPosition({(4.8*(gStates.offerSize+1))+21.6, 2.05, -22.2})
		getObjectFromGUID(GUID.zone.actionDeck).setPosition({(4.8*(gStates.offerSize+1))+21.6, 2.05, -16.2})
		--change size of offer Zone
		getObjectFromGUID(GUID.zone.offer).setScale({4.8*gStates.offerSize, 0.3, 9.57})
		getObjectFromGUID(GUID.zone.offer).setPosition({(2.4*(gStates.offerSize-1))+26.4, 1.13, -19.2})
		if id=="e4372aOfferUp" then
			--run fill slide after a wait frame.
			compactAndRefillDeedOffer()
		else
			--flip existing cards if shrinking the offer.
			for _, card in pairs(getObjectFromGUID(GUID.zone.offer).getObjects()) do
				if math.floor(((card.getPosition()[1]-21.6)/4.8)+0.5)==gStates.offerSize+1 and card.type=="Card" then
					standardDeckCycleMarkReturned(gameCardType(card), card)
					card.unlock()
					card.setRotation({0.00, 180.00, 180.00})
				end
			end
		end
		safeWaitFrames("Offers",function()
			OfferPause=false
			getObjectFromGUID(GUID.deck.spell).UI.setXmlTable({	{tag="Button", attributes={id="e4372aOfferUp", onClick="global/offerAdjust", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", height=150, width=240, position="60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
															children={	{tag="Image", attributes={id="e4372aOfferUpImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																		{tag="Text", attributes={fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text=">"}}}},
															{tag="Button", attributes={id="e4372aOfferDown", onClick="global/offerAdjust", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", height=150, width=240, position="-60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
															children={	{tag="Image", attributes={id="e4372aOfferDownImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																		{tag="Text", attributes={fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text="<"}}}}})
		end, 60)
	end
end

