	end)
	if started~=true then
		QuestPrivate.apocalypseQuestClearRewardCompletionGate(card,playerIndex)
		QuestPrivate.apocalypseQuestInterfaceAdd(card,true)
		finishQuestResolution(0.5)
	end
	return true,started
end

