	{{36.70,1.20,20.25},{37.33,1.14,21.45},{38.02,1.14,22.63},{36.11,1.14,19.04}},
	{{39.87,1.13,19.41},{38.79,1.13,18.75},{41.16,1.13,19.20},{40.33,1.13,20.87}},
