local function playerSetupInitializeState()
	gStates.playerSetupReady=false
	gStates.proxySetupReady=proxyPlayerIsActive()~=true
	gStates.volkareSetupReady=gStates.positionMageKnight[5]~="Volkare"
	gStates.mirrorSource=gStates.mirrorSource or {}
	gStates.mirrorSetupReady=false
	local mirrorExpected=0
	for seat=1,4 do
		if gStates.positionMageKnight[seat]~="nobody" then mirrorExpected=mirrorExpected+1 end
	end
	if mirrorExpected==0 then gStates.mirrorSetupReady=true end
	if gStates.heroChallenges==true then gStates.heroChallengeReservedSkills={} end
	return mirrorExpected
end

local function playerSetupResolveRandomMages()
	gStates.originalChoiceMageKnights={gStates.positionMageKnight[1],gStates.positionMageKnight[2],gStates.positionMageKnight[3],gStates.positionMageKnight[4],gStates.positionMageKnight[5]}
	for position=1,5 do
		if gStates.positionMageKnight[position]=="Random" or gStates.positionMageKnight[position]=="All Skills" then
			local randomMK=""
			local duplicate=true
			while duplicate==true do
				duplicate=false
				randomMK=mageKnights[math.random(1,#mageKnights-3)].mage
				for otherPosition=1,5 do
					if randomMK==gStates.positionMageKnight[otherPosition] then duplicate=true break end
				end
				if gStates.useCustomMageKnights==false and customMages[randomMK]~=nil then duplicate=true end
				if gStates.riseOfTheForgemasters~=3 and randomMK=="Jormund" then duplicate=true end
				if duplicate==false and gStates.heroChallenges==true then
					if heroChallengesData[randomMK]==nil then
						duplicate=true
					else
						local oldChoice=gStates.positionMageKnight[position]
						gStates.positionMageKnight[position]=randomMK
						local assignment=heroChallengeCountryAssignment(false)
						gStates.positionMageKnight[position]=oldChoice
						if assignment==nil then duplicate=true end
					end
				end
			end
			gStates.positionMageKnight[position]=randomMK
		end
	end
end

local function playerSetupFinishProxyComponents()
	if proxyPlayerIsActive()~=true then return end
	safeWaitCondition("SetupGame",function()
		proxySetupReferenceCards()
		proxySetupShieldBag()
		safeWaitCondition("SetupGame",function()
			gStates.proxySetupReady=true
		end,function()
			local shield=gStates.proxyShieldBagGUID~=nil and getObjectFromGUID(gStates.proxyShieldBagGUID) or nil
			return getObjectFromGUID("0e855c")~=nil and getObjectFromGUID("dbf566")~=nil and shield~=nil
		end,10,function() error("SetupGame timed out waiting for Proxy reference components.",2) end)
	end,function()
		return getObjectFromGUID(dummyBoard)~=nil and getObjectFromGUID(GUID.bag.apocalypseDragon)~=nil
	end,10,function() error("SetupGame timed out waiting for the Proxy setup sources.",2) end)
end

local function playerSetupPositionNeeded(position,context)
	return (gStates.positionMageKnight[position]~="nobody" and position<=4) or
		(gStates.positionMageKnight[5]~="nobody" and context.dummyPlayed==0)
end

local function playerSetupDeployCommonComponents(position,offsetPosition,context)
	--Layout everything from the Common Bag if needed
	local source=getObjectFromGUID(GUID.bag.common)
	if source==nil then error("SetupGame missing common player-component bag.",2) end
	local commonBag=source.clone()
	commonBag.setPosition({-60.0+offsetPosition, 1.5, -38.0})
	for i=1, #PLAYER_SETUP_COMMON_PARTS, 1 do
		local skip=0
		local part=PLAYER_SETUP_COMMON_PARTS[i]
		local params={position={part[1]+offsetPosition,part[2],part[3]}, rotation={0,180,0}, smooth=false}
		if (i>=2 and i<=7) or (i>=11 and i<=14) then params.rotation={0, 30, 0} end
		if position==5 then params.position[1]=params.position[1]-25.2 params.position[3]=params.position[3]+21.1 end
		if i==1 and position<=4 and gStates.positionMageKnight[position]~="nobody" then local obj=commonBag.takeObject() obj.destruct() skip=1 end--destroy the Dummy Board if this is a player
		if i==1 and position<=4 and gStates.positionMageKnight[position]=="nobody" then--change a player position into a dummy position
			getObjectFromGUID(playerBoard[position]).destruct()
			getObjectFromGUID(colorBand[position]).setScale({7.48, 0.01, 2.5})
			getObjectFromGUID(colorBand[position]).setColorTint("Black")
			getObjectFromGUID(colorBand[position]).setPosition({getObjectFromGUID(colorBand[position]).getPosition()[1]-12.5, 0.98, -30.0})
			if getObjectFromGUID(playAreaGuideText[position])~=nil then getObjectFromGUID(playAreaGuideText[position]).destruct() end
			if getObjectFromGUID(playAreaGuideBackground[position])~=nil then getObjectFromGUID(playAreaGuideBackground[position]).destruct() end
		end
		if i==8 and position<=4 and gStates.positionMageKnight[position]~="nobody" then--snuck the new poison card in with the regular wound cards
			commonBag.takeObject({guid="d1e6c3", position={-40.86+offsetPosition, 1.08, -36.10}, smooth=false}).lock()
		end
		if (gStates.positionMageKnight[position]=="nobody" or position==5) and ((i>=2 and gStates.positionMageKnight[5]=="Volkare") or (i>=8 and gStates.positionMageKnight[5]~="nobody")) then context.dummyPlayed=1 break end--just dummy board for Volkare
		if i>=11 and gStates.riseOfTheForgemasters<=1 then break end
		if i>=15 and gStates.riseOfTheForgemasters<=2 then break end
		if skip==0 then local obj=safeTakeObject("SetupGame",commonBag,params).lock() end
	end
	commonBag.destruct()
end

local function playerSetupCreateMirrorSource(position,offsetPosition,context)
	--mirror source
	if (gStates.positionMageKnight[position]~="nobody" and position~=5) then
		local source=getObjectFromGUID("b5a6ce")
		if source==nil then error("SetupGame missing mirror source object b5a6ce.",2) end
		local obj=source.clone()
		obj.setPosition({-58.25+offsetPosition, 0.98, -28.53})
		safeWaitCondition("SetupGame",function()
			obj.lock()
			obj.setRotation({0,180,0})
			obj.registerCollisions()
			gStates.mirrorSource[#gStates.mirrorSource+1]=obj.guid
			context.mirrorReady=context.mirrorReady+1
			if context.mirrorReady>=context.mirrorExpected then gStates.mirrorSetupReady=true end
		end,function() return obj~=nil and obj.resting==true end,10,function()
			error("SetupGame timed out waiting for a player mirror source to settle.",2)
		end)
	end
end

local function playerSetupMageBag(position,offsetPosition)
	local mage=gStates.positionMageKnight[position]
	if mage=="nobody" then mage=gStates.positionMageKnight[5] end
	for i=1,#mageKnights do
		if mage==mageKnights[i].mage then
			local source=getObjectFromGUID(mageKnights[i].bag)
			if source==nil then error("SetupGame missing Mage bag for "..tostring(mage)..".",2) end
			local playerBag=source.clone()
			playerBag.setPosition({-60.0+offsetPosition,1.5,-38.0})
			return playerBag
		end
	end
	error("SetupGame could not resolve a Mage bag for "..tostring(mage)..".",2)
end

local function playerSetupDeployUniqueComponents(orderIndex,position,offsetPosition,playerBag,context)
	--Layout everything from the mage bag assigned to the position
	--1-Turn Order, 2-Unique Cards, 3-Dummy Inventory, 4-Skills, 5-Skill Reference Card 1, 6-Skill Reference Card 2,
	--7-Avatar, 8-Shield Fame, 9-Shield Rep, 10-Shield Control, 11-Quest Marker,
	--12-Command token Blank, 13-5 Command Tokens
	local turnRef=1
	for i=1, #PLAYER_SETUP_UNIQUE_PARTS, 1 do
		local skip=0
		local part=PLAYER_SETUP_UNIQUE_PARTS[i]
		local params={position={part[1]+offsetPosition,part[2],part[3]}, smooth=false, setColorTint=""}
		--turn markers all go in Shuffled Order
		if i==1 then
			if (gStates.positionMageKnight[position]=="nobody" or position==5) then--Dummy and Volkare
				local dummyStats={	seatPos=position, mage=gStates.positionMageKnight[5], fame=0, fameGain=0, reputation=0, repGain=0, scoreLoop=0, hand=5, baseHand=5, handBonus=0, tactic=1, keepsBeat=0, gladesMarked={}, deedCount=11, discardCount=0, defeatedCities={}, deadDeckInventory={}, score={Glade=0, GraveYard=0},
									dummyCrystals={["Red"]=0, Blue=0, Green=0, ["White"]=0}}
				if scenarioList[gStates.scenarioRef][gStates.playersRef].dummyTacticSelection=="F" then
					params.position={-1.9, 0.96, -19.4}--if dummy draws first
					context.startPos[1]=1
					turnOrder[1]=dummyStats
				else
					params.position={-1.9, 0.96, -19.4-(gStates.playerCount*1.4)}--if dummy draw last
					context.startPos[gStates.playerCount+1]=1
					turnOrder[gStates.playerCount+1]=dummyStats
					turnOrder[gStates.playerCount+1].tactic=gStates.playerCount+1
					turnRef=gStates.playerCount+1
				end
			else--Mage Knights
				local duplicate=true
				while duplicate==true do
					duplicate=false
					turnRef=math.random(1, gStates.playerCount)
					if scenarioList[gStates.scenarioRef][gStates.playersRef].dummyTacticSelection=="F" then turnRef=turnRef+1 end
					if context.startPos[turnRef]==1 then duplicate=true else context.startPos[turnRef]=1 end
				end
				params.position={-1.9, 0.96, -19.4-((turnRef-1)*1.4)}
				turnOrder[turnRef]={seatPos=position,mage=gStates.positionMageKnight[position], fame=0, fameGain=0, reputation=0, repGain=0, scoreLoop=0, level=1, levelUp=0, influence=6, hand=5, baseHand=5, handBonus=0, tactic=turnRef, keepsBeat=0, gladesMarked={}, deedCount=11, discardCount=0, combatIconHide="None", defeatedCities={}, levelUpComplete=false, avatarLocation="portal", deadDeckInventory={}, levelingStats={}, score={Glade=0, GraveYard=0}}
			end
		end

		--Player Deed Deck
		if i==2 then
			params.rotation={180, 0, 0}--Orient cards face down
			if (gStates.positionMageKnight[position]=="nobody" or position==5) then--Dummy and Volkare deck go in different spot
				params.position={-67.96+offsetPosition, 1.17, -43.17}
			end
			params.callback_function=function(obj) obj.shuffle() end
		end

		--Dummy Invetory Card
		if i==3 and (gStates.positionMageKnight[position]~="nobody" and position<5) then local destr=safeTakeObject("SetupGame",playerBag,params) destr.destruct() skip=1 end--Delete Dummy Inventory when this is a player

		--Skills Container or Volkare's Level Chart
		if i==4 then
			if (gStates.positionMageKnight[position]=="nobody" or position==5) then--Checks if this position is a dummy
				if gStates.positionMageKnight[5]=="Volkare" then
					params.position={39.16, 0.97, 35.00}
					params.guid="b2ec85"--Volkare Level Chart: explicit GUID pull rather than relying on bag order.
				else
					if gStates.playerCount==1 and gStates.dummyAllSkills==false then
						params.position={-78.12+offsetPosition, 1.6, -31.03}--Skills container Position
					else
						local destr=safeTakeObject("SetupGame",playerBag,params) destr.destruct() skip=1
					end
				end
			end
		end

		--Skill Refernce Card 1
		if i==5 and (gStates.positionMageKnight[position]=="nobody" or position==5) and ((gStates.positionMageKnight[5]=="Volkare" or gStates.playerCount~=1) or gStates.dummyAllSkills==true) then
			local destr=safeTakeObject("SetupGame",playerBag,params) destr.destruct() skip=1
		end

		--Skill Refernce Card 2
		if i==6 then
			if (gStates.positionMageKnight[position]=="nobody" or position==5) and ((gStates.positionMageKnight[5]=="Volkare" or gStates.playerCount~=1) or gStates.dummyAllSkills==true) then
				local destr=safeTakeObject("SetupGame",playerBag,params) destr.destruct() skip=1
			else
				params.callback_function=function(obj) obj.lock() end
				if (gStates.coop==0 or gStates.WarOfFourComp==true) and gStates.positionMageKnight[position]~="Ymirgh" and gStates.positionMageKnight[position]~="Malek" and gStates.positionMageKnight[position]~="Duscenia" and gStates.positionMageKnight[position]~="Mevok" and gStates.positionMageKnight[position]~="Zirtae" then
					params.callback_function=function(ob) local obj=ob.setState(1) obj.lock() end
				end
			end
		end

		--Player Avater or Volkare's Wound Card
		if i==7 then
			if (gStates.positionMageKnight[position]=="nobody" or position==5) then--Checks if this position is a dummy
				if gStates.positionMageKnight[5]=="Volkare" then
					params.rotation={180, 0, 0}
					params.position={-67.96+offsetPosition, 1.17, -50.17}--Flip wound card over if Volkare
					params.callback_function=volkareSetup
				elseif proxyPlayerIsActive()==true then
					--Use one of the same four Portal-card positions as a normal player whenever one is free.
					--With four human players there is no fifth Portal position, so the Proxy starts on the Dummy board instead.
					local proxyPos,onPortal=proxySetupAvatarPosition()
					params.position=proxyPos
					params.callback_function=function(obj)
						obj.unlock()
						gStates.proxyAvatarOffMap=(onPortal~=true)
						local proxyIndex=proxyPlayerIndex()
						if proxyIndex~=nil and turnOrder[proxyIndex]~=nil then turnOrder[proxyIndex].avatarLocation=onPortal==true and "portal" or nil end
					end
				else
					local destr=safeTakeObject("SetupGame",playerBag,params) destr.destruct() skip=1
				end
			else
				--params.position[1]=params.position[1]-(offsetPosition/1.07)--Avatar
				local portal=PLAYER_SETUP_PORTAL_POSITIONS[orderIndex]
				params.position={portal[1],portal[2],portal[3]}
			end
		end

		--Fame Marker, Volkare's Terrain Tile or Dummy's Crystals. Dummy is Setup
		if i==8 then
			if (gStates.positionMageKnight[position]=="nobody" or position==5) then--Checks if this position is a dummy
				if position<5 then
					getObjectFromGUID(deedDeckZones[position]).setPosition({offsetPosition-68, 1.15, -43.20})
					getObjectFromGUID(deedDeckDiscardZones[position]).setPosition({offsetPosition-77.21, 1.15, -43.20})
				end
				if gStates.positionMageKnight[5]=="Volkare" then
					local cityBag=getObjectFromGUID(GUID.bag.terrain.leftCity)
					if cityBag==nil then error("Volkare setup missing City terrain bag",2) end
					if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" then
						--Keep the Camp out of the map zone until mapSetup is ready to reveal it.
						--Quest now uses the same staging rule so its Camp cannot begin a separate reveal timer.
						local bagPos=cityBag.getPosition()
						params.position={bagPos.x,bagPos.y+2,bagPos.z}
					else
						params.position={-12.0297, 2.0,  8.8586}--The War of Four camp tile position
					end
					runtimeMapSetHexFeature(GUID.tile.volkareCamp,"center","")
					gStates.hexOverideSave[GUID.tile.volkareCamp]={center=""}
					if gStates.randomTileOrientation==false then params.rotation={0, 180, 180} else params.rotation={0, math.random(1, 6)*60, 180} end
					params.guid=GUID.tile.volkareCamp
					local obj=safeTakeObject("SetupGame",cityBag,params)
					if obj==nil then error("Volkare setup missing Camp terrain tile 835c91 from City terrain bag",2) end
					--The Camp originated as a special Volkare component and historically had no Terrain tag.
					--Now that it lives in the City terrain pool, normalize it before it ever reaches the map.
					if obj.hasTag("Terrain")~=true then obj.addTag("Terrain") end
					skip=1
				else
					local params={position={-69.4, 1.41, -36.5}, rotation={0, 30, 0}, smooth=false, index=0}
					if position==5 then params.position[1]=params.position[1]-25.2 params.position[3]=params.position[3]+21.1 end
					params.position[1]=params.position[1]+offsetPosition
					for a=1, 3, 1 do
						params.position[1]=params.position[1]-(1.7)
						local obj=safeTakeObject("SetupGame",playerBag,params)
						obj.lock()
						local b=obj.getDescription()
						if scenarioList[gStates.scenarioRef][gStates.playersRef].dummyTacticSelection=="F" then
							turnOrder[1].dummyCrystals[b]=turnOrder[1].dummyCrystals[b]+1
						else
							turnOrder[gStates.playerCount+1].dummyCrystals[b]=turnOrder[gStates.playerCount+1].dummyCrystals[b]+1
						end
					end
					break
				end
			else
				params.position[1]=(params.position[1]-(offsetPosition/1.032))+(5.3*gStates.blitz)--Fame Marker
			end
		end

		--Reputation Marker or Volkare's Avatar
		if i==9 then
			if (gStates.positionMageKnight[position]=="nobody" or position==5) then--Checks if this position is a dummy
				if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" then
					params.position={-37.2305, 1.6, -5.6911}--Volkare's Return Avatar position
				else
					params.position={-12.0297, 1.6, 8.8586}--Volkare's Quest Avatar position
				end
				local obj=safeTakeObject("SetupGame",playerBag,params)
				--Volkare is stored in the Mage bag before the map exists. Keep him physical so the
				--starting terrain can lift/settle him normally; setup locks him only after map completion.
				if gStates.positionMageKnight[5]=="Volkare" and obj~=nil then obj.unlock() end
				skip=1
			else
				local blitzSub=gStates.blitz
				local reputationPosition=PLAYER_SETUP_REPUTATION_POSITIONS[blitzSub-gStates.rampage+3][position]
				params.position={reputationPosition[1],reputationPosition[2],reputationPosition[3]}--Reputation Marker
				turnOrder[turnRef].reputation=(0+blitzSub-gStates.rampage)*2
			end
		end

		-- or Volkare's Arrow Guide or Volkares Dice
		if i==10 then
			if ((position<5 and gStates.positionMageKnight[position]=="nobody" and gStates.positionMageKnight[5]=="Volkare") or gStates.positionMageKnight[position]=="Volkare") then
				params.position={-72.89+offsetPosition,1.5,-33.0}--Volkare Dice
			end
		end

		--or Volkares Scenario Reference Card
		if i==11 then
			if (position<5 and gStates.positionMageKnight[position]=="nobody" and gStates.positionMageKnight[5]=="Volkare") or gStates.positionMageKnight[position]=="Volkare" then
				params.position={-72.5+offsetPosition, 1.06, -48.23}
				params.callback_function=function(obj) obj.lock() end
				if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" then
					params.callback_function=function(ob) local obj=ob.setState(2) obj.lock() end
				end
			end
		end

		--Volkare's Marker
		if i==12 then
			if (position<5 and gStates.positionMageKnight[position]=="nobody" and gStates.positionMageKnight[5]=="Volkare") or gStates.positionMageKnight[position]=="Volkare" then
				params.position={-76+offsetPosition, 1.16, -31}
				params.callback_function=function(obj) obj.lock() end
			else
				params.rotation={0.00, 180.00, 180.00}
			end
		end

		if i==13 then
			if (position<5 and gStates.positionMageKnight[position]=="nobody" and gStates.positionMageKnight[5]=="Volkare") or gStates.positionMageKnight[position]=="Volkare" then
				if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" then
					params.position={-37.23, 2.5, -5.69}
					params.rotation={0.0, 210.0, 0.0}--Volkare's Return Guide position
					params.callback_function=function(guide)
						safeWaitCondition("SetupGame",function()
							guide.jointTo(getObjectFromGUID(volkare.model),{["type"]="Fixed"})
						end,function() return guide~=nil and guide.resting==true and getObjectFromGUID(volkare.model)~=nil end,10,function()
							error("SetupGame timed out waiting to attach Volkare's Return guide.",2)
						end)
					end
				else
					params.position={-12.03, 2.5, 8.86}--Volkare's Quest Guide position
					params.rotation={0.0, 210.0, 0.0}
					params.callback_function=function(guide)
						safeWaitCondition("SetupGame",function()
							guide.setState(2)
							safeWaitCondition("SetupGame",function()
								getObjectFromGUID("be2dc2").jointTo(getObjectFromGUID(volkare.model),{["type"]="Fixed"})
							end,function() return getObjectFromGUID("be2dc2")~=nil and getObjectFromGUID(volkare.model)~=nil end,10,function()
								error("SetupGame timed out waiting for Volkare's Quest guide state.",2)
							end)
						end,function() return guide~=nil and guide.resting==true and getObjectFromGUID(volkare.model)~=nil end,10,function()
							error("SetupGame timed out waiting to prepare Volkare's Quest guide.",2)
						end)
					end
				end
				skip=1
			end
		end

		--Volkare is Setup
		if i==13 and (gStates.positionMageKnight[position]=="nobody" or position==5) then break end

		if position==5 and i~=1 then params.position[1]=params.position[1]-25.2 params.position[3]=params.position[3]+21.1 end
		if skip==0 then
			local obj=safeTakeObject("SetupGame",playerBag,params)
			if (i==4 or i==5 or i==10 or i==11 or i==13) and gStates.positionMageKnight[position]~="nobody" and position<5 then obj.lock() end--lock player board components
			if (i==1 or i==3 or i==4 or i==5 or i==11) and (gStates.positionMageKnight[position]=="nobody" or position==5) then obj.lock() end--lock dummy board components
			if i==1 then turnOrder[turnRef].turnOrderTokenGUID=obj.guid end
			if (i==4 and gStates.positionMageKnight[position]~="nobody" and position<=4) or (i==4 and gStates.playerCount==1) then
				turnOrder[turnRef].skillBagGUID=obj.guid
				--Hero Challenges reserve the prescribed first Skill before the Hero's remaining Skill bag is shuffled.
				if gStates.heroChallenges==true and position<=4 and gStates.positionMageKnight[position]~="nobody" then
					local challenge=heroChallengesData[turnOrder[turnRef].mage]
					if challenge~=nil then
						local reserved=obj.takeObject({guid=challenge.skillGUID,position={(position*40)-113.0,1.5,-48.9},rotation={0,180,0},smooth=false})
						--turnOrder is re-sorted during play, so reserve by stable Mage Knight identity rather than array index.
						if reserved~=nil then reserved.lock() gStates.heroChallengeReservedSkills[turnOrder[turnRef].mage]=reserved.guid end
					end
				end
				obj.shuffle()
			end
			if i==8 and gStates.positionMageKnight[position]~="nobody" and position<=4 then turnOrder[turnRef].fameGUID=obj.guid end
			if i==9 and gStates.positionMageKnight[position]~="nobody" and position<=4 then turnOrder[turnRef].reputationGUID=obj.guid end
			if i==13 and gStates.positionMageKnight[position]~="nobody" and position<=4 then turnOrder[turnRef].commandGUID=obj.guid end
			if i==1 and gStates.positionMageKnight[position]~="nobody" and position<=4 then
				local inventoryImage=PLAYER_SETUP_INVENTORIES[gStates.positionMageKnight[position]]
				if inventoryImage~=nil then getObjectFromGUID(playerBoard[position]).addDecal({name="Mage Inventory", url=inventoryImage, position={1.735, 0.11, -0.32}, rotation={90.0, 180.0, 0.0}, scale={1.164, 1.219, 10}}) end
				turnOrder[turnRef].playerBoardGUID=playerBoard[position]
			end
		end
	end
	if gStates.positionMageKnight[position]=="Mevok" then
		local obj=safeTakeObject("SetupGame",playerBag,{guid="32bc89", position={-77.30+offsetPosition, 1.05, -53.65}, smooth=false, setColorTint="", callback_function=function(obj) obj.lock() end})
		local obj=safeTakeObject("SetupGame",playerBag,{guid="2dbfde", position={-73.90+offsetPosition, 1.05, -53.65}, smooth=false, setColorTint="", callback_function=function(obj) obj.lock() end})
	end
end

local function playerSetupCleanupPosition(position)
	getObjectFromGUID(deedDeckZones[position]).destruct()
	getObjectFromGUID(deedDeckDiscardZones[position]).destruct()
	getObjectFromGUID(colorBand[position]).destruct()
	if position~=5 then getObjectFromGUID(playerBoard[position]).destruct() end
	if getObjectFromGUID(playAreaGuideText[position])~=nil then getObjectFromGUID(playAreaGuideText[position]).destruct() end
	if getObjectFromGUID(playAreaGuideBackground[position])~=nil then getObjectFromGUID(playAreaGuideBackground[position]).destruct() end
end

local function playerSetupDeployPosition(orderIndex,position,context)
	if playerSetupPositionNeeded(position,context)~=true then
		playerSetupCleanupPosition(position)
		return
	end
	local offsetPosition=position*40-40
	playerSetupDeployCommonComponents(position,offsetPosition,context)
	playerSetupCreateMirrorSource(position,offsetPosition,context)
	local playerBag=playerSetupMageBag(position,offsetPosition)
	playerSetupDeployUniqueComponents(orderIndex,position,offsetPosition,playerBag,context)
	playerBag.destruct()
end

function setupPlayersReady()
	if gStates==nil or gStates.playerSetupReady~=true or gStates.mirrorSetupReady~=true then return false end
	if proxyPlayerIsActive()==true and gStates.proxySetupReady~=true then return false end
	if gStates.positionMageKnight[5]=="Volkare" and gStates.volkareSetupReady~=true then return false end
	return true
end

--Go through the five player positions and put out pieces based on the game settings
function playerSetup()
	local context={
		mirrorExpected=playerSetupInitializeState(),
		mirrorReady=0,
		dummyPlayed=0,
		startPos={0,0,0,0,0}
	}
	playerSetupResolveRandomMages()

	--The selected Mage Knight's normal Shield source may belong to a player position that is cleaned
	--before the Dummy/Proxy position is built. Preserve a dedicated Proxy copy first.
	if proxyPlayerIsActive()==true then proxyStageShieldBag() end

	for orderIndex,position in ipairs(PLAYER_SETUP_POSITION_ORDER) do
		playerSetupDeployPosition(orderIndex,position,context)
	end
	playerSetupFinishProxyComponents()
	gStates.playerSetupReady=true
end

--Setup additional volkare components (Skill for Solo, Unit Crytals, And Monster Pugs)
function volkareSetup()
	--Add wounds to Volkare's Deck
	local VolkareWounds=20
	local PlayerBag={}
	if gStates.gameScenario=="The War of Four" then gStates.volkareRaceLevel=3 end
	if gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four" then VolkareWounds=24-(4*gStates.volkareRaceLevel) else VolkareWounds=21-(3*gStates.volkareRaceLevel)-(2*gStates.blitz) end
	if gStates.gameScenario=="Custom" then VolkareWounds=0 end
	for i=1, VolkareWounds, 1 do
		getObjectFromGUID(GUID.deck.volkare).putObject(getObjectFromGUID(GUID.card.volkareWoundTemplate).clone({position={getObjectFromGUID(GUID.deck.volkare).getPosition()[1], -2, getObjectFromGUID(GUID.deck.volkare).getPosition()[3]}}))--The wound card to Volkare's Deck
	end
	getObjectFromGUID(GUID.deck.volkare).shuffle()
	if gStates.gameScenario~="Custom" then getObjectFromGUID(GUID.card.volkareWoundTemplate).destruct() end--The wound card

	--Add a random skill set if solo playing
	if gStates.playerCount==1 and gStates.volkareSkills~="All Skills" then
		local duplicate=true
		local randomMKIndex=1
		if gStates.volkareSkills=="Random" then
			while duplicate==true do
				duplicate=false
				randomMKIndex=math.random(1, #mageKnights-3)
				local randomMK=mageKnights[randomMKIndex].mage
				for i=1, 4, 1 do
					if randomMK==gStates.positionMageKnight[i] then duplicate=true end
				end
				if gStates.useCustomMageKnights==false and customMages[randomMK]~=nil then duplicate=true end
				if gStates.riseOfTheForgemasters~=3 and randomMK=="Jormund" then duplicate=true end
			end
		else
			for index, mageDetails in ipairs(mageKnights) do
				if mageDetails.mage==gStates.volkareSkills then randomMKIndex=index break end
			end
		end
		local PlayerBag=getObjectFromGUID(mageKnights[randomMKIndex].bag).clone({position={getObjectFromGUID(dummyBoard).getPosition()[1]-10.16, 5.15, getObjectFromGUID(dummyBoard).getPosition()[3]+12.14}})
		local skillBag=PlayerBag.takeObject({index=12})--Skill Container
		skillBag.lock()
		turnOrder[2].skillBagGUID=skillBag.guid--he doesn't get skills in more than solo
		skillBag.setPosition({getObjectFromGUID(dummyBoard).getPosition()[1]-5.62, 1.6, getObjectFromGUID(dummyBoard).getPosition()[3]+6.97})
		skillBag.shuffle()
		local skillRef=PlayerBag.takeObject({index=10})
		skillRef.lock()
		skillRef.setPosition({getObjectFromGUID(dummyBoard).getPosition()[1]-4.4, 1.05, -49})
		local skillRef=PlayerBag.takeObject({index=10})
		skillRef.lock()
		skillRef.setPosition({getObjectFromGUID(dummyBoard).getPosition()[1]-7.8, 1.05, -49})
		PlayerBag.destruct()
	end

	--Add Volkare unit crystals based on Player count and Race Level.
	--Each die face owns a physical Unit-offer slot; the broad offer zone replaces the old slot zones.
	gStates.volkareUnitCrystals={}
	if gStates.gameScenario~="The War of Four" then
		local VolkareUnits=gStates.playerCount+(gStates.volkareRaceLevel-1)
		local PlayerBag=getObjectFromGUID(GUID.bag.volkare).clone()
		local obj=PlayerBag.takeObject({position={37, 1.29, -1.14}, guid="1212f3"})--Crystal Container
		obj.shuffle()
		for i=1, VolkareUnits, 1 do
			local obj2=obj.takeObject()
			obj2.lock()
			obj2.setPosition({36.0-(4.8*(i-1)), 1.29, -1.15})
			obj2.setRotation({0, 30, 0})
			gStates.volkareUnitCrystals[obj2.getName()]={slot=i,crystalGUID=obj2.guid}
		end
		PlayerBag.destruct()
		obj.destruct()
	end

	--add unit tokens based on Volkare's Level
	gStates.volkareLevel=gStates.cityLevels[#gStates.cityLevels]
	table.remove(gStates.cityLevels, #gStates.cityLevels)
	if gStates.monsterSetupReady==true then
		volkareArmy()
	else
		safeWaitCondition("SetupGame",volkareArmy,function() return gStates.monsterSetupReady==true end,10,function()
			error("SetupGame timed out waiting for monster piles before building Volkare's Army.",2)
		end)
	end

	--Move reminder Tokens
	getObjectFromGUID(GUID.bag.volkare).takeObject({rotation={0.0, 180.0, 0.0}, position={getObjectFromGUID(cityScriptZones[volkare.discZone].cityCard).getPosition()[1]+2.2, 1.5, getObjectFromGUID(cityScriptZones[volkare.discZone].cityCard).getPosition()[3]+2.2}, guid=GUID.bag.volkareReminder})
end

--add unit tokens based on Volkare's Level
function volkareArmy()
	gStates.cityMonsterQty[volkare.model]={}
	if gStates.gameScenario~="Custom" then
		local VolkareArmy={	{},		  {},		{},		  {0,1,1,2},{1,0,1,2}, {1,0,1,3}, {1,0,2,2}, {1,1,2,2}, {1,1,2,3}, {1,1,2,5}, {2,0,2,5}, {2,0,2,6}, {2,0,2,7}, {2,0,3,6}, {2,1,3,6},
							{2,2,4,4},{2,2,4,5},{2,2,4,6},{2,2,4,8},{2,2,4,10},{3,1,4,10},{4,0,4,10},{4,0,4,11},{4,0,4,12},{4,0,4,13},{4,0,4,14},{4,0,5,13},{4,0,6,12},{4,1,6,12},{4,2,6,12}}
		--{no. White Units, No. Gray Units, No. Red Units, No. Green Units}(Level 4 to 15 shown, other levels made by adding levels togeather)
		local PugDraw={monsterPiles.white,monsterPiles.gray,monsterPiles.red,monsterPiles.green}
		--{White Unit Bag, Gray Unit Bag, Red Unit Bag, Green Unit Bag}
		if (gStates.volkareLevel<=20 and gStates.removeShadesOfTezlaMonsters==true and gStates.removeLostLegionExpansion==true) or (gStates.volkareLevel<=30 and (gStates.removeShadesOfTezlaMonsters~=true or gStates.removeLostLegionExpansion==false)) or (gStates.removeShadesOfTezlaMonsters~=true and gStates.removeLostLegionExpansion==false) then
			for i=1, 4, 1 do
				local LoopsNeeded=math.ceil(gStates.volkareLevel/30)
				local levelConverted=math.floor(gStates.volkareLevel/LoopsNeeded)
				local leftover=gStates.volkareLevel-(LoopsNeeded*levelConverted)+levelConverted
				getObjectFromGUID(PugDraw[i]).shuffle()
				for x=1, LoopsNeeded, 1 do
					if x==LoopsNeeded then levelConverted=leftover end
					for a=1, VolkareArmy[levelConverted][i], 1 do
						local params={position={0, 0, 0}, rotation={0, 180, 180}}
						params.position[1]=getObjectFromGUID(dummyBoard).getPosition()[1]+(0.2*a)+(2.2*x)+2.5
						params.position[2]=getObjectFromGUID(dummyBoard).getPosition()[2]+(0.2*a)+1
						params.position[3]=getObjectFromGUID(dummyBoard).getPosition()[3]+(0.2*a)+(2.2*i)-2.9
						local obj2=getObjectFromGUID(PugDraw[i]).takeObject(params)
						gStates.cityMonsterQty[volkare.model][obj2.guid]="alive"
						gStates.monsterPlayLocation[obj2.guid]={params.position[1], params.position[2], params.position[3]}
					end
				end
			end
		else
			broadcastToAll("{en}Volkare's Army is too large with your setup. You will need to create it when you fight him for the first time{ru}Армия Волкара слишком велика с вашей настройкой. Вам нужно будет создать ее, когда вы сразитесь с ним в первый раз{zh-tw}现在不用设置沃里卡的军队, 你将在首次和他交锋时设置这些{zh-cn}现在不用设置沃里卡的军队, 你将在首次和他交锋时设置这些{ko}볼케어의 군대 규모가 너무 큽니다. 플레이어가 직접 첫 전투 세팅을 준비해주세요.{es}El ejército de Volkare es demasiado grande con tu configuración. Necesitarás crearlo cuando luches contra él por primera vez.{fr}L'armée de Volkare est trop grande avec votre configuration. Vous devrez le créer lorsque vous le combattrez pour la première fois{pt-br}O exército de Volkare é muito grande com a sua configuração. Você precisará criá-lo quando você for lutar com ele pela primeira vez{de}Volkare's Armee ist mit deiner Aufstellung zu groß. Du musst sie erstellen, wenn du zum ersten Mal gegen ihn kämpfst.", warningColor)
		end
		--Change his models level
		getObjectFromGUID(volkare.model).setCustomObject({diffuse=cityLevelImage[volkare.model][math.floor(gStates.volkareLevel/math.ceil(gStates.volkareLevel/15))]})
		getObjectFromGUID(volkare.model).reload()
		safeWaitCondition("SetupGame",function()
			local model=getObjectFromGUID(volkare.model)
			--This flag means the model reload is complete, not that Volkare is ready to be frozen.
			--The initial map cannot start until this flag is true, so locking here would guarantee
			--that he is frozen on the bare table before his starting terrain is constructed.
			if model~=nil then model.unlock() end
			gStates.volkareSetupReady=true
		end,function()
			local model=getObjectFromGUID(volkare.model)
			return model~=nil and model.resting==true
		end,10,function() error("SetupGame timed out waiting for Volkare's model to reload.",2) end)
		cityLevelButtons(volkare.model, "Volkar")
	else
		gStates.volkareSetupReady=true
	end
end

end)
__bundle_register("SetupGame.Components", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Physical setup for monster pools and Tezla scenario components.
-- The save starts with the ordinary monster pools already containing all Lost Legion and Tezla
-- enemy tokens. Membership is defined once in setupContentRoster; setup only removes excluded
-- tokens or moves Tezla tokens into the dedicated faction pools required by a scenario.

local monsterSetupMoves={}
local monsterSetupLeadersReady=false

local lostLegionEnemyPools=setupContentRoster.lostLegion.enemies
local darkCrusaderEnemyPools=setupContentRoster.shadesOfTezla.enemies.dark
local elementalistEnemyPools=setupContentRoster.shadesOfTezla.enemies.elementalist

local function monsterBagContainsGUID(bag,guid)
	if bag==nil then return false end
	for _,entry in ipairs(bag.getObjects()) do
		if entry.guid==guid then return true end
	end
	return false
end

local function moveMonsterToken(sourceGUID,tokenGUID,destinationGUID)
	local source=getObjectFromGUID(sourceGUID)
	if source==nil then error("SetupGame missing monster source bag "..tostring(sourceGUID),2) end
	local token=safeTakeObject("SetupGame",source,{guid=tokenGUID,smooth=false})
	if token==nil then error("SetupGame could not extract monster token "..tostring(tokenGUID).." from "..tostring(sourceGUID),2) end
	if destinationGUID~=nil then
		local destination=getObjectFromGUID(destinationGUID)
		if destination==nil then error("SetupGame missing monster destination bag "..tostring(destinationGUID),2) end
		destination.putObject(token)
	else
		local trash=getObjectFromGUID(trashCan)
		if trash==nil then error("SetupGame missing trash chest while removing monster token "..tostring(tokenGUID),2) end
		trash.putObject(token)
	end
	monsterSetupMoves[#monsterSetupMoves+1]={source=sourceGUID,destination=destinationGUID,guid=tokenGUID}
end

local function moveMonsterPoolSet(poolSet,toFaction)
	for _,pool in ipairs(poolSet) do
		for _,tokenGUID in ipairs(pool.tokens) do
			moveMonsterToken(pool.source,tokenGUID,toFaction==true and pool.destination or nil)
		end
	end
end

local function destroyMonsterBags(guids)
	for _,guid in ipairs(guids) do
		local bag=getObjectFromGUID(guid)
		if bag~=nil then bag.destruct() end
	end
end

local function configurePreloadedTokenBags(guids,keep,label)
	for _,guid in ipairs(guids) do
		local bag=getObjectFromGUID(guid)
		if keep==true then
			if bag==nil then error("SetupGame missing preloaded "..tostring(label).." bag "..tostring(guid),2) end
			bag.lock()
		elseif bag~=nil then
			bag.destruct()
		end
	end
end

local function monsterPoolConfigurationReady()
	for _,move in ipairs(monsterSetupMoves) do
		local source=getObjectFromGUID(move.source)
		if source==nil or monsterBagContainsGUID(source,move.guid)==true then return false end
		if move.destination~=nil then
			local destination=getObjectFromGUID(move.destination)
			if destination==nil or monsterBagContainsGUID(destination,move.guid)~=true then return false end
		end
	end
	return true
end

local function shuffleMonsterPiles()
	local toBeShuffled={monsterPiles.redElem,monsterPiles.tanElem,monsterPiles.greenElem,monsterPiles.rewardElem,
		monsterPiles.redDark,monsterPiles.tanDark,monsterPiles.greenDark,monsterPiles.rewardDark,
		monsterPiles.rewardApoc,monsterPiles.rewardCouncil,monsterPiles.possessed,
		monsterPiles.tan,monsterPiles.green,monsterPiles.red,monsterPiles.purple,monsterPiles.white,monsterPiles.gray,monsterPiles.yellow}
	for _,guid in ipairs(toBeShuffled) do
		local pile=getObjectFromGUID(guid)
		if pile~=nil then pile.shuffle() end
	end
	gStates.monsterSetupReady=true
end

local function deployTezlaComponents(entries,includeScenarioComponents)
	local tezlaBag=getObjectFromGUID(GUID.bag.tezla)
	if tezlaBag==nil then error("SetupGame missing Shades of Tezla component bag.",2) end
	for _,entry in ipairs(entries) do
		if entry.always==true or includeScenarioComponents==true then
			local obj=safeTakeObject("SetupGame",tezlaBag,{
				guid=entry.guid,
				position=entry.position,
				rotation={0,180,entry.flip or 0},
				smooth=false})
			if obj==nil then error("SetupGame could not deploy Shades of Tezla component "..tostring(entry.guid),2) end
			obj.lock()
		end
	end
end

--Monster Pool Setup
function monsterSetup()
	monsterSetupMoves={}
	monsterSetupLeadersReady=false
	gStates.monsterSetupReady=false

	--Lost Legion enemies are already in the seven normal pools. Removing the expansion is subtractive.
	if gStates.removeLostLegionExpansion==true then moveMonsterPoolSet(lostLegionEnemyPools,false) end

	local scenario=gStates.gameScenario
	local darkSupport=scenario=="Life and Death" or scenario=="The War of Four" or scenario=="Ultimate Conquest" or scenario=="The Realm of the Dead Blitz"
	local elemSupport=scenario=="Life and Death" or scenario=="The War of Four" or scenario=="Ultimate Conquest" or scenario=="The Hidden Valley Blitz"
	local darkFactionEnemies=scenario=="Life and Death" or scenario=="The War of Four" or scenario=="The Realm of the Dead Blitz"
	local elemFactionEnemies=scenario=="Life and Death" or scenario=="The War of Four" or scenario=="The Hidden Valley Blitz"
	local darkBags={monsterPiles.greenDark,monsterPiles.tanDark,monsterPiles.redDark}
	local elemBags={monsterPiles.greenElem,monsterPiles.tanElem,monsterPiles.redElem}
	local tezlaRewardsNeeded=gStates.removeShadesOfTezlaMonsters~=true or gStates.useCustomMageKnights==true
	configurePreloadedTokenBags({
		monsterPiles.rewardDark,GUID.bag.discard.darkReward,
		monsterPiles.rewardElem,GUID.bag.discard.elementalistReward
	},tezlaRewardsNeeded,"Shades of Tezla reward")
	local darkComponents={
		{guid=darkCrusader.disc,position={-52.00,0.97,6.50}},
		{guid=darkCrusader.token,position={-55.30,0.97,10.20}},
		{guid=darkCrusader.terrainHex,position={-34.70,0.98,-27.00}},
		{guid="f8c83e",position={-65.16,0.98,-5.50}},
		{guid=GUID.bag.cemetery,position={-36.09,0.97,-24.87},flip=180},
		{guid="2ca34f",position={-53.50,0.98,15.50},always=true}
	}
	local elemComponents={
		{guid=elementalist.disc,position={-63.50,0.97,6.50}},
		{guid=elementalist.token,position={-67.00,0.97,10.20}},
		{guid=elementalist.terrainHex,position={-37.49,0.98,-27.00}},
		{guid="7121c7",position={-70.16,0.98,-5.50}},
		{guid="8fe07e",position={-49.50,0.98,15.50},always=true}
	}

	if gStates.removeShadesOfTezlaMonsters~=true then
		deployTezlaComponents(darkComponents,darkSupport)
		deployTezlaComponents(elemComponents,elemSupport)

		--The six faction bags load empty in their table positions. Fill only the faction pools used by
		--this scenario; otherwise delete those bags and leave their enemies in the normal pools.
		if darkFactionEnemies==true then moveMonsterPoolSet(darkCrusaderEnemyPools,true) else destroyMonsterBags(darkBags) end
		if elemFactionEnemies==true then moveMonsterPoolSet(elementalistEnemyPools,true) else destroyMonsterBags(elemBags) end
	else
		moveMonsterPoolSet(darkCrusaderEnemyPools,false)
		moveMonsterPoolSet(elementalistEnemyPools,false)
		destroyMonsterBags(darkBags)
		destroyMonsterBags(elemBags)
		--Custom Mage Knights can still use Tezla rewards even when the Tezla enemies are removed.
		if gStates.useCustomMageKnights==true then
			deployTezlaComponents(darkComponents,false)
			deployTezlaComponents(elemComponents,false)
		end
	end

	if scenario=="Life and Death" then
		local factionDie=safeTakeObject("SetupGame",getObjectFromGUID(GUID.bag.tezla),{guid="27911e",smooth=false,position={-50.63,1.47,1.16}})
		if factionDie==nil then error("SetupGame could not deploy the Life and Death faction die.",2) end
	end
	--Set faction leader levels when the physical leader pieces have actually registered.
	local leaderLevel=gStates.cityLevels[1]
	local scenario=gStates.gameScenario
	local expectDark=gStates.removeShadesOfTezlaMonsters~=true and
		(scenario=="Life and Death" or scenario=="The War of Four" or scenario=="Ultimate Conquest" or scenario=="The Realm of the Dead Blitz")
	local expectElem=gStates.removeShadesOfTezlaMonsters~=true and
		(scenario=="Life and Death" or scenario=="The War of Four" or scenario=="Ultimate Conquest" or scenario=="The Hidden Valley Blitz")

	local function leaderObjectsReady()
		if expectDark and (getObjectFromGUID(darkCrusader.disc)==nil or getObjectFromGUID(darkCrusader.token)==nil) then return false end
		if expectElem and (getObjectFromGUID(elementalist.disc)==nil or getObjectFromGUID(elementalist.token)==nil) then return false end
		return true
	end

	--reload() destroys and recreates the physical object. Existence alone is not a completion signal:
	--wait for the replacement leader pieces to be registered and settled before advertising setup readiness.
	local function leaderObjectSettled(guid)
		local obj=getObjectFromGUID(guid)
		return obj~=nil and obj.spawning~=true and obj.resting==true
	end
	local function leaderObjectsSettled()
		if expectDark and (leaderObjectSettled(darkCrusader.disc)~=true or leaderObjectSettled(darkCrusader.token)~=true) then return false end
		if expectElem and (leaderObjectSettled(elementalist.disc)~=true or leaderObjectSettled(elementalist.token)~=true) then return false end
		return true
	end

	local function finishLeaderSetup()
		local darkToken=getObjectFromGUID(darkCrusader.token)
		if darkToken~=nil then
			darkToken.addDecal({name="NightRules",position={0.85,0.15,-0.85},rotation={90,180,0},scale={0.6,0.6,1},url=nightRulesDecal})
			if gStates.monsterPerks[darkCrusader.token]==nil then gStates.monsterPerks[darkCrusader.token]={nightRules=true} else gStates.monsterPerks[darkCrusader.token].nightRules=true end
		end
		monsterSetupLeadersReady=true
	end

	local function applyLeaderSetup()
		if scenario~="Ultimate Conquest" then
			local elemDisc=getObjectFromGUID(elementalist.disc)
			local elemToken=getObjectFromGUID(elementalist.token)
			if elemDisc~=nil and elemToken~=nil then
				elemDisc.setCustomObject({image=leaderData[elementalist.terrainHex][leaderLevel].discImg})
				elemDisc.reload()
				elemToken.setCustomObject({image=leaderData[elementalist.terrainHex][leaderLevel].tokenImg})
				elemToken.setName("Elementalist Leader Level "..leaderLevel)
				elemToken.reload()
				monsterPugs[elementalist.token]=leaderData[elementalist.terrainHex][leaderLevel].abilities
				gStates.elementalistLevel=leaderLevel
				gStates.cityMonsterQty[elementalist.terrainHex]={[elementalist.token]="alive",extra={}}
				gStates.monsterPlayLocation[elementalist.token]={-55.3,3.0,15.3}
			end
			local darkDisc=getObjectFromGUID(darkCrusader.disc)
			local darkToken=getObjectFromGUID(darkCrusader.token)
			if darkDisc~=nil and darkToken~=nil then
				darkDisc.setCustomObject({image=leaderData[darkCrusader.terrainHex][leaderLevel].discImg})
				darkDisc.reload()
				darkToken.setCustomObject({image=leaderData[darkCrusader.terrainHex][leaderLevel].tokenImg})
				darkToken.setName("Dark Crusader Leader Level "..leaderLevel)
				darkToken.reload()
				monsterPugs[darkCrusader.token]=leaderData[darkCrusader.terrainHex][leaderLevel].abilities
				gStates.darkCrusaderLevel=leaderLevel
				gStates.cityMonsterQty[darkCrusader.terrainHex]={[darkCrusader.token]="alive",extra={}}
				gStates.monsterPlayLocation[darkCrusader.token]={-55.3,3.0,6.7}
			end
		end
		if expectDark or expectElem then
			safeWaitCondition("SetupGame",finishLeaderSetup,leaderObjectsSettled,10,function()
				error("SetupGame timed out waiting for faction leaders to reload and settle.",2)
			end)
		else
			finishLeaderSetup()
		end
	end

	if leaderObjectsReady()==true then
		applyLeaderSetup()
	else
		safeWaitCondition("SetupGame",applyLeaderSetup,leaderObjectsReady,10,function()
			error("SetupGame timed out waiting for faction leader setup objects.",2)
		end)
	end

	--Monster piles are ready only when every merge is physically reflected in its destination and
	--the optional faction-leader setup has completed.
	safeWaitCondition("SetupGame",shuffleMonsterPiles,function()
		return monsterSetupLeadersReady==true and monsterPoolConfigurationReady()==true
	end,15,function() error("SetupGame timed out waiting for monster setup to complete.",2) end)
end

end)
__bundle_register("PlayingGame.PlayerBoard.Events", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Module-private helpers. Predeclared so forward references keep resolving locally.
local removeCardRemoveDecal

-- Player-board scripting-zone reactions dispatched by PlayingGame.Events.

local crystalManaNames={["Red Mana"]=true,["Green Mana"]=true,["Blue Mana"]=true,["White Mana"]=true,["Black Mana"]=true,["Gold Mana"]=true}

--Face-down cards in a player play area get a physical decal instead of Object UI.
local cardRemoveDecalURL="https://steamusercontent-a.akamaihd.net/ugc/1661232230977162756/90D8AEB60005119DD4182B5FD24D7BDD8243B5F3/"
function cardInPlayerPlayArea(cardGUID)
	for a=1, 4 do
		local zone=getObjectFromGUID(playerPlayAreas[a])
		if zone~=nil then for _, card in pairs(zone.getObjects()) do if card.guid==cardGUID then return true end end end
	end
	return false
end
removeCardRemoveDecal=function(card)
	if card==nil then return end
	local decals={}
	local changed=false
	for _, decal in pairs(card.getDecals() or {}) do
		if decal.name=="Card Remove" then changed=true else decals[#decals+1]=decal end
	end
	if changed==true then card.setDecals(decals) end
end
function refreshCardRemoveDecal(card)
	if card==nil or card.type~="Card" or not (gameCards[card.guid]==nil or gameCards[card.guid].full==nil) then return end
	removeCardRemoveDecal(card)
	if card.is_face_down==true and cardInPlayerPlayArea(card.guid)==true then
		--Face-down cards are rotated over, so put the decal on the card's local underside.
		card.addDecal({name="Card Remove", url=cardRemoveDecalURL, position={0,-0.5,0}, rotation={270,180,180}, scale={1.7,2.0,1}})
	end
end

function playerBoardZoneEnterSettled(ctx)
	local zone=ctx.zone
	local obj=ctx.obj
	local zoneGUID=ctx.zoneGUID
	local objGUID=ctx.objGUID
	local zoneInfo=ctx.zoneInfo
	local objType=ctx.objType
	--Updates Main UI buttons when anything is played to a mage's play area/deed deck/discard.
	--Keep play-area refreshes distinct so mainUIUpdate can skip deck bookkeeping that cannot have changed.
	if gStates.turnNumber>0 then--makes sure end of round doesn't have errors
		if zoneInfo~=nil and (zoneInfo.kind=="play" or zoneInfo.kind=="deed" or zoneInfo.kind=="discard") and turnOrderIndexAtSeat(zoneInfo.seatPos)~=nil then
			local seatPos=zoneInfo.seatPos
			if zoneInfo.kind=="deed" and (objType=="Card" or objType=="Deck") then
				if objType=="Deck" then obj.max_typed_number=1 end
				scheduleEndRoundDeedStateRefresh(seatPos)
			end
			--remove banner card from register if returned to deck.
			if zoneInfo.kind=="discard" and gameCards[objGUID]~=nil and gameCards[objGUID].half~=nil then gStates.bannercard[gameCards[objGUID].half]=nil end
			if zoneInfo.kind=="play" then
				updatePlayAreaObjectState(seatPos, obj, true)
				dayTactic2ExpireIfCardPlayed(seatPos)
				schedulePlayAreaCardScale(seatPos)
				mainUIUpdate("Object entered into play area")
			else mainUIUpdate("Object entered into deed deck or discard") end
		end
	end

	--Object entered player board
	if zoneInfo~=nil and zoneInfo.kind=="play" then
		--increment Master of chaos skill
		if objGUID==GUID.skill.masterOfChaos then
			if masterOfChaosPause==false then
				masterOfChaosPause=true
				if masterOfChaosWait~=nil then Wait.stop(masterOfChaosWait) end
				local temp=gStates.masterOfChaos+1
				if temp==7 then temp=1 end
				obj.setCustomObject({image=masterOfChaosData[temp].image})
				for a=1, #turnOrder, 1 do
					if turnOrder[a].masterOfChaos~=nil then turnOrder[a].masterOfChaos="used" break end
				end
				obj.reload()
				safeWaitFrames("PlayerBoard.Events",function() masterOfChaosPause=false end, 10)
			end
			return true
		end

		--Add combat buttons to monster tokens.
		local addedButtons=monsterObjectButtons(obj)


		--Add fortified symbol
		if gStates.monsterPlayLocation[objGUID]~=nil and monsterPugs[objGUID]~=nil and monsterPugs[objGUID].unfortified==nil then
			local target=gStates.monsterPlayLocation[objGUID]
			local attackingVolkare=false
			if gStates.cityMonsterQty[volkare.model]~=nil then
				for guid, state in pairs(gStates.cityMonsterQty[volkare.model]) do
					if guid==objGUID then
						local volkareObj=gStates.volkareModel~=nil and getObjectFromGUID(gStates.volkareModel) or nil
						if volkareObj~=nil then target={volkareObj.getPosition()[1], volkareObj.getPosition()[2], volkareObj.getPosition()[3]} end
						attackingVolkare=true
					end
				end
			end
			local mapObjects=getObjectFromGUID(mapArea).getObjects()
			local terTile, monsterhexBearing=terrainHexAtPosition(target, mapObjects)
			if terTile~=nil and monsterhexBearing~=nil and gStates.volkareState~=nil and gStates.volkareState:sub(1, 9)~="Attacking" then

				--fortified for Volkare's Army
				if attackingVolkare==true and monsterPugs[objGUID].unfortified==nil and (terrainTiles[terTile.guid].hexFeature[monsterhexBearing]=="mage tower" or terrainTiles[terTile.guid].hexFeature[monsterhexBearing]=="keep") then
					local found=false
					local existingDecals=obj.getDecals() or {}
					for _, decalDetails in pairs(existingDecals) do
						if decalDetails.name=="Fortified" then found=true break end
					end
					if found==false then
						obj.addDecal({name="Fortified", url="https://steamusercontent-a.akamaihd.net/ugc/15769941683634999180/45D8BF9859C1F2C026A3B40DA634B74286E2C3EB/", position={0.8, 0.15, -0.8}, rotation={90, 180, 0}, scale={0.72, 0.72, 1}})
						if gStates.monsterPerks[objGUID]==nil then gStates.monsterPerks[objGUID]={fortified=true} else gStates.monsterPerks[objGUID].fortified=true end
					end
				end


			end
		end
		--Manual monster movement cannot assume the current avatar crossed a particular wall.
		--If the avatar is not on an adjacent hex, use the existing wall-choice interface.
		resolveManualMonsterWallFortified(obj)
		if #addedButtons>0 then obj.UI.setXmlTable(addedButtons) end

		--Toggle Half Cards
		if gameCards[objGUID]~=nil and gameCards[objGUID].half~=nil then
			local bannerPosition=obj.getPosition()
			if bannerPosition[3]>=-38.4 then
				local pass=bannerPosition[1]
				local halfGUID=gameCards[objGUID].half
				obj.setState(2)
				local bannerSeat=zoneInfo.seatPos
				safeWaitFrames("PlayerBoard.Events",function()
					local halfCard=getObjectFromGUID(halfGUID)
					if halfCard~=nil then
						halfCard.setScale({0.65, 1, 0.65})
						halfCard.setPosition({pass, 1.2, -38.12})
						scheduleUnitLayoutRefresh(bannerSeat)
					end
				end, 3)
			end
		end

		--Add/remove the Card Remove decal when a normal card enters the player play area.
		if objType=="Card" and (gameCards[objGUID]==nil or gameCards[objGUID].full==nil) then
			safeWaitFrames("PlayerBoard.Events",function() local card=getObjectFromGUID(objGUID) if card~=nil then refreshCardRemoveDecal(card) end end, 2)
		end

		--Add command decal to banner of Command
		if objGUID==GUID.card.bannerOfCommandToken then
			bannerOfCommandDecal()
			scheduleUnitLayoutRefresh(zoneInfo.seatPos)
		end

		--if object is a crystal then alter it's animation.
		if crystalManaNames[obj.getName()]==true then
			safeWaitTime("PlayerBoard.Events",function() if getObjectFromGUID(objGUID)~=nil then obj.AssetBundle.playTriggerEffect(0) end end, 0.1)
			safeWaitTime("PlayerBoard.Events",function() if getObjectFromGUID(objGUID)~=nil then obj.AssetBundle.playLoopingEffect(1) end end, 1)
		end
	end

	--Unit Area work is event-driven: split accidental two-card Unit decks only when this area changes.
	local unitZoneInfo=zoneInfo
	if unitZoneInfo~=nil and unitZoneInfo.kind=="unit" then
		local unitSeatPos=unitZoneInfo.seatPos
		if objType=="Card" or objType=="Deck" then safeWaitFrames("PlayerBoard.Events",function() separateCombinedUnitsInArea(unitSeatPos) end, 2) end
		scheduleUnitLayoutRefresh(unitSeatPos)
		--Monster tokens may be dropped directly on Units. Give them the same combat controls and reward refresh as Play Area monsters.
		if monsterPugs[objGUID]~=nil then
			local monsterGUID=objGUID
			safeWaitFrames("PlayerBoard.Events",function()
				local monster=getObjectFromGUID(monsterGUID)
				if monster~=nil and objectInPlayerCombatArea(monsterGUID)==true then
					local addedButtons=monsterObjectButtons(monster)
					if #addedButtons>0 then monster.UI.setXmlTable(addedButtons) end
					mainUIUpdate("Monster entered unit area")
				end
			end, 2)
		end
	end

	--Re-add avatar buttons when an avatar enters a non-map zone. Entering the map scripting
	--zone happens before onObjectDrop has recalculated its new hex, so refreshing here would
	--briefly attach the previous location's buttons. The settled drop owns the map refresh.
	if mageKnightAvatarGUIDs[objGUID]==true and zoneGUID~=mapArea then addAvatarButtons() end

	--Change wound cards dropped on units to wound token.
	if zoneInfo~=nil and zoneInfo.kind=="unit" and objType=="Card" and obj.getGMNotes()=="Wound" then
		local woundPosition=obj.getPosition()
		local woundX=woundPosition[1]
		if woundPosition[3]>=-37 and ((woundX>-65.3 and woundX<-42.7) or (woundX>-25.3 and woundX<-2.7) or
			(woundX>14.7 and woundX<37.3) or (woundX>54.7 and woundX<77.3)) then
			getObjectFromGUID("ab56f3").takeObject({position={woundX, woundPosition[2], -33.29}, smooth=false})
			obj.destruct()
		end
	end

        --flip ruin down if one of its monsters is Down
        if gStates.ruinMonsters~=nil and gStates.ruinMonsters[objGUID]~=nil then
            local ruinObj=getObjectFromGUID(gStates.ruinMonsters[objGUID])
            if ruinObj==nil then
                --The monster token has been reused after its Ruin was removed; discard the stale link.
                gStates.ruinMonsters[objGUID]=nil
            elseif obj.is_face_down==true then
                if ruinObj.is_face_down==false then ruinObj.flip() end
            else
                local flip=true
                for monsterGUID, _ in pairs(gStates.ruinMonsters) do
                    local monsterObj=getObjectFromGUID(monsterGUID)
                    if monsterObj~=nil and monsterObj.is_face_down==true then flip=false break end
                end
                if flip==true and ruinObj.is_face_down==true then ruinObj.flip() end
            end
        end

	--record potion return locationTest
	if zoneInfo~=nil and zoneInfo.kind=="crystal" and obj.getName():reverse():sub(1, 6)=="noitoP" then
		local potionPosition=obj.getPosition()
		gStates.mageSkills[objGUID]={potionPosition[1], potionPosition[2], potionPosition[3]}
	end

	--Lock possesed token on to nearest monster
	if (zoneGUID==mapArea or (zoneInfo~=nil and zoneInfo.kind=="play"))
		and monsterPugs[objGUID]~=nil and monsterPugs[objGUID].pugType=="possessed" then
		attachEnemy(nil, nil, "attach", obj, zone)
	end
	return false
end

function playerBoardZoneLeave(ctx)
	local zone=ctx.zone
	local obj=ctx.obj
	local zoneGUID=ctx.zoneGUID
	local objGUID=ctx.objGUID
	local zoneInfo=ctx.zoneInfo
	local objType=ctx.objType
	if obj~=nil and skillTokens[obj.guid]~=nil and (skillTokens[obj.guid].skillType=="Coop" or skillTokens[obj.guid].skillType=="Comp") then
		for playerIndex, details in pairs(turnOrder) do
			if details.seatPos~=nil and zone.guid==playerPlayAreas[details.seatPos] then coopCompSkillLeftPlayArea(obj.guid, playerIndex) break end
		end
	end
	if gStates.turnNumber>0 and turnOrder[gStates.turnNumber]~=nil and zone.guid==handZones[turnOrder[gStates.turnNumber].seatPos] then scheduleTactic4HandBonusRefresh() end
	if (zone.guid==playerPlayAreas[2] or zone.guid==playerPlayAreas[3] or zone.guid==playerPlayAreas[1] or zone.guid==playerPlayAreas[4]) and getObjectFromGUID(obj.guid)~=nil then
		--remove icons from monsters
		obj.UI.setXmlTable({{}})
		--Only remove the face-down card decal once the card is confirmed outside all player play areas.
		if obj.type=="Card" then
			local cardGUID=obj.guid
			safeWaitFrames("PlayerBoard.Events",function() local card=getObjectFromGUID(cardGUID) if card~=nil and cardInPlayerPlayArea(cardGUID)==false then removeCardRemoveDecal(card) end end, 2)
		end

		--restore card size, except Unit cards still owned by the overlapping Unit Area layout.
		if ((gameCards[obj.guid]~=nil and gameCards[obj.guid].full==nil) or obj.getGMNotes()=="Wound")
			and not (unitLayoutIsUnit(obj) and unitLayoutObjectInAnyUnitArea(obj.guid)) then obj.setScale({1.5,1,1.5}) end

		safeWaitTime("PlayerBoard.Events",function()
			--Toggle half cards when picked up.
			if getObjectFromGUID(obj.guid)~=nil then
				if gameCards[obj.guid]~=nil and gameCards[obj.guid].full~=nil and obj.getPosition()[2]>2 then
					obj.setState(1)
					safeWaitFrames("PlayerBoard.Events",function() if getObjectFromGUID(gameCards[obj.guid].full)~=nil then getObjectFromGUID(gameCards[obj.guid].full).setScale({1.5, 1, 1.5}) end end, 1)
				end

				--if object is a crystal then remove highlight.
				local crystalGlow={["Red Mana"]={1, 0, 0}, ["Green Mana"]={0, 1, 0}, ["Blue Mana"]={0, 0, 1}, ["White Mana"]={1, 1, 1}, ["Black Mana"]={0.3, 0.0, 0.6}, ["Gold Mana"]={1, 0.9, 0}}
				if crystalGlow[obj.getName()]~=nil then
					obj.AssetBundle.playLoopingEffect(0)
				end
			end
		end, 0.22)
		--Decrement Master of chaos skill
		if obj.guid==GUID.skill.masterOfChaos and masterOfChaosPause==false then
			if masterOfChaosWait~=nil then Wait.stop(masterOfChaosWait) end
			safeWaitFrames("PlayerBoard.Events",function() masterOfChaosWait=safeWaitCondition("PlayerBoard.Events",function()
				for a=1, #turnOrder, 1 do
					if turnOrder[a].masterOfChaos~=nil and turnOrder[a].masterOfChaos~="incrementented in turn" then turnOrder[a].masterOfChaos="available" break end
				end
				getObjectFromGUID(GUID.skill.masterOfChaos).setCustomObject({image=masterOfChaosData[gStates.masterOfChaos].image})
				getObjectFromGUID(GUID.skill.masterOfChaos).reload()
				masterOfChaosWait=nil
			end, function() return getObjectFromGUID(GUID.skill.masterOfChaos).resting end) end, 5)
		end
	end
	--A Card or whole Deck leaving the deed pile can make End Round available.
	if obj~=nil and (obj.type=="Card" or obj.type=="Deck") then
		for _, details in pairs(turnOrder) do if zone.guid==deedDeckZones[details.seatPos] then scheduleEndRoundDeedStateRefresh(details.seatPos) break end end
	end
	--Updates Main UI buttons when anything is removed from a mages play Area
	if gStates.turnNumber>0 then
		for a=1, #turnOrder, 1 do
			local seatPos=turnOrder[a].seatPos
			if zone.guid==playerPlayAreas[seatPos] then
				updatePlayAreaObjectState(seatPos, obj, false)
				schedulePlayAreaCardScale(seatPos)
				if unitLayoutIsCommand(obj) then scheduleUnitLayoutRefreshAfterCommandRelease(seatPos,obj.guid) end
				mainUIUpdate("Object removed from zone")
				break
			elseif zone.guid==deedDeckDiscardZones[seatPos] then
				mainUIUpdate("Object removed from zone")
				break
			end
		end
	end

	--A monster leaving a Unit Area can change pending fame/reputation just like leaving the Play Area.
	local leftUnitArea=false
	local leftUnitSeat=nil
	for seatPos=1,4 do if zone.guid==playerUnitAreas[seatPos] then leftUnitArea=true leftUnitSeat=seatPos break end end
	if leftUnitArea==true then
		if unitLayoutIsCommand(obj) then scheduleUnitLayoutRefreshAfterCommandRelease(leftUnitSeat,obj.guid) else scheduleUnitLayoutRefresh(leftUnitSeat) end
		if unitLayoutIsUnit(obj) then
			local unitGUID=obj.guid
			safeWaitFrames("PlayerBoard.Events",function()
				local unit=getObjectFromGUID(unitGUID)
				if unit~=nil and unitLayoutObjectInAnyUnitArea(unitGUID)==false then unit.setScale({unitLayoutConfig.cardScale,1,unitLayoutConfig.cardScale}) end
			end,2)
		end
	end
	if leftUnitArea==true and monsterPugs[obj.guid]~=nil then
		local monsterGUID=obj.guid
		safeWaitFrames("PlayerBoard.Events",function()
			local monster=getObjectFromGUID(monsterGUID)
			if monster~=nil and objectInPlayerCombatArea(monsterGUID)==false then monster.UI.setXmlTable({{}}) end
			mainUIUpdate("Monster removed from unit area")
		end, 2)
	end
end

end)
__bundle_register("PlayingGame.PlayerBoard.UnitLayout", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Module-private helpers. Predeclared so forward references keep resolving locally.
local unitLayoutSnapType, refreshUnitLayoutSnapPoints, unitLayoutCommandPriority, unitLayoutX, unitLayoutObjects
local unitLayoutSnapshot, unitLayoutIsCompanion, refreshUnitLayout, unitLayoutObjectInUnitArea

-- Runtime Unit/Command-slot layout and compression on player boards.

unitLayoutConfig={nativeSlots=6, firstOffset=-103.57, nativeSpacing=3.84, cardScale=1.5, associationRadius=2.05}
unitLayoutWait=unitLayoutWait or {}
unitLayoutExpanded=unitLayoutExpanded or {}

--Each native Unit slot has six attached player-board snap points:
--1 Banner, 2 Command (one also tagged Unit), and 3 Wound. When overflow compresses the
--Unit columns, rebuild only this snap family at the same dynamic X centres.
unitLayoutSnapType=function(point)
	if point==nil then return nil end
	local banner=false
	local wound=false
	local command=false
	local unit=false
	for _,tag in ipairs(point.tags or {}) do
		if tag=="Banner" then banner=true
		elseif tag=="Wound" then wound=true
		elseif tag=="Command" then command=true
		elseif tag=="Unit" then unit=true end
	end
	if banner then return "banner" end
	if wound then return "wound" end
	if command and unit then return "unitCommand" end
	if command then return "command" end
	return nil
end

refreshUnitLayoutSnapPoints=function(seatPos,commandCount)
	if seatPos==nil then return end
	local board=getObjectFromGUID(playerBoard[seatPos])
	if board==nil then return end
	local slotCount=math.max(unitLayoutConfig.nativeSlots,commandCount or 0)
	local snaps=board.getSnapPoints() or {}
	local kept={}
	local counts={banner=0,wound=0,unitCommand=0,command=0}
	for _,point in ipairs(snaps) do
		local snapType=unitLayoutSnapType(point)
		if snapType~=nil then counts[snapType]=counts[snapType]+1 else kept[#kept+1]=point end
	end

	--The stock board has 6/18/6/6 of these points. Dynamic versions preserve the same 1:3:1:1 ratio.
	--If a future board asset changes that family, leave it untouched rather than deleting unknown snaps.
	local currentSlots=counts.banner
	if currentSlots<1 or counts.wound~=currentSlots*3 or counts.unitCommand~=currentSlots or counts.command~=currentSlots then
		print("UNIT LAYOUT SNAP ERROR: Player "..tostring(seatPos).." board snap family was not recognised.")
		return
	end
	if currentSlots==slotCount then return end

	local boardPos=board.getPosition()
	for slot=1,slotCount do
		--positionToLocal automatically accounts for each board's 180 degree rotation and 8.2 scale.
		local localCenter=board.positionToLocal({unitLayoutX(seatPos,slot,slotCount),boardPos[2],boardPos[3]})
		local centerX=localCenter.x or localCenter[1]
		kept[#kept+1]={position={centerX,0,-0.155},tags={"Banner"}}
		kept[#kept+1]={position={centerX,0,-0.398},tags={"Unit","Command"}}
		kept[#kept+1]={position={centerX+0.070,0,-0.574},tags={"Wound"}}
		kept[#kept+1]={position={centerX,0,-0.574},tags={"Wound"}}
		kept[#kept+1]={position={centerX-0.070,0,-0.574},tags={"Wound"}}
		kept[#kept+1]={position={centerX,0,-0.830},tags={"Command"}}
	end
	board.setSnapPoints(kept)
end

function unitLayoutIsUnit(obj)
	if obj==nil then return false end
	local cardType=gameCardType(obj)
	return cardType=="Regular Unit" or cardType=="Elite Unit"
end

function unitLayoutIsCommand(obj)
	if obj==nil then return false end
	--Bonds of Loyalty is physically a Skill token, but while claimed in Norowas' Unit Area it provides
	--an extra Command slot exactly like Banner of Command. Its asset does not reliably carry the GM Note.
	return obj.getGMNotes()=="Command Token" or obj.getGMNotes()=="Bonds of Loyalty" or obj.guid==GUID.skill.bondsOfLoyalty or obj.guid==GUID.card.bannerOfCommandToken
end

unitLayoutCommandPriority=function(obj)
	if obj==nil then return 9 end
	if obj.getGMNotes()=="Command Token" then return 1 end
	if obj.getGMNotes()=="Bonds of Loyalty" or obj.guid==GUID.skill.bondsOfLoyalty then return 2 end
	if obj.guid==GUID.card.bannerOfCommandToken then return 3 end
	return 9
end

unitLayoutX=function(seatPos, slot, commandCount)
	local displayCount=math.max(unitLayoutConfig.nativeSlots, commandCount or unitLayoutConfig.nativeSlots)
	local width=unitLayoutConfig.nativeSpacing*(unitLayoutConfig.nativeSlots-1)
	local spacing=width/(displayCount-1)
	return (seatPos*40)+unitLayoutConfig.firstOffset+((slot-1)*spacing)
end

function unitLayoutCardScale(commandCount)
	if commandCount==nil or commandCount<=unitLayoutConfig.nativeSlots then return unitLayoutConfig.cardScale end
	return unitLayoutConfig.cardScale*((unitLayoutConfig.nativeSlots-1)/(commandCount-1))
end

--Only the Unit scripting zone defines Unit capacity; this preserves the Banner/Bonds behaviour the recruitment code already relied on.
unitLayoutObjects=function(seatPos)
	local unitZone=getObjectFromGUID(playerUnitAreas[seatPos])
	if unitZone==nil then return {} end
	return unitZone.getObjects()
end

unitLayoutSnapshot=function(seatPos)
	local objects=unitLayoutObjects(seatPos)
	local commands={}
	local units={}
	local unitByGuid={}
	for _, obj in pairs(objects) do
		if unitLayoutIsCommand(obj) then commands[#commands+1]=obj end
		if unitLayoutIsUnit(obj) then units[#units+1]=obj unitByGuid[obj.guid]=obj end
	end
	table.sort(commands, function(a,b)
		local ax=a.getPosition()[1]
		local bx=b.getPosition()[1]
		if math.abs(ax-bx)<0.05 then
			local ap=unitLayoutCommandPriority(a)
			local bp=unitLayoutCommandPriority(b)
			if ap==bp then return a.guid<b.guid end
			return ap<bp
		end
		return ax<bx
	end)
	table.sort(units, function(a,b)
		local ax=a.getPosition()[1]
		local bx=b.getPosition()[1]
		if math.abs(ax-bx)<0.05 then return a.guid<b.guid end
		return ax<bx
	end)

	local unitBySlot={}
	local unitSlotByGuid={}
	local usedCommand={}
	for _, unit in ipairs(units) do
		local unitX=unit.getPosition()[1]
		local bestSlot=nil
		local bestDistance=nil
		for slot, command in ipairs(commands) do
			if usedCommand[slot]~=true then
				local distance=math.abs(unitX-command.getPosition()[1])
				if bestDistance==nil or distance<bestDistance then bestDistance=distance bestSlot=slot end
			end
		end
		if bestSlot~=nil then
			usedCommand[bestSlot]=true
			unitBySlot[bestSlot]=unit
			unitSlotByGuid[unit.guid]=bestSlot
		end
	end

	local expanded=unitLayoutExpanded[seatPos]==true or #commands>unitLayoutConfig.nativeSlots
	if expanded==false and #commands<=unitLayoutConfig.nativeSlots then
		for _, unit in ipairs(units) do
			local scale=unit.getScale()
			local sx=scale.x or scale[1]
			if sx~=nil and sx<unitLayoutConfig.cardScale-0.02 then expanded=true break end
		end
	end
	local slotX={}
	for slot, command in ipairs(commands) do
		if #commands>unitLayoutConfig.nativeSlots or expanded==true then slotX[slot]=unitLayoutX(seatPos, slot, #commands)
		else slotX[slot]=command.getPosition()[1] end
	end
	return {objects=objects, commands=commands, units=units, unitByGuid=unitByGuid, unitBySlot=unitBySlot, unitSlotByGuid=unitSlotByGuid, slotX=slotX, expanded=expanded}
end

function unitLayoutFirstFreeCommand(seatPos)
	local layout=unitLayoutSnapshot(seatPos)
	if #layout.commands>unitLayoutConfig.nativeSlots then refreshUnitLayout(seatPos) end
	for slot, command in ipairs(layout.commands) do
		if layout.unitBySlot[slot]==nil then return slot, layout.slotX[slot], command, layout end
	end
	return nil, nil, nil, layout
end

--Before overflow, new Command sources fill an unused printed column. From the seventh onward they enter at the right edge and trigger a reflow.
function unitLayoutNextCommandX(seatPos)
	local layout=unitLayoutSnapshot(seatPos)
	local count=#layout.commands
	if count>=unitLayoutConfig.nativeSlots or layout.expanded==true then
		local newCount=count+1
		return unitLayoutX(seatPos, newCount, newCount), newCount
	end
	local used={}
	for _, command in ipairs(layout.commands) do
		local commandX=command.getPosition()[1]
		local bestSlot=1
		local bestDistance=math.abs(commandX-unitLayoutX(seatPos,1,unitLayoutConfig.nativeSlots))
		for slot=2, unitLayoutConfig.nativeSlots do
			local distance=math.abs(commandX-unitLayoutX(seatPos,slot,unitLayoutConfig.nativeSlots))
			if distance<bestDistance then bestDistance=distance bestSlot=slot end
		end
		used[bestSlot]=true
	end
	for slot=1, unitLayoutConfig.nativeSlots do
		if used[slot]~=true then return unitLayoutX(seatPos,slot,unitLayoutConfig.nativeSlots), count+1 end
	end
	return unitLayoutX(seatPos,count+1,count+1), count+1
end

function unitLayoutNearestUnit(objects, x)
	local nearest=nil
	local nearestDistance=nil
	for _, obj in pairs(objects or {}) do
		if unitLayoutIsUnit(obj) then
			local distance=math.abs(x-obj.getPosition()[1])
			if nearestDistance==nil or distance<nearestDistance then nearest=obj nearestDistance=distance end
		end
	end
	return nearest, nearestDistance
end

unitLayoutIsCompanion=function(obj)
	if obj==nil or unitLayoutIsUnit(obj) or unitLayoutIsCommand(obj) then return false end
	if obj.getGMNotes()=="Unit Wound" or obj.type=="Dice" or obj.type=="Figurine" then return true end
	if skillTokens[obj.guid]~=nil or monsterPugs[obj.guid]~=nil then return true end
	if gameCards[obj.guid]~=nil and gameCards[obj.guid].full~=nil then return true end
	return false
end

function unitLayoutObjectInAnyUnitArea(guid)
	for seatPos=1,4 do
		local zone=getObjectFromGUID(playerUnitAreas[seatPos])
		if zone~=nil then for _, obj in pairs(zone.getObjects()) do if obj.guid==guid then return true end end end
	end
	return false
end

refreshUnitLayout=function(seatPos)
	if seatPos==nil then return end
	local layout=unitLayoutSnapshot(seatPos)
	local commandCount=#layout.commands
	if commandCount<=unitLayoutConfig.nativeSlots and layout.expanded~=true then return end
	refreshUnitLayoutSnapPoints(seatPos,commandCount)
	local targetScale=unitLayoutCardScale(commandCount)
	local unitMoves={}

	for slot, command in ipairs(layout.commands) do
		local targetX=unitLayoutX(seatPos,slot,commandCount)
		local pos=command.getPosition()
		if math.abs(pos[1]-targetX)>0.02 and (command.held_by_color==nil or command.held_by_color=="") then command.setPositionSmooth({targetX,pos[2],pos[3]}) end
	end

	for _, unit in ipairs(layout.units) do
		local slot=layout.unitSlotByGuid[unit.guid]
		local scale=unit.getScale()
		local sx=scale.x or scale[1]
		local sz=scale.z or scale[3]
		if sx==nil or sz==nil or math.abs(sx-targetScale)>0.01 or math.abs(sz-targetScale)>0.01 then unit.setScale({targetScale,1,targetScale}) end
		if slot~=nil then
			local pos=unit.getPosition()
			local targetX=unitLayoutX(seatPos,slot,commandCount)
			unitMoves[#unitMoves+1]={oldX=pos[1], targetX=targetX}
			if math.abs(pos[1]-targetX)>0.02 and (unit.held_by_color==nil or unit.held_by_color=="") then unit.setPositionSmooth({targetX,pos[2],pos[3]}) end
		end
	end

	--Keep wounds, Mana, Unit reminders, combat tokens and attached Banner cards with the Unit column they were sitting on.
	for _, obj in pairs(layout.objects) do
		if unitLayoutIsCompanion(obj) then
			local pos=obj.getPosition()
			local bestMove=nil
			local bestDistance=nil
			for _, move in ipairs(unitMoves) do
				local distance=math.abs(pos[1]-move.oldX)
				if bestDistance==nil or distance<bestDistance then bestDistance=distance bestMove=move end
			end
			if bestMove~=nil and bestDistance<=unitLayoutConfig.associationRadius and (obj.held_by_color==nil or obj.held_by_color=="") then
				--Preserve the object's offset from its Unit (notably the three left/centre/right Wound snaps)
				--while moving the whole Unit column to its compressed position.
				local targetX=bestMove.targetX+(pos[1]-bestMove.oldX)
				if math.abs(pos[1]-targetX)>0.02 then obj.setPositionSmooth({targetX,pos[2],pos[3]}) end
			end
		end
	end
	unitLayoutExpanded[seatPos]=commandCount>unitLayoutConfig.nativeSlots
end

function scheduleUnitLayoutRefresh(seatPos)
	if seatPos==nil then return end
	if unitLayoutWait[seatPos]~=nil then Wait.stop(unitLayoutWait[seatPos]) end
	unitLayoutWait[seatPos]=safeWaitTime("SetupGame",function()
		unitLayoutWait[seatPos]=nil
		refreshUnitLayout(seatPos)
	end,0.2)
end

unitLayoutObjectInUnitArea=function(guid,seatPos)
	local zone=seatPos~=nil and getObjectFromGUID(playerUnitAreas[seatPos]) or nil
	if zone~=nil then for _,obj in pairs(zone.getObjects()) do if obj.guid==guid then return true end end end
	return false
end

--Players routinely lift Command tokens to place them on Units. Do not temporarily re-expand the whole
--Unit layout while a permanent Command source is in their hand; only resize if it is actually dropped away.
function scheduleUnitLayoutRefreshAfterCommandRelease(seatPos,commandGUID)
	if seatPos==nil or commandGUID==nil then return end
	safeWaitCondition("SetupGame",function()
		safeWaitFrames("SetupGame",function()
			if unitLayoutObjectInUnitArea(commandGUID,seatPos)==false then scheduleUnitLayoutRefresh(seatPos) end
		end,2)
	end,function()
		local command=getObjectFromGUID(commandGUID)
		if command==nil then return true end
		local released=command.held_by_color==nil or command.held_by_color==""
		return released and command.resting==true
	end)
end

end)
__bundle_register("PlayingGame.PlayerBoard.CardFlow", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Player-board card-flow runtime.

--Deed/discard descriptions are informational and only need rebuilding when that physical pile changes.
--Key the debounce by scripting zone rather than Deck GUID because TTS can replace/collapse Deck objects as cards merge or are drawn.
local deckDescriptionWait={}
--Deed draws are always single-digit in normal play. TTS otherwise waits to see if another digit is coming before firing onObjectNumberTyped.
function setDeedDeckImmediateNumberTyping(seatPos)
	local zoneGUID=deedDeckZones[seatPos]
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if zone==nil then return end
	for _, obj in pairs(zone.getObjects()) do if obj.type=="Deck" then obj.max_typed_number=1 end end
end

local function refreshDeedPileDescription(seatPos, zoneType)
	local playerStats=nil
	for _, details in pairs(turnOrder) do if details.seatPos==seatPos then playerStats=details break end end
	if playerStats==nil then return end
	local zoneGUID=zoneType=="deed" and deedDeckZones[seatPos] or deedDeckDiscardZones[seatPos]
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if zone==nil then return end
	for _, deck in pairs(zone.getObjects()) do
		if deck.type=="Deck" or deck.type=="Card" then
			if playerStats.mage~=gStates.positionMageKnight[5] then
				for color, playerZone in pairs(gStates.handColors) do if playerZone==seatPos then deck.setGMNotes(color) break end end
			end
			local deckStats={	["Red"]={0, "{en}Red Card(s){ru}Красная(ых) карточка(и){zh-tw}紅色卡{zh-cn}红色卡{ko}빨간색 카드{es}Tarjeta(s) Roja{fr}Carte(s) Rouge{pt-br}Cartas Vermelhas{de}Rote Karten"},
								["Green"]={0, "{en}Green Card(s){ru}Зеленая(ых) карточка(и){zh-tw}綠色卡{zh-cn}绿色卡{ko}녹색 카드{es}Tarjeta(s) Verde{fr}Carte(s) Verte{pt-br}Cartas Verdes{de}Grüne Karten"},
								["Blue"]={0, "{en}Blue Card(s){ru}Синяя(ых) карточка(и){zh-tw}藍色卡{zh-cn}蓝色卡{ko}파란색 카드{es}Tarjeta(s) Azul{fr}Carte(s) Bleue{pt-br}Cartas Azuis{de}Blaue Karten"},
								["White"]={0, "{en}White Card(s){ru}Белая(ых) карточка(и){zh-tw}白色卡{zh-cn}白色卡{ko}흰색 카드{es}Tarjeta(s) Blanca{fr}Carte(s) Blanche{pt-br}Cartas Brancas{de}Weiße Karten"},
								["Starting"]={0, "{en}Basic Action(s){ru}Базовое(ых) действие(я){zh-tw}基本行動卡{zh-cn}基本行动卡{ko}기본 액션 카드{es}Acciones Básicas{fr}Action(s) de Base{pt-br}Ações Básicas{de}Basis Aktionen"},
								["Advanced Action"]={0, "{en}Advanced Action(s){ru}Особое(ые) действие(я){zh-tw}高級行動卡{zh-cn}高级行动卡{ko}상급 액션 카드{es}Acciones Avanzadas{fr}Action(s) Avancée{pt-br}Ações Avançadas{de}Erweiterte Aktionen"},
								["Spell"]={0, "{en}Spell(s){ru}Заклинание(я){zh-tw}法術卡{zh-cn}法术卡{ko}마법 카드{es}Hechizo(s){fr}Sort(s){pt-br}Feitiços{de}Zauber"},
								["Wound"]={0, "{en}Wound(s){ru}Рана(ы){zh-tw}創傷卡{zh-cn}创伤卡{ko}부상{es}Herida(s){fr}Blessure(s){pt-br}Ferimentos{de}Wunde(n)"},
								["Artifact"]={0, "{en}Artifact(s){ru}Артефакт(а){zh-tw}神器卡{zh-cn}神器卡{ko}유물{es}Artefacto(s){fr}Artefact(s){pt-br}Artefatos{de}Artefakt(e)"},
								["Move"]={0, "{en}Card(s) are Move{ru}Карта(ы) - это Движение{zh-tw}移動類卡牌{zh-cn}移动类卡牌{ko}장의 이동 카드{es}Las Cartas se Mueven{fr}Les cartes sont Mouvements{pt-br}Cartas são Movimento{de}Karte(n) sind Bewegung"},
								["Combat"]={0, "{en}Card(s) are Combat{ru}Карта(ы) - это Боевые{zh-tw}戰鬥類卡牌{zh-cn}战斗类卡牌{ko}장의 전투 카드{es}Las Cartas son de Combate{fr}Les cartes sont Combat{pt-br}Cartas são Combate{de}Karte(n) sind Angriff"},
								["Influence"]={0, "{en}Card(s) are Influence{ru}Карта(ы) - это Влияние{zh-tw}影響力卡牌{zh-cn}影响力卡牌{ko}장의 영향력 카드{es}Las Cartas tienen Influencia{fr}Les cartes sont Influence{pt-br}Cartas são Influência{de}Karte(n) sind Einfluss"},
								["Special"]={0, "{en}Card(s) are Special{ru}Карта(ы) - это Особая{zh-tw}特殊類卡牌{zh-cn}特殊类卡牌{ko}장의 특수효과 카드{es}Las Cartas son Especiales{fr}Les cartes sont Spéciales{pt-br}Cartas são Especiais{de}Karte(n) sind Spezial"},
								["Heal"]={0, "{en}Card(s) are Heal{ru}Карта(ы) - это Лечение{zh-tw}治療類卡牌{zh-cn}治疗类卡牌{ko}장의 치유 카드{es}Las Cartas se Curan{fr}Les cartes sont Guéries{pt-br}Cartas são Cura{de}Karte(n) sind Heilung"},
								["Action"]={0, "{en}Card(s) are Action{ru}Карта(ы) - это Действие{zh-tw}行動類卡牌{zh-cn}行动类卡牌{ko}장의 행동 카드{es}Las Cartas son Acción{fr}Les cartes sont des Actions{pt-br}Cartas são Ações{de}Karte(n) sind Aktionen"}}
			--count card types colours, and abilities
			local deedCards=deck.type=="Deck" and deck.getObjects() or {{guid=deck.guid}}
			local cardSearch={["deed"]=deedCards}
			deck.setName("{en}Deed Cards{ru}Колода Деяний{zh-tw}功能卡牌{zh-cn}功能卡牌{ko}행동 카드{es}Tarjetas de Escritura{fr}Cartes D'acte{pt-br}Cartas de Façanha{de}Handlungskarten")
			if zoneType=="deed" and playerStats.tactic==6 and gStates.dayRound==false and #gStates.powerStored>0 then
				cardSearch={["deed"]=deedCards, ["stored"]=gStates.powerStored}
				deck.setName(joinLang({"{en}Deed Cards +{ru}Карты Деяний +{zh-tw}功能卡牌 +{zh-cn}功能卡牌 +{ko}행동 카드 +{es}Tarjetas de Escritura +{fr}Cartes D'acte +{pt-br}Cartas de Façanha +{de}Handlungskarten +", #gStates.powerStored, "{en} Stored{ru} Сбережено{zh-tw} 已儲存{zh-cn} 已储存{ko} 장 저장됨{es} Almacenado{fr} Stockée{pt-br} Armazenada{de} Gelagert"}))
			end
			for _, cardpile in pairs(cardSearch) do
				for _, deedCard in pairs(cardpile) do
					if gameCards[deedCard.guid]~=nil and gameCards[deedCard.guid].cardType~="Regular Unit" and gameCards[deedCard.guid].cardType~="Elite Unit" then
						deckStats[gameCards[deedCard.guid].cardType][1]=deckStats[gameCards[deedCard.guid].cardType][1]+1
						for _, cardColor in pairs(gameCards[deedCard.guid].color) do deckStats[cardColor][1]=deckStats[cardColor][1]+1 end
						for _, cardAction in pairs(gameCards[deedCard.guid].action) do if cardAction~="Banner" then deckStats[cardAction][1]=deckStats[cardAction][1]+1 end end
					else
						deckStats["Wound"][1]=deckStats["Wound"][1]+1
					end
				end
			end
			--write a description
			local deckDescription=""
			for statName, statValue in pairs(deckStats) do
				if statValue[1]>0 then
					deckDescription=joinLang({deckDescription, statValue[1], " ", statValue[2], "\n"})
				end
				if statName=="White" or statName=="Artifact" then deckDescription=joinLang({deckDescription, "----------\n"}) end
			end
			deckDescription=joinLang({deckDescription, "----------"})
			deck.setDescription(deckDescription)
			break
		end
	end
end

function scheduleDeedPileDescriptionRefresh(seatPos, zoneType)
	local zoneGUID=zoneType=="deed" and deedDeckZones[seatPos] or deedDeckDiscardZones[seatPos]
	if zoneGUID==nil then return end
	if deckDescriptionWait[zoneGUID]~=nil then Wait.stop(deckDescriptionWait[zoneGUID]) end
	deckDescriptionWait[zoneGUID]=safeWaitTime("PlayerBoard.CardFlow",function()
		deckDescriptionWait[zoneGUID]=nil
		refreshDeedPileDescription(seatPos, zoneType)
	end, 0.75)
end

function containerInsideDeckZone(container, zone)
	if container==nil or zone==nil then return false end
	for _, zoneObj in pairs(zone.getObjects()) do if zoneObj.guid==container.guid then return true end end
	--Zone membership can lag a deck merge by a frame, so use the zone bounds as a fallback.
	local pos=container.getPosition()
	local zonePos=zone.getPosition()
	local zoneScale=zone.getScale()
	return math.abs(pos[1]-zonePos[1])<=zoneScale[1]/2 and math.abs(pos[3]-zonePos[3])<=zoneScale[3]/2
end

local function containerDeedPileLocation(container)
	if container==nil or container.type~="Deck" then return nil,nil end
	for _, details in pairs(turnOrder) do
		local seatPos=details.seatPos
		local deedZone=getObjectFromGUID(deedDeckZones[seatPos])
		if containerInsideDeckZone(container, deedZone)==true then return seatPos,"deed" end
		local discardZone=getObjectFromGUID(deedDeckDiscardZones[seatPos])
		if containerInsideDeckZone(container, discardZone)==true then return seatPos,"discard" end
	end
	return nil,nil
end

function refreshContainerDeckDescription(container)
	local seatPos,zoneType=containerDeedPileLocation(container)
	if seatPos==nil then return false end
	refreshDeedPileDescription(seatPos,zoneType)
	return true
end

function scheduleContainerDeckDescriptionRefresh(container)
	local seatPos,zoneType=containerDeedPileLocation(container)
	if seatPos==nil then return end
	scheduleDeedPileDescriptionRefresh(seatPos,zoneType)
end

--Move cards visibly to a player's Deed deck without allowing two cards to converge on the same pile.
--Each seat owns its own queue, so different players can receive cards simultaneously.
deedTransferState={queues={},active={},transit={}}
function deedTransferBusy(seatPos)
	local queue=deedTransferState.queues[seatPos]
	return deedTransferState.active[seatPos]~=nil or (queue~=nil and #queue>0)
end

function deedTransferAnyBusy()
	for seatPos=1,4 do if deedTransferBusy(seatPos)==true then return true end end
	return false
end

function deedTransferPile(zone,ignoreGUID)
	if zone==nil then return nil end
	local single=nil
	for _, obj in pairs(zone.getObjects()) do
		if obj.guid~=ignoreGUID then
			if obj.type=="Deck" then return obj end
			if obj.type=="Card" then single=obj end
		end
	end
	return single
end

function deedTransferHomePosition(seatPos)
	return {-74.19+(40*(seatPos-1)),1.50,-43.16}
end

function deedTransferComplete(seatPos,entry,placed)
	deedTransferState.transit[entry.guid]=nil
	deedTransferState.active[seatPos]=nil
	local queue=deedTransferState.queues[seatPos]
	local transferFinished=false
	if queue~=nil then
		for index, queued in ipairs(queue) do
			if queued.guid==entry.guid then table.remove(queue,index) break end
		end
		if #queue==0 then deedTransferState.queues[seatPos]=nil transferFinished=true end
	else
		transferFinished=true
	end
	if transferFinished==true then rewindTransactionFinish("Deed transfer "..tostring(seatPos)) end
	if placed==true and turnOrder[entry.playerIndex]~=nil then
		turnOrder[entry.playerIndex].deedCount=(turnOrder[entry.playerIndex].deedCount or 0)+1
	end
	safeWaitFrames("PlayerBoard.CardFlow",function() deedTransferProcess(seatPos) end,2)
end

function deedTransferFinishHover(seatPos,entry)
	local card=getObjectFromGUID(entry.guid)
	local zone=getObjectFromGUID(deedDeckZones[seatPos])
	if card==nil or zone==nil then deedTransferComplete(seatPos,entry,false) return end
	card.unlock()
	local pile=deedTransferPile(zone,entry.guid)
	if pile~=nil then
		local pilePos=pile.getPosition()
		local cardPos=card.getPosition()
		card.setPosition({pilePos[1],math.max(cardPos[2],pilePos[2]+1.0),pilePos[3]})
		pile.putObject(card)
		deedTransferComplete(seatPos,entry,true)
		return
	end
	--An empty Deed zone has no container to receive putObject. Smooth the first card down to the normal
	--deck home, then let the next queued card use that card as its pile.
	local home=deedTransferHomePosition(seatPos)
	card.setRotationSmooth({0,180,180},false,false)
	card.setPositionSmooth(home,false,false)
	safeWaitCondition("PlayerBoard.CardFlow",function()
		deedTransferComplete(seatPos,entry,true)
	end,function()
		local moving=getObjectFromGUID(entry.guid)
		if moving==nil then return true end
		local pos=moving.getPosition()
		return moving.resting==true and math.abs(pos[1]-home[1])<0.25 and math.abs(pos[2]-home[2])<0.35 and math.abs(pos[3]-home[3])<0.25
	end,2.5,function()
		local moving=getObjectFromGUID(entry.guid)
		if moving~=nil then moving.setPosition(home) moving.setRotation({0,180,180}) end
		deedTransferComplete(seatPos,entry,moving~=nil)
	end)
end

function deedTransferHoverPosition(seatPos,queueIndex)
	local home=deedTransferHomePosition(seatPos)
	return {home[1],home[2]+2.0+((queueIndex-1)*0.1),home[3]}
end

function deedTransferHoverReached(guid,target)
	local moving=getObjectFromGUID(guid)
	if moving==nil then return true end
	local pos=moving.getPosition()
	return math.abs(pos[1]-target[1])<0.18 and math.abs(pos[2]-target[2])<0.18 and math.abs(pos[3]-target[3])<0.18
end

function deedTransferSendToHover(seatPos,entry,queueIndex)
	if entry==nil or entry.hoverStarted==true then return end
	local card=getObjectFromGUID(entry.guid)
	local zone=getObjectFromGUID(deedDeckZones[seatPos])
	if card==nil or zone==nil then return end
	entry.hoverStarted=true
	entry.hover=deedTransferHoverPosition(seatPos,queueIndex)
	deedTransferState.transit[entry.guid]=zone.guid
	local pile=deedTransferPile(zone,entry.guid)
	local rotation=pile~=nil and pile.getRotation() or {0,180,180}
	card.setRotationSmooth(rotation,false,false)
	card.setPositionSmooth(entry.hover,false,false)
	safeWaitCondition("PlayerBoard.CardFlow",function()
		local moving=getObjectFromGUID(entry.guid)
		if moving~=nil then moving.lock() end
		entry.arrived=true
		deedTransferProcess(seatPos)
	end,function()
		return deedTransferHoverReached(entry.guid,entry.hover)
	end,4.0,function()
		local moving=getObjectFromGUID(entry.guid)
		if moving~=nil then moving.setPosition(entry.hover) moving.lock() end
		entry.arrived=true
		deedTransferProcess(seatPos)
	end)
end

function deedTransferProcess(seatPos)
	if deedTransferState.active[seatPos]~=nil then return end
	local queue=deedTransferState.queues[seatPos]
	if queue==nil or #queue==0 then return end
	local entry=queue[1]
	local card=getObjectFromGUID(entry.guid)
	local zone=getObjectFromGUID(deedDeckZones[seatPos])
	if card==nil or zone==nil then deedTransferComplete(seatPos,entry,false) return end
	if entry.hoverStarted~=true then deedTransferSendToHover(seatPos,entry,1) return end
	if entry.arrived~=true then return end
	deedTransferState.active[seatPos]=entry.guid
	deedTransferFinishHover(seatPos,entry)
end

function queueCardToDeedDeck(playerIndex,card,rewindReady)
	if card==nil or turnOrder[playerIndex]==nil then return false end
	local seatPos=turnOrder[playerIndex].seatPos
	if seatPos==nil or deedDeckZones[seatPos]==nil or getObjectFromGUID(deedDeckZones[seatPos])==nil then return false end
	local guid=card.guid
	local queue=deedTransferState.queues[seatPos]
	if deedTransferState.active[seatPos]==guid then return true end
	if queue~=nil then for _, entry in ipairs(queue) do if entry.guid==guid then return true end end end
	--The transfer queue is runtime-only, so take the rewind point before lifting the first card. Closely
	--spaced claims for the same seat share this owner and are all allowed to queue behind the same snapshot.
	if rewindReady~=true then
		rewindTransactionStart(function() queueCardToDeedDeck(playerIndex,card,true) end,"Deed transfer "..tostring(seatPos))
		return true
	end
	card.unlock()
	card.UI.setXmlTable({{}})
	card.setScale({1.5,1,1.5})
	--Lift vertically before any horizontal movement. This clears Quest cards and offer cards, and gives the
	--ordinary source-zone leave callback a chance to resolve before transit suppression begins.
	local pos=card.getPosition()
	card.setPosition({pos[1],pos[2]+3.0,pos[3]})
	deedTransferState.queues[seatPos]=deedTransferState.queues[seatPos] or {}
	local entry={guid=guid,playerIndex=playerIndex}
	deedTransferState.queues[seatPos][#deedTransferState.queues[seatPos]+1]=entry
	local queueIndex=#deedTransferState.queues[seatPos]
	--Every claimed Deed card starts its normal smooth move immediately after the source-zone leave settles.
	--Cards wait directly above the Deed deck, separated vertically by 0.1 so simultaneous claims stay visible
	--and cannot collide. They are then inserted into the deck in original claim order.
	safeWaitFrames("PlayerBoard.CardFlow",function()
		deedTransferSendToHover(seatPos,entry,queueIndex)
		deedTransferProcess(seatPos)
	end,2)
	return true
end

--Move's an offer or tactic card to a player's location
local fillWait=false
function processCardClaim(player, mouseButton, id, rewindReady)
	if mouseButton~="-3" then
		if legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then
			local claimedCard=getObjectFromGUID(id:sub(1, 6))
			if claimedCard~=nil then
				local source=id:sub(7, string.len(id))
				local cardClaimRewindOwner="Card claim "..tostring(claimedCard.guid)
				--Left-click card claims can update offers/rewards immediately while the physical card then travels
				--through the Deed-transfer queue. Protect the whole claim so a failed rewind-store never applies
				--the bookkeeping without also starting the physical transfer.
				if source~="unit" and mouseButton=="-1" and rewindReady~=true then
					if rewindTransactionOwnerActive(cardClaimRewindOwner)==true then return end
					rewindTransactionStart(function() processCardClaim(player,mouseButton,id,true) end,cardClaimRewindOwner)
					return
				end
				--Unit cards remain locked in the offer until recruitment is actually approved.
				--Other claim types keep their existing behaviour.
				if source~="unit" then
					claimedCard.unlock()
					local tacticSource=source:sub(1, string.len(source)-1)=="tactic"
					if tacticSource==true then
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-117.83 , 3.0, -43.16},false,false)
					elseif mouseButton=="-1" then
						queueCardToDeedDeck(gStates.turnNumber,claimedCard)
					else
						claimedCard.setPosition({claimedCard.getPosition()[1], claimedCard.getPosition()[2]+3, claimedCard.getPosition()[3]})
					end
					cardClaim=true
					safeWaitTime("PlayerBoard.CardFlow",function() cardClaim=false end, 2)
					--add decal to tactic if playing Ultimate Conquest
					if gStates.gameScenario=="Ultimate Conquest" then
						for _, mage2 in pairs(mageKnights) do
							if mage2.mage==turnOrder[gStates.turnNumber].mage then
								local posX=-1*((turnOrder[gStates.turnNumber].seatPos*0.34)-0.85)
								safeWaitTime("PlayerBoard.CardFlow",function()
									claimedCard.addDecal({name="Used Already Shield", url=mage2.shieldImage,
									position={posX, 0.11, -0.9}, rotation={90.0, 180.0, 0.0}, scale={0.4, 0.4, 1}})
								end, 1)
							end
						end
					end
					--Left-click Deed claims are handled by the serialized smooth-transfer queue above. Preserve the
					--existing alternate claim action and tactic destination exactly as before.
					if mouseButton=="-2" and tacticSource~=true then
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-105.0 , 4.59, -47.55},false,false)
					elseif mouseButton~="-1" and tacticSource~=true then
						claimedCard.flip()
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-114.19 , 3.0, -43.16},false,false)
					end
					if source=="offer" and fillWait==false then fillWait=true safeWaitTime("PlayerBoard.CardFlow",function() compactAndRefillDeedOffer() fillWait=false end, 1.2) end
					if source=="artifactReward" then
						if turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" then gStates.theGauntletArtifactClaimed=true end
						gStates.dealtArtifacts[id:sub(1, 6)]=false
						claimedCard.UI.setXmlTable({{}})
						local remainingGUID={}
						for GUID, state in pairs(gStates.dealtArtifacts) do if state==true then remainingGUID[#remainingGUID+1]=GUID end end
						if #remainingGUID==1 then
							--Return the unclaimed Artifact through the shared physical bottom-deck helper.
							local artifactDeck=getObjectFromGUID(GUID.deck.artifact)
							local returnedArtifact=getObjectFromGUID(remainingGUID[1])
							if returnedArtifact~=nil then
								standardDeckCycleMarkReturned("Artifact",returnedArtifact)
								if artifactDeck~=nil then putCardAtBottom(artifactDeck,returnedArtifact) end
								returnedArtifact.UI.setXmlTable({{}})
							end
							--reset buttons
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactDown", "active", "true")
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOffer", "active", "true")
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactUp", "active", "true")
							gStates.artifactRewards=1
							gStates.dealtArtifacts=nil
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOfferText", "text", joinLang({"{en}Reward {ru}Награда {zh-tw}獎勵{zh-cn}奖励{ko}보상 {es}Premiar {fr}Reward {pt-br}Premiar {de}Belohnung ", gStates.artifactRewards}))
						end
					end
					if gameCards[claimedCard.guid]~=nil and source~="artifactReward" then
						broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-tw} 獲得 {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", gameCards[claimedCard.guid].name[1], "."}), positionToColor(gStates.turnNumber))
					else
						broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-tw} 獲得 {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", getObjectFromGUID(claimedCard.guid).getName(), "."}), positionToColor(gStates.turnNumber))
					end
				else
					if fillWait==false then--Move the Unit card to an empty command-source column
						local seatPos=turnOrder[gStates.turnNumber].seatPos
						local slot, unitX, commandSource, layout=unitLayoutFirstFreeCommand(seatPos)
						local found=slot~=nil
						if found==true then
							claimedCard.unlock()
							local scale=unitLayoutCardScale(#layout.commands)
							claimedCard.setScale({scale,1,scale})
							claimedCard.setPositionSmooth({unitX,2.0,-34.74},false,false)
							fillWait=true
							safeWaitFrames("PlayerBoard.CardFlow",function() safeWaitCondition("PlayerBoard.CardFlow",function() fillWait=false scheduleUnitLayoutRefresh(seatPos) end, function() return claimedCard.resting end) end,5)
							if gameCards[claimedCard.guid]~=nil then
								broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-tw} 獲得 {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", gameCards[claimedCard.guid].name[1], "."}), positionToColor(gStates.turnNumber))
							end
						end
						if found==false then broadcastToAll("{en}You have no free command tokens to enlist another unit{ru}У вас нет свободного жетона командования, чтобы нанять еще один отряд{zh-tw}你沒有空閒的指揮標記可招募另一個單位{zh-cn}你没有闲置的位置招募新部队{ko}유닛을 고용할 지휘 토큰이 부족합니다{es}No tienes fichas de mando gratuitas para alistar otra unidad{fr}Vous n'avez pas de jetons de commande gratuits pour enrôler une autre unité{pt-br}Você não tem Fichas de Comando livres para recrutar outra unidade{de}Du hast keine freien Befehlsmarken, um eine andere Einheit anzuwerben.", warningColor) end
						--Warn only after the normal location rules plus conquered Camp-as-City proximity are checked.
						if gameCards[claimedCard.guid]~=nil and unitRecruitableAtCurrentLocation(gStates.turnNumber,claimedCard)~=true then
							broadcastToAll("{en}Claimed Unit normally isn't recruited from the location you're currently at.{ru}Забранный Отряд обычно не нанимается из того места, где вы в данный момент находитесь.{zh-tw}你目前所在的位置通常不能招募這個單位{zh-cn}你所在的位置通常不能招募这个部队{ko}보통은, 그 유닛을 현재 장소에서 고용할 수 없습니다{es}La Unidad reclamada normalmente no se recluta en la ubicación en la que se encuentra actualmente.{fr}L'Unité réclamée n'est normalement pas recrutée à l'endroit où vous vous trouvez actuellement.{pt-br}Unidade Clamada normalmente não é recrutada da localização que você está agora.{de}Die beanspruchte Einheit wird normalerweise nicht von dem Ort rekrutiert, an dem Sie sich gerade befinden.", positionToColor(gStates.turnNumber))
						end
					else
						broadcastToAll("{en}Let the last card settle before claiming the next unit.{ru}Не спешите. Позвольте предыдущей карте переместиться, прежде чем брать следующую.{zh-tw}請等上一張卡片穩定後再招募下一個單位。{zh-cn}征召下一个部队前, 把上一个结算清{ko}이전 유닛이 완전히 놓일 때 까지 기다려주세요{es}Deje que la última carta se asiente antes de reclamar la siguiente unidad.{fr}Laissez la dernière carte s'installer avant de réclamer l'unité suivante.{pt-br}Deixe a última carta se encaixar antes de clamar a próxima unidade.{de}Lassen Sie die letzte Karte ruhen, bevor Sie die nächste Einheit beanspruchen.", warningColor)
					end
				end
				--activate some of the tactics effects.
				if source:sub(1, string.len(source)-1)=="tactic" then
					turnOrder[gStates.turnNumber].tactic=tonumber(source:sub(7, string.len(source)))
					if gStates.dayRound==true and turnOrder[gStates.turnNumber].tactic==5 then
						drawExactDeedCards(gStates.turnNumber, 2, "DrawOne")
					end
					if gStates.dayRound==true and turnOrder[gStates.turnNumber].tactic==2 then
						safeWaitTime("PlayerBoard.CardFlow",function() dayTactic2ButtonActivate() end, 2)--activate after the tactic card finishes moving to the player area
					end
					nextTurnMerged("incrementTurn")
				end
				if rewindReady==true then safeWaitTime("PlayerBoard.CardFlow",function() rewindTransactionFinish(cardClaimRewindOwner) end,1.5) end
			end
		else
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				if turnOrder[gStates.turnNumber].mage=="Volkare" then
					broadcastToAll("{en}Volkare doesn't claim cards{ru}Волкар не берет карты{zh-tw}沃卡爾不會取得卡牌{zh-cn}傻孩子, 沃里卡不选卡{ko}볼케어는 카드를 획득하지 않습니다{es}Volkare no reclama cartas{fr}Volkare ne réclame pas de cartes{pt-br}Volkare não clama cartas{de}Volkare beansprucht keine Karten", warningColor)
				else
					broadcastToAll("{en}Dummy doesn't claim cards this way{ru}Виртуальный игрок не получает карты таким образом{zh-tw}虛擬玩家不會以這種方式取得卡牌{zh-cn}虚拟玩家不会这样选卡{ko}가상 플레이어는 카드를 이런 방식으로 얻지 않습니다{es}El muñeco no reclama cartas de esta manera{fr}Le mannequin ne réclame pas les cartes de cette façon{pt-br}Jog. Fictício não clama cartas desta forma{de}Dummy beansprucht auf diese Weise keine Karten", warningColor)
				end
			end
		end
	end
end

function coralQuickWittedSetAside(playerIndex)
	local playerDetails=turnOrder[playerIndex]
	if playerDetails==nil or playerDetails.mage~="Coral" or playerDetails.mage==gStates.positionMageKnight[5] or playerDetails.dropoutState~=nil then return nil end
	local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
	if deedZone==nil then return nil end
	for _, obj in pairs(deedZone.getObjects()) do
		if obj.type=="Deck" and obj.getQuantity()>1 then
			for _, cardData in pairs(obj.getObjects()) do if cardData.guid==GUID.card.quickWitted then return obj end end
		end
	end
	return nil
end

--Returns Quick Witted only when it has become Coral's lone physical Deed card.
function coralQuickWittedLastDeedCard(playerIndex)
	local playerDetails=turnOrder[playerIndex]
	if playerDetails==nil or playerDetails.mage~="Coral" or playerDetails.mage==gStates.positionMageKnight[5] or playerDetails.dropoutState~=nil then return nil end
	local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
	if deedZone==nil then return nil end
	for _, obj in pairs(deedZone.getObjects()) do if obj.type=="Card" and obj.guid==GUID.card.quickWitted then return obj end end
	return nil
end

coralDrawPending=nil
local coralDrawBypass=false
local coralDrawExactCount=nil

--Quick Witted prompts can remain open while turnOrder is re-sorted. Resolve Coral by her fixed board seat instead of a stale turnOrder index.
local function coralDrawPlayerIndex(seatPos)
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.seatPos==seatPos and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then return playerIndex end
	end
	return nil
end

function showCoralDrawChoice(playerIndex, drawCount, sourceId)
	if drawCount<1 or turnOrder[playerIndex]==nil then return end
	local seatPos=turnOrder[playerIndex].seatPos
	if coralDrawPending~=nil and coralDrawPending.seatPos==seatPos then
		coralDrawPending.remaining=coralDrawPending.remaining+drawCount
		drawCount=coralDrawPending.remaining
	else
		coralDrawPending={seatPos=seatPos, remaining=drawCount, sourceId=sourceId}
	end
	UI.setAttribute("CoralDrawChoiceQuestion", "text", joinLang({drawCount,"{en} card draw(s) remaining. Replace one draw with Quick Witted?{ru} доборов карт осталось. Заменить один добор на Quick Witted?{zh-tw} 次抽牌剩餘。用 Quick Witted 取代其中一次抽牌？{zh-cn} 次抽牌剩余。用 Quick Witted 替代其中一次抽牌？{ko}번의 카드 뽑기가 남았습니다. 한 번을 Quick Witted로 대체하시겠습니까?{es} robos de carta restantes. ¿Reemplazar un robo por Quick Witted?{fr} pioches restantes. Remplacer une pioche par Quick Witted ?{pt-br} compras de carta restantes. Substituir uma compra por Quick Witted?{de} Kartenziehungen verbleiben. Einen Zug durch Quick Witted ersetzen?"}))
	UI.setAttribute("CoralDrawFullPanel", "active", drawCount>1 and "true" or "false")
	UI.setAttribute("CoralDrawChoice", "visibility", positionToColor(playerIndex).."|Black")
	UI.show("CoralDrawChoice")
end

function clearCoralDrawChoice()
	coralDrawPending=nil
	UI.hide("CoralDrawChoice")
end

--A Coral draw can turn a Deck into a lone Card or rebuild it after a manual draw is intercepted.
--Refresh from the scripting zone after TTS has settled so hover text/counts describe the final physical pile.
local function coralScheduleDeedRefresh(seatPos, delayFrames)
	safeWaitFrames("PlayerBoard.CardFlow",function()
		scheduleDeedPileDescriptionRefresh(seatPos, "deed")
		scheduleEndRoundDeedStateRefresh(seatPos)
	end, delayFrames or 4)
end

--Returns Coral's player index only when this object is her physical Deed Deck and Quick Witted is still available inside it.
function coralManualQuickWittedDeck(object)
	if object==nil or object.type~="Deck" then return nil end
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedDeck=coralQuickWittedSetAside(playerIndex)
			if deedDeck~=nil and deedDeck.guid==object.guid then return playerIndex end
			return nil
		end
	end
	return nil
end

--A manual top-card draw creates a Card from the Deck; onPlayerAction therefore does not reliably see the Deck.
--Use the exact container-leave event instead, then check held_by_color a few frames later to distinguish a player drag from scripted draws.
function coralManualQuickWittedLeaveSource(container)
	if container==nil or container.type~="Deck" then return nil end
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return nil end
			local inDeedZone=false
			for _, zoneObj in pairs(deedZone.getObjects()) do
				if zoneObj.guid==container.guid then inDeedZone=true break end
			end
			if inDeedZone==false then return nil end
			for _, cardData in pairs(container.getObjects()) do
				if cardData.guid==GUID.card.quickWitted then return playerIndex end
			end
			if container.remainder~=nil and container.remainder.guid==GUID.card.quickWitted then return playerIndex end
			return nil
		end
	end
	return nil
end

function coralRestoreManualDraw(playerIndex, deckGuid, card, showChoice)
	if playerIndex==nil or card==nil or card.isDestroyed() then return end
	local seatPos=turnOrder[playerIndex].seatPos
	card.drop()
	safeWaitFrames("PlayerBoard.CardFlow",function()
		if card==nil or card.isDestroyed() then return end
		local destination=getObjectFromGUID(deckGuid)
		if destination==nil or destination.type~="Deck" then
			local deedZone=getObjectFromGUID(deedDeckZones[seatPos])
			if deedZone~=nil then
				for _, obj in pairs(deedZone.getObjects()) do
					if obj.guid~=card.guid and (obj.type=="Deck" or obj.type=="Card") then
						destination=obj
						if obj.guid==GUID.card.quickWitted then break end
					end
				end
			end
		end
		if destination==nil or destination.isDestroyed() then return end
		destination.putObject(card)
		coralScheduleDeedRefresh(seatPos, 3)
		if showChoice~=false then safeWaitFrames("PlayerBoard.CardFlow",function()
			local currentPlayerIndex=coralDrawPlayerIndex(seatPos)
			if currentPlayerIndex~=nil and coralDrawPending==nil then showCoralDrawChoice(currentPlayerIndex, 1, "DrawOne") end
		end, 5) end
	end, 1)
end

local function coralRunNormalDraw(playerIndex, id, exactCount)
	local previousTurn=gStates.turnNumber
	gStates.turnNumber=playerIndex
	coralDrawBypass=true
	coralDrawExactCount=exactCount
	drawUpTo({color="Black"}, "-1", id)
	coralDrawExactCount=nil
	coralDrawBypass=false
	gStates.turnNumber=previousTurn
end

--Object scripts such as Day Tactic 2 can route Coral draws through the same Quick Witted-aware draw path.
--Track the whole external draw flow, including the few frames where Draw One temporarily closes and then reopens the choice.
local coralExternalDrawSeat=nil
local coralExternalDrawFinishPause=nil
local function coralFinishExternalDraw(seatPos, delayFrames)
	if coralExternalDrawSeat~=seatPos then return end
	if coralExternalDrawFinishPause~=nil then Wait.stop(coralExternalDrawFinishPause) end
	coralExternalDrawFinishPause=safeWaitFrames("PlayerBoard.CardFlow",function()
		coralExternalDrawFinishPause=nil
		if coralExternalDrawSeat==seatPos then coralExternalDrawSeat=nil end
	end, delayFrames or 10)
end

function coralExternalQuickWittedDraw(params)
	if params==nil then return end
	local playerIndex=coralDrawPlayerIndex(params.seatPos)
	if playerIndex==nil then return end
	coralExternalDrawSeat=params.seatPos
	local previousTurn=gStates.turnNumber
	gStates.turnNumber=playerIndex
	coralDrawExactCount=tonumber(params.count) or 1
	drawUpTo({color="Black"}, "-1", params.sourceId or "DrawOne")
	coralDrawExactCount=nil
	gStates.turnNumber=previousTurn
	if coralDrawPending==nil or coralDrawPending.seatPos~=params.seatPos then coralFinishExternalDraw(params.seatPos, 10) end
end

function coralExternalDrawPending(params)
	return params~=nil and coralExternalDrawSeat==params.seatPos
end

--Run a scripted exact-count Deed draw as one operation. Coral uses the tracked external
--Quick Witted flow; every other Mage Knight uses the same exact-count draw engine without a prompt.
function drawExactDeedCards(playerIndex, count, sourceId)
	local details=turnOrder[playerIndex]
	count=tonumber(count) or 0
	if details==nil or count<1 then return end
	if details.mage=="Coral" and details.mage~=gStates.positionMageKnight[5] and details.dropoutState==nil then
		coralExternalQuickWittedDraw({seatPos=details.seatPos, count=count, sourceId=sourceId or "DrawOne"})
	else
		coralRunNormalDraw(playerIndex, sourceId or "DrawOne", count)
	end
end

--Night Tactic 4 needs a single multi-card draw request so Coral sees the normal Quick Witted choice,
--including Draw Full, instead of several one-card requests competing with the pending prompt.
function coralTactic4Draw(playerIndex, exactCount)
	local previousTurn=gStates.turnNumber
	gStates.turnNumber=playerIndex
	coralDrawExactCount=exactCount
	drawUpTo({color="Black"}, "-1", "DrawOne")
	coralDrawExactCount=nil
	gStates.turnNumber=previousTurn
end

local function coralTakeQuickWitted(playerIndex)
	local deedDeck=coralQuickWittedSetAside(playerIndex)
	if deedDeck==nil then return false end
	local playerPosition=turnOrder[playerIndex].seatPos
	safeTakeObject("PlayerBoard.CardFlow",deedDeck,{guid=GUID.card.quickWitted, position={(playerPosition*40)-105, 4.59, -47.55}, rotation={0, 180, 0}, smooth=false, callback_function=function(card) card.setScale({1.5, 1, 1.5}) end})
	turnOrder[playerIndex].deedCount=math.max(0,(turnOrder[playerIndex].deedCount or 0)-1)
	coralScheduleDeedRefresh(playerPosition, 4)
	return true
end

function coralDrawChoice(player, mouseButton, id)
	if mouseButton~="-1" or coralDrawPending==nil or player==nil then return end
	local pending=coralDrawPending
	local playerIndex=coralDrawPlayerIndex(pending.seatPos)
	local playerDetails=playerIndex~=nil and turnOrder[playerIndex] or nil
	if playerDetails==nil or legalPlayerCheck(player.color, pending.seatPos, "NoDummyException")~=true then return end
	if id=="CoralDrawQuickWitted" then
		UI.hide("CoralDrawChoice")
		coralDrawPending=nil
		if coralTakeQuickWitted(playerIndex)==true then
			pending.remaining=pending.remaining-1
			if pending.remaining>0 then safeWaitFrames("PlayerBoard.CardFlow",function()
				local currentIndex=coralDrawPlayerIndex(pending.seatPos)
				if currentIndex~=nil then coralRunNormalDraw(currentIndex, pending.sourceId, pending.remaining) end
			end, 2) end
		else
			coralRunNormalDraw(playerIndex, pending.sourceId, pending.remaining)
		end
		coralScheduleDeedRefresh(pending.seatPos, 4)
		if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
	elseif id=="CoralDrawOne" then
		--Keep the choice visible while the single card is dealt; temporarily clear pending input so repeated clicks cannot queue extra draws.
		coralDrawPending=nil
		coralRunNormalDraw(playerIndex, "DrawOne", 1)
		pending.remaining=pending.remaining-1
		if pending.remaining>0 then
			--A few frames is enough for TTS to remove the drawn card from the Deck and update zone contents.
			safeWaitFrames("PlayerBoard.CardFlow",function()
				local currentIndex=coralDrawPlayerIndex(pending.seatPos)
				if currentIndex==nil then UI.hide("CoralDrawChoice") return end
				--If the last normal card was just drawn, Quick Witted has become the physical Deed Deck and the remaining draw is mandatory.
				if coralQuickWittedSetAside(currentIndex)==nil then
					UI.hide("CoralDrawChoice")
					coralRunNormalDraw(currentIndex, pending.sourceId, pending.remaining)
					if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
				else
					showCoralDrawChoice(currentIndex, pending.remaining, pending.sourceId)
				end
			end, 4)
		else
			UI.hide("CoralDrawChoice")
			if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
		end
		coralScheduleDeedRefresh(pending.seatPos, 5)
	elseif id=="CoralDrawFull" then
		UI.hide("CoralDrawChoice")
		coralDrawPending=nil
		coralRunNormalDraw(playerIndex, pending.sourceId, pending.remaining)
		coralScheduleDeedRefresh(pending.seatPos, 5)
		if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
	end
end

--Night Tactic 2 can rebuild a Deed pile from either a Deck or its final loose Card.
--Resolve one physical card at a time so TTS Deck->Card collapse cannot invalidate the next takeObject call.
local function nightTacticTwoCardGUIDs(zone)
	local guids={}
	if zone==nil then return guids end
	for _, obj in pairs(zone.getObjects()) do
		if obj.type=="Card" then guids[#guids+1]=obj.guid
		elseif obj.type=="Deck" then for _, data in pairs(obj.getObjects()) do guids[#guids+1]=data.guid end end
	end
	for a=#guids,2,-1 do local b=math.random(a) guids[a],guids[b]=guids[b],guids[a] end
	return guids
end

local function nightTacticTwoFindCard(zone, guid)
	if zone==nil or guid==nil then return nil,nil end
	for _, obj in pairs(zone.getObjects()) do
		if obj.type=="Card" and obj.guid==guid then return obj,nil end
		if obj.type=="Deck" then
			for _, data in pairs(obj.getObjects()) do if data.guid==guid then return nil,obj end end
		end
	end
	return nil,nil
end

local function nightTacticTwoRefillAndDraw(playerIndex, drawCount, done)
	local details=turnOrder[playerIndex]
	if details==nil then if done~=nil then done(0,0) end return end
	local seatPos=details.seatPos
	local discardZone=getObjectFromGUID(deedDeckDiscardZones[seatPos])
	local deedZone=getObjectFromGUID(deedDeckZones[seatPos])
	if discardZone==nil or deedZone==nil then if done~=nil then done(0,0) end return end
	local available=nightTacticTwoCardGUIDs(discardZone)
	local selected={}
	for a=1, math.min(3,#available) do selected[a]=available[a] end
	local deckPos=deedZone.getPosition()
	deckPos={deckPos[1],1.50,deckPos[3]}
	local returned=0

	local function finish(drawn)
		safeWaitFrames("PlayerBoard.CardFlow",function()
			turnOrder[playerIndex].deedCount=readDeedPileCardCount(seatPos)
			scheduleDeedPileDescriptionRefresh(seatPos,"deed")
			scheduleDeedPileDescriptionRefresh(seatPos,"discard")
			scheduleEndRoundDeedStateRefresh(seatPos)
			if done~=nil then done(returned,drawn) end
		end,4)
	end

	local function drawReturned(index, drawn)
		if index>drawCount then finish(drawn) return end
		local pile=nil
		for _, obj in pairs(deedZone.getObjects()) do
			if obj.type=="Deck" then pile=obj break end
			if obj.type=="Card" then pile=obj end
		end
		if pile==nil then finish(drawn) return end
		local handPos={(seatPos*40)-105-(index*0.2),4.59,-47.55}
		if pile.type=="Deck" then
			local card=pile.takeObject({position=handPos,rotation={0,180,0},smooth=false})
			if card==nil then finish(drawn) return end
		else
			pile.setScale({1.5,1,1.5})
			pile.setRotation({0,180,0})
			pile.setPosition(handPos)
		end
		safeWaitFrames("PlayerBoard.CardFlow",function() drawReturned(index+1,drawn+1) end,2)
	end

	local function returnSelected(index)
		if index>#selected then
			safeWaitFrames("PlayerBoard.CardFlow",function() drawReturned(1,0) end,4)
			return
		end
		local loose,deck=nightTacticTwoFindCard(discardZone,selected[index])
		local function placed(card)
			if card~=nil then
				card.setScale({1.5,1,1.5})
				card.setRotation({0,180,180})
				card.setPosition({deckPos[1],deckPos[2]+1.0,deckPos[3]})
				returned=returned+1
			end
			safeWaitFrames("PlayerBoard.CardFlow",function() returnSelected(index+1) end,3)
		end
		if loose~=nil then placed(loose)
		elseif deck~=nil then
			safeTakeObject("PlayerBoard.CardFlow",deck,{guid=selected[index],position={deckPos[1],deckPos[2]+1.0,deckPos[3]},rotation={0,180,180},smooth=false,callback_function=placed})
		else returnSelected(index+1) end
	end

	returnSelected(1)
end

--Draw cards from a deed deck into that positions hand
cardClaim=false
function drawUpTo(player, mouseButton, id)
	if mouseButton=="-1" then
		local playerPosition=turnOrder[gStates.turnNumber].seatPos
		if legalPlayerCheck(player.color, playerPosition)==true then
			if deedTransferBusy(playerPosition)==true then
				safeWaitCondition("PlayerBoard.CardFlow",function() drawUpTo(player,mouseButton,id) end,function() return deedTransferBusy(playerPosition)~=true end,10,function() drawUpTo(player,mouseButton,id) end)
				return
			end
			local meditationBonus=0
			if id=="DrawHand" and gStates.meditationDrawBonus~=nil then
				meditationBonus=gStates.meditationDrawBonus[gStates.turnNumber] or 0
				if meditationBonus>0 then
					gStates.meditationDrawBonus[gStates.turnNumber]=nil
					safeWaitFrames("PlayerBoard.CardFlow",function() mainUIUpdate("Meditation Draw Bonus Used") end, 1)
				end
			end
			local deedDeck=nil
			for _, possibleDeck in pairs(getObjectFromGUID(deedDeckZones[playerPosition]).getObjects()) do
				if possibleDeck.type=="Deck" or possibleDeck.type=="Card" then deedDeck=possibleDeck break end
			end
			--Quick Witted is already physically in Coral's Deed Deck; when it is the final card it resolves as a normal single-card Deed Deck.
			if deedDeck~=nil or (id=="DrawHand" and turnOrder[gStates.turnNumber].tactic==2 and gStates.dayRound==false and gStates.tacticTwoState~="Used" and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5]) then
				local cardsInHand=0
				local handSize=turnOrder[gStates.turnNumber].hand+turnOrder[gStates.turnNumber].handBonus+gStates.tactic4HandBonus+meditationBonus
				if id=="DrawHand" then
					for _, possibleCards in pairs(getObjectFromGUID(handZones[playerPosition]).getObjects()) do if possibleCards.type=="Card" then cardsInHand=cardsInHand+1 end end
				else--Draw one
					cardsInHand=handSize-1
				end
				local drawNeeded=coralDrawExactCount or (handSize-cardsInHand)
				if drawNeeded>0 then
					local turnAffected=gStates.turnNumber
					--While normal Deed cards remain, Coral may replace any individual card draw with Quick Witted.
					if coralDrawBypass==false and deedDeck~=nil and coralQuickWittedSetAside(turnAffected)~=nil then
						showCoralDrawChoice(turnAffected, drawNeeded, id)
						return
					end
					local function drawCardstoHand()
						local excess=drawNeeded
						local deckPos={-74.19+(40*(turnOrder[turnAffected].seatPos-1)), 1.50, -43.16}
						if deedDeck~=nil then
							if deedDeck.type=="Deck" then
								local deckQuantity=deedDeck.getQuantity()
								local drawNow=math.min(drawNeeded, deckQuantity)
								excess=drawNeeded-drawNow
								local deckTakes=drawNow
								local takeRemainder=drawNow==deckQuantity
								if takeRemainder==true then deckTakes=math.max(0,deckQuantity-1) end
								for x=1, deckTakes do
									local drawn=deedDeck.takeObject({position={(playerPosition*40)-105-(x*0.2), 4.59, -47.55}, rotation={0, 180, 0}})
									if drawn~=nil then turnOrder[turnAffected].deedCount=math.max(0,(turnOrder[turnAffected].deedCount or 0)-1) end
								end
								if takeRemainder==true then
									safeWaitFrames("PlayerBoard.CardFlow",function()
										local deedZone=getObjectFromGUID(deedDeckZones[turnOrder[turnAffected].seatPos])
										if deedZone==nil then return end
										for _, remainder in pairs(deedZone.getObjects()) do
											if remainder.type=="Card" then
												remainder.setScale({1.5, 1, 1.5})
												remainder.setPositionSmooth({(playerPosition*40)-105-(drawNow*0.2), 4.59, -47.55})
												remainder.setRotationSmooth({0, 180, 0})
												turnOrder[turnAffected].deedCount=math.max(0,(turnOrder[turnAffected].deedCount or 0)-1)
												break
											end
										end
										coralScheduleDeedRefresh(turnOrder[turnAffected].seatPos, 3)
									end, 2)
								end
							else
								excess=drawNeeded-1
								deedDeck.setScale({1.5, 1, 1.5})
								deedDeck.setPositionSmooth({(playerPosition*40)-105, 4.59, -47.55})
								deedDeck.setRotationSmooth({0, 180, 0})
								turnOrder[turnAffected].deedCount=math.max(0,(turnOrder[turnAffected].deedCount or 0)-1)
							end
							coralScheduleDeedRefresh(turnOrder[turnAffected].seatPos, 4)
						end
						cardClaim=false
						safeWaitFrames("PlayerBoard.CardFlow",function()
							safeWaitTime("PlayerBoard.CardFlow",function()
								--Night tactic 2 grab three random discards back to deck if draw will reduce to 0.
								if id=="DrawHand" and excess>0 and gStates.endRoundCalled==false and turnOrder[turnAffected].tactic==2 and gStates.dayRound==false and gStates.tacticTwoState~="Used" and turnOrder[turnAffected].mage~=gStates.positionMageKnight[5] then
									gStates.tacticTwoState="Used"
									nightTacticTwoRefillAndDraw(turnAffected,excess,function()
										local tactic=getObjectFromGUID("f6ad01")
										if tactic~=nil and tactic.is_face_down==false then tactic.flip() end
										broadcastToAll("{en}Night Tactic Two was used to refill the Deed Deck with up to 3 random discards{ru}Ночная Тактика 2 была использована, чтобы вернуть до 3 случайных карт из сброса в Колоду деяний{zh-tw}夜間戰術 2 已用最多 3 張隨機棄牌補充行動牌庫{zh-cn}夜间战术 2 已用最多 3 张随机弃牌补充行动牌库{ko}밤 전략 2로 버린 카드 중 무작위로 최대 3장을 행동 덱에 되돌렸습니다{es}La Táctica Nocturna 2 se usó para devolver hasta 3 descartes aleatorios al mazo de Proezas{fr}La Tactique de Nuit 2 a remis jusqu'à 3 défausses aléatoires dans le paquet d'Actions{pt-br}A Tática Noturna 2 devolveu até 3 descartes aleatórios ao Baralho de Façanhas{de}Nachttaktik 2 hat bis zu 3 zufällige Ablagekarten in das Handlungskartendeck zurückgelegt", positionToColor(turnAffected))
									end)
								end
							end, 0.5)
						end, 2)
					end
					if cardClaim==true then safeWaitTime("PlayerBoard.CardFlow",function() drawCardstoHand() end, 1.5) else drawCardstoHand() end--make sure the card has entered the deck
				end
		    end
		end
	end
end

--True once there is no real Coral player, or Quick Witted is physically back in Coral's Deed Deck.
function coralQuickWittedReadyForDraw()
	for _, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return false end
			for _, obj in pairs(deedZone.getObjects()) do
				if obj.type=="Card" and obj.guid==GUID.card.quickWitted then return true end
				if obj.type=="Deck" then for _, cardData in pairs(obj.getObjects()) do if cardData.guid==GUID.card.quickWitted then return true end end end
			end
			return false
		end
	end
	return true
end

--Starting Deed Decks are taken from bags and shuffled asynchronously. Deal only after every active
--Mage Knight's complete Deed pile is registered in its scripting zone and has finished moving.
function startingDeedDecksReadyForDraw()
	for playerIndex, playerDetails in ipairs(turnOrder) do
		if playerDetails.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return false end
			local deedPileFound=false
			for _, obj in pairs(deedZone.getObjects()) do
				if obj.type=="Deck" or obj.type=="Card" then
					deedPileFound=true
					if obj.resting~=true then return false end
				end
			end
			if deedPileFound==false then return false end
		end
	end
	return true
end

--Replace the old four-second setup cushion with actual Deck readiness. Coral preparation runs once
--after all Deed Decks exist; the timeout retains a final fallback if TTS never reports a settled state.
function dealStartingHandsWhenReady()
	local coralPrepared=false
	local function finishStartingHandsDeal()
		dealAllHands()
		--Give the dealt cards a few frames to leave their Deck objects before automatic rewind snapshots resume.
		safeWaitFrames("PlayerBoard.CardFlow",function() rewindTransactionFinish("Game setup") end,15)
	end
	safeWaitCondition("PlayerBoard.CardFlow",finishStartingHandsDeal, function()
		if startingDeedDecksReadyForDraw()==false then return false end
		if coralPrepared==false then
			coralPrepared=true
			coralSetAsideQuickWitted()
			return false
		end
		return coralQuickWittedReadyForDraw()
	end, 10, function()
		coralSetAsideQuickWitted()
		safeWaitFrames("PlayerBoard.CardFlow",finishStartingHandsDeal, 5)
	end)
end

--Meditation / Trance card smarts. Top/Bot starts as Meditation; adding discard cards to the Deed Deck tells the script Trance was powered.
meditationTranceCardGUID="2eb8d0"
local function meditationPlayerIndex(card)
	if card==nil then return nil end
	for playerIndex, details in pairs(turnOrder) do
		local area=details.seatPos~=nil and getObjectFromGUID(playerPlayAreas[details.seatPos]) or nil
		if area~=nil then for _, obj in pairs(area.getObjects()) do if obj.guid==card.guid then return playerIndex end end end
	end
	return nil
end

local function meditationDiscardSnapshot(playerIndex)
	local cards={}
	local zone=turnOrder[playerIndex]~=nil and getObjectFromGUID(deedDeckDiscardZones[turnOrder[playerIndex].seatPos]) or nil
	if zone==nil then return cards end
	for _, obj in pairs(zone.getObjects()) do
		if obj.type=="Card" then cards[obj.guid]=true
		elseif obj.type=="Deck" then for _, data in pairs(obj.getObjects()) do cards[data.guid]=true end end
	end
	return cards
end

local function meditationCardCount(cards)
	local count=0
	for _, _ in pairs(cards or {}) do count=count+1 end
	return count
end
--Card-effect controls are only shown while the card is essentially vertical.
--Read the card's settled world rotation rather than inferring orientation from Q/E presses.
--The 10 degree tolerance is intentionally below TTS's normal 15 degree rotation step.
function cardEffectIsVertical(card)
	if card==nil then return false end
	local rotation=card.getRotation()
	local y=((rotation~=nil and rotation[2]) or 0)%180
	return math.min(y,180-y)<=10
end

--End-turn card cleanup belongs with deed/card flow rather than Combat. Return the current
--discard destination because the first loose card becomes the physical discard pile.
function cleanupPlayedCardAtEndTurn(card, playerIndex, cardDestination)
	if card==nil or card.type~="Card" or turnOrder[playerIndex]==nil then return cardDestination end
	local keepInPlay=false

	--Banner cards remain attached/available for their own banner handling.
	if gameCards[card.guid]~=nil and gameCards[card.guid].full~=nil then
		gStates.bannercard[card.guid]="played"
		keepInPlay=true
	end

	--Steady Tempo stays in the play area while its explicit end-turn choice is unresolved.
	if isSteadyTempoGUID~=nil and isSteadyTempoGUID(card.guid)==true and cardEffectIsVertical(card)==true then
		keepInPlay=true
		gStates.turnForfeited=false
		if card.is_face_down==false then steadyTempoPrepare(card, playerIndex) end
	end

	--Mysterious Box and Crystal Joy both have an unresolved end-turn choice while upright and
	--face up. A sideways Mysterious Box was used as a generic card and is discarded normally;
	--a face-down copy follows the normal thrown-away cleanup path.
	local manualEndTurnCard=(card.guid=="085e69" or card.guid=="7ebe5e")
		and card.is_face_down==false and cardEffectIsVertical(card)==true
	if manualEndTurnCard then keepInPlay=true gStates.turnForfeited=false end

	if card.getDescription()=="Quest" then keepInPlay=true gStates.turnForfeited=false end
	if keepInPlay==true then return cardDestination end

	gStates.turnForfeited=false
	local trash=getObjectFromGUID(trashCan)
	if card.is_face_down==true then
		if trash~=nil then trash.putObject(card) end
		return cardDestination
	end

	for _, ownedGUID in ipairs(turnOrder[playerIndex].deadDeckInventory or {}) do
		if card.guid==ownedGUID then
			if gStates.timeBending=="Started" and playerIndex==gStates.realTurn then
				if card.guid==timeBendingGUID then
					gStates.timeBendingRemovedSeat=turnOrder[playerIndex].seatPos
					if trash~=nil then trash.putObject(card) end
					broadcastToAll("{en}Time Bend Left Play{ru}«Изгиб времени» покинул игру{zh-tw}「時間彎曲」離開遊戲區{zh-cn}“时间弯曲”离开游戏区{ko}시간 왜곡이 플레이 영역을 떠났습니다{es}Curvatura Temporal salió del juego{fr}Courbure du Temps a quitté le jeu{pt-br}Dobra Temporal saiu de jogo{de}Zeitkrümmung hat das Spiel verlassen", positionToColor(playerIndex))
				else
					card.setRotation({0.0,180.0,0.0})
					card.setPosition({(turnOrder[playerIndex].seatPos*40)-100,4,-48.40})
				end
			elseif cardDestination==nil then
				card.setRotation({0.0,180.0,0.0})
				card.setPosition({(turnOrder[playerIndex].seatPos*40)-110.54,1.12,-43.20})
				cardDestination=card
			else
				local cardPos=card.getPosition()
				card.setPosition({cardPos[1],1.9,cardPos[3]})
				cardDestination=cardDestination.putObject(card)
			end
			break
		end
	end
	return cardDestination
end

local function meditationStripXmlButtons(card)
	local xml=card.UI.getXmlTable() or {}
	for a=#xml, 1, -1 do
		local id=xml[a].attributes~=nil and xml[a].attributes.id or nil
		if id==card.guid.."meditationTop" or id==card.guid.."meditationBot" or id==card.guid.."tranceTop" or id==card.guid.."tranceBot" then table.remove(xml,a) end
	end
	return xml
end

local function meditationRemoveButtons(card)
	if card==nil then return end
	local before=card.UI.getXmlTable() or {}
	local xml=meditationStripXmlButtons(card)
	if #xml~=#before then
		if #xml>0 then card.UI.setXmlTable(xml) else card.UI.setXml("") end
	end
end

local function meditationAddButtons(card, tranceReady)
	if card==nil then return end
	if cardEffectIsVertical(card)==false then meditationRemoveButtons(card) return end
	--Replace only our two controls, preserving any unrelated object UI on the card.
	local xml=meditationStripXmlButtons(card)
	if tranceReady==true then
		xml[#xml+1]=createClaimButton(card.guid, "tranceTop") xml[#xml+1]=createClaimButton(card.guid, "tranceBot")
	else
		xml[#xml+1]=createClaimButton(card.guid, "meditationTop") xml[#xml+1]=createClaimButton(card.guid, "meditationBot")
	end
	card.UI.setXmlTable(xml)
end

local function meditationNewState(playerIndex)
	local discard=meditationDiscardSnapshot(playerIndex)
	local required=math.min(2, meditationCardCount(discard))
	return {player=playerIndex, mode="waiting", discard=discard, required=required, accepted={}, acceptedSet={}, resolved=false}
end

function resetMeditationTranceState()
	local card=getObjectFromGUID(meditationTranceCardGUID)
	if card~=nil then meditationRemoveButtons(card) end
	gStates.meditationTranceState=nil
end

function refreshMeditationTrance()
	local card=getObjectFromGUID(meditationTranceCardGUID)
	if card==nil then return end
	local playerIndex=meditationPlayerIndex(card)
	--Picking the card up can briefly move it outside the player zone. Hide its controls,
	--but keep the resolved/unresolved state until the next turn explicitly resets it.
	if playerIndex==nil or cardEffectIsVertical(card)==false then meditationRemoveButtons(card) return end
	local state=gStates.meditationTranceState
	if state==nil or state.player~=playerIndex then gStates.meditationTranceState=meditationNewState(playerIndex) state=gStates.meditationTranceState end
	if state.resolved==true then meditationRemoveButtons(card) return end
	if state.mode=="trance" then
		if #state.accepted>=(state.required or 2) then meditationAddButtons(card, true) else meditationRemoveButtons(card) end
	else meditationAddButtons(card, false) end
end

local function meditationContainerIsDeedDeck(container, playerIndex)
	if container==nil or turnOrder[playerIndex]==nil then return false end
	local zone=getObjectFromGUID(deedDeckZones[turnOrder[playerIndex].seatPos])
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==container.guid then return true end end
	local a,b=container.getPosition(),zone.getPosition()
	return ((a[1]-b[1])^2)+((a[3]-b[3])^2)<6.25
end

local function meditationAcceptTranceCard(cardGUID)
	local state=gStates.meditationTranceState
	if state==nil or state.resolved==true or #state.accepted>=(state.required or 2) or state.discard==nil or state.discard[cardGUID]~=true or (state.acceptedSet~=nil and state.acceptedSet[cardGUID]==true) then return false end
	if (state.required or 0)<1 then return false end
	if state.acceptedSet==nil then state.acceptedSet={} end
	state.mode="trance" state.accepted[#state.accepted+1]=cardGUID state.acceptedSet[cardGUID]=true
	broadcastToAll(joinLang({"{en}Trance Card Accepted ({ru}Карта Транса принята ({zh-tw}已接受入定卡（{zh-cn}已接受入定卡（{ko}트랜스 카드 승인 ({es}Carta de Trance aceptada ({fr}Carte de Transe acceptée ({pt-br}Carta de Transe aceita ({de}Trance-Karte akzeptiert (",#state.accepted,"/",state.required,")"}), positionToColor(state.player))
	safeWaitFrames("PlayerBoard.CardFlow",function() refreshMeditationTrance() end, 2)
	return true
end

function meditationTranceContainerEnter(container, obj)
	if obj==nil then return end
	if obj.guid==meditationTranceCardGUID then meditationRemoveButtons(obj) gStates.meditationTranceState=nil return end
	local state=gStates.meditationTranceState
	if state~=nil and state.resolved~=true and meditationContainerIsDeedDeck(container, state.player)==true then meditationAcceptTranceCard(obj.guid) end
end

function meditationTranceCheckLooseCard(cardGUID)
	local state=gStates.meditationTranceState
	if state==nil or state.resolved==true or state.discard==nil or state.discard[cardGUID]~=true then return end
	local card=getObjectFromGUID(cardGUID)
	if card==nil or turnOrder[state.player]==nil then return end
	local zone=getObjectFromGUID(deedDeckZones[turnOrder[state.player].seatPos])
	if zone==nil then return end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==cardGUID then meditationAcceptTranceCard(cardGUID) return end end
end

local function meditationTakeCard(zone, cardGUID, position, callback)
	if zone==nil then return false end
	for _, pile in pairs(zone.getObjects()) do
		if pile.type=="Card" and pile.guid==cardGUID then pile.setPosition(position) pile.setRotation({0,180,0}) callback(pile) return true end
		if pile.type=="Deck" then
			for _, data in pairs(pile.getObjects()) do
				if data.guid==cardGUID then safeTakeObject("PlayerBoard.CardFlow",pile,{guid=cardGUID, position=position, rotation={0,180,0}, smooth=false, callback_function=callback}) return true end
			end
		end
	end
	return false
end

local function meditationInsertDeedCard(playerIndex, card, destination, callback)
	local zone=turnOrder[playerIndex]~=nil and getObjectFromGUID(deedDeckZones[turnOrder[playerIndex].seatPos]) or nil
	if zone==nil or card==nil then if callback~=nil then callback(false) end return end
	local pile=nil
	for _, obj in pairs(zone.getObjects()) do if obj.guid~=card.guid then if obj.type=="Deck" then pile=obj break elseif obj.type=="Card" then pile=obj end end end
	if pile==nil then
		local pos=zone.getPosition() card.setRotation({0,180,180}) card.setPosition({pos[1],1.50,pos[3]})
		safeWaitFrames("PlayerBoard.CardFlow",function() if callback~=nil then callback(true) end end, 2) return
	end
	local pos=pile.getPosition()
	if pile.type=="Deck" then
		card.setScale({1.5,1,1.5}) card.setRotation(pile.getRotation()) card.setPosition({pos[1]+3,pos[2]+(destination=="top" and 0.5 or -0.5),pos[3]})
		safeWaitFrames("PlayerBoard.CardFlow",function() if pile~=nil and not pile.isDestroyed() and card~=nil and not card.isDestroyed() then pile.putObject(card) end safeWaitFrames("PlayerBoard.CardFlow",function() if callback~=nil then callback(true) end end, 1) end, 1)
	else
		local rotation=pile.getRotation() card.setScale({1.5,1,1.5}) card.setRotation(rotation)
		if destination=="top" then card.setPosition({pos[1],pos[2]+0.28,pos[3]}) else pile.setPosition({pos[1],pos[2]+0.28,pos[3]}) card.setPosition({pos[1],pos[2],pos[3]}) end
		safeWaitFrames("PlayerBoard.CardFlow",function() if callback~=nil then callback(true) end end, 4)
	end
end

local function meditationMoveCards(playerIndex, sourceType, cardGUIDs, destination, done)
	local moved=0
	local function moveNext(index)
		if index>#cardGUIDs then if done~=nil then done(moved) end return end
		local sourceZone=getObjectFromGUID((sourceType=="discard" and deedDeckDiscardZones or deedDeckZones)[turnOrder[playerIndex].seatPos])
		local deckZone=getObjectFromGUID(deedDeckZones[turnOrder[playerIndex].seatPos])
		local deckPos=deckZone~=nil and deckZone.getPosition() or {turnOrder[playerIndex].seatPos*40-114,1.5,-43}
		local staging={deckPos[1]+4,3.0,deckPos[3]}
		local found=meditationTakeCard(sourceZone, cardGUIDs[index], staging, function(card)
			meditationInsertDeedCard(playerIndex, card, destination, function(success) if success==true then moved=moved+1 end safeWaitFrames("PlayerBoard.CardFlow",function() moveNext(index+1) end, 2) end)
		end)
		if found==false then safeWaitFrames("PlayerBoard.CardFlow",function() moveNext(index+1) end, 1) end
	end
	moveNext(1)
end

local function meditationGrantDrawBonus(playerIndex)
	if gStates.meditationDrawBonus==nil then gStates.meditationDrawBonus={} end
	gStates.meditationDrawBonus[playerIndex]=2
	if playerIndex==gStates.turnNumber then safeWaitFrames("PlayerBoard.CardFlow",function() if gStates.turnNumber==playerIndex then mainUIUpdate("Meditation Draw Bonus") end end, 1) end
end

local function meditationFinish(playerIndex, destination, moved, expected, name)
	turnOrder[playerIndex].deedCount=(turnOrder[playerIndex].deedCount or 0)+moved
	if moved~=expected then
		local effect=name=="Trance" and "{en}Trance{ru}Транс{zh-tw}入定{zh-cn}入定{ko}트랜스{es}Trance{fr}Transe{pt-br}Transe{de}Trance" or "{en}Meditation{ru}Медитация{zh-tw}冥想{zh-cn}冥想{ko}명상{es}Meditación{fr}Méditation{pt-br}Meditação{de}Meditation"
		broadcastToAll(joinLang({effect,"{en} could not find all selected discard cards.{ru}: не удалось найти все выбранные карты сброса.{zh-tw}：找不到所有選定的棄牌。{zh-cn}：找不到所有选定的弃牌。{ko}: 선택한 버린 카드를 모두 찾지 못했습니다.{es}: no se pudieron encontrar todas las cartas de descarte seleccionadas.{fr} : impossible de trouver toutes les cartes de défausse sélectionnées.{pt-br}: não foi possível encontrar todas as cartas de descarte selecionadas.{de}: Nicht alle ausgewählten Ablagekarten konnten gefunden werden."}), positionToColor(playerIndex))
	end
	if destination=="bottom" and moved>0 and turnOrder[playerIndex].mage=="Coral" then safeWaitFrames("PlayerBoard.CardFlow",function() coralSetAsideQuickWitted() end, 8) end
end

local function meditationResolve(destination, buttonPlayerColor)
	local card=getObjectFromGUID(meditationTranceCardGUID)
	local playerIndex=meditationPlayerIndex(card)
	if card==nil or playerIndex==nil or legalPlayerCheck(buttonPlayerColor, turnOrder[playerIndex].seatPos)~=true then return end
	local state=gStates.meditationTranceState
	if state==nil or state.player~=playerIndex then refreshMeditationTrance() state=gStates.meditationTranceState end
	if state==nil or state.resolved==true then return end
	if state.mode=="trance" then
		local required=state.required or math.min(2,#state.accepted)
		if #state.accepted<required then broadcastToAll(joinLang({"{en}Trance: add {ru}Транс: сначала добавьте ещё {zh-tw}入定：請先從棄牌堆再加入 {zh-cn}入定：请先从弃牌堆再加入 {ko}트랜스: 먼저 버린 카드 더미에서 {es}Trance: añade primero {fr}Transe : ajoutez d'abord {pt-br}Transe: primeiro adicione {de}Trance: Lege zuerst noch ",required-#state.accepted,"{en} more chosen card(s) from your discard pile to your Deed deck first.{ru} выбранных карт из сброса в Колоду деяний.{zh-tw} 張選定的卡到行動牌庫。{zh-cn} 张选定的卡到行动牌库。{ko}장의 선택한 카드를 행동 덱에 추가하세요.{es} carta(s) elegida(s) de tu descarte a tu mazo de Proezas.{fr} carte(s) choisie(s) de votre défausse dans votre paquet d'Actions.{pt-br} carta(s) escolhida(s) do descarte ao seu Baralho de Façanhas.{de} ausgewählte Karte(n) aus deinem Ablagestapel in dein Handlungskartendeck."}), positionToColor(playerIndex)) return end
		state.resolved=true meditationRemoveButtons(card) meditationGrantDrawBonus(playerIndex)
		local selected={}
		for a=1, required do selected[#selected+1]=state.accepted[a] end
		meditationMoveCards(playerIndex, "deed", selected, destination, function(moved) meditationFinish(playerIndex, destination, moved, required, "Trance") end)
		return
	end
	local discard=meditationDiscardSnapshot(playerIndex)
	local choices={}
	for guid, _ in pairs(discard) do choices[#choices+1]=guid end
	local amount=math.min(2,#choices)
	local selected={}
	for a=1, amount do selected[#selected+1]=table.remove(choices,math.random(#choices)) end
	state.resolved=true meditationRemoveButtons(card) meditationGrantDrawBonus(playerIndex)
	if amount==0 then
		broadcastToAll(joinLang({"{en}Meditation: no discard cards to return. Draw +2 over hand limit still applies.{ru}Медитация: в сбросе нет карт для возврата. Добор +2 сверх лимита руки всё равно действует.{zh-tw}冥想：棄牌堆沒有可返回的卡。仍可比手牌上限多抽 2 張。{zh-cn}冥想：弃牌堆没有可返回的卡。仍可比手牌上限多抽 2 张。{ko}명상: 되돌릴 버린 카드가 없습니다. 손패 제한보다 +2장 더 뽑는 효과는 그대로 적용됩니다.{es}Meditación: no hay cartas de descarte que devolver. Aún puedes robar +2 por encima del límite de mano.{fr}Méditation : aucune carte de défausse à remettre. La pioche de +2 au-dessus de la limite de main s'applique quand même.{pt-br}Meditação: não há cartas de descarte para devolver. Comprar +2 acima do limite de mão ainda se aplica.{de}Meditation: Keine Ablagekarten zum Zurücklegen. +2 Karten über das Handlimit hinaus ziehen gilt trotzdem."}), positionToColor(playerIndex))
		return
	end
	meditationMoveCards(playerIndex, "discard", selected, destination, function(moved)
		meditationFinish(playerIndex, destination, moved, amount, "Meditation")
		if moved==amount then
			local destinationText=destination=="top" and "{en}top{ru}верх{zh-tw}頂部{zh-cn}顶部{ko}맨 위{es}parte superior{fr}dessus{pt-br}topo{de}oberste Ende" or "{en}bottom{ru}низ{zh-tw}底部{zh-cn}底部{ko}맨 아래{es}parte inferior{fr}dessous{pt-br}fundo{de}unterste Ende"
			broadcastToAll(joinLang({"{en}Meditation returned {ru}Медитация вернула {zh-tw}冥想將 {zh-cn}冥想将 {ko}명상으로 무작위 버린 카드 {es}Meditación devolvió {fr}Méditation a remis {pt-br}Meditação devolveu {de}Meditation hat ",amount,"{en} random discard card(s) to the {ru} случайных карт из сброса в {zh-tw} 張隨機棄牌放回行動牌庫的{zh-cn} 张随机弃牌放回行动牌库的{ko}장을 행동 덱의 {es} carta(s) de descarte aleatoria(s) a la {fr} carte(s) de défausse aléatoire(s) sur le {pt-br} carta(s) de descarte aleatória(s) ao {de} zufällige Ablagekarte(n) an das ",destinationText,"{en} of the Deed deck.{ru} Колоды деяний.{zh-tw}。{zh-cn}。{ko}에 되돌렸습니다.{es} del mazo de Proezas.{fr} du paquet d'Actions.{pt-br} do Baralho de Façanhas.{de} des Handlungskartendecks zurückgelegt."}), positionToColor(playerIndex))
		end
	end)
end

function meditationTranceTop(player, mouseButton, id) if mouseButton~="-3" then meditationResolve("top", player.color) end end

function meditationTranceBot(player, mouseButton, id) if mouseButton~="-3" then meditationResolve("bottom", player.color) end end

--Steady Tempo end-of-turn choice. The card deliberately remains in the play area
--during cleanup, then these small card-attached buttons decide where it goes.
local steadyTempoGUIDs={ ["1f362f"]=true, ["6e506a"]=true }
function isSteadyTempoGUID(guid) return guid~=nil and steadyTempoGUIDs[guid]==true end
local function steadyTempoPlayerIndex(seatPos)
	for playerIndex, details in pairs(turnOrder) do if details.seatPos==seatPos then return playerIndex end end
	return nil
end

function steadyTempoPendingForSeat(seatPos)
	if seatPos==nil or gStates.steadyTempoPending==nil then return false end
	for _, pendingSeat in pairs(gStates.steadyTempoPending) do if pendingSeat==seatPos then return true end end
	return false
end

function steadyTempoUpdateRewardGate(seatPos)
	if seatPos==nil or gStates.preEndTurn~=true or turnOrder[gStates.turnNumber]==nil or turnOrder[gStates.turnNumber].seatPos~=seatPos then return end
	--Only asynchronous cleanup physically disables Rewards Claimed. Steady Tempo is a normal
	--Rewards Claimed soft lock: the button stays clickable, explains the problem, and times out.
	local blocked=rewardClaimDelayActive==true
	UI.setAttribute("PreEndTurn", "interactable", blocked and "false" or "true")
	UI.setAttribute("PreEndTurnImage", "image", blocked and "Sliced Button/Button New Deactive" or "Sliced Button/Button New Active")
end

local function steadyTempoStripButtons(card)
	local xml=card~=nil and (card.UI.getXmlTable() or {}) or {}
	for a=#xml, 1, -1 do
		local id=xml[a].attributes~=nil and xml[a].attributes.id or nil
		if id==card.guid.."steadyTempoDiscard" or id==card.guid.."steadyTempoBot" or id==card.guid.."steadyTempoTop" then table.remove(xml,a) end
	end
	return xml
end

function steadyTempoRemoveButtons(card)
	if card==nil then return end
	local before=card.UI.getXmlTable() or {}
	local xml=steadyTempoStripButtons(card)
	if #xml~=#before then if #xml>0 then card.UI.setXmlTable(xml) else card.UI.setXml("") end end
end

local function steadyTempoHasDeedPile(playerIndex)
	local details=turnOrder[playerIndex]
	local zone=details~=nil and getObjectFromGUID(deedDeckZones[details.seatPos]) or nil
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.type=="Deck" or obj.type=="Card" then return true end end
	return false
end

local function steadyTempoCardInPlayArea(card, seatPos)
	local zone=card~=nil and getObjectFromGUID(playerPlayAreas[seatPos]) or nil
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==card.guid then return true end end
	return false
end

local function steadyTempoAddButtons(card, playerIndex)
	if card==nil or turnOrder[playerIndex]==nil then return end
	if cardEffectIsVertical(card)==false then steadyTempoRemoveButtons(card) return end
	local xml=steadyTempoStripButtons(card)
	xml[#xml+1]=createClaimButton(card.guid, "steadyTempoDiscard")
	--The printed basic effect only permits the bottom option while the Deed deck is not empty.
	if steadyTempoHasDeedPile(playerIndex)==true then xml[#xml+1]=createClaimButton(card.guid, "steadyTempoBot") end
	xml[#xml+1]=createClaimButton(card.guid, "steadyTempoTop")
	card.UI.setXmlTable(xml)
end

function steadyTempoPrepare(card, playerIndex)
	if card==nil or isSteadyTempoGUID(card.guid)==false or turnOrder[playerIndex]==nil then return end
	if cardEffectIsVertical(card)==false then steadyTempoRemoveButtons(card) return end
	if gStates.steadyTempoPending==nil then gStates.steadyTempoPending={} end
	local seatPos=turnOrder[playerIndex].seatPos
	gStates.steadyTempoPending[card.guid]=seatPos
	steadyTempoAddButtons(card, playerIndex)
	steadyTempoUpdateRewardGate(seatPos)
	if gStates.preEndTurn==true and mainUIUpdate~=nil then mainUIUpdate("Steady Tempo pending") end
end

function steadyTempoClearPending(cardGUID)
	local seatPos=gStates.steadyTempoPending~=nil and gStates.steadyTempoPending[cardGUID] or nil
	if gStates.steadyTempoPending~=nil then gStates.steadyTempoPending[cardGUID]=nil end
	local card=getObjectFromGUID(cardGUID)
	if card~=nil then steadyTempoRemoveButtons(card) end
	if seatPos~=nil then steadyTempoUpdateRewardGate(seatPos) end
	if gStates.preEndTurn==true and mainUIUpdate~=nil then mainUIUpdate("Steady Tempo resolved") end
end

function steadyTempoRefreshCard(cardGUID)
	if gStates.steadyTempoPending==nil then return end
	local seatPos=gStates.steadyTempoPending[cardGUID]
	local card=seatPos~=nil and getObjectFromGUID(cardGUID) or nil
	local playerIndex=seatPos~=nil and steadyTempoPlayerIndex(seatPos) or nil
	if card==nil or playerIndex==nil then return end
	if steadyTempoCardInPlayArea(card, seatPos)==true and card.is_face_down==false and cardEffectIsVertical(card)==true then steadyTempoAddButtons(card, playerIndex) else steadyTempoRemoveButtons(card) end
end

function steadyTempoRefreshAll()
	if gStates.steadyTempoPending==nil then return end
	for cardGUID, _ in pairs(gStates.steadyTempoPending) do steadyTempoRefreshCard(cardGUID) end
end

local function steadyTempoMoveToDiscard(playerIndex, card)
	local details=turnOrder[playerIndex]
	local zone=details~=nil and getObjectFromGUID(deedDeckDiscardZones[details.seatPos]) or nil
	if zone==nil or card==nil then return false end
	local pile=nil
	for _, obj in pairs(zone.getObjects()) do if obj.type=="Deck" then pile=obj break elseif obj.type=="Card" then pile=obj end end
	card.setScale({1.5,1,1.5}) card.setRotation({0,180,0})
	if pile==nil then
		local pos=zone.getPosition() card.setPosition({pos[1],1.50,pos[3]})
	else
		local pos=pile.getPosition() card.setPosition({pos[1]+3,pos[2]+0.5,pos[3]})
		safeWaitFrames("PlayerBoard.CardFlow",function() if pile~=nil and not pile.isDestroyed() and card~=nil and not card.isDestroyed() then pile.putObject(card) end end, 1)
	end
	safeWaitFrames("PlayerBoard.CardFlow",function() scheduleDeedPileDescriptionRefresh(details.seatPos, "discard") end, 6)
	return true
end

function steadyTempoChoice(player, mouseButton, id)
	if mouseButton=="-3" or player==nil or id==nil then return end
	local cardGUID=id:sub(1,6)
	if isSteadyTempoGUID(cardGUID)==false or gStates.steadyTempoPending==nil then return end
	local seatPos=gStates.steadyTempoPending[cardGUID]
	local playerIndex=seatPos~=nil and steadyTempoPlayerIndex(seatPos) or nil
	local card=getObjectFromGUID(cardGUID)
	if playerIndex==nil or card==nil or legalPlayerCheck(player.color, seatPos)~=true then return end
	local choice=id:sub(7)
	if choice=="steadyTempoBot" and steadyTempoHasDeedPile(playerIndex)==false then steadyTempoAddButtons(card, playerIndex) return end
	--Remove the controls immediately, but keep the pending flag until the card physically reaches its destination.
	--Rewards Claimed therefore cannot race a Top insertion and draw the old top card first.
	steadyTempoRemoveButtons(card)
	if choice=="steadyTempoDiscard" then
		if steadyTempoMoveToDiscard(playerIndex, card)==true then safeWaitFrames("PlayerBoard.CardFlow",function() steadyTempoClearPending(cardGUID) end, 2)
		else steadyTempoAddButtons(card, playerIndex) end
		return
	end
	local destination=choice=="steadyTempoBot" and "bottom" or "top"
	meditationInsertDeedCard(playerIndex, card, destination, function(success)
		if success~=true then steadyTempoAddButtons(card, playerIndex) return end
		turnOrder[playerIndex].deedCount=(turnOrder[playerIndex].deedCount or 0)+1
		scheduleDeedPileDescriptionRefresh(seatPos, "deed")
		scheduleEndRoundDeedStateRefresh(seatPos)
		--Quick Witted remains Coral's actual set-aside bottom card; Steady Tempo sits immediately above it.
		if destination=="bottom" and turnOrder[playerIndex].mage=="Coral" then
			scheduleCoralQuickWittedBottom(6)
			safeWaitFrames("PlayerBoard.CardFlow",function() steadyTempoClearPending(cardGUID) end, 8)
		else steadyTempoClearPending(cardGUID) end
	end)
end

--Keep Quick Witted Set Aside at the bottom of Coral's physical Deed Deck.
--Taking it out and putting it back at the Deck's resting elevation inserts it at the bottom.
function coralSetAsideQuickWitted()
	local cardGUID=GUID.card.quickWitted
	for _, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return end
			local deedDeck=nil
			for _, obj in pairs(deedZone.getObjects()) do
				if obj.type=="Deck" then
					deedDeck=obj
					for _, cardData in pairs(obj.getObjects()) do
						if cardData.guid==cardGUID then
							local deckPos=obj.getPosition()
							safeTakeObject("PlayerBoard.CardFlow",obj,{guid=cardGUID, position={deckPos[1]+3, deckPos[2], deckPos[3]}, rotation={0, 180, 180}, smooth=false, callback_function=function(card)
								safeWaitFrames("PlayerBoard.CardFlow",function()
									local currentDeck=nil
									for _, currentObj in pairs(deedZone.getObjects()) do if currentObj.type=="Deck" then currentDeck=currentObj break end end
									if currentDeck~=nil then
										local currentPos=currentDeck.getPosition()
										card.setScale({1.5, 1, 1.5})
										card.setPosition({currentPos[1]+3, currentPos[2]-0.5, currentPos[3]})
										currentDeck.putObject(card)
									else
										card.setPosition({deckPos[1], deckPos[2], deckPos[3]})
									end
								end, 1)
							end})
							return
						end
					end
				end
			end
			return
		end
	end
end

--Deals all the hands by fast forwarding through the turns
function dealAllHands()
	local temp=gStates.turnNumber
	for a=1, #turnOrder, 1 do
		gStates.turnNumber=a
		if turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] and playerDropoutInactive(gStates.turnNumber)==false then drawUpTo({color="Black"}, "-1", "DrawHand") end--color is only there to stop error
	end
	gStates.turnNumber=temp
	safeWaitTime("PlayerBoard.CardFlow",function()
		for x=1, #turnOrder, 1 do
			--Records current amount of cards in deed deck
			turnOrder[x].deedCount=0
			for _, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[x].seatPos]).getObjects()) do
				if b.type=="Card" then turnOrder[x].deedCount=1 end
				if b.type=="Deck" then turnOrder[x].deedCount=b.getQuantity() end
			end
		end
	end, 0.5)
end

--Fill any gaps in the offer by sliding more cards down the line
local function compactAndRefillDeedOfferRaw()
	local offerList={{}, {}}
	local sourceDeck={GUID.zone.actionDeck, GUID.zone.spellDeck}
	for _, obj in pairs(getObjectFromGUID(GUID.zone.offer).getObjects()) do
		if obj.type=="Card" then --and obj.resting==true then
			local cardSpot=obj.getPosition()
			offerList[math.floor(((-cardSpot[3]-10.2)/6)+0.5)][math.floor(((cardSpot[1]-21.6)/4.8)+0.5)]=obj.guid
		end
	end
	--fill gaps in the offer
	for column=1, gStates.offerSize, 1 do
		for row=1, 2, 1 do
			if offerList[row][column]==nil then
				for replaceColumn=column+1, gStates.offerSize+1, 1 do
					if replaceColumn<gStates.offerSize+1 then
						--fill empty spaces with cards further up the offer
						if offerList[row][replaceColumn]~=nil then
							local cardMove=getObjectFromGUID(offerList[row][replaceColumn])
							cardMove.unlock()
							cardMove.setPositionSmooth({(column*4.8)+21.6, 1.5, -((row*6)+10.2)})
							cardMove.setRotationSmooth({0, 180, 0})
							safeWaitCondition("PlayerBoard.CardFlow",function() safeWaitTime("PlayerBoard.CardFlow",function() cardMove.lock() end, 1) end, function() return cardMove.resting end)
							offerList[row][column]=offerList[row][replaceColumn]
							offerList[row][replaceColumn]=nil
							break
						end
					else
						--fill empty spaces from deck when no cards are found
						local deckName=row==1 and "Advanced Action" or "Spell"
						standardDeckCycleShuffleIfReached(deckName)
						local MainDeck=getObjectFromGUID(sourceDeck[row]).getObjects()
						if MainDeck[1]~=nil then
							if MainDeck[1].type=="Deck" then
								local newcard=MainDeck[1].takeObject({position={((column*4.8)+21.6), 1.5, -((row*6)+10.2)}, rotation={0, 180, 0}})
								offerList[row][column]=newcard.guid
								safeWaitCondition("PlayerBoard.CardFlow",function() safeWaitTime("PlayerBoard.CardFlow",function() newcard.lock() end, 1) end, function() return newcard.resting end)
							else
								MainDeck[1].setPositionSmooth({(column*4.8)+21.6, 1.5, -((row*6)+10.2)})
								MainDeck[1].setRotationSmooth({0, 180, 0})
								MainDeck[1]=nil
							end
						end
					end
				end
			end
		end
	end
end

function compactAndRefillDeedOffer()
	return safeCallback("compactAndRefillDeedOffer",function() return compactAndRefillDeedOfferRaw() end)
end

-- Glade discard healing
local gladeDiscardHealButtonGUID=nil

function removeGladeDiscardHealButton(obj)
	if obj==nil then return end
	local remove={}
	for _, button in pairs(obj.getButtons() or {}) do if button.click_function=="gladeDiscardHeal" then remove[#remove+1]=button.index end end
	table.sort(remove, function(a,b) return a>b end)
	for _, index in ipairs(remove) do obj.removeButton(index) end
	local xml=obj.UI.getXmlTable() or {}
	local changed=false
	for i=#xml, 1, -1 do
		if xml[i].attributes~=nil and xml[i].attributes.id=="GladeDiscardHealButton" then table.remove(xml, i) changed=true end
	end
	if changed==true then
		if #xml>0 then obj.UI.setXmlTable(xml) else obj.UI.setXmlTable({{}}) end
	end
end
local function clearGladeDiscardHealButtons()
	if gladeDiscardHealButtonGUID~=nil then removeGladeDiscardHealButton(getObjectFromGUID(gladeDiscardHealButtonGUID)) gladeDiscardHealButtonGUID=nil end
	for _, details in pairs(turnOrder or {}) do
		if details.seatPos~=nil then
			local zone=getObjectFromGUID(deedDeckDiscardZones[details.seatPos])
			if zone~=nil then for _, obj in pairs(zone.getObjects()) do removeGladeDiscardHealButton(obj) end end
		end
	end
end
local function gladeDiscardWound(playerIndex)
	local details=turnOrder[playerIndex]
	local zone=details~=nil and getObjectFromGUID(deedDeckDiscardZones[details.seatPos]) or nil
	if zone==nil then return nil, nil end
	for _, obj in pairs(zone.getObjects()) do
		if obj.type=="Card" and obj.getGMNotes()=="Wound" then return obj, obj.guid end
		if obj.type=="Deck" then
			for _, data in pairs(obj.getObjects()) do if data.gm_notes=="Wound" then return obj, data.guid end end
		end
	end
	return nil, nil
end
function refreshGladeDiscardHealButton()
	clearGladeDiscardHealButtons()
	local playerIndex=gStates.turnNumber
	local details=turnOrder[playerIndex]
	if details==nil or details.mage==gStates.positionMageKnight[5] or playerDropoutInactive(playerIndex)==true then return end
	if gStates.preEndTurn~=true or gStates.coopAssaultPhase=="combat" or gameOver==true or UI.getAttribute("RewardCheck", "active")~="true" then return end
	if details.avatarLocation~="glade" and not (gStates.gameScenario=="The Hidden Valley Blitz" and details.avatarLocation=="hidden valley") then return end
	if scenarioRestLocationIsAvailable()~=true then return end
	if gStates.gladeDiscardHealUsed==nil then gStates.gladeDiscardHealUsed={} end
	if gStates.gladeDiscardHealUsed[details.seatPos]==true then return end
	local discardObj=gladeDiscardWound(playerIndex)
	if discardObj==nil then return end
	removeGladeDiscardHealButton(discardObj)
	local xml=discardObj.UI.getXmlTable() or {}
	xml[#xml+1]={tag="Button", attributes={id="GladeDiscardHealButton", onClick="global/gladeDiscardHealUI", width=100, height=100, position="0 0 -100", rotation="0 0 0", colors="#00000000|#00000000|#00000000|#00000000"},
		children={{tag="Image", attributes={image="Glade Heal Button", width=100, height=100, rotation="0 0 180", preserveAspect="true"}}}}
	discardObj.UI.setXmlTable(xml)
	gladeDiscardHealButtonGUID=discardObj.guid
end
function gladeDiscardHealUI(player, value, id)
	local obj=gladeDiscardHealButtonGUID~=nil and getObjectFromGUID(gladeDiscardHealButtonGUID) or nil
	if obj~=nil and player~=nil then gladeDiscardHeal(obj, player.color, false) end
end
function gladeDiscardHeal(obj, playerColor, altClick)
	local playerIndex=gStates.turnNumber
	local details=turnOrder[playerIndex]
	if details==nil or legalPlayerCheck(playerColor, details.seatPos)~=true then return end
	if gStates.preEndTurn~=true or gStates.coopAssaultPhase=="combat" or gameOver==true or UI.getAttribute("RewardCheck", "active")~="true" or
		(details.avatarLocation~="glade" and not (gStates.gameScenario=="The Hidden Valley Blitz" and details.avatarLocation=="hidden valley")) or scenarioRestLocationIsAvailable()~=true then refreshGladeDiscardHealButton() return end
	if gStates.gladeDiscardHealUsed==nil then gStates.gladeDiscardHealUsed={} end
	if gStates.gladeDiscardHealUsed[details.seatPos]==true then refreshGladeDiscardHealButton() return end
	local source, woundGUID=gladeDiscardWound(playerIndex)
	if source==nil or woundGUID==nil then refreshGladeDiscardHealButton() return end
	gStates.gladeDiscardHealUsed[details.seatPos]=true
	clearGladeDiscardHealButtons()
	local playArea=getObjectFromGUID(playerPlayAreas[details.seatPos])
	local pos=playArea~=nil and playArea.getPosition() or {(details.seatPos*40)-100,1.5,-39.4}
	local destination={pos[1],2.7,pos[3]}
	local function finishHeal(wound)
		if wound==nil then return end
		wound.setScale({1.5,1,1.5})
	end
	if source.type=="Deck" then
		safeTakeObject("CardFlow",source,{guid=woundGUID, position=destination, rotation={0,180,0}, smooth=true, callback_function=finishHeal})
	else
		source.setScale({1.5,1,1.5})
		source.setRotationSmooth({0,180,0})
		source.setPositionSmooth(destination)
		finishHeal(source)
	end
end

-- Coral Quick Witted scheduling
local coralQuickWittedShufflePause=nil
function scheduleCoralQuickWittedBottom(delayFrames)
	if coralQuickWittedShufflePause~=nil then Wait.stop(coralQuickWittedShufflePause) end
	coralQuickWittedShufflePause=safeWaitFrames("CardFlow",function() coralQuickWittedShufflePause=nil coralSetAsideQuickWitted() end, delayFrames or 5)
end

-- Wound dealing helper
function DealWound(paramaters)
	local woundbag=getObjectFromGUID(paramaters.guid)
	local playerPosition=math.ceil((woundbag.getPosition()[1]+80)/40)
	if legalPlayerCheck(paramaters.player.color, playerPosition)==true then
		woundbag.takeObject({position={(playerPosition*40)-91, 2.98, -48.40}})
		if paramaters.id=="DealPoison" then
			woundbag.takeObject({position={(playerPosition*40)-110.54, 2, -43.20}})
		end
	end
end

end)
